/**
 * TERRA BELLUM — battle serialisation & log narration (GDD §13).
 *
 * "Dice rolls and battle logic run behind seeded, logged interfaces so any
 * battle is replayable deterministically for debugging and balance review."
 *
 * PURE MODULE: no Three.js, no DOM.
 */

import type {
  BattleEvent,
  BattleParticipant,
  BattleSide,
  BattleState,
  Terrain,
} from '../types';

export const REPLAY_VERSION = 1;

export interface BattleReplay {
  v: number;
  id: string;
  seed: number;
  boardId: string;
  boardName: string;
  terrain: Terrain;
  hexId: string;
  w: number;
  h: number;
  participants: { attacker: BattleParticipant; defender: BattleParticipant };
  winner?: BattleSide;
  endReason?: 'wipe' | 'concede' | 'timeout';
  log: BattleEvent[];
}

export function serializeBattle(s: BattleState): string {
  const replay: BattleReplay = {
    v: REPLAY_VERSION,
    id: s.id,
    seed: s.seed,
    boardId: s.boardId,
    boardName: s.boardName,
    terrain: s.terrain,
    hexId: s.hexId,
    w: s.w,
    h: s.h,
    participants: { attacker: s.attacker, defender: s.defender },
    winner: s.winner,
    endReason: s.endReason,
    log: s.log,
  };
  return JSON.stringify(replay);
}

export function parseBattleLog(json: string): { seed: number; boardId: string; log: BattleEvent[] } {
  let raw: unknown;
  try {
    raw = JSON.parse(json);
  } catch {
    throw new Error('battle replay: not valid JSON');
  }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('battle replay: root is not an object');
  }
  const o = raw as Record<string, unknown>;
  if (typeof o.seed !== 'number' || !Number.isFinite(o.seed)) {
    throw new Error('battle replay: missing seed');
  }
  if (typeof o.boardId !== 'string' || o.boardId.length === 0) {
    throw new Error('battle replay: missing boardId');
  }
  if (!Array.isArray(o.log)) throw new Error('battle replay: missing log');
  for (const e of o.log) {
    if (e === null || typeof e !== 'object' || typeof (e as { t?: unknown }).t !== 'string') {
      throw new Error('battle replay: malformed log entry');
    }
  }
  return { seed: o.seed, boardId: o.boardId, log: o.log as BattleEvent[] };
}

// ─────────────────────────────────────────────────────────────────────────────
// Ticker text
// ─────────────────────────────────────────────────────────────────────────────

const SIDE_LABEL: Record<BattleSide, string> = {
  attacker: 'ATTACKER',
  defender: 'DEFENDER',
};

/** Compact call-sign for a unit id, for the scrolling combat ticker. */
export function shortId(id: string): string {
  const tail = id.split(/[_:]/).pop() ?? id;
  return tail.slice(-4).toUpperCase();
}

const at = (x: number, y: number): string => `${x}·${y}`;

/** One short, uppercase combat-log line per event. */
export function describeEvent(e: BattleEvent): string {
  switch (e.t) {
    case 'battle_start':
      return `ENGAGEMENT OPEN // BOARD ${e.boardId.toUpperCase()} // SEED ${e.seed}`;
    case 'deploy':
      return `${SIDE_LABEL[e.side]} DEPLOYS ${e.units.length} CHASSIS`;
    case 'side_pick':
      return `DEFENDER CLAIMS THE ${e.bottom === 'defender' ? 'SOUTH' : 'NORTH'} LINE`;
    case 'obstacles_placed':
      return `DEFENDER SEALS ${e.tiles.length} TILE${e.tiles.length === 1 ? '' : 'S'}`;
    case 'turn_start':
      return `TURN ${e.turn} — ${SIDE_LABEL[e.side]} ACTIVE`;
    case 'roll':
      return `ROLL ${e.dice[0]}·${e.dice[1]}·${e.dice[2]}`;
    case 'triple_zero':
      return `${e.playerName.toUpperCase()}: TRIPLE ZERO — ALL SYSTEMS COLD`;
    case 'assign':
      return `DIE ${e.die + 1} → ${shortId(e.unitId)} (${e.ap} AP)`;
    case 'move':
      return `${shortId(e.unitId)} MOVES ${at(e.from.x, e.from.y)} → ${at(e.to.x, e.to.y)}`;
    case 'teleport':
      return `${shortId(e.unitId)} PHASES ${at(e.from.x, e.from.y)} → ${at(e.to.x, e.to.y)}`;
    case 'attack':
      return e.killed
        ? `${shortId(e.unitId)} DESTROYS ${shortId(e.targetId)} (${e.damage} DMG)`
        : `${shortId(e.unitId)} HITS ${shortId(e.targetId)} FOR ${e.damage}${
            e.mitigated > 0 ? ` (−${e.mitigated} MITIGATED)` : ''
          }`;
    case 'attack_wall':
      return e.destroyed
        ? `${shortId(e.unitId)} BREACHES WALL ${at(e.x, e.y)}`
        : `${shortId(e.unitId)} CRACKS WALL ${at(e.x, e.y)} FOR ${e.damage}`;
    case 'brace':
      return `${shortId(e.unitId)} BRACES`;
    case 'hazard':
      return e.killed
        ? `${shortId(e.unitId)} BURNS DOWN IN THE VENT`
        : `${shortId(e.unitId)} TAKES ${e.damage} VENT DAMAGE`;
    case 'collapse':
      return `TILE ${at(e.x, e.y)} GIVES WAY`;
    case 'turn_end':
      return `${SIDE_LABEL[e.side]} ENDS TURN`;
    case 'concede':
      return `${SIDE_LABEL[e.side]} CONCEDES THE FIELD`;
    case 'timeout_pass':
      return `${SIDE_LABEL[e.side]} MISSED THE CLOCK`;
    case 'battle_end':
      return `${SIDE_LABEL[e.winner]} HOLDS THE FIELD — ${e.reason.toUpperCase()}`;
    default: {
      const never: never = e;
      throw new Error(`unhandled battle event ${JSON.stringify(never)}`);
    }
  }
}
