  async commitDeployment(
    placements: { unitId: UnitId; x: number; y: number }[],
  ): Promise<Result<void>> {
    const side = this.mySide();
    const battle = this.battle;
    const layout =
      placements.length > 0 || !battle || !side
        ? placements
        : battle.units
            .filter((u) => u.side === side && u.alive)
            .map((u) => ({ unitId: u.id, x: u.x, y: u.y }));
    return this.battleAction({ t: 'commit_deployment', placements: layout });
  }

