  // ── guild (GDD §8, §9) ────────────────────────────────────────────────────

  /**
   * The banner is forwarded on the wire as two extra fields. `CreateGuildReq`
   * (backend/firebase/functions.ts) does not declare them yet, so the callable
   * contract has to be widened server-side before the Cloud Function can honour
   * the founder's choice; until then it allocates the mark itself, exactly as it
   * does for a request with no banner at all. Nothing here can silently issue a
   * colour the server did not agree to — the snapshot is authoritative.
   */
  async createGuild(
    name: string,
    tag: string,
    motto: string,
    banner?: BannerRequest,
  ): Promise<Result<GuildId>> {
    return this.send(async (calls, worldId) => {
      const req: CreateGuildReq & Partial<BannerRequest> = { worldId, name, tag, motto };
      if (banner) {
        req.color = banner.color;
        req.emblem = banner.emblem;
      }
      const res = await calls.createGuild(req);
      return res.ok ? ok(res.value.guildId) : err(res.error);
    });
  }

