  /**
   * The one player-authored document write. Security rules pin `authorId` to
   * the caller's uid and refuse any `kind` other than `text`.
   */
  async sendChat(channel: string, text: string): Promise<Result<void>> {
    const body = text.trim();
    if (!body) return err('nothing to say');
    const gate = this.ready();
    if (!gate.ok) return err(gate.error);
    const fs = this.fs;
    const db = this.store;
    if (!fs || !db) return err('server unreachable');

    try {
      const message: ChatMessage = {
        id: uid('msg'),
        channel,
        authorId: this.meId,
        authorName: this.players[this.meId]?.name ?? 'COMMANDER',
        text: body.slice(0, 500),
        at: Date.now(),
        kind: 'text',
      };
      await fs.addDoc(fs.collection(db, PATHS.chat()), chatConverter.toFirestore(message));
      return ok(undefined);
    } catch (error) {
      return err(describe(error));
    }
  }

