  // ── notifications (client-local; the server pushes via FCM) ───────────────

  async markNotificationRead(id: string): Promise<Result<void>> {
    const index = this.notifications.findIndex((n) => n.id === id);
    if (index < 0) return err('no such notification');
    this.notifications = this.notifications.map((n) => (n.id === id ? { ...n, read: true } : n));
    this.publish();
    return ok(undefined);
  }

  async clearNotifications(): Promise<Result<void>> {
    this.notifications = [];
    this.publish();
    return ok(undefined);
  }

