/**
 * Tiny reactive store (GDD §2 allows "Zustand or plain TS store").
 *
 * Holds two things:
 *  - the authoritative GameState mirrored from IBackend
 *  - client-only view state (selection, open panel, camera intent)
 *
 * Zero Three.js, zero DOM. Both the render layer and the UI layer subscribe.
 */
import type { ArmyId, BattleState, GameState, HexId, UnitId, DieIndex } from './types';

export type ScreenId =
  | 'boot'
  | 'onboarding'
  | 'staging'
  | 'map'
  | 'battle'
  | 'guild'
  | 'diplomacy'
  | 'season_end';

export type GuildTab = 'chat' | 'roster' | 'objectives' | 'transfers';

export interface ViewState {
  screen: ScreenId;
  guildTab: GuildTab;
  /**
   * Session latch for the banner-choice step (GDD §8).
   *
   * Set once the commander is on a roster and never cleared, so the onboarding
   * screen is a one-time gate: a returning player who already has a guild goes
   * straight to staging, and a player who later leaves their guild — or is wiped
   * off the map and sent back to staging — is never asked to found a banner a
   * second time. Session-scoped rather than persisted because the offline world
   * is re-seeded on every load, and a persisted flag would strand a fresh
   * commander in a fresh world with no way to get a banner at all.
   */
  onboarded: boolean;
  /** Currently selected hex on the global map. */
  selectedHexId?: HexId;
  /** Army selected for orders. */
  selectedArmyId?: ArmyId;
  /** Hex the camera should fly to (consumed by the render layer). */
  focusHexId?: HexId;
  focusNonce: number;
  /** Path preview while dragging an order. */
  previewPath: HexId[];
  /** Battle-layer selection. */
  selectedUnitId?: UnitId;
  selectedDie?: DieIndex;
  /** Tiles highlighted for the selected battle unit. */
  moveTargets: string[];
  attackTargets: UnitId[];
  /** Open parley thread. */
  openParleyId?: string;
  openTreatyId?: string;
  /** Which overlay layers are visible on the map. */
  layers: { pings: boolean; marks: boolean; intel: boolean; objectives: boolean; yields: boolean };
  /** Cinematic playing — suppress input. */
  cinematic?: 'triple_zero' | 'battle_intro' | 'victory' | 'defeat' | 'season_end';
  /** Whether the low-spec renderer path is active. */
  lowSpec: boolean;
}

export type Listener<T> = (value: T, prev: T) => void;

export class Store<T> {
  private value: T;
  private listeners = new Set<Listener<T>>();

  constructor(initial: T) {
    this.value = initial;
  }

  get(): T {
    return this.value;
  }

  set(next: T): void {
    const prev = this.value;
    this.value = next;
    for (const fn of this.listeners) fn(next, prev);
  }

  /** Shallow merge. Only meaningful for object-shaped stores. */
  patch(part: Partial<T>): void {
    this.set({ ...(this.value as object), ...part } as T);
  }

  subscribe(fn: Listener<T>): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  /** Subscribe to a derived slice; fires only when the slice changes. */
  select<S>(selector: (v: T) => S, fn: (s: S) => void, eq: (a: S, b: S) => boolean = Object.is): () => void {
    let last = selector(this.value);
    return this.subscribe((v) => {
      const next = selector(v);
      if (!eq(last, next)) {
        last = next;
        fn(next);
      }
    });
  }
}

export const view = new Store<ViewState>({
  screen: 'boot',
  guildTab: 'chat',
  onboarded: false,
  focusNonce: 0,
  previewPath: [],
  moveTargets: [],
  attackTargets: [],
  layers: { pings: true, marks: true, intel: true, objectives: true, yields: false },
  lowSpec: false,
});

/** Mirror of backend state. Replaced wholesale on every backend push. */
export const game = new Store<GameState | null>(null as GameState | null);

export function gameState(): GameState {
  const s = game.get();
  if (!s) throw new Error('game state not ready');
  return s;
}

export function currentBattle(): BattleState | undefined {
  return game.get()?.battle;
}

export function setScreen(screen: ScreenId): void {
  if (view.get().screen !== screen) view.patch({ screen });
}

export function focusHex(hexId: HexId): void {
  view.patch({ focusHexId: hexId, focusNonce: view.get().focusNonce + 1 });
}

// ── event bus for one-shot cinematics / fx cues ─────────────────────────────

export interface FxEvent {
  type:
    | 'shake'
    | 'toast'
    | 'dice_roll'
    | 'triple_zero'
    | 'unit_destroyed'
    | 'attack'
    | 'capture'
    | 'battle_end'
    | 'notification'
    | 'ping';
  payload?: unknown;
}

type FxListener = (e: FxEvent) => void;
const fxListeners = new Set<FxListener>();

export function emitFx(e: FxEvent): void {
  for (const fn of fxListeners) fn(e);
}

export function onFx(fn: FxListener): () => void {
  fxListeners.add(fn);
  return () => fxListeners.delete(fn);
}
