/**
 * Top-anchored toasts. One host per document; every toast slides down, holds,
 * and slides back out. Severity drives the coloured left rail.
 */
import { el, haptic } from '../dom';

export type ToastKind = 'info' | 'ok' | 'warn' | 'bad' | 'intel';

export interface ToastOpts {
  title: string;
  body?: string;
  kind?: ToastKind;
  /** Lifetime in ms. Defaults to 3400 (4800 for `bad`). */
  ms?: number;
  onClick?: () => void;
}

const GLYPH: Record<ToastKind, string> = {
  info: '▚',
  ok: '✓',
  warn: '⚠',
  bad: '✕',
  intel: '◎',
};

const HAPTIC: Record<ToastKind, number | number[]> = {
  info: 8,
  ok: [10, 40, 14],
  warn: [16, 60, 16],
  bad: [26, 50, 26, 50, 26],
  intel: [8, 30, 8],
};

const MAX_VISIBLE = 4;

let host: HTMLElement | null = null;

/** Attaches (or re-attaches) the toast host. Safe to call more than once. */
export function mountToastHost(root: HTMLElement): void {
  if (host && host.parentElement === root) return;
  host?.remove();
  host = el('div', {
    class: 'toast-host',
    attrs: { role: 'status' },
    aria: { live: 'polite', atomic: 'false' },
  });
  root.appendChild(host);
}

function ensureHost(): HTMLElement {
  if (!host || !host.isConnected) mountToastHost(document.body);
  return host as HTMLElement;
}

export function toast(opts: ToastOpts): void {
  const kind = opts.kind ?? 'info';
  const life = Math.max(900, opts.ms ?? (kind === 'bad' ? 4800 : 3400));
  const parent = ensureHost();

  while (parent.childElementCount >= MAX_VISIBLE) {
    parent.firstElementChild?.remove();
  }

  const node = el('div', {
    class: `toast toast--${kind}${opts.onClick ? ' toast--clickable' : ''}`,
  });

  node.appendChild(el('span', { class: 'toast__rail', aria: { hidden: 'true' } }));
  node.appendChild(el('span', { class: 'toast__glyph', text: GLYPH[kind], aria: { hidden: 'true' } }));

  const text = el('div', { class: 'toast__text' }, el('div', { class: 'toast__title', text: opts.title }));
  if (opts.body) text.appendChild(el('div', { class: 'toast__body', text: opts.body }));
  node.appendChild(text);

  const timerBar = el('span', { class: 'toast__timer', aria: { hidden: 'true' } });
  node.appendChild(timerBar);

  let removed = false;
  const remove = (): void => {
    if (removed) return;
    removed = true;
    node.classList.add('toast--out');
    window.setTimeout(() => node.remove(), 280);
  };

  let handle = window.setTimeout(remove, life);

  node.addEventListener('pointerdown', () => {
    window.clearTimeout(handle);
  });
  node.addEventListener('pointerup', () => {
    handle = window.setTimeout(remove, 900);
  });

  node.addEventListener('click', () => {
    opts.onClick?.();
    remove();
  });

  parent.appendChild(node);
  haptic(HAPTIC[kind]);

  // Drive the lifetime bar with the Web Animations API so it stays off the
  // main-thread style path and pauses cleanly if the tab is hidden.
  try {
    timerBar.animate(
      [{ transform: 'scaleX(1)' }, { transform: 'scaleX(0)' }],
      { duration: life, easing: 'linear', fill: 'forwards' },
    );
  } catch {
    /* WAAPI unavailable — the bar simply stays full. */
  }
}

/** Removes every visible toast (used on screen transitions into battle). */
export function clearToasts(): void {
  if (!host) return;
  for (const child of Array.from(host.children)) child.remove();
}
