/**
 * Resources & economy — GDD §4.
 *
 * Every controlled hex pays Minerals per hourly tick; gas fields additionally
 * pay Gas. Yields land in the *individual owner's* stockpile, are clamped to the
 * configured caps, and are accumulated into `player.harvested` for the season
 * leaderboard tiebreak (GDD §11).
 *
 * PURE: no Three.js, no DOM.
 */
import type { Cost, GameState, Hex, PlayerId } from '../types';
import { ECONOMY } from '../../config/balance';
import { isHexOpen } from './generate';

const ZERO: Cost = { m: 0, g: 0 };

/** Per-tick yield of a single hex, before ownership is considered. */
export function hexYield(state: GameState, hex: Hex): Cost {
  if (!state.world.hexes[hex.id]) return { ...ZERO };
  const bonus = 1 + (ECONOMY.fortYieldBonus[hex.fortLevel] ?? 0);
  const m = Math.round(ECONOMY.mineralsPerHex * ECONOMY.yieldByTerrain[hex.terrain] * bonus);
  const g = hex.gas ? Math.round(ECONOMY.gasPerGasHex * bonus) : 0;
  return { m, g };
}

/** Sum of every open hex the player controls. */
export function playerYield(state: GameState, playerId: PlayerId): Cost {
  let m = 0;
  let g = 0;
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId !== playerId) continue;
    if (!isHexOpen(state.world, hex.id)) continue;
    const y = hexYield(state, hex);
    m += y.m;
    g += y.g;
  }
  return { m, g };
}

/** Hexes controlled by a player in open sectors. */
export function playerHexCount(state: GameState, playerId: PlayerId): number {
  let n = 0;
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId === playerId && isHexOpen(state.world, hex.id)) n++;
  }
  return n;
}

/**
 * Pay out every whole `ECONOMY.tickMs` period elapsed since `state.lastTick`.
 * Stockpiles clamp at the configured caps; `harvested` accumulates what was
 * actually banked, so overflow is never counted twice.
 */
export function tickEconomy(state: GameState, now: number): void {
  if (state.lastTick > now) {
    // Clock ran backwards (clock skew / state rewind) — re-anchor, pay nothing.
    state.lastTick = now;
    return;
  }
  const elapsed = now - state.lastTick;
  if (elapsed < ECONOMY.tickMs) return;
  const periods = Math.floor(elapsed / ECONOMY.tickMs);
  state.lastTick += periods * ECONOMY.tickMs;

  const gains = new Map<PlayerId, Cost>();
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.ownerId) continue;
    if (!isHexOpen(state.world, hex.id)) continue;
    const y = hexYield(state, hex);
    const acc = gains.get(hex.ownerId);
    if (acc) {
      acc.m += y.m * periods;
      acc.g += y.g * periods;
    } else {
      gains.set(hex.ownerId, { m: y.m * periods, g: y.g * periods });
    }
  }

  for (const [playerId, gain] of gains) {
    const player = state.players[playerId];
    if (!player) continue;
    const beforeM = player.minerals;
    const beforeG = player.gas;
    player.minerals = Math.min(ECONOMY.capMinerals, beforeM + gain.m);
    player.gas = Math.min(ECONOMY.capGas, beforeG + gain.g);
    player.harvested = {
      m: player.harvested.m + (player.minerals - beforeM),
      g: player.harvested.g + (player.gas - beforeG),
    };
  }
}

/** Can this player pay? */
export function canAfford(state: GameState, playerId: PlayerId, cost: Cost): boolean {
  const player = state.players[playerId];
  if (!player) return false;
  return player.minerals >= cost.m && player.gas >= cost.g;
}

/** Debit a stockpile. Returns false and changes nothing when unaffordable. */
export function spend(state: GameState, playerId: PlayerId, cost: Cost): boolean {
  const player = state.players[playerId];
  if (!player) return false;
  if (player.minerals < cost.m || player.gas < cost.g) return false;
  player.minerals -= cost.m;
  player.gas -= cost.g;
  return true;
}

/** Credit a stockpile, respecting the caps. Refunds never count as harvest. */
export function refund(state: GameState, playerId: PlayerId, cost: Cost): void {
  const player = state.players[playerId];
  if (!player) return;
  player.minerals = Math.min(ECONOMY.capMinerals, player.minerals + cost.m);
  player.gas = Math.min(ECONOMY.capGas, player.gas + cost.g);
}

export const scaleCost = (cost: Cost, n: number): Cost => ({ m: cost.m * n, g: cost.g * n });
export const halveCost = (cost: Cost): Cost => ({
  m: Math.floor(cost.m / 2),
  g: Math.floor(cost.g / 2),
});
