/**
 * TERRA BELLUM — tactical rules (GDD §7).
 *
 * Pure queries over a BattleState. Nothing here mutates state except the
 * explicitly named `apply*` helpers, which the engine calls.
 *
 * Geometry contract:
 *  - MOVEMENT is orthogonal only (GDD §7.2.4: "up to the unit's MOV in tiles,
 *    orthogonal, no diagonals").
 *  - RANGE is Chebyshev — a gun does not care about street corners, only about
 *    line of sight.
 */

import type { BattleSide, BattleState, BattleUnit, Tile, Trait } from '../types';
import { BATTLE } from '../../config/balance';
import { UNITS } from '../../config/units';

export const ORTHOGONAL: readonly (readonly [number, number])[] = [
  [0, -1],
  [1, 0],
  [0, 1],
  [-1, 0],
];

export interface ReachNode {
  x: number;
  y: number;
  cost: number;
  path: { x: number; y: number }[];
}

export const tileKey = (x: number, y: number): string => `${x},${y}`;

export function otherSide(side: BattleSide): BattleSide {
  return side === 'attacker' ? 'defender' : 'attacker';
}

export function hasTrait(u: BattleUnit, trait: Trait): boolean {
  return UNITS[u.type].traits.includes(trait);
}

/**
 * Has this battle resolved? Call this instead of comparing `s.phase` inline —
 * the engine mutates the phase behind the compiler's back, so a literal
 * comparison after an engine call gets narrowed away.
 */
export function isOver(s: BattleState): boolean {
  return s.phase === 'ended';
}

// ─────────────────────────────────────────────────────────────────────────────
// Board queries
// ─────────────────────────────────────────────────────────────────────────────

export function inBounds(s: BattleState, x: number, y: number): boolean {
  return Number.isInteger(x) && Number.isInteger(y) && x >= 0 && y >= 0 && x < s.w && y < s.h;
}

export function tileAt(s: BattleState, x: number, y: number): Tile | null {
  if (!inBounds(s, x, y)) return null;
  return s.grid[y][x];
}

export function unitAt(s: BattleState, x: number, y: number): BattleUnit | null {
  for (const u of s.units) {
    if (u.alive && u.x === x && u.y === y) return u;
  }
  return null;
}

/** Obstacle, an intact destructible wall, or a collapsed unstable tile. */
export function isBlocking(s: BattleState, x: number, y: number): boolean {
  const t = tileAt(s, x, y);
  if (!t) return true; // off-board counts as solid
  switch (t.kind) {
    case 'obstacle':
      return true;
    case 'destructible':
      return (t.hp ?? 0) > 0;
    case 'unstable':
      return t.collapsed === true;
    default:
      return false;
  }
}

/** Chebyshev distance — the firing metric. */
export function battleDistance(ax: number, ay: number, bx: number, by: number): number {
  return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
}

/** Orthogonal step distance — the walking metric. */
export function stepDistance(ax: number, ay: number, bx: number, by: number): number {
  return Math.abs(ax - bx) + Math.abs(ay - by);
}

// ─────────────────────────────────────────────────────────────────────────────
// Line of sight
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Every tile whose interior the centre-to-centre segment passes through,
 * endpoints included. An exact corner crossing cuts the corner (it enters
 * neither orthogonal neighbour's interior), which keeps diagonal fire honest.
 */
export function lineTiles(ax: number, ay: number, bx: number, by: number): { x: number; y: number }[] {
  const out: { x: number; y: number }[] = [{ x: ax, y: ay }];
  const dx = bx - ax;
  const dy = by - ay;
  const nx = Math.abs(dx);
  const ny = Math.abs(dy);
  const sx = dx > 0 ? 1 : -1;
  const sy = dy > 0 ? 1 : -1;
  let px = ax;
  let py = ay;
  let ix = 0;
  let iy = 0;
  while (ix < nx || iy < ny) {
    const decision = (1 + 2 * ix) * ny - (1 + 2 * iy) * nx;
    if (decision === 0) {
      px += sx;
      py += sy;
      ix++;
      iy++;
    } else if (decision < 0) {
      px += sx;
      ix++;
    } else {
      py += sy;
      iy++;
    }
    out.push({ x: px, y: py });
  }
  return out;
}

/** Supercover line; blockers strictly between the endpoints block. */
export function hasLineOfSight(
  s: BattleState,
  ax: number,
  ay: number,
  bx: number,
  by: number,
): boolean {
  if (ax === bx && ay === by) return true;
  const line = lineTiles(ax, ay, bx, by);
  for (let i = 1; i < line.length - 1; i++) {
    if (isBlocking(s, line[i].x, line[i].y)) return false;
  }
  return true;
}

// ─────────────────────────────────────────────────────────────────────────────
// Unit queries
// ─────────────────────────────────────────────────────────────────────────────

/** Unit RNG plus the elevation bonus while it is standing on high ground. */
export function effectiveRange(s: BattleState, u: BattleUnit): number {
  const base = UNITS[u.type].rng;
  const t = tileAt(s, u.x, u.y);
  return base + (t && t.kind === 'elevation' ? BATTLE.elevationRange : 0);
}

export function livingUnits(s: BattleState, side: BattleSide): BattleUnit[] {
  return s.units.filter((u) => u.side === side && u.alive);
}

/** May this unit pass through (x, y)? Occupied tiles are never passable. */
export function canEnter(s: BattleState, u: BattleUnit, x: number, y: number): boolean {
  if (!inBounds(s, x, y)) return false;
  const occupant = unitAt(s, x, y);
  if (occupant && occupant.id !== u.id) return false;
  if (isBlocking(s, x, y)) return hasTrait(u, 'ignores_obstacles');
  return true;
}

/** May this unit finish its move on (x, y)? */
export function canEndOn(s: BattleState, u: BattleUnit, x: number, y: number): boolean {
  if (!canEnter(s, u, x, y)) return false;
  // Even a flyer has to come down somewhere solid.
  if (isBlocking(s, x, y)) return false;
  const t = tileAt(s, x, y);
  if (!t) return false;
  if (t.kind === 'rough' && hasTrait(u, 'no_rough_end')) return false;
  return true;
}

/**
 * Every tile this unit could legally finish on, spending `ap` action points.
 * BFS over orthogonal steps only; budget is `ap × MOV` tiles. Keyed "x,y",
 * excludes the starting tile.
 */
export function reachableTiles(s: BattleState, u: BattleUnit, ap: number): Map<string, ReachNode> {
  const out = new Map<string, ReachNode>();
  const budget = Math.max(0, Math.floor(ap)) * UNITS[u.type].mov;
  if (budget <= 0) return out;

  const seen = new Set<string>([tileKey(u.x, u.y)]);
  let frontier: ReachNode[] = [{ x: u.x, y: u.y, cost: 0, path: [] }];

  while (frontier.length > 0) {
    const next: ReachNode[] = [];
    for (const node of frontier) {
      if (node.cost >= budget) continue;
      for (const [dx, dy] of ORTHOGONAL) {
        const nx = node.x + dx;
        const ny = node.y + dy;
        const key = tileKey(nx, ny);
        if (seen.has(key)) continue;
        if (!canEnter(s, u, nx, ny)) continue;
        seen.add(key);
        const step: ReachNode = {
          x: nx,
          y: ny,
          cost: node.cost + 1,
          path: [...node.path, { x: nx, y: ny }],
        };
        if (canEndOn(s, u, nx, ny)) out.set(key, step);
        next.push(step);
      }
    }
    frontier = next;
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Combat maths — deterministic (GDD §7.2)
// ─────────────────────────────────────────────────────────────────────────────

export function defenseOf(s: BattleState, u: BattleUnit): number {
  let d = u.braced ? BATTLE.braceDefense : 0;
  const t = tileAt(s, u.x, u.y);
  if (t && t.kind === 'cover' && hasTrait(u, 'cover_bonus')) d += BATTLE.coverDefense;
  return d;
}

export function computeDamage(
  s: BattleState,
  attacker: BattleUnit,
  target: BattleUnit,
): { damage: number; mitigated: number } {
  const raw = UNITS[attacker.type].atk;
  const defense = defenseOf(s, target);
  const damage = Math.max(BATTLE.minDamage, raw - defense);
  return { damage, mitigated: raw - damage };
}

/** Can `attacker` legally shoot `target` right now (range + LOS + hostility)? */
export function canAttack(s: BattleState, attacker: BattleUnit, target: BattleUnit): boolean {
  if (!attacker.alive || !target.alive) return false;
  if (attacker.side === target.side) return false;
  if (battleDistance(attacker.x, attacker.y, target.x, target.y) > effectiveRange(s, attacker)) {
    return false;
  }
  return hasLineOfSight(s, attacker.x, attacker.y, target.x, target.y);
}

// ─────────────────────────────────────────────────────────────────────────────
// Deployment
// ─────────────────────────────────────────────────────────────────────────────

/** The rows this side deploys on (top or bottom, per `s.bottomSide`). */
export function deployRowsFor(s: BattleState, side: BattleSide): number[] {
  const rows: number[] = [];
  for (let i = 0; i < BATTLE.deployRows; i++) {
    rows.push(side === s.bottomSide ? s.h - 1 - i : i);
  }
  return rows.sort((a, b) => a - b);
}

export function deployZone(s: BattleState, side: BattleSide): { x: number; y: number }[] {
  const out: { x: number; y: number }[] = [];
  for (const y of deployRowsFor(s, side)) {
    for (let x = 0; x < s.w; x++) {
      if (!isBlocking(s, x, y)) out.push({ x, y });
    }
  }
  return out;
}

/** True when (x, y) sits outside both deployment bands. */
export function isNeutralGround(s: BattleState, y: number): boolean {
  return y >= BATTLE.deployRows && y < s.h - BATTLE.deployRows;
}

// ─────────────────────────────────────────────────────────────────────────────
// Mutating tile effects
// ─────────────────────────────────────────────────────────────────────────────

function pairedPad(s: BattleState, from: Tile): Tile | null {
  if (from.pairId === undefined) return null;
  for (let y = 0; y < s.h; y++) {
    for (let x = 0; x < s.w; x++) {
      const t = s.grid[y][x];
      if (t.kind === 'teleport' && t.pairId === from.pairId && !(t.x === from.x && t.y === from.y)) {
        return t;
      }
    }
  }
  return null;
}

/**
 * Resolve the tile the unit just finished on: teleport pads relocate it to
 * their partner, unstable crust counts the crossing and gives way.
 */
export function applyTileEntry(
  s: BattleState,
  u: BattleUnit,
  x: number,
  y: number,
  now: number,
): void {
  const t = tileAt(s, x, y);
  if (!t || !u.alive) return;

  if (t.kind === 'teleport') {
    const dest = pairedPad(s, t);
    if (dest && !unitAt(s, dest.x, dest.y)) {
      const from = { x, y };
      u.x = dest.x;
      u.y = dest.y;
      s.log.push({ t: 'teleport', at: now, unitId: u.id, from, to: { x: dest.x, y: dest.y } });
    }
    return;
  }

  if (t.kind === 'unstable' && t.collapsed !== true) {
    t.crossings = (t.crossings ?? 0) + 1;
    if (t.crossings >= BATTLE.unstableCrossings) {
      // The crust gives way under the chassis that triggered it. That unit is
      // left standing in the hole — free to walk out, never able to walk back.
      t.collapsed = true;
      s.log.push({ t: 'collapse', at: now, x, y });
    }
  }
}

/** Hazard tiles bite anything of `side` still standing on them at turn end. */
export function applyEndOfTurnHazards(s: BattleState, side: BattleSide, now: number): void {
  for (const u of livingUnits(s, side)) {
    const t = tileAt(s, u.x, u.y);
    if (!t || t.kind !== 'hazard') continue;
    u.hp -= BATTLE.hazardDamage;
    const killed = u.hp <= 0;
    if (killed) {
      u.hp = 0;
      u.alive = false;
    }
    s.log.push({ t: 'hazard', at: now, unitId: u.id, damage: BATTLE.hazardDamage, killed });
  }
}
