/**
 * Pointy-top axial hex math. Pure — no rendering, no state.
 * Reference: redblobgames hexagon guide (axial/cube conversions).
 */
import type { Axial, HexId } from './types';

export const AXIAL_DIRECTIONS: readonly Axial[] = [
  { q: 1, r: 0 },
  { q: 1, r: -1 },
  { q: 0, r: -1 },
  { q: -1, r: 0 },
  { q: -1, r: 1 },
  { q: 0, r: 1 },
] as const;

export const hexId = (q: number, r: number): HexId => `${q},${r}`;
export const idOf = (a: Axial): HexId => hexId(a.q, a.r);

export function parseHexId(id: HexId): Axial {
  const i = id.indexOf(',');
  return { q: Number(id.slice(0, i)), r: Number(id.slice(i + 1)) };
}

export const axialEq = (a: Axial, b: Axial): boolean => a.q === b.q && a.r === b.r;

export function neighbors(a: Axial): Axial[] {
  return AXIAL_DIRECTIONS.map((d) => ({ q: a.q + d.q, r: a.r + d.r }));
}

export function neighborIds(id: HexId): HexId[] {
  const a = parseHexId(id);
  return AXIAL_DIRECTIONS.map((d) => hexId(a.q + d.q, a.r + d.r));
}

/** Cube distance between two axial coords. */
export function hexDistance(a: Axial, b: Axial): number {
  const dq = a.q - b.q;
  const dr = a.r - b.r;
  const ds = -dq - dr;
  return (Math.abs(dq) + Math.abs(dr) + Math.abs(ds)) / 2;
}

export function hexDistanceId(a: HexId, b: HexId): number {
  return hexDistance(parseHexId(a), parseHexId(b));
}

/** All hexes within `radius` of centre, inclusive. */
export function hexesInRange(center: Axial, radius: number): Axial[] {
  const out: Axial[] = [];
  for (let dq = -radius; dq <= radius; dq++) {
    const lo = Math.max(-radius, -dq - radius);
    const hi = Math.min(radius, -dq + radius);
    for (let dr = lo; dr <= hi; dr++) {
      out.push({ q: center.q + dq, r: center.r + dr });
    }
  }
  return out;
}

/** Ring of exactly `radius` distance from centre. */
export function hexRing(center: Axial, radius: number): Axial[] {
  if (radius <= 0) return [{ ...center }];
  const out: Axial[] = [];
  let cur: Axial = {
    q: center.q + AXIAL_DIRECTIONS[4].q * radius,
    r: center.r + AXIAL_DIRECTIONS[4].r * radius,
  };
  for (let side = 0; side < 6; side++) {
    for (let step = 0; step < radius; step++) {
      out.push({ ...cur });
      cur = { q: cur.q + AXIAL_DIRECTIONS[side].q, r: cur.r + AXIAL_DIRECTIONS[side].r };
    }
  }
  return out;
}

// ── Cube helpers for line drawing ───────────────────────────────────────────

interface Cube {
  x: number;
  y: number;
  z: number;
}

const toCube = (a: Axial): Cube => ({ x: a.q, z: a.r, y: -a.q - a.r });
const toAxial = (c: Cube): Axial => ({ q: c.x, r: c.z });

function cubeRound(c: Cube): Cube {
  let rx = Math.round(c.x);
  let ry = Math.round(c.y);
  let rz = Math.round(c.z);
  const dx = Math.abs(rx - c.x);
  const dy = Math.abs(ry - c.y);
  const dz = Math.abs(rz - c.z);
  if (dx > dy && dx > dz) rx = -ry - rz;
  else if (dy > dz) ry = -rx - rz;
  else rz = -rx - ry;
  return { x: rx, y: ry, z: rz };
}

const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/** Straight line of hexes from a to b, inclusive of both ends. */
export function hexLine(a: Axial, b: Axial): Axial[] {
  const n = hexDistance(a, b);
  if (n === 0) return [{ ...a }];
  const ca = toCube(a);
  const cb = toCube(b);
  const out: Axial[] = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    out.push(
      toAxial(
        cubeRound({
          x: lerp(ca.x, cb.x, t),
          y: lerp(ca.y, cb.y, t),
          z: lerp(ca.z, cb.z, t),
        }),
      ),
    );
  }
  return out;
}

// ── World-space projection (used by the render layer only) ──────────────────

const SQRT3 = Math.sqrt(3);

/** Axial → world XZ for a pointy-top layout. */
export function axialToWorld(a: Axial, radius: number): { x: number; z: number } {
  return {
    x: radius * (SQRT3 * a.q + (SQRT3 / 2) * a.r),
    z: radius * (1.5 * a.r),
  };
}

/** World XZ → nearest axial. */
export function worldToAxial(x: number, z: number, radius: number): Axial {
  const q = ((SQRT3 / 3) * x - (1 / 3) * z) / radius;
  const r = ((2 / 3) * z) / radius;
  const c = cubeRound({ x: q, z: r, y: -q - r });
  return toAxial(c);
}

/**
 * A* over a hex graph.
 * @param passable  can the path enter this hex at all?
 * @param cost      relative cost of entering this hex (>= 1)
 * @returns list of hex ids from start (exclusive) to goal (inclusive), or null.
 */
export function findPath(
  start: HexId,
  goal: HexId,
  passable: (id: HexId) => boolean,
  cost: (id: HexId) => number,
  maxNodes = 20000,
): HexId[] | null {
  if (start === goal) return [];
  const goalAx = parseHexId(goal);

  const open = new Map<HexId, number>([[start, 0]]);
  const gScore = new Map<HexId, number>([[start, 0]]);
  const came = new Map<HexId, HexId>();
  const closed = new Set<HexId>();
  let visited = 0;

  while (open.size > 0) {
    // pop lowest f
    let cur: HexId = '';
    let best = Infinity;
    for (const [id, f] of open) {
      if (f < best) {
        best = f;
        cur = id;
      }
    }
    open.delete(cur);
    if (cur === goal) {
      const path: HexId[] = [];
      let node: HexId | undefined = goal;
      while (node !== undefined && node !== start) {
        path.push(node);
        node = came.get(node);
      }
      return path.reverse();
    }
    closed.add(cur);
    if (++visited > maxNodes) return null;

    for (const nb of neighborIds(cur)) {
      if (closed.has(nb)) continue;
      // The goal itself is allowed to be "impassable" (it may hold an enemy).
      if (nb !== goal && !passable(nb)) continue;
      const tentative = (gScore.get(cur) ?? Infinity) + cost(nb);
      if (tentative < (gScore.get(nb) ?? Infinity)) {
        came.set(nb, cur);
        gScore.set(nb, tentative);
        open.set(nb, tentative + hexDistance(parseHexId(nb), goalAx));
      }
    }
  }
  return null;
}
