/**
 * GDD §10 — Diplomacy.
 *
 * Parleys (private cross-guild threads), structured resource trades, a peace
 * flag, and free-text treaties written turn-by-turn and signed by both sides.
 *
 * ┌───────────────────────────────────────────────────────────────────────────┐
 * │ ENFORCEMENT IS SOCIAL, NOT MECHANICAL — FINAL DESIGN (GDD §10 and §14).   │
 * │                                                                           │
 * │ Nothing in this file restricts a single game action. A signed treaty is a │
 * │ timestamped, archived DOCUMENT: it makes betrayal *provable*, never       │
 * │ impossible. The peace flag is likewise informational — it must never gate │
 * │ movement, capture, battle or any other verb. Do not add enforcement here  │
 * │ or anywhere else; that is a permanent design decision, not a v1 shortcut. │
 * └───────────────────────────────────────────────────────────────────────────┘
 *
 * PURE: no DOM, no Three.js.
 */
import { can, guildOf } from '../guild/permissions';
import { guildChannel, parleyChannel, systemMessage } from '../guild/social';
import { createTransfer, planTransfer } from '../guild/transfers';
import { uid } from '../rng';
import type {
  Cost,
  GameState,
  GuildId,
  Parley,
  ParleyId,
  PlayerId,
  Result,
  Signature,
  TradeOffer,
  Transfer,
  Treaty,
  TreatyId,
  TreatyRevision,
} from '../types';
import { err, ok } from '../types';

// ─────────────────────────────────────────────────────────────────────────────
// Parleys
// ─────────────────────────────────────────────────────────────────────────────

/** The other signatory of a parley. */
export function otherGuild(parley: Parley, guildId: GuildId): GuildId {
  return parley.guilds[0] === guildId ? parley.guilds[1] : parley.guilds[0];
}

export function parleyBetween(
  state: GameState,
  a: GuildId,
  b: GuildId,
): Parley | undefined {
  return Object.values(state.parleys).find(
    (p) => p.guilds.includes(a) && p.guilds.includes(b),
  );
}

/** Every parley a guild is party to, most recently active first. */
export function parleysFor(state: GameState, guildId: GuildId): Parley[] {
  return Object.values(state.parleys)
    .filter((p) => p.guilds.includes(guildId))
    .sort((a, b) => b.lastActivity - a.lastActivity);
}

/**
 * Open (or re-open) a parley with a rival guild.
 * Requires diplomacy permission — Leaders and designated Officers only.
 * An existing thread is returned rather than duplicated.
 */
export function openParley(
  state: GameState,
  byPlayerId: PlayerId,
  withGuildId: GuildId,
  now: number,
): Result<ParleyId> {
  if (!can(state, byPlayerId, 'diplomacy')) return err('diplomats only');

  const mine = guildOf(state, byPlayerId);
  if (!mine) return err('you are not in a guild');
  if (mine.id === withGuildId) return err('you cannot parley with yourself');

  const them = state.guilds[withGuildId];
  if (!them) return err('unknown guild');

  const existing = parleyBetween(state, mine.id, withGuildId);
  if (existing) {
    existing.lastActivity = now;
    return ok(existing.id);
  }

  const parley: Parley = {
    id: uid('par'),
    guilds: [mine.id, withGuildId],
    createdAt: now,
    peace: false,
    lastActivity: now,
  };
  state.parleys[parley.id] = parley;

  systemMessage(
    state,
    parleyChannel(parley.id),
    `CHANNEL OPEN — ${mine.tag} ⇄ ${them.tag}`,
    'system',
    now,
  );
  return ok(parley.id);
}

/** Diplomat of one of the two guilds in this parley? */
export function isParleyDiplomat(
  state: GameState,
  playerId: PlayerId,
  parleyId: ParleyId,
): boolean {
  const parley = state.parleys[parleyId];
  const guild = guildOf(state, playerId);
  if (!parley || !guild) return false;
  return parley.guilds.includes(guild.id) && can(state, playerId, 'diplomacy');
}

function requireSeat(
  state: GameState,
  playerId: PlayerId,
  parleyId: ParleyId,
): Result<{ parley: Parley; guildId: GuildId }> {
  const parley = state.parleys[parleyId];
  if (!parley) return err('unknown parley');
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');
  if (!parley.guilds.includes(guild.id)) return err('you are not party to this parley');
  if (!can(state, playerId, 'diplomacy')) return err('diplomats only');
  return ok({ parley, guildId: guild.id });
}

// ─────────────────────────────────────────────────────────────────────────────
// Trades
// ─────────────────────────────────────────────────────────────────────────────

const costIsValid = (c: Cost): boolean =>
  Number.isFinite(c.m) && Number.isFinite(c.g) && c.m >= 0 && c.g >= 0;

/** Open trade offers on a thread, newest first. */
export function tradesFor(state: GameState, parleyId: ParleyId): TradeOffer[] {
  return state.trades.filter((t) => t.parleyId === parleyId).sort((a, b) => b.at - a.at);
}

/**
 * Put a structured offer on the table: `offer` is what the proposing guild
 * gives, `request` is what it wants back. The proposing diplomat must actually
 * hold what they are offering — no phantom deals.
 */
export function proposeTrade(
  state: GameState,
  parleyId: ParleyId,
  byPlayerId: PlayerId,
  offer: Cost,
  request: Cost,
  now: number,
): Result<TradeOffer> {
  const seat = requireSeat(state, byPlayerId, parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  if (!costIsValid(offer) || !costIsValid(request)) return err('invalid trade terms');
  if (offer.m + offer.g <= 0 && request.m + request.g <= 0) return err('empty trade');

  const proposer = state.players[byPlayerId];
  if (!proposer) return err('unknown commander');
  if (proposer.minerals < offer.m) return err('not enough minerals to cover the offer');
  if (proposer.gas < offer.g) return err('not enough gas to cover the offer');

  const trade: TradeOffer = {
    id: uid('trd'),
    parleyId,
    fromGuild: guildId,
    toGuild: otherGuild(parley, guildId),
    byId: byPlayerId,
    byName: proposer.name,
    offer: { m: offer.m, g: offer.g },
    request: { m: request.m, g: request.g },
    status: 'open',
    at: now,
  };
  state.trades.push(trade);
  parley.lastActivity = now;

  systemMessage(
    state,
    parleyChannel(parleyId),
    `OFFER — ${proposer.name}: ${offer.m}M ${offer.g}G ⇄ ${request.m}M ${request.g}G`,
    'trade',
    now,
  );
  return ok(trade);
}

/**
 * Accept or decline an offer.
 *
 * On acceptance the resources are NOT teleported: two real shipments are
 * created between the two signing diplomats using the GDD §9.3 transfer-time
 * rules, so a cross-guild deal takes exactly as long to land as an internal
 * one. Both legs are validated before either is committed.
 */
export function respondTrade(
  state: GameState,
  tradeId: string,
  byPlayerId: PlayerId,
  accept: boolean,
  now: number,
): Result<void> {
  const trade = state.trades.find((t) => t.id === tradeId);
  if (!trade) return err('unknown offer');
  if (trade.status !== 'open') return err('offer already resolved');

  const seat = requireSeat(state, byPlayerId, trade.parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  // The proposing guild may only withdraw; the receiving guild answers.
  if (guildId === trade.fromGuild) {
    if (accept) return err('you cannot accept your own offer');
    trade.status = 'cancelled';
    trade.resolvedAt = now;
    parley.lastActivity = now;
    systemMessage(state, parleyChannel(trade.parleyId), 'OFFER WITHDRAWN', 'trade', now);
    return ok(undefined);
  }
  if (guildId !== trade.toGuild) return err('this offer is not addressed to you');

  if (!accept) {
    trade.status = 'declined';
    trade.resolvedAt = now;
    parley.lastActivity = now;
    systemMessage(state, parleyChannel(trade.parleyId), 'OFFER DECLINED', 'trade', now);
    return ok(undefined);
  }

  const givePayload = { minerals: trade.offer.m, gas: trade.offer.g, units: {} };
  const takePayload = { minerals: trade.request.m, gas: trade.request.g, units: {} };
  const opts = { crossGuild: true };

  // Pre-flight both legs so acceptance is all-or-nothing.
  if (givePayload.minerals + givePayload.gas > 0) {
    const leg = planTransfer(state, trade.byId, byPlayerId, givePayload, opts);
    if (!leg.ok) return err(`their side cannot ship: ${leg.error}`);
  }
  if (takePayload.minerals + takePayload.gas > 0) {
    const leg = planTransfer(state, byPlayerId, trade.byId, takePayload, opts);
    if (!leg.ok) return err(`your side cannot ship: ${leg.error}`);
  }

  const shipped: Transfer[] = [];
  if (givePayload.minerals + givePayload.gas > 0) {
    const leg = createTransfer(state, trade.byId, byPlayerId, givePayload, now, opts);
    if (!leg.ok) return err(leg.error);
    shipped.push(leg.value);
  }
  if (takePayload.minerals + takePayload.gas > 0) {
    const leg = createTransfer(state, byPlayerId, trade.byId, takePayload, now, opts);
    if (!leg.ok) return err(leg.error);
    shipped.push(leg.value);
  }

  trade.status = 'accepted';
  trade.resolvedAt = now;
  parley.lastActivity = now;

  const eta = shipped.reduce((max, t) => Math.max(max, t.arrivesAt), now);
  const responder = state.players[byPlayerId];
  systemMessage(
    state,
    parleyChannel(trade.parleyId),
    `OFFER ACCEPTED by ${responder?.name ?? 'UNKNOWN'} — ${shipped.length} shipment(s) in transit`,
    'trade',
    now,
  );
  for (const gid of parley.guilds) {
    systemMessage(
      state,
      guildChannel(gid),
      `TRADE EXECUTED — convoys land in ${Math.round((eta - now) / 60000)} min`,
      'trade',
      now,
    );
  }
  return ok(undefined);
}

// ─────────────────────────────────────────────────────────────────────────────
// Peace flag (INFORMATIONAL ONLY)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Declare or end peace.
 *
 * The Parley carries a single shared flag, so peace is mutual by construction:
 * either diplomat may raise or lower it and both guilds are told. It is a
 * DECLARATION, not a rule — nothing in the game consults it before allowing a
 * move, a capture or a battle (GDD §10, §14: enforcement is social only).
 */
export function setPeace(
  state: GameState,
  parleyId: ParleyId,
  byPlayerId: PlayerId,
  peace: boolean,
  now: number,
): Result<Parley> {
  const seat = requireSeat(state, byPlayerId, parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  if (parley.peace === peace) return err(peace ? 'already at peace' : 'already not at peace');

  parley.peace = peace;
  parley.peaceSince = peace ? now : undefined;
  parley.lastActivity = now;

  const mine = state.guilds[guildId];
  const theirs = state.guilds[otherGuild(parley, guildId)];
  const line = peace
    ? `PEACE DECLARED — ${mine?.tag ?? '???'} ⇄ ${theirs?.tag ?? '???'}. Non-binding: honour it or do not.`
    : `PEACE ENDED — ${mine?.tag ?? '???'} ⇄ ${theirs?.tag ?? '???'}.`;

  systemMessage(state, parleyChannel(parleyId), line, 'system', now);
  for (const gid of parley.guilds) systemMessage(state, guildChannel(gid), line, 'alert', now);
  return ok(parley);
}

// ─────────────────────────────────────────────────────────────────────────────
// Treaties — turn-based free-text documents
// ─────────────────────────────────────────────────────────────────────────────

export function treatiesFor(state: GameState, parleyId: ParleyId): Treaty[] {
  return Object.values(state.treaties)
    .filter((t) => t.parleyId === parleyId)
    .sort((a, b) => b.createdAt - a.createdAt);
}

/** Open a blank document. The author's guild holds the pen first. */
export function createTreaty(
  state: GameState,
  parleyId: ParleyId,
  byPlayerId: PlayerId,
  title: string,
  now: number,
): Result<TreatyId> {
  const seat = requireSeat(state, byPlayerId, parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  const name = title.trim();
  if (!name) return err('a treaty needs a title');

  const treaty: Treaty = {
    id: uid('tty'),
    parleyId,
    guilds: [parley.guilds[0], parley.guilds[1]],
    title: name,
    text: '',
    status: 'drafting',
    editingGuild: guildId,
    signatures: [],
    createdAt: now,
    revisions: [],
  };
  state.treaties[treaty.id] = treaty;
  parley.lastActivity = now;

  systemMessage(state, parleyChannel(parleyId), `DOCUMENT OPENED — "${name}"`, 'treaty', now);
  return ok(treaty.id);
}

/** Does this player currently hold the pen on this document? */
export function holdsThePen(state: GameState, playerId: PlayerId, treatyId: TreatyId): boolean {
  const treaty = state.treaties[treatyId];
  const guild = guildOf(state, playerId);
  if (!treaty || !guild) return false;
  return (
    treaty.status === 'drafting' &&
    treaty.editingGuild === guild.id &&
    can(state, playerId, 'diplomacy')
  );
}

/**
 * Write a revision and PASS THE PEN to the other guild (GDD §10: "one side
 * edits, submits, other side edits or signs").
 *
 * Any prior signature is voided by a new revision — a signature attests to the
 * exact text that was on the table when it was given.
 */
export function submitTreatyRevision(
  state: GameState,
  treatyId: TreatyId,
  byPlayerId: PlayerId,
  text: string,
  now: number,
): Result<Treaty> {
  const treaty = state.treaties[treatyId];
  if (!treaty) return err('unknown treaty');
  if (treaty.status === 'signed') return err('this document is signed and frozen');

  const seat = requireSeat(state, byPlayerId, treaty.parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  if (treaty.editingGuild !== guildId) return err('the other side holds the pen');

  const player = state.players[byPlayerId];
  if (!player) return err('unknown commander');

  const revision: TreatyRevision = { at: now, byGuild: guildId, byName: player.name, text };
  treaty.revisions.push(revision);
  treaty.text = text;
  treaty.signatures = [];
  treaty.editingGuild = otherGuild(parley, guildId);
  parley.lastActivity = now;

  systemMessage(
    state,
    parleyChannel(treaty.parleyId),
    `REVISION ${treaty.revisions.length} FILED by ${player.name} — pen passed to ${
      state.guilds[treaty.editingGuild]?.tag ?? '???'
    }`,
    'treaty',
    now,
  );
  return ok(treaty);
}

/**
 * Sign. One signature per guild; either side may sign whenever it is happy with
 * the text on the table. When BOTH guilds have signed the document freezes,
 * takes a timestamp, and drops into both Diplomacy Archives.
 *
 * Freezing is a document-integrity rule, not an enforcement mechanic: the
 * signed text can no longer be edited, but it still restricts nothing.
 */
export function signTreaty(
  state: GameState,
  treatyId: TreatyId,
  byPlayerId: PlayerId,
  now: number,
): Result<Treaty> {
  const treaty = state.treaties[treatyId];
  if (!treaty) return err('unknown treaty');
  if (treaty.status === 'signed') return err('already signed');

  const seat = requireSeat(state, byPlayerId, treaty.parleyId);
  if (!seat.ok) return err(seat.error);
  const { parley, guildId } = seat.value;

  if (!treaty.text.trim()) return err('there is nothing written to sign');
  if (treaty.signatures.some((s) => s.guildId === guildId)) {
    return err('your guild has already signed');
  }

  const player = state.players[byPlayerId];
  if (!player) return err('unknown commander');

  const signature: Signature = {
    guildId,
    playerId: byPlayerId,
    playerName: player.name,
    at: now,
  };
  treaty.signatures.push(signature);
  parley.lastActivity = now;

  const bothSigned =
    treaty.guilds.every((gid) => treaty.signatures.some((s) => s.guildId === gid));

  if (!bothSigned) {
    systemMessage(
      state,
      parleyChannel(treaty.parleyId),
      `SIGNED by ${player.name} (${state.guilds[guildId]?.tag ?? '???'}) — awaiting counter-signature`,
      'treaty',
      now,
    );
    return ok(treaty);
  }

  treaty.status = 'signed';
  treaty.signedAt = now;
  // The pen is spent; keep the field pointing at the last editor for the record.

  systemMessage(
    state,
    parleyChannel(treaty.parleyId),
    `TREATY EXECUTED — "${treaty.title}" archived with both signatures`,
    'treaty',
    now,
  );
  for (const gid of treaty.guilds) {
    systemMessage(
      state,
      guildChannel(gid),
      `TREATY ARCHIVED — "${treaty.title}". Binding in reputation only; the map remains open.`,
      'treaty',
      now,
    );
  }
  return ok(treaty);
}

/**
 * The Diplomacy Archive: every signed treaty a guild is party to, newest first.
 * Readable by ALL members of each guild (GDD §10) — no diplomacy rank needed.
 */
export function archiveFor(state: GameState, guildId: GuildId): Treaty[] {
  return Object.values(state.treaties)
    .filter((t) => t.status === 'signed' && t.guilds.includes(guildId))
    .sort((a, b) => (b.signedAt ?? b.createdAt) - (a.signedAt ?? a.createdAt));
}

/**
 * Read access. Signed treaties are public inside both guilds; drafts stay with
 * the diplomats until they are executed.
 */
export function canReadTreaty(
  state: GameState,
  playerId: PlayerId,
  treatyId: TreatyId,
): boolean {
  const treaty = state.treaties[treatyId];
  const guild = guildOf(state, playerId);
  if (!treaty || !guild) return false;
  if (!treaty.guilds.includes(guild.id)) return false;
  if (treaty.status === 'signed') return true;
  return can(state, playerId, 'diplomacy');
}

/**
 * Informational only. Provided so the UI can label a rival "AT PEACE" on the
 * overview — it is deliberately NOT consulted by movement, capture or battle
 * code, and no caller may use it to block an action (GDD §10, §14).
 */
export function atPeaceWith(state: GameState, a: GuildId, b: GuildId): boolean {
  if (a === b) return true;
  return parleyBetween(state, a, b)?.peace === true;
}
