/**
 * Firebase wiring. The game runs fully on the mock backend when no project id
 * is configured, so the build is playable offline out of the box (GDD §2/§13:
 * IBackend is the single seam; Firebase is a swap, not a rewrite).
 *
 * To go live, create `.env.local` with:
 *   VITE_FIREBASE_API_KEY=...
 *   VITE_FIREBASE_AUTH_DOMAIN=...
 *   VITE_FIREBASE_PROJECT_ID=...
 *   VITE_FIREBASE_STORAGE_BUCKET=...
 *   VITE_FIREBASE_MESSAGING_SENDER_ID=...
 *   VITE_FIREBASE_APP_ID=...
 *   VITE_FIREBASE_DATABASE_URL=...
 */

const env = import.meta.env as Record<string, string | undefined>;

export const FIREBASE_CONFIG = {
  apiKey: env.VITE_FIREBASE_API_KEY ?? '',
  authDomain: env.VITE_FIREBASE_AUTH_DOMAIN ?? '',
  projectId: env.VITE_FIREBASE_PROJECT_ID ?? '',
  storageBucket: env.VITE_FIREBASE_STORAGE_BUCKET ?? '',
  messagingSenderId: env.VITE_FIREBASE_MESSAGING_SENDER_ID ?? '',
  appId: env.VITE_FIREBASE_APP_ID ?? '',
  databaseURL: env.VITE_FIREBASE_DATABASE_URL ?? '',
};

/** True when a real Firebase project is configured. */
export const FIREBASE_ENABLED: boolean =
  FIREBASE_CONFIG.projectId.length > 0 && FIREBASE_CONFIG.apiKey.length > 0;

