/**
 * Readouts: segmented meters, animated resource pills, and the split power bar
 * required by GDD §9.2 (unit power and territory power stay separately legible).
 */
import { ECONOMY } from '../../config/balance';
import { el, fmtNum, svg as svgEl } from '../dom';

// ─────────────────────────────────────────────────────────────────────────────
// Meter
// ─────────────────────────────────────────────────────────────────────────────

export interface MeterOpts {
  /** Any CSS colour. Defaults to `var(--cyan)`. */
  color?: string;
  /** Draw N segment dividers across the track. */
  segments?: number;
  label?: string;
  /** Track height in px. Defaults to 8. */
  height?: number;
  /** Show `value / max` on the right of the label row. */
  readout?: boolean;
  /** Turn amber below 40% and crimson below 15% (HP bars). */
  autoTint?: boolean;
}

export interface MeterController {
  el: HTMLElement;
  set(v: number, max?: number): void;
}

export function meter(value: number, max: number, opts: MeterOpts = {}): MeterController {
  const height = opts.height ?? 8;
  const root = el('div', {
    class: 'meter',
    style: `--meter-h:${height}px${opts.color ? `;--meter-color:${opts.color}` : ''}`,
  });

  let readNode: HTMLElement | null = null;
  if (opts.label !== undefined || opts.readout) {
    const head = el('div', { class: 'meter__head' });
    head.appendChild(el('span', { class: 'meter__label', text: opts.label ?? '' }));
    readNode = el('span', { class: 'meter__read' });
    head.appendChild(readNode);
    root.appendChild(head);
  }

  const fill = el('div', { class: 'meter__fill' });
  const track = el('div', { class: 'meter__track' }, fill);
  if (opts.segments && opts.segments > 1) {
    track.appendChild(
      el('div', {
        class: 'meter__segs',
        style: `--seg-w:${(100 / opts.segments).toFixed(4)}%`,
        aria: { hidden: 'true' },
      }),
    );
  }
  root.appendChild(track);

  let curMax = Math.max(1, max);

  const render = (v: number, m: number): void => {
    curMax = Math.max(1, m);
    const clamped = Math.max(0, Math.min(curMax, v));
    const ratio = clamped / curMax;
    fill.style.width = `${(ratio * 100).toFixed(2)}%`;
    if (readNode) readNode.textContent = `${fmtNum(clamped)} / ${fmtNum(curMax)}`;
    if (opts.autoTint) {
      root.classList.toggle('meter--danger', ratio <= 0.15);
      root.classList.toggle('meter--warn', ratio > 0.15 && ratio <= 0.4);
      root.classList.toggle('meter--ok', ratio > 0.4);
    }
    root.setAttribute('role', 'meter');
    root.setAttribute('aria-valuenow', String(Math.round(clamped)));
    root.setAttribute('aria-valuemax', String(Math.round(curMax)));
  };

  render(value, curMax);

  return {
    el: root,
    set(v: number, m?: number): void {
      render(v, m ?? curMax);
    },
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Resource pill
// ─────────────────────────────────────────────────────────────────────────────

export type ResourceKind = 'm' | 'g';

export interface ResourcePillOpts {
  /** Stockpile cap. Defaults to the configured cap for the resource. */
  cap?: number;
  /** Per-hour delta shown as `+n/h`. */
  delta?: number;
  /** Compact 26px variant for the status bar. */
  small?: boolean;
  /** Hide the `/cap` suffix. */
  hideCap?: boolean;
}

export interface ResourcePillController {
  el: HTMLElement;
  set(v: number): void;
  setDelta(perHour: number): void;
}

const RES_ICON: Record<ResourceKind, string> = {
  // Mineral: cut crystal shard.
  m: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round">
        <path d="M12 2.4l6.4 5.1-2.4 12.1H8L5.6 7.5z"/>
        <path d="M5.6 7.5h12.8M12 2.4l-4 17.2M12 2.4l4 17.2" opacity=".55"/>
      </svg>`,
  // Gas: pressurised vent canister.
  g: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">
        <path d="M8.2 9.5h7.6v9.2a2 2 0 01-2 2h-3.6a2 2 0 01-2-2z"/>
        <path d="M10 9.5V6.4a2 2 0 114 0v3.1"/>
        <path d="M12 12.6v4.6M10.2 14.4h3.6" opacity=".7"/>
      </svg>`,
};

const RES_CAP: Record<ResourceKind, number> = {
  m: ECONOMY.capMinerals,
  g: ECONOMY.capGas,
};

const RES_NAME: Record<ResourceKind, string> = { m: 'minerals', g: 'gas' };

/** Tweens `from → to` over `ms`, calling `onFrame` each rAF. */
function tween(from: number, to: number, ms: number, onFrame: (v: number) => void): () => void {
  const start = performance.now();
  let raf = 0;
  const step = (t: number): void => {
    const p = Math.min(1, (t - start) / ms);
    // easeOutCubic
    const e = 1 - Math.pow(1 - p, 3);
    onFrame(from + (to - from) * e);
    if (p < 1) raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
  return () => cancelAnimationFrame(raf);
}

export function resourcePill(
  kind: ResourceKind,
  value: number,
  opts: ResourcePillOpts = {},
): ResourcePillController {
  const cap = opts.cap ?? RES_CAP[kind];
  const root = el('div', {
    class: `pill pill--${kind}${opts.small ? ' pill--sm' : ''}`,
    aria: { label: RES_NAME[kind] },
  });

  const icon = el('span', { class: 'pill__icon', aria: { hidden: 'true' } });
  icon.appendChild(svgEl(RES_ICON[kind]));
  root.appendChild(icon);

  const val = el('span', { class: 'pill__val' });
  root.appendChild(val);

  let capNode: HTMLElement | null = null;
  if (!opts.hideCap && cap > 0) {
    capNode = el('span', { class: 'pill__cap', text: `/${fmtNum(cap)}` });
    root.appendChild(capNode);
  }

  let deltaNode: HTMLElement | null = null;
  const setDelta = (perHour: number): void => {
    if (!deltaNode) {
      deltaNode = el('span', { class: 'pill__delta' });
      root.appendChild(deltaNode);
    }
    const sign = perHour >= 0 ? '+' : '−';
    deltaNode.textContent = `${sign}${fmtNum(Math.abs(perHour))}/h`;
    deltaNode.classList.toggle('is-neg', perHour < 0);
  };

  let shown = value;
  let cancel: (() => void) | null = null;
  let bumpHandle = 0;

  const paint = (v: number): void => {
    val.textContent = fmtNum(v);
  };

  const applyCapState = (v: number): void => {
    if (cap <= 0) return;
    const ratio = v / cap;
    root.classList.toggle('is-capped', ratio >= 0.999);
    root.classList.toggle('is-near-cap', ratio >= 0.9 && ratio < 0.999);
  };

  paint(shown);
  applyCapState(shown);
  if (opts.delta !== undefined) setDelta(opts.delta);

  return {
    el: root,
    set(v: number): void {
      if (Math.round(v) === Math.round(shown)) {
        applyCapState(v);
        shown = v;
        return;
      }
      cancel?.();
      const from = shown;
      shown = v;
      applyCapState(v);
      root.classList.remove('is-bump');
      void root.offsetWidth;
      root.classList.add('is-bump');
      window.clearTimeout(bumpHandle);
      bumpHandle = window.setTimeout(() => root.classList.remove('is-bump'), 460);
      cancel = tween(from, v, 620, paint);
    },
    setDelta,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Power bar (GDD §9.2)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Two-segment bar showing where a commander's strength comes from:
 * cyan = power from the units they command, gold = power from the ground they
 * hold. Both magnitudes are labelled, never merged into a single number only.
 */
export function powerBar(unitPower: number, territoryPower: number): HTMLElement {
  const u = Math.max(0, Math.round(unitPower));
  const t = Math.max(0, Math.round(territoryPower));
  const total = u + t;
  const uPct = total > 0 ? (u / total) * 100 : 0;
  const tPct = total > 0 ? (t / total) * 100 : 0;

  const bar = el(
    'div',
    { class: 'powerbar__bar', attrs: { role: 'img' }, aria: { label: `power ${total}` } },
    el('div', {
      class: 'powerbar__seg powerbar__seg--unit',
      style: `width:${uPct.toFixed(2)}%`,
    }),
    el('div', {
      class: 'powerbar__seg powerbar__seg--terr',
      style: `width:${tPct.toFixed(2)}%`,
    }),
  );

  return el(
    'div',
    { class: 'powerbar' },
    el(
      'div',
      { class: 'powerbar__top' },
      el('span', { class: 'powerbar__caption', text: 'POWER POINTS' }),
      el('span', { class: 'powerbar__total', text: fmtNum(total) }),
    ),
    bar,
    el(
      'div',
      { class: 'powerbar__legend' },
      el(
        'span',
        { class: 'powerbar__key powerbar__key--unit' },
        el('i'),
        'UNITS ',
        el('b', { text: fmtNum(u) }),
      ),
      el(
        'span',
        { class: 'powerbar__key powerbar__key--terr' },
        el('i'),
        'TERRITORY ',
        el('b', { text: fmtNum(t) }),
      ),
    ),
  );
}
