/**
 * TERRA BELLUM — canonical domain types.
 *
 * ARCHITECTURE RULE (GDD §2): this file, and everything under /src/game, has
 * ZERO Three.js imports. Pure data + pure logic only. The render layer is a
 * dumb view over these shapes.
 */

// ─────────────────────────────────────────────────────────────────────────────
// Identity
// ─────────────────────────────────────────────────────────────────────────────

export type PlayerId = string;
export type GuildId = string;
export type ArmyId = string;
export type UnitId = string;
export type DroneId = string;
export type SectorId = string;
export type HexId = string; // canonical `${q},${r}`
export type BattleId = string;
export type ParleyId = string;
export type TreatyId = string;

// ─────────────────────────────────────────────────────────────────────────────
// Hex geometry (pointy-top, axial)
// ─────────────────────────────────────────────────────────────────────────────

export interface Axial {
  q: number;
  r: number;
}

export type Terrain = 'plains' | 'ridge' | 'crater' | 'ruins' | 'gasfield';
export type FortLevel = 0 | 1 | 2 | 3;

export interface FortBuild {
  targetLevel: 1 | 2 | 3;
  startedAt: number;
  completesAt: number;
}

export interface ProductionOrder {
  id: string;
  unitType: UnitType;
  remaining: number;
  startedAt: number;
  completesAt: number; // completion of the NEXT unit in this order
}

export interface CaptureState {
  playerId: PlayerId;
  guildId: GuildId;
  armyId: ArmyId;
  startedAt: number;
  completesAt: number;
}

export interface Hex {
  id: HexId;
  q: number;
  r: number;
  sectorId: SectorId;
  terrain: Terrain;
  gas: boolean;
  ownerId?: PlayerId;
  fortLevel: FortLevel;
  fortBuild?: FortBuild;
  production: ProductionOrder[];
  capture?: CaptureState;
  /** Reserve units garrisoned here (beyond an army's carry cap). */
  reserves: Partial<Record<UnitType, number>>;
}

export type SectorState = 'active' | 'locked' | 'closing' | 'unlocking';

export interface Sector {
  id: SectorId;
  name: string;
  designation: string; // e.g. "SEC-07 KHARON"
  center: Axial;
  hexIds: HexId[];
  state: SectorState;
  /** Announced future events (GDD §3.2 — one full week of advance notice). */
  opensAt?: number;
  closesAt?: number;
  /** Season rotation slot index; lower opens earlier. */
  rotationIndex: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Units
// ─────────────────────────────────────────────────────────────────────────────

export type UnitType =
  | 'exo'
  | 'walker'
  | 'pallet'
  | 'flyer'
  | 'heavy_pallet'
  | 'elite_flyer'
  | 'drone';

export type Trait =
  | 'cover_bonus' // +1 defense on cover tiles
  | 'no_rough_end' // cannot end movement on rough tiles
  | 'ignores_obstacles' // flies over obstacles when moving
  | 'map_only'; // never enters battle

export interface Cost {
  m: number;
  g: number;
}

export interface UnitDef {
  type: UnitType;
  name: string;
  codename: string;
  cost: Cost;
  hp: number;
  atk: number;
  rng: number;
  mov: number;
  traits: Trait[];
  buildTimeMs: number;
  /** Combat unit (enters the tactical layer)? */
  combat: boolean;
  blurb: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Armies & drones (strategic layer)
// ─────────────────────────────────────────────────────────────────────────────

export interface ArmyUnit {
  id: UnitId;
  type: UnitType;
  hp: number;
}

export interface MoveStep {
  hexId: HexId;
  arrivesAt: number;
}

export interface Army {
  id: ArmyId;
  ownerId: PlayerId;
  guildId: GuildId;
  name: string;
  hexId: HexId;
  units: ArmyUnit[];
  /** Queued path; index 0 is the next hex being entered. */
  path: MoveStep[];
  movingFrom?: HexId;
  departedAt?: number;
  arrivesAt?: number;
  /** Siege wait against a level-3 fort (GDD §6). */
  siege?: { hexId: HexId; startedAt: number; readyAt: number };
  /**
   * Post-march regroup stamp. The column may not be given a NEW march order
   * until this moment; halting, retreating and force-retreating are never
   * gated by it. Set when a march comes to a stop — see `beginMove` and
   * `moveCooldownRemaining` in game/world/movement.ts.
   */
  moveReadyAt?: number;
}

export interface Drone {
  id: DroneId;
  ownerId: PlayerId;
  guildId: GuildId;
  hexId: HexId;
  path: MoveStep[];
  movingFrom?: HexId;
  departedAt?: number;
  arrivesAt?: number;
  alive: boolean;
}

export interface ArmyIntel {
  ownerId: PlayerId;
  ownerName: string;
  guildId: GuildId;
  guildTag: string;
  unitCount: number;
  composition: Partial<Record<UnitType, number>>;
}

export interface IntelSnapshot {
  hexId: HexId;
  at: number;
  ownerId?: PlayerId;
  ownerName?: string;
  guildId?: GuildId;
  guildTag?: string;
  fortLevel: FortLevel;
  army?: ArmyIntel;
}

// ─────────────────────────────────────────────────────────────────────────────
// Players & guilds
// ─────────────────────────────────────────────────────────────────────────────

export type GuildRole = 'leader' | 'officer' | 'member';

export interface Player {
  id: PlayerId;
  name: string;
  guildId?: GuildId;
  minerals: number;
  gas: number;
  online: boolean;
  lastSeen: number;
  /** Hue 0-360 for procedural avatar/banner tinting. */
  hue: number;
  deployed: boolean;
  harvested: Cost;
  /** AI-driven simulated player (Phase 1 world sim). */
  bot: boolean;
}

export interface Guild {
  id: GuildId;
  name: string;
  tag: string;
  motto: string;
  /** 0xRRGGBB banner colour. */
  color: number;
  leaderId: PlayerId;
  memberIds: PlayerId[];
  roles: Record<PlayerId, GuildRole>;
  /** Officers explicitly granted diplomacy access (leader always has it). */
  diplomats: PlayerId[];
  createdAt: number;
  emblem: number; // index into procedural emblem set
}

export type GuildCapability =
  | 'appoint'
  | 'diplomacy'
  | 'grand_objective'
  | 'short_objective'
  | 'kick'
  | 'chat';

// ─────────────────────────────────────────────────────────────────────────────
// Communication
// ─────────────────────────────────────────────────────────────────────────────

export type ChatKind = 'text' | 'system' | 'triple_zero' | 'alert' | 'ping' | 'trade' | 'treaty';

export interface ChatMessage {
  id: string;
  channel: string; // 'guild:<id>' | 'officer:<id>' | 'parley:<id>'
  authorId: PlayerId;
  authorName: string;
  text: string;
  at: number;
  kind: ChatKind;
}

export type PingKind = 'attack' | 'defend' | 'scout' | 'rally' | 'danger';

export interface Ping {
  id: string;
  guildId: GuildId;
  hexId: HexId;
  kind: PingKind;
  authorId: PlayerId;
  authorName: string;
  at: number;
  expiresAt: number;
}

export interface Mark {
  id: string;
  guildId: GuildId;
  hexId: HexId;
  label: string;
  authorId: PlayerId;
  authorName: string;
  at: number;
}

export interface Objective {
  id: string;
  guildId: GuildId;
  title: string;
  detail: string;
  hexIds: HexId[];
  grand: boolean;
  createdBy: PlayerId;
  createdByName: string;
  createdAt: number;
  dueAt?: number;
  committed: PlayerId[];
  done: boolean;
}

// ─────────────────────────────────────────────────────────────────────────────
// Transfers
// ─────────────────────────────────────────────────────────────────────────────

export interface TransferPayload {
  minerals: number;
  gas: number;
  units: Partial<Record<UnitType, number>>;
}

export type TransferStatus = 'in_transit' | 'delivered' | 'cancelled';

export interface Transfer {
  id: string;
  guildId: GuildId;
  fromId: PlayerId;
  toId: PlayerId;
  payload: TransferPayload;
  sentAt: number;
  arrivesAt: number;
  distance: number;
  status: TransferStatus;
}

// ─────────────────────────────────────────────────────────────────────────────
// Diplomacy
// ─────────────────────────────────────────────────────────────────────────────

export type TradeStatus = 'open' | 'accepted' | 'declined' | 'cancelled';

export interface TradeOffer {
  id: string;
  parleyId: ParleyId;
  fromGuild: GuildId;
  toGuild: GuildId;
  byId: PlayerId;
  byName: string;
  /** What fromGuild gives. */
  offer: Cost;
  /** What fromGuild wants back. */
  request: Cost;
  status: TradeStatus;
  at: number;
  resolvedAt?: number;
}

export interface Signature {
  guildId: GuildId;
  playerId: PlayerId;
  playerName: string;
  at: number;
}

export interface TreatyRevision {
  at: number;
  byGuild: GuildId;
  byName: string;
  text: string;
}

export interface Treaty {
  id: TreatyId;
  parleyId: ParleyId;
  guilds: [GuildId, GuildId];
  title: string;
  text: string;
  status: 'drafting' | 'signed';
  /** Turn-based editing: only this guild may edit right now. */
  editingGuild: GuildId;
  signatures: Signature[];
  createdAt: number;
  signedAt?: number;
  revisions: TreatyRevision[];
}

export interface Parley {
  id: ParleyId;
  guilds: [GuildId, GuildId];
  createdAt: number;
  peace: boolean;
  peaceSince?: number;
  lastActivity: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Battle (tactical layer, GDD §7)
// ─────────────────────────────────────────────────────────────────────────────

export type TileKind =
  | 'floor'
  | 'obstacle' // impassable, blocks LOS
  | 'rough' // passable; pallet tanks may not END here
  | 'cover' // +1 defense for units with cover_bonus
  | 'hazard' // 2 damage on turn end
  | 'teleport' // paired
  | 'destructible' // 2 HP wall, blocks LOS until destroyed
  | 'elevation' // +1 RNG while occupied
  | 'unstable'; // collapses to obstacle after 2 crossings

export interface Tile {
  x: number;
  y: number;
  kind: TileKind;
  /** destructible wall HP */
  hp?: number;
  /** teleport pair id */
  pairId?: number;
  /** unstable crossing counter */
  crossings?: number;
  /** unstable tile that has collapsed into an obstacle */
  collapsed?: boolean;
  /** placed by an L2-fort defender before deployment */
  placed?: boolean;
}

export type BattleSide = 'attacker' | 'defender';
export type DieIndex = 0 | 1 | 2;

export interface BattleUnit {
  id: UnitId;
  side: BattleSide;
  type: UnitType;
  hp: number;
  maxHp: number;
  x: number;
  y: number;
  alive: boolean;
  braced: boolean;
  /** AP remaining from this turn's assigned die. */
  ap: number;
  attacksThisTurn: number;
  /** Which die was assigned this turn (for UI). */
  die?: DieIndex;
  /** Source army unit id so surviving HP can be written back. */
  sourceUnitId: UnitId;
}

export type BattlePhase =
  | 'intro'
  | 'side_pick' // L1+ fort defender picks deployment side
  | 'obstacle_place' // L2 fort defender places bonus obstacles
  | 'deploy'
  | 'rolling'
  | 'assign'
  | 'acting'
  | 'ended';

export interface BattleParticipant {
  playerId: PlayerId;
  playerName: string;
  guildId: GuildId;
  guildTag: string;
  guildColor: number;
  armyId: ArmyId;
  /** Local human control, or AI auto-defense (GDD §7.4). */
  ai: boolean;
}

export type BattleEvent =
  | { t: 'battle_start'; at: number; boardId: string; seed: number }
  | { t: 'deploy'; at: number; side: BattleSide; units: { id: UnitId; type: UnitType; x: number; y: number }[] }
  | { t: 'side_pick'; at: number; side: BattleSide; bottom: BattleSide }
  | { t: 'obstacles_placed'; at: number; side: BattleSide; tiles: { x: number; y: number }[] }
  | { t: 'turn_start'; at: number; side: BattleSide; turn: number }
  | { t: 'roll'; at: number; side: BattleSide; dice: [number, number, number] }
  | { t: 'triple_zero'; at: number; side: BattleSide; playerName: string }
  | { t: 'assign'; at: number; side: BattleSide; die: DieIndex; unitId: UnitId; ap: number }
  | { t: 'move'; at: number; unitId: UnitId; from: { x: number; y: number }; to: { x: number; y: number }; path: { x: number; y: number }[] }
  | { t: 'teleport'; at: number; unitId: UnitId; from: { x: number; y: number }; to: { x: number; y: number } }
  | { t: 'attack'; at: number; unitId: UnitId; targetId: UnitId; damage: number; mitigated: number; killed: boolean }
  | { t: 'attack_wall'; at: number; unitId: UnitId; x: number; y: number; damage: number; destroyed: boolean }
  | { t: 'brace'; at: number; unitId: UnitId }
  | { t: 'hazard'; at: number; unitId: UnitId; damage: number; killed: boolean }
  | { t: 'collapse'; at: number; x: number; y: number }
  | { t: 'turn_end'; at: number; side: BattleSide }
  | { t: 'concede'; at: number; side: BattleSide }
  | { t: 'timeout_pass'; at: number; side: BattleSide }
  | { t: 'battle_end'; at: number; winner: BattleSide; reason: 'wipe' | 'concede' | 'timeout' };

export interface BattleState {
  id: BattleId;
  seed: number;
  boardId: string;
  boardName: string;
  terrain: Terrain;
  hexId: HexId;
  w: number;
  h: number;
  grid: Tile[][]; // grid[y][x]
  units: BattleUnit[];
  turn: BattleSide;
  turnNumber: number;
  dice: [number, number, number] | null;
  assignments: Partial<Record<DieIndex, UnitId>>;
  phase: BattlePhase;
  /** Which side deploys on the BOTTOM rows (y = h-1, h-2). */
  bottomSide: BattleSide;
  /** Bonus obstacles the L2 defender still has to place. */
  obstaclesToPlace: number;
  log: BattleEvent[];
  winner?: BattleSide;
  endReason?: 'wipe' | 'concede' | 'timeout';
  turnEndsAt: number;
  attacker: BattleParticipant;
  defender: BattleParticipant;
  missedTimers: Record<BattleSide, number>;
  /** Fort level of the contested hex — drives defender bonuses. */
  fortLevel: FortLevel;
}

// ─────────────────────────────────────────────────────────────────────────────
// Board templates (data, GDD §13 — "board layouts are data, not code")
// ─────────────────────────────────────────────────────────────────────────────

export interface BoardTemplate {
  id: string;
  name: string;
  terrain: Terrain;
  w: number;
  h: number;
  /** Row strings, one char per tile. See CHAR_TO_TILE in game/board/templates.ts. */
  rows: string[];
  twist: string;
  blurb: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Season & world
// ─────────────────────────────────────────────────────────────────────────────

export type SeasonPhase = 'running' | 'ended';

export interface SeasonState {
  index: number;
  name: string;
  startedAt: number;
  endsAt: number;
  phase: SeasonPhase;
  /** Server-pre-generated rotation order (hidden beyond the reveal window). */
  rotation: SectorId[];
  rotationCursor: number;
  nextRotationAt: number;
  /**
   * Guilds that have held at least one hex at some point this season. Domination
   * (GDD §11) is an *elimination*, so it may only be judged against banners that
   * actually took the field — otherwise a fresh world ends the instant the first
   * commander plants a flag.
   */
  contested: GuildId[];
  winnerGuildId?: GuildId;
  endReason?: 'domination' | 'forfeit' | 'timeout';
}

export interface WorldState {
  hexes: Record<HexId, Hex>;
  sectors: Record<SectorId, Sector>;
  radius: number;
}

export interface PendingBattle {
  id: BattleId;
  hexId: HexId;
  attackerArmyId: ArmyId;
  defenderArmyId: ArmyId;
  attackerId: PlayerId;
  defenderId: PlayerId;
  graceEndsAt: number;
  /** Set when the defender accepted, or the grace window expired → AI. */
  accepted: boolean;
}

export interface GameNotification {
  id: string;
  at: number;
  kind: 'info' | 'combat' | 'alert' | 'intel' | 'transfer' | 'diplomacy' | 'season';
  title: string;
  body: string;
  hexId?: HexId;
  read: boolean;
}

// ─────────────────────────────────────────────────────────────────────────────
// Root game state
// ─────────────────────────────────────────────────────────────────────────────

export interface GameState {
  now: number;
  meId: PlayerId;
  world: WorldState;
  players: Record<PlayerId, Player>;
  guilds: Record<GuildId, Guild>;
  armies: Record<ArmyId, Army>;
  drones: Record<DroneId, Drone>;
  transfers: Transfer[];
  chat: Record<string, ChatMessage[]>;
  pings: Ping[];
  marks: Mark[];
  objectives: Objective[];
  parleys: Record<ParleyId, Parley>;
  trades: TradeOffer[];
  treaties: Record<TreatyId, Treaty>;
  /** Per-guild last-seen intel snapshots. */
  intel: Record<GuildId, Record<HexId, IntelSnapshot>>;
  season: SeasonState;
  battle?: BattleState;
  pendingBattles: PendingBattle[];
  notifications: GameNotification[];
  /** Last hourly economy tick timestamp. */
  lastTick: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Power points (GDD §9.2)
// ─────────────────────────────────────────────────────────────────────────────

export interface PowerBreakdown {
  unitPower: number;
  territoryPower: number;
  total: number;
  hexCount: number;
  yieldPerHour: Cost;
}

// ─────────────────────────────────────────────────────────────────────────────
// Utility
// ─────────────────────────────────────────────────────────────────────────────

export type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export const ok = <T>(value: T): Result<T> => ({ ok: true, value });
export const err = <T = never>(error: string): Result<T> => ({ ok: false, error });
