/**
 * TERRA BELLUM — backend selection (GDD §2, §13).
 *
 * `IBackend` is the single seam between the game and any server. When a real
 * Firebase project is configured the live adapter is used; otherwise the whole
 * world runs locally in the mock, which is a complete game rather than a stub —
 * seeded world generation, rival guilds, economy, sieges, battles and all.
 *
 * The Firebase SDK is only ever loaded from inside `FirebaseBackend.init()`, so
 * the offline build never pays for the bundle.
 */
import type { BackendKind, IBackend } from './IBackend';
import { FIREBASE_ENABLED } from '../config/firebase';
import { MockBackend } from './mock/MockBackend';
import { FirebaseBackend } from './firebase/FirebaseBackend';

/** Which implementation this build will hand out. */
export const backendKind: BackendKind = FIREBASE_ENABLED ? 'firebase' : 'mock';

/** Construct the backend for this environment. Call `init()` before use. */
export function createBackend(): IBackend {
  return FIREBASE_ENABLED ? new FirebaseBackend() : new MockBackend();
}

export type { IBackend, BackendKind, AuthSession } from './IBackend';
export { me } from './IBackend';
export { MockBackend } from './mock/MockBackend';
export { FirebaseBackend } from './firebase/FirebaseBackend';
export { seedWorld } from './mock/seedWorld';
export { BotDirector } from './mock/bots';
export { makeNameForge, defaultCommanderName } from './names';
