import type { FortLevel, Terrain, PingKind } from '../game/types';

const SEC = 1000;
const MIN = 60 * SEC;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

/**
 * ── READING THE TIMERS IN THIS FILE ─────────────────────────────────────────
 *
 * Every duration below is GAME time. The offline world runs compressed at
 * `SIM.timeScale`, so what a player actually waits is `value / SIM.timeScale`.
 *
 * At the shipped scale (30) the conversion is deliberately trivial:
 *
 *     1 game minute = 2 real seconds     1 game hour = 2 real minutes
 *
 * Keep that ratio in mind when touching anything marked [TUNE] — a number that
 * reads sensibly in fiction can still be unplayable on the wall clock. The
 * strategic layer was previously compressed 90×, which turned a 5-minute hex
 * step into a 3.3-second teleport and left no window to react to an attack.
 */

// ─────────────────────────────────────────────────────────────────────────────
// Global map (GDD §3)
// ─────────────────────────────────────────────────────────────────────────────

export const MAP = {
  /** World radius in hexes from origin. */
  worldRadius: 22,
  /** Target hexes per sector (GDD §3.1: ~30–60). */
  sectorSizeMin: 30,
  sectorSizeMax: 60,
  sectorCount: 12,
  /** How many sectors are playable at once. */
  activeSectors: 4,
  /**
   * Base time for one hex step. [TUNE: GDD §3.4 says 5 min base]
   *
   * Raised well past the GDD default on purpose. A march has to be legible on
   * the wall clock, and the floor is one REAL minute per hex: at `SIM.timeScale`
   * this is 60 real seconds on plains, 96 on ridge, 78 on crater. No single hex
   * of ground anywhere on the map can change hands faster than a defender can
   * plausibly react to it.
   */
  moveMsPerHex: 30 * MIN,
  /**
   * Regroup after a march. A column that has just arrived may not be given a
   * new march order until this has elapsed (see `beginMove`). Halting,
   * retreating and force-retreating are never gated by it. [TUNE]
   *
   * One game hour = two real minutes = exactly one resource tick, so a column
   * that takes ground sits out one production cycle before it can push on.
   * This is what makes holding a hex a decision rather than a waypoint.
   */
  moveCooldownMs: 1 * HOUR,
  /** Terrain movement multipliers. */
  moveCostByTerrain: {
    plains: 1.0,
    ridge: 1.6,
    crater: 1.3,
    ruins: 1.2,
    gasfield: 1.1,
  } as Record<Terrain, number>,
  /**
   * ── THE DEFENSIVE WINDOW ─────────────────────────────────────────────────
   *
   * Capture is the only way ground changes hands, so this timer — not the march
   * — is what decides whether defence is a real option (GDD pillar 4). It is
   * scaled so that taking ground somebody OWNS always leaves them a minute or
   * two of real time to answer, on top of the march they could see coming.
   *
   * At `SIM.timeScale`, `captureMs + owned + fortLevel × perLevel` comes out as:
   *
   *     neutral ground        20 min →  40 real s
   *     owned, no fort        45 min →  90 real s
   *     owned + Outpost       55 min → 110 real s
   *     owned + Bastion       65 min → 130 real s
   *     owned + Citadel       75 min → 150 real s  (plus the 30 min siege)
   *
   * Unclaimed dirt stays quick on purpose: nobody is being defended there.
   *
   * Note the deliberate side effect on the owned line — 45 game minutes is
   * longer than a 30-minute hex step, so a column can no longer flip enemy
   * hexes in passing while it marches through. It has to stop and hold the
   * ground, which is the whole point.
   */
  captureMs: 20 * MIN,
  /** Extra capture time when the hex already belongs to somebody. [TUNE] */
  captureMsOwnedBonus: 25 * MIN,
  /** Extra capture time per fortification level on an enemy hex. [TUNE] */
  captureMsPerFortLevel: 10 * MIN,
  /**
   * Drone travel is faster than an army — roughly 3× — so recon stays the
   * answer to a slow map rather than another thing you wait on. [TUNE]
   */
  droneMsPerHex: 8 * MIN,
} as const;

