  /** Destructible wall HP. */
  wallHp: 2,
  /** Unstable tile collapses after this many crossings. */
  unstableCrossings: 2,
  /** Missed turn timers before auto-concede. */
  missedTimersToConcede: 3,
  /** Deployment rows per side. */
  deployRows: 2,
  /** Minimum damage a landed hit deals after mitigation. */
  minDamage: 0,
  /** Defender grace window before AI auto-defense. [TUNE: 5 min] */
