// Simulation (Phase-1 offline world with simulated rival guilds)
// ─────────────────────────────────────────────────────────────────────────────

export const SIM = {
  /**
   * Time compression for the offline/mock backend so long timers are
   * observable in a play session. 1 = real time. [TUNE]
   *
   * 30 means 1 game minute = 2 real seconds. It was 90, which made the whole
   * strategic layer illegible: armies crossed a hex in 3.3 real seconds, an
   * L1 outpost went up in 20, and an attacker could be standing on you before
   * the alert ticker had finished scrolling. Every other timer in this file is
   * divided by this number to get what the player actually waits, so moving it
   * moves the entire world — check `moveMsPerHex`, `FORTS.buildMs` and
   * `ECONOMY.tickMs` together whenever it changes.
   */
  timeScale: 30,
  botGuilds: 5,
  botsPerGuild: 6,
  /** How often bot commanders re-evaluate. */
  botThinkMs: 6 * SEC,
  /** Chance a bot acts on a given think tick. */
  botActChance: 0.55,
} as const;

