/**
 * GDD §9.3 — Transfers (resources & units).
 *
 *   deliveryTime = hexDistance(senderNearestOwnedHex, receiverNearestOwnedHex)
 *                  × GUILD.transferMsPerHex,  floored at GUILD.transferMinMs
 *
 * Shipments debit the sender immediately, are visible to the whole guild while
 * in transit, and can be cancelled before halfway (GUILD.transferCancelBefore).
 *
 * PURE: no DOM, no Three.js.
 */
import { ECONOMY, GUILD } from '../../config/balance';
import { hexDistance, parseHexId } from '../hex';
import { uid } from '../rng';
import type {
  GameState,
  GuildId,
  HexId,
  PlayerId,
  Result,
  Transfer,
  TransferPayload,
  UnitType,
} from '../types';
import { err, ok } from '../types';
import { guildOf } from './permissions';

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

const unitTypesOf = (units: TransferPayload['units']): UnitType[] =>
  (Object.keys(units) as UnitType[]).filter((t) => (units[t] ?? 0) > 0);

/** Total unit count in a payload. */
export function payloadUnitCount(payload: TransferPayload): number {
  let n = 0;
  for (const type of unitTypesOf(payload.units)) n += payload.units[type] ?? 0;
  return n;
}

/** True when a payload carries nothing at all. */
export function payloadIsEmpty(payload: TransferPayload): boolean {
  return payload.minerals <= 0 && payload.gas <= 0 && payloadUnitCount(payload) === 0;
}

/** Every hex a player controls. */
export function ownedHexIds(state: GameState, playerId: PlayerId): HexId[] {
  const out: HexId[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId === playerId) out.push(hex.id);
  }
  return out;
}

/** How many units of `type` a player has sitting in reserve across their hexes. */
export function reserveCount(state: GameState, playerId: PlayerId, type: UnitType): number {
  let n = 0;
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId !== playerId) continue;
    n += hex.reserves[type] ?? 0;
  }
  return n;
}

/**
 * The player's owned hex closest to `toward` — the logistics node a shipment
 * leaves from or lands at (GDD §9.3).
 *
 * With no `toward` the player's de-facto capital is returned instead: the most
 * fortified hex, tie-broken by garrison size then hex id, so the choice is
 * deterministic and independent of object iteration order.
 *
 * Fallback: a commander who has just deployed may own no hex yet, in which case
 * the hex their army stands on is used so they are not cut out of logistics.
 */
export function nearestOwnedHex(
  state: GameState,
  playerId: PlayerId,
  toward?: HexId,
): HexId | undefined {
  let candidates = ownedHexIds(state, playerId);

  if (candidates.length === 0) {
    const armyHexes = new Set<HexId>();
    for (const army of Object.values(state.armies)) {
      if (army.ownerId === playerId) armyHexes.add(army.hexId);
    }
    candidates = [...armyHexes];
  }
  if (candidates.length === 0) return undefined;

  if (toward !== undefined) {
    const target = parseHexId(toward);
    let best: HexId | undefined;
    let bestDist = Infinity;
    for (const id of [...candidates].sort()) {
      const d = hexDistance(parseHexId(id), target);
      if (d < bestDist) {
        bestDist = d;
        best = id;
      }
    }
    return best;
  }

  let best = candidates[0];
  let bestScore = -Infinity;
  for (const id of [...candidates].sort()) {
    const hex = state.world.hexes[id];
    let garrison = 0;
    if (hex) {
      for (const type of Object.keys(hex.reserves) as UnitType[]) {
        garrison += hex.reserves[type] ?? 0;
      }
    }
    const score = (hex ? hex.fortLevel : 0) * 1000 + garrison;
    if (score > bestScore) {
      bestScore = score;
      best = id;
    }
  }
  return best;
}

/**
 * Flight time between two logistics nodes.
 * `distance × GUILD.transferMsPerHex`, never below `GUILD.transferMinMs`.
 */
export function transferTime(
  state: GameState,
  fromId: HexId,
  toId: HexId,
): { ms: number; distance: number } {
  // Unknown hexes still resolve — the ids alone carry the axial coordinates.
  void state;
  const distance = hexDistance(parseHexId(fromId), parseHexId(toId));
  const ms = Math.max(GUILD.transferMinMs, distance * GUILD.transferMsPerHex);
  return { ms, distance };
}

// ─────────────────────────────────────────────────────────────────────────────
// Creating a shipment
// ─────────────────────────────────────────────────────────────────────────────

export interface TransferOptions {
  /**
   * Skip the same-guild check. Used only by diplomatic trades (GDD §10), where
   * two guilds exchange resources under the same transfer-time rules.
   */
  crossGuild?: boolean;
}

export interface TransferPlan {
  fromHexId: HexId;
  toHexId: HexId;
  ms: number;
  distance: number;
  guildId: GuildId;
}

/**
 * Dry-run a shipment: resolves the route and proves the sender can pay, without
 * touching any state. Callers that must create two shipments atomically (trade
 * acceptance) validate both plans before committing either.
 */
export function planTransfer(
  state: GameState,
  fromId: PlayerId,
  toId: PlayerId,
  payload: TransferPayload,
  opts: TransferOptions = {},
): Result<TransferPlan> {
  if (fromId === toId) return err('you cannot ship to yourself');

  const sender = state.players[fromId];
  const receiver = state.players[toId];
  if (!sender || !receiver) return err('unknown commander');

  const senderGuild = guildOf(state, fromId);
  if (!senderGuild) return err('you are not in a guild');
  if (!opts.crossGuild && receiver.guildId !== senderGuild.id) {
    return err('transfers stay inside the guild');
  }

  if (payload.minerals < 0 || payload.gas < 0) return err('invalid payload');
  if (payloadIsEmpty(payload)) return err('nothing to send');
  if (!Number.isFinite(payload.minerals) || !Number.isFinite(payload.gas)) {
    return err('invalid payload');
  }

  if (sender.minerals < payload.minerals) return err('not enough minerals');
  if (sender.gas < payload.gas) return err('not enough gas');

  for (const type of unitTypesOf(payload.units)) {
    const want = payload.units[type] ?? 0;
    if (!Number.isInteger(want)) return err('unit counts must be whole');
    if (reserveCount(state, fromId, type) < want) return err(`not enough ${type} in reserve`);
  }

  const toHexId = nearestOwnedHex(state, toId);
  if (toHexId === undefined) return err('recipient holds no ground to receive at');
  const fromHexId = nearestOwnedHex(state, fromId, toHexId);
  if (fromHexId === undefined) return err('you hold no ground to ship from');

  const { ms, distance } = transferTime(state, fromHexId, toHexId);
  return ok({ fromHexId, toHexId, ms, distance, guildId: senderGuild.id });
}

/**
 * Create a shipment. The sender is debited immediately — resources in transit
 * are gone from the stockpile, which is what makes cancellation meaningful.
 */
export function createTransfer(
  state: GameState,
  fromId: PlayerId,
  toId: PlayerId,
  payload: TransferPayload,
  now: number,
  opts: TransferOptions = {},
): Result<Transfer> {
  const planned = planTransfer(state, fromId, toId, payload, opts);
  if (!planned.ok) return err(planned.error);
  const plan = planned.value;

  const sender = state.players[fromId];
  sender.minerals -= payload.minerals;
  sender.gas -= payload.gas;

  // Units leave from the departure node first, then from the nearest hexes.
  const units: Partial<Record<UnitType, number>> = {};
  for (const type of unitTypesOf(payload.units)) {
    const want = payload.units[type] ?? 0;
    takeReserves(state, fromId, type, want, plan.fromHexId);
    units[type] = want;
  }

  const transfer: Transfer = {
    id: uid('trf'),
    guildId: plan.guildId,
    fromId,
    toId,
    payload: { minerals: payload.minerals, gas: payload.gas, units },
    sentAt: now,
    arrivesAt: now + plan.ms,
    distance: plan.distance,
    status: 'in_transit',
  };
  state.transfers.push(transfer);
  return ok(transfer);
}

/** Pull `count` units of `type` out of a player's reserves, nearest hex first. */
function takeReserves(
  state: GameState,
  playerId: PlayerId,
  type: UnitType,
  count: number,
  fromHexId: HexId,
): number {
  let remaining = count;
  const origin = parseHexId(fromHexId);
  const hexes = ownedHexIds(state, playerId)
    .sort()
    .sort((a, b) => hexDistance(parseHexId(a), origin) - hexDistance(parseHexId(b), origin));

  for (const id of hexes) {
    if (remaining <= 0) break;
    const hex = state.world.hexes[id];
    const have = hex.reserves[type] ?? 0;
    if (have <= 0) continue;
    const take = Math.min(have, remaining);
    const left = have - take;
    if (left > 0) hex.reserves[type] = left;
    else delete hex.reserves[type];
    remaining -= take;
  }
  return count - remaining;
}

/** Push units into a hex's reserve garrison. */
function giveReserves(state: GameState, hexId: HexId, units: TransferPayload['units']): void {
  const hex = state.world.hexes[hexId];
  if (!hex) return;
  for (const type of unitTypesOf(units)) {
    hex.reserves[type] = (hex.reserves[type] ?? 0) + (units[type] ?? 0);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Cancellation (GDD §9.3 — "can be cancelled before halfway")
// ─────────────────────────────────────────────────────────────────────────────

/** Fraction of the flight already completed, clamped to [0, 1]. */
export function transferProgress(transfer: Transfer, now: number): number {
  const total = transfer.arrivesAt - transfer.sentAt;
  if (total <= 0) return 1;
  return Math.min(1, Math.max(0, (now - transfer.sentAt) / total));
}

/**
 * Cancellable while strictly before GUILD.transferCancelBefore of the flight.
 * Exactly at the halfway mark the window has closed.
 */
export function canCancelTransfer(transfer: Transfer, now: number): boolean {
  if (transfer.status !== 'in_transit') return false;
  return transferProgress(transfer, now) < GUILD.transferCancelBefore;
}

/** Recall a shipment and refund the sender. Only the sender may recall. */
export function cancelTransfer(
  state: GameState,
  transferId: string,
  byPlayerId: PlayerId,
  now: number,
): Result<Transfer> {
  const transfer = state.transfers.find((t) => t.id === transferId);
  if (!transfer) return err('unknown shipment');
  if (transfer.fromId !== byPlayerId) return err('only the sender can recall a shipment');
  if (transfer.status !== 'in_transit') return err('shipment already resolved');
  if (!canCancelTransfer(transfer, now)) return err('past the halfway mark — too late to recall');

  refund(state, transfer);
  transfer.status = 'cancelled';
  return ok(transfer);
}

function refund(state: GameState, transfer: Transfer): void {
  const sender = state.players[transfer.fromId];
  if (sender) {
    sender.minerals = Math.min(ECONOMY.capMinerals, sender.minerals + transfer.payload.minerals);
    sender.gas = Math.min(ECONOMY.capGas, sender.gas + transfer.payload.gas);
  }
  if (payloadUnitCount(transfer.payload) > 0) {
    const home = nearestOwnedHex(state, transfer.fromId);
    if (home !== undefined) giveReserves(state, home, transfer.payload.units);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Delivery
// ─────────────────────────────────────────────────────────────────────────────

export interface TransferEvent {
  transfer: Transfer;
  /** Hex the units landed at, if any were carried and a node existed. */
  toHexId?: HexId;
  deliveredMinerals: number;
  deliveredGas: number;
  /** Overflow burned off by the ECONOMY stockpile caps. */
  wastedMinerals: number;
  wastedGas: number;
  deliveredUnits: Partial<Record<UnitType, number>>;
  /** Units with nowhere to land — the recipient holds no ground any more. */
  lostUnits: Partial<Record<UnitType, number>>;
}

/**
 * Land every shipment whose clock has run out. Resources respect the ECONOMY
 * stockpile caps; the overflow is reported so the UI can say so out loud.
 */
export function tickTransfers(state: GameState, now: number): TransferEvent[] {
  const events: TransferEvent[] = [];

  for (const transfer of state.transfers) {
    if (transfer.status !== 'in_transit') continue;
    if (transfer.arrivesAt > now) continue;

    const receiver = state.players[transfer.toId];
    transfer.status = 'delivered';

    const event: TransferEvent = {
      transfer,
      deliveredMinerals: 0,
      deliveredGas: 0,
      wastedMinerals: 0,
      wastedGas: 0,
      deliveredUnits: {},
      lostUnits: {},
    };

    if (receiver) {
      const m = Math.min(ECONOMY.capMinerals, receiver.minerals + transfer.payload.minerals);
      event.deliveredMinerals = m - receiver.minerals;
      event.wastedMinerals = transfer.payload.minerals - event.deliveredMinerals;
      receiver.minerals = m;

      const g = Math.min(ECONOMY.capGas, receiver.gas + transfer.payload.gas);
      event.deliveredGas = g - receiver.gas;
      event.wastedGas = transfer.payload.gas - event.deliveredGas;
      receiver.gas = g;
    }

    if (payloadUnitCount(transfer.payload) > 0) {
      const landing = nearestOwnedHex(state, transfer.toId);
      if (landing !== undefined && receiver) {
        giveReserves(state, landing, transfer.payload.units);
        event.toHexId = landing;
        event.deliveredUnits = { ...transfer.payload.units };
      } else {
        event.lostUnits = { ...transfer.payload.units };
      }
    }

    events.push(event);
  }

  return events;
}

// ─────────────────────────────────────────────────────────────────────────────
// Planning surface (GDD §9.3 — the timeline the guild coordinates against)
// ─────────────────────────────────────────────────────────────────────────────

export interface TransferRow {
  transfer: Transfer;
  direction: 'incoming' | 'outgoing';
  fromName: string;
  toName: string;
  /** True when the counterparty sits outside `guildId` (diplomatic trade). */
  crossGuild: boolean;
  progress: number;
  remainingMs: number;
  cancellable: boolean;
}

export interface TransferTimeline {
  incoming: TransferRow[];
  outgoing: TransferRow[];
  /** Every row exactly once, soonest arrival first. */
  all: TransferRow[];
}

/**
 * In-flight shipments touching a guild, split into incoming and outgoing.
 *
 * Without `viewerId` the split is guild-relative, so an internal shipment
 * legitimately appears in both lists — it is both leaving one member and
 * arriving at another. Pass `viewerId` for a single commander's personal view.
 */
export function transferTimeline(
  state: GameState,
  guildId: GuildId,
  now: number,
  viewerId?: PlayerId,
): TransferTimeline {
  const incoming: TransferRow[] = [];
  const outgoing: TransferRow[] = [];
  const all: TransferRow[] = [];

  const inGuild = (playerId: PlayerId): boolean => state.players[playerId]?.guildId === guildId;

  for (const transfer of state.transfers) {
    if (transfer.status !== 'in_transit') continue;

    const senderSide = viewerId ? transfer.fromId === viewerId : inGuild(transfer.fromId);
    const receiverSide = viewerId ? transfer.toId === viewerId : inGuild(transfer.toId);
    if (!senderSide && !receiverSide) continue;
    if (transfer.guildId !== guildId && !inGuild(transfer.fromId) && !inGuild(transfer.toId)) {
      continue;
    }

    const base = {
      transfer,
      fromName: state.players[transfer.fromId]?.name ?? 'UNKNOWN',
      toName: state.players[transfer.toId]?.name ?? 'UNKNOWN',
      crossGuild: !inGuild(transfer.fromId) || !inGuild(transfer.toId),
      progress: transferProgress(transfer, now),
      remainingMs: Math.max(0, transfer.arrivesAt - now),
      cancellable:
        canCancelTransfer(transfer, now) && (!viewerId || transfer.fromId === viewerId),
    };

    let row: TransferRow | undefined;
    if (receiverSide) {
      row = { ...base, direction: 'incoming' };
      incoming.push(row);
    }
    if (senderSide) {
      const out: TransferRow = { ...base, direction: 'outgoing' };
      outgoing.push(out);
      row = row ?? out;
    }
    if (row) all.push(row);
  }

  const bySoonest = (a: TransferRow, b: TransferRow): number =>
    a.transfer.arrivesAt - b.transfer.arrivesAt;
  incoming.sort(bySoonest);
  outgoing.sort(bySoonest);
  all.sort(bySoonest);

  return { incoming, outgoing, all };
}
