// ─────────────────────────────────────────────────────────────────────────────
// Guild sigil — procedural emblem from `guild.emblem` + `guild.color`
// ─────────────────────────────────────────────────────────────────────────────

/** Inner markup for each emblem index. Drawn inside a 64×64 viewBox. */
const EMBLEMS: string[] = [
  // 0 — chevron stack
  `<path d="M18 40l14-12 14 12" /><path d="M18 30l14-12 14 12" opacity=".55"/>`,
  // 1 — cleft delta
  `<path d="M32 14L48 46H16z"/><path d="M32 26l8 16H24z" opacity=".6"/>`,
  // 2 — targeting rings
  `<circle cx="32" cy="32" r="14"/><circle cx="32" cy="32" r="6" opacity=".65"/>
   <path d="M32 12v6M32 46v6M12 32h6M46 32h6"/>`,
  // 3 — four-point star
  `<path d="M32 12l5 15 15 5-15 5-5 15-5-15-15-5 15-5z"/>`,
  // 4 — split bar shield
  `<path d="M16 18h32v10H16z"/><path d="M22 32h20v14H22z" opacity=".6"/><path d="M32 18v28" opacity=".4"/>`,
  // 5 — radial spokes
  `<path d="M32 12v40M14.5 22l35 20M49.5 22l-35 20"/><circle cx="32" cy="32" r="5"/>`,
  // 6 — interlocked hexes
  `<path d="M32 12l12 7v14l-12 7-12-7V19z"/><path d="M32 24l8 4.6v9.2L32 42.4 24 37.8v-9.2z" opacity=".6"/>`,
  // 7 — blade & crossbar
  `<path d="M32 10l6 10-6 34-6-34z"/><path d="M18 26h28" opacity=".65"/>`,
];

const HEX_FRAME = 'M32 4l24.2 14v28L32 60 7.8 46V18z';

/**
 * Renders a guild banner as a self-contained inline SVG. Deterministic: the
 * same guild always produces the same mark.
 */
export function guildSigil(guild: Guild, size = 34): HTMLElement {
  const color = cssHex(guild.color);
  const inner = EMBLEMS[Math.abs(guild.emblem) % EMBLEMS.length];
  const gid = `sg${Math.abs(guild.emblem) % EMBLEMS.length}_${(guild.color >>> 0).toString(16)}`;

  const markup = `<svg viewBox="0 0 64 64" width="${size}" height="${size}" aria-hidden="true">
      <defs>
        <linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="64">
          <stop offset="0" stop-color="${color}" stop-opacity=".34"/>
          <stop offset="1" stop-color="${color}" stop-opacity=".05"/>
        </linearGradient>
      </defs>
      <path d="${HEX_FRAME}" fill="url(#${gid})" stroke="${color}" stroke-width="2.4"
            stroke-linejoin="round" opacity=".9"/>
      <g fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round"
         stroke-linecap="round">${inner}</g>
    </svg>`;

  const wrap = el('span', {
    class: 'sigil',
    style: `display:inline-flex;width:${size}px;height:${size}px;filter:drop-shadow(0 0 6px ${rgba(
      guild.color,
      0.55,
    )})`,
    aria: { label: `${guild.tag} banner` },
  });
  wrap.appendChild(svgEl(markup));
  return wrap;
}

/** Neutral mark for a commander with no guild. */
function unaffiliatedSigil(size = 34): HTMLElement {
  const markup = `<svg viewBox="0 0 64 64" width="${size}" height="${size}" aria-hidden="true">
      <path d="${HEX_FRAME}" fill="none" stroke="#475974" stroke-width="2.2"
            stroke-dasharray="6 5" stroke-linejoin="round"/>
      <path d="M24 32h16" stroke="#6e87a6" stroke-width="3" stroke-linecap="round"/>
    </svg>`;
  const wrap = el('span', {
    class: 'sigil',
    style: `display:inline-flex;width:${size}px;height:${size}px`,
    aria: { label: 'unaffiliated' },
  });
  wrap.appendChild(svgEl(markup));
  return wrap;
}

// ─────────────────────────────────────────────────────────────────────────────
// Top status bar
// ─────────────────────────────────────────────────────────────────────────────

export interface TopBarOpts {
  /** A notification row was tapped. */
  onNotification?: (n: GameNotification) => void;
  onMarkRead?: (id: string) => void;
  onClearAll?: () => void;
  /** Guild sigil tapped. */
  onSigil?: () => void;
}

const NOTIF_LIMIT = 40;

export class TopBar {
  readonly el: HTMLElement;

  private readonly sigilSlot: HTMLElement;
  private readonly seasonName: HTMLElement;
  private readonly bell: HTMLButtonElement;
  private readonly drawer: HTMLElement;
  private readonly drawerList: HTMLElement;
  private readonly mPill: ResourcePillController;
  private readonly gPill: ResourcePillController;
  private readonly opts: TopBarOpts;

  private clock: CountdownController;
  private seasonTarget = 0;
  private sigilKey = '';
  private notifKey = '';
  private drawerOpen = false;

  /** Simulated-clock estimator: state.now can advance faster than wall time. */
  private syncNow = Date.now();
  private syncWall = Date.now();
  private rate = 1;

  constructor(opts: TopBarOpts = {}) {
    this.opts = opts;

    this.sigilSlot = el('button', {
      class: 'topbar__sigil',
      attrs: { type: 'button' },
      aria: { label: 'guild' },
    });
    this.sigilSlot.addEventListener('click', () => {
      haptic(8);
      opts.onSigil?.();
    });

    this.seasonName = el('div', { class: 'topbar__season-name', text: 'SEASON' });
    this.clock = countdown(0, { compact: true, getNow: () => this.now(), doneText: 'ENDED' });
    const season = el('div', { class: 'topbar__season' }, this.seasonName, this.clock.el);

    this.mPill = resourcePill('m', 0, { small: true, cap: ECONOMY.capMinerals });
    this.gPill = resourcePill('g', 0, { small: true, cap: ECONOMY.capGas });
    const res = el('div', { class: 'topbar__res' }, this.mPill.el, this.gPill.el);

    this.bell = iconButton(ICONS.bell, {
      variant: 'bare',
      label: 'notifications',
      class: 'topbar__bell',
      onClick: () => this.toggleDrawer(),
    });

    const inner = el('div', { class: 'topbar__inner' }, this.sigilSlot, season, res, this.bell);

    this.drawerList = el('div', { class: 'notif__list' });
    const clearBtn = button('CLEAR', {
      variant: 'quiet',
      small: true,
      onClick: () => {
        this.opts.onClearAll?.();
        this.closeDrawer();
      },
    });
    this.drawer = el(
      'div',
      { class: 'notif' },
      panel(
        { title: 'SIGNAL LOG', subtitle: 'incoming traffic', actions: [clearBtn] },
        this.drawerList,
      ),
    );

    this.el = el('div', { class: 'topbar' }, inner, this.drawer);

    document.addEventListener('pointerdown', this.onDocPointer, true);
  }

  /** Estimated authoritative "now", extrapolated between backend pushes. */
  now(): number {
    return this.syncNow + (Date.now() - this.syncWall) * this.rate;
  }

  sync(state: GameState): void {
    // clock estimation
    const wall = Date.now();
    const dWall = wall - this.syncWall;
    const dNow = state.now - this.syncNow;
    if (dWall > 250 && dNow > 0) {
      const measured = dNow / dWall;
      if (measured > 0.05 && measured < 5000) this.rate = this.rate * 0.7 + measured * 0.3;
    }
    this.syncNow = state.now;
    this.syncWall = wall;

    const me = state.players[state.meId];
    if (me) {
      this.mPill.set(me.minerals);
      this.gPill.set(me.gas);
    }

    // season readout
    if (this.seasonName.textContent !== state.season.name) {
      this.seasonName.textContent = state.season.name;
    }
    if (state.season.endsAt !== this.seasonTarget) {
      this.seasonTarget = state.season.endsAt;
      this.clock.setTarget(state.season.endsAt);
    }

    // guild sigil
    const guild = me?.guildId ? state.guilds[me.guildId] : undefined;
    const key = guild ? `${guild.id}:${guild.emblem}:${guild.color}` : 'none';
    if (key !== this.sigilKey) {
      this.sigilKey = key;
      clear(this.sigilSlot);
      this.sigilSlot.appendChild(guild ? guildSigil(guild, 26) : unaffiliatedSigil(26));
    }

    // notifications
    const notes = state.notifications;
    const unread = notes.reduce((n, x) => n + (x.read ? 0 : 1), 0);
    this.bell.classList.toggle('has-unread', unread > 0);
    let badge = this.bell.querySelector<HTMLElement>('.icon-btn__badge');
    if (unread > 0) {
      if (!badge) {
        badge = el('span', { class: 'icon-btn__badge' });
        this.bell.appendChild(badge);
      }
      badge.textContent = unread > 99 ? '99+' : String(unread);
    } else if (badge) {
      badge.remove();
    }

    const nextKey = `${notes.length}:${unread}:${notes[0]?.id ?? ''}`;
    if (nextKey !== this.notifKey) {
      this.notifKey = nextKey;
      this.renderNotifications(notes, state.now);
    }
  }

  setHidden(hidden: boolean): void {
    this.el.classList.toggle('is-hidden', hidden);
    if (hidden) this.closeDrawer();
  }

  dispose(): void {
    document.removeEventListener('pointerdown', this.onDocPointer, true);
    this.clock.stop();
    this.el.remove();
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private onDocPointer = (ev: PointerEvent): void => {
    if (!this.drawerOpen) return;
    const t = ev.target as Node | null;
    if (t && (this.drawer.contains(t) || this.bell.contains(t))) return;
    this.closeDrawer();
  };

  private toggleDrawer(): void {
    if (this.drawerOpen) this.closeDrawer();
    else this.openDrawer();
  }

  private openDrawer(): void {
    this.drawerOpen = true;
    this.drawer.classList.add('is-open');
  }

  private closeDrawer(): void {
    this.drawerOpen = false;
    this.drawer.classList.remove('is-open');
  }

  private renderNotifications(notes: GameNotification[], now: number): void {
    clear(this.drawerList);
    if (notes.length === 0) {
      this.drawerList.appendChild(emptyState('◇', 'no signals logged'));
      return;
    }
    const ordered = [...notes].sort((a, b) => b.at - a.at).slice(0, NOTIF_LIMIT);
    for (const n of ordered) {
      const row = el('button', {
        class: `notif__item${n.read ? '' : ' is-unread'}`,
        attrs: { type: 'button' },
        data: { kind: n.kind },
      });
      row.appendChild(
        el(
          'div',
          { class: 'notif__row' },
          el('span', { class: 'notif__title', text: n.title }),
          el('span', { class: 'notif__at', text: fmtAgo(n.at, now) }),
        ),
      );
      row.appendChild(el('div', { class: 'notif__body', text: n.body }));
      row.addEventListener('click', () => {
        if (!n.read) this.opts.onMarkRead?.(n.id);
        this.opts.onNotification?.(n);
        this.closeDrawer();
      });
      this.drawerList.appendChild(row);
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Bottom dock
// ─────────────────────────────────────────────────────────────────────────────

export type DockKey = 'map' | 'guild' | 'diplomacy' | 'roster' | 'menu';

const DOCK_ICONS: Record<DockKey, string> = {
  map: `<svg viewBox="0 0 24 24"><path d="M12 2.2l3.8 2.2v4.4L12 11l-3.8-2.2V4.4z"/>
        <path d="M8.2 8.8L12 11v4.4L8.2 17.6 4.4 15.4V11z"/>
        <path d="M15.8 8.8L19.6 11v4.4l-3.8 2.2L12 15.4V11z"/></svg>`,
  guild: `<svg viewBox="0 0 24 24"><path d="M12 3l7.4 2.5v6.1c0 4.4-3.1 7.9-7.4 9.2-4.3-1.3-7.4-4.8-7.4-9.2V5.5z"/>
        <path d="M8.7 11.4l3.3 3 3.3-3"/></svg>`,
  diplomacy: `<svg viewBox="0 0 24 24"><path d="M4 4.2v15.6"/><path d="M4 5.4h7.4L9.6 8l1.8 2.6H4"/>
        <path d="M20 19.8V4.2"/><path d="M20 18.6h-7.4l1.8-2.6-1.8-2.6H20"/></svg>`,
  roster: `<svg viewBox="0 0 24 24"><circle cx="6.4" cy="6.8" r="2.6"/>
        <path d="M2.5 12.6c.5-1.9 2-2.9 3.9-2.9s3.4 1 3.9 2.9"/>
        <path d="M13.6 6.8h7.9M13.6 11.2h7.9M2.5 16.2h19M2.5 19.8h12.5"/></svg>`,
  menu: `<svg viewBox="0 0 24 24"><path d="M3.5 7h8.5M17.5 7h3M3.5 12h3.5M11 12h9.5M3.5 17h11M19.5 17h1"/>
        <circle cx="14.8" cy="7" r="2.1"/><circle cx="9" cy="12" r="2.1"/><circle cx="17" cy="17" r="2.1"/></svg>`,
};

const DOCK_ITEMS: { key: DockKey; label: string; screen?: ScreenId }[] = [
  { key: 'map', label: 'MAP', screen: 'map' },
  { key: 'guild', label: 'GUILD', screen: 'guild' },
  { key: 'diplomacy', label: 'PARLEY', screen: 'diplomacy' },
  { key: 'roster', label: 'ROSTER', screen: 'guild' },
  { key: 'menu', label: 'MENU' },
];

export interface DockOpts {
  /** Overrides the built-in settings modal. */
  onMenu?: () => void;
}

export class Dock {
  readonly el: HTMLElement;

  private readonly glow: HTMLElement;
  private readonly buttons = new Map<DockKey, HTMLButtonElement>();
  private readonly cbs: ((screen: ScreenId) => void)[] = [];
  private readonly ro: ResizeObserver;
  private active: DockKey = 'map';

  constructor(opts: DockOpts = {}) {
    const inner = el('div', { class: 'dock__inner' });
    this.glow = el('div', { class: 'dock__glow', aria: { hidden: 'true' } });
    inner.appendChild(this.glow);

    for (const item of DOCK_ITEMS) {
      const btn = el('button', {
        class: 'dock__btn',
        attrs: { type: 'button' },
        data: { dock: item.key },
        aria: { label: item.label },
      });
      btn.insertAdjacentHTML('beforeend', DOCK_ICONS[item.key]);
      btn.appendChild(el('span', { text: item.label }));
      btn.addEventListener('click', () => {
        haptic(11);
        if (item.key === 'menu') {
          if (opts.onMenu) opts.onMenu();
          else openShellMenu({});
          return;
        }
        if (item.key === 'roster') view.patch({ guildTab: 'roster' });
        if (item.key === 'guild' && view.get().guildTab === 'roster') {
          view.patch({ guildTab: 'chat' });
        }
        this.setActiveKey(item.key);
        if (item.screen) for (const cb of this.cbs) cb(item.screen);
      });
      this.buttons.set(item.key, btn);
      inner.appendChild(btn);
    }

    this.el = el('nav', { class: 'dock', aria: { label: 'primary' } }, inner);

    this.ro = new ResizeObserver(() => this.place());
    this.ro.observe(inner);
    requestAnimationFrame(() => this.place());
  }

  setActive(screen: ScreenId): void {
    if (screen === 'map') this.setActiveKey('map');
    else if (screen === 'diplomacy') this.setActiveKey('diplomacy');
    else if (screen === 'guild') {
      this.setActiveKey(view.get().guildTab === 'roster' ? 'roster' : 'guild');
    } else this.setActiveKey(null);
  }

  onSelect(cb: (screen: ScreenId) => void): void {
    this.cbs.push(cb);
  }

  setHidden(hidden: boolean): void {
    this.el.classList.toggle('is-hidden', hidden);
  }

  dispose(): void {
    this.ro.disconnect();
    this.cbs.length = 0;
    this.el.remove();
  }

  private setActiveKey(key: DockKey | null): void {
    for (const [k, btn] of this.buttons) btn.classList.toggle('is-active', k === key);
    if (key) {
      this.active = key;
      this.glow.style.opacity = '1';
    } else {
      this.glow.style.opacity = '0';
    }
    this.place();
  }

  private place(): void {
    const btn = this.buttons.get(this.active);
    if (!btn || btn.offsetWidth <= 0) return;
    this.glow.style.width = `${btn.offsetWidth}px`;
    this.glow.style.transform = `translateX(${btn.offsetLeft}px)`;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Shell settings menu
// ─────────────────────────────────────────────────────────────────────────────

const SETTINGS_KEY = 'tb:settings';

interface ShellSettings {
  lowSpec: boolean;
  reduceMotion: boolean;
}

function readSettings(): ShellSettings {
  try {
    const raw = window.localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<ShellSettings>;
      return { lowSpec: parsed.lowSpec === true, reduceMotion: parsed.reduceMotion === true };
    }
  } catch {
    /* storage unavailable — fall through to defaults */
  }
  return { lowSpec: false, reduceMotion: false };
}

function writeSettings(s: ShellSettings): void {
  try {
    window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(s));
  } catch {
    /* ignore */
  }
}

/** Applies persisted shell settings. Called once at boot by the app shell. */
export function applyStoredSettings(): void {
  const s = readSettings();
  document.body.classList.toggle('reduce-motion', s.reduceMotion);
  if (s.lowSpec !== view.get().lowSpec) view.patch({ lowSpec: s.lowSpec });
}

function toggleRow(
  name: string,
  hint: string,
  value: boolean,
  onChange: (next: boolean) => void,
): HTMLElement {
  const knob = el('span', { class: value ? 'switch is-on' : 'switch', aria: { hidden: 'true' } });
  const row = el(
    'button',
    { class: 'menu-toggle', attrs: { type: 'button' }, aria: { pressed: value } },
    el(
      'span',
      { class: 'menu-toggle__text' },
      el('span', { class: 'menu-toggle__name', text: name }),
      el('span', { class: 'menu-toggle__hint', text: hint }),
    ),
    knob,
  );
  let state = value;
  row.addEventListener('click', () => {
    state = !state;
    knob.classList.toggle('is-on', state);
    row.setAttribute('aria-pressed', String(state));
    haptic(9);
    onChange(state);
  });
  return row;
}

export interface ShellMenuOpts {
  /** Present the commander's callsign with a rename affordance. */
  commanderName?: string;
  onRename?: () => void;
  /** Extra rows appended below the standard settings. */
  extra?: HTMLElement[];
}

/** The MENU destination: renderer, motion and map-overlay preferences. */
export function openShellMenu(opts: ShellMenuOpts): void {
  const settings = readSettings();
  const layers = view.get().layers;

  const body = el('div', { class: 'menu-grid' });

  if (opts.commanderName) {
    body.appendChild(sectionHeader('COMMANDER'));
    const row = el(
      'div',
      { class: 'row' },
      el('span', { class: 'grow truncate display', text: opts.commanderName }),
    );
    if (opts.onRename) {
      row.appendChild(button('RENAME', { variant: 'ghost', small: true, onClick: opts.onRename }));
    }
    body.appendChild(row);
  }

  body.appendChild(sectionHeader('DISPLAY'));
  body.appendChild(
    toggleRow('LOW-SPEC RENDERER', 'fewer effects, higher frame rate', settings.lowSpec, (next) => {
      settings.lowSpec = next;
      writeSettings(settings);
      view.patch({ lowSpec: next });
    }),
  );
  body.appendChild(
    toggleRow('REDUCE MOTION', 'stills instead of sweeps', settings.reduceMotion, (next) => {
      settings.reduceMotion = next;
      writeSettings(settings);
      document.body.classList.toggle('reduce-motion', next);
    }),
  );

  body.appendChild(sectionHeader('MAP OVERLAYS'));
  const layerDefs: { key: keyof typeof layers; name: string; hint: string }[] = [
    { key: 'pings', name: 'PINGS', hint: 'guild tactical markers' },
    { key: 'marks', name: 'MARKS', hint: 'persistent annotations' },
    { key: 'intel', name: 'INTEL', hint: 'last-seen drone snapshots' },
    { key: 'objectives', name: 'OBJECTIVES', hint: 'guild objective targets' },
    { key: 'yields', name: 'YIELDS', hint: 'per-hex resource output' },
  ];
  for (const def of layerDefs) {
    body.appendChild(
      toggleRow(def.name, def.hint, layers[def.key], (next) => {
        const nextLayers = { ...view.get().layers };
        nextLayers[def.key] = next;
        view.patch({ layers: nextLayers });
      }),
    );
  }

  if (opts.extra?.length) {
    body.appendChild(sectionHeader('SESSION'));
    for (const node of opts.extra) body.appendChild(node);
  }

  body.appendChild(
    el(
      'div',
      { class: 'menu-meta' },
      el('span', { text: 'TERRA BELLUM — ORBITAL COMMAND CONSOLE' }),
      el('span', { text: `PALETTE ${GUILD_COLORS.length} BANNERS · BUILD 1.0.0` }),
    ),
  );

  openModal({ title: 'SYSTEMS', body, actions: [{ label: 'CLOSE', variant: 'ghost' }] });
}
