/**
 * Minimal DOM toolkit. Every UI module builds with these helpers so markup
 * stays declarative and disposal stays leak-free.
 */

export type Child = Node | string | number | null | undefined | false;

export interface ElProps {
  class?: string;
  id?: string;
  text?: string;
  html?: string;
  style?: Partial<CSSStyleDeclaration> | string;
  attrs?: Record<string, string | number | boolean | undefined>;
  data?: Record<string, string | number | undefined>;
  on?: Partial<Record<keyof HTMLElementEventMap, (ev: never) => void>> & Record<string, (ev: never) => void>;
  aria?: Record<string, string | number | boolean | undefined>;
}

export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: ElProps = {},
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (props.class) node.className = props.class;
  if (props.id) node.id = props.id;
  if (props.text !== undefined) node.textContent = props.text;
  if (props.html !== undefined) node.innerHTML = props.html;
  if (props.style) {
    if (typeof props.style === 'string') node.setAttribute('style', props.style);
    else Object.assign(node.style, props.style);
  }
  if (props.attrs) {
    for (const [k, v] of Object.entries(props.attrs)) {
      if (v === undefined || v === false) continue;
      node.setAttribute(k, v === true ? '' : String(v));
    }
  }
  if (props.aria) {
    for (const [k, v] of Object.entries(props.aria)) {
      if (v === undefined) continue;
      node.setAttribute(k.startsWith('aria-') ? k : `aria-${k}`, String(v));
    }
  }
  if (props.data) {
    for (const [k, v] of Object.entries(props.data)) {
      if (v === undefined) continue;
      node.dataset[k] = String(v);
    }
  }
  if (props.on) {
    for (const [k, fn] of Object.entries(props.on)) {
      node.addEventListener(k, fn as EventListener);
    }
  }
  append(node, children);
  return node;
}

export function append(parent: Node, children: Child[]): void {
  for (const c of children) {
    if (c === null || c === undefined || c === false) continue;
    parent.appendChild(typeof c === 'object' ? c : document.createTextNode(String(c)));
  }
}

export function frag(...children: Child[]): DocumentFragment {
  const f = document.createDocumentFragment();
  append(f, children);
  return f;
}

/** Build an SVG element from a raw markup string. */
export function svg(markup: string, className?: string): SVGElement {
  const wrap = document.createElement('div');
  wrap.innerHTML = markup.trim();
  const node = wrap.firstElementChild as SVGElement;
  if (className) node.setAttribute('class', className);
  return node;
}

export function clear(node: Node): void {
  while (node.firstChild) node.removeChild(node.firstChild);
}

export function qs<T extends Element = HTMLElement>(sel: string, root: ParentNode = document): T | null {
  return root.querySelector<T>(sel);
}

export function qsa<T extends Element = HTMLElement>(sel: string, root: ParentNode = document): T[] {
  return Array.from(root.querySelectorAll<T>(sel));
}

/** Collects teardown functions. */
export class Disposer {
  private fns: (() => void)[] = [];
  add(fn: () => void): void {
    this.fns.push(fn);
  }
  listen<K extends keyof WindowEventMap>(
    target: EventTarget,
    type: K | string,
    fn: (ev: never) => void,
    opts?: AddEventListenerOptions,
  ): void {
    target.addEventListener(type, fn as EventListener, opts);
    this.fns.push(() => target.removeEventListener(type, fn as EventListener, opts));
  }
  interval(fn: () => void, ms: number): void {
    const h = window.setInterval(fn, ms);
    this.fns.push(() => window.clearInterval(h));
  }
  raf(fn: (dt: number) => void): void {
    let running = true;
    let last = performance.now();
    const loop = (t: number) => {
      if (!running) return;
      const dt = Math.min(64, t - last);
      last = t;
      fn(dt);
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
    this.fns.push(() => {
      running = false;
    });
  }
  dispose(): void {
    for (const fn of this.fns.splice(0)) {
      try {
        fn();
      } catch {
        /* ignore */
      }
    }
  }
}

// ── formatting helpers ──────────────────────────────────────────────────────

export function fmtNum(n: number): string {
  if (!Number.isFinite(n)) return '—';
  const abs = Math.abs(n);
  if (abs >= 1_000_000) return (n / 1_000_000).toFixed(abs >= 10_000_000 ? 0 : 1) + 'M';
  if (abs >= 10_000) return (n / 1000).toFixed(0) + 'K';
  if (abs >= 1000) return (n / 1000).toFixed(1) + 'K';
  return Math.round(n).toString();
}

export function fmtDuration(ms: number): string {
  if (ms <= 0) return '00:00';
  const s = Math.floor(ms / 1000);
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  if (d > 0) return `${d}d ${h.toString().padStart(2, '0')}h`;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;
  return `${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;
}

export function fmtClock(at: number): string {
  const d = new Date(at);
  return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
}

export function fmtAgo(at: number, now: number): string {
  const ms = Math.max(0, now - at);
  if (ms < 60_000) return 'now';
  if (ms < 3_600_000) return `${Math.floor(ms / 60_000)}m ago`;
  if (ms < 86_400_000) return `${Math.floor(ms / 3_600_000)}h ago`;
  return `${Math.floor(ms / 86_400_000)}d ago`;
}

export const cssHex = (n: number): string => '#' + (n >>> 0).toString(16).padStart(6, '0');

export function rgba(hex: number, a: number): string {
  return `rgba(${(hex >> 16) & 255}, ${(hex >> 8) & 255}, ${hex & 255}, ${a})`;
}

export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) =>
    c === '&' ? '&amp;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '"' ? '&quot;' : '&#39;',
  );
}

/** Haptic feedback where available; silently ignored elsewhere. */
export function haptic(pattern: number | number[] = 12): void {
  try {
    navigator.vibrate?.(pattern);
  } catch {
    /* ignore */
  }
}
