/**
 * Strategic-layer movement — GDD §3.4, §6, §7.3.
 *
 * Armies walk hex-to-hex in real time. Arrivals resolve into one of: a battle
 * trigger, a siege wait against a Citadel, a capture timer, or nothing.
 *
 * PURE: no Three.js, no DOM.
 */
import type {
  Army,
  ArmyId,
  ArmyUnit,
  GameState,
  Hex,
  HexId,
  MoveStep,
  PlayerId,
  Result,
  UnitId,
  UnitType,
  WorldState,
} from '../types';
import { err, ok } from '../types';
import { BATTLE, FORT_RULES, MAP } from '../../config/balance';
import { UNITS } from '../../config/units';
import { findPath, hexDistanceId, neighborIds } from '../hex';
import { uid } from '../rng';
import { isHexOpen } from './generate';
import { destroyFort } from './fortify';

// ─────────────────────────────────────────────────────────────────────────────
// Events
// ─────────────────────────────────────────────────────────────────────────────

export type MoveEvent =
  | { t: 'arrived'; at: number; armyId: ArmyId; hexId: HexId; fromHexId: HexId }
  | { t: 'battle_trigger'; at: number; armyId: ArmyId; hexId: HexId; defenderArmyId: ArmyId }
  | {
      t: 'siege_started';
      at: number;
      armyId: ArmyId;
      hexId: HexId;
      defenderArmyId: ArmyId;
      readyAt: number;
    }
  | { t: 'capture_started'; at: number; armyId: ArmyId; hexId: HexId; completesAt: number }
  | { t: 'blocked'; at: number; armyId: ArmyId; hexId: HexId; reason: string };

export type CaptureEvent =
  | {
      t: 'captured';
      at: number;
      hexId: HexId;
      armyId: ArmyId;
      playerId: PlayerId;
      guildId: string;
      previousOwnerId?: PlayerId;
    }
  | { t: 'capture_cancelled'; at: number; hexId: HexId; armyId: ArmyId; reason: string };

// ─────────────────────────────────────────────────────────────────────────────
// Faction helpers (a guildless commander is his own faction)
// ─────────────────────────────────────────────────────────────────────────────

export function factionOf(state: GameState, playerId: PlayerId): string {
  const player = state.players[playerId];
  return player?.guildId ?? playerId;
}

export function areHostile(state: GameState, a: PlayerId, b: PlayerId): boolean {
  if (a === b) return false;
  return factionOf(state, a) !== factionOf(state, b);
}

export function armiesOnHex(state: GameState, hexId: HexId): Army[] {
  const out: Army[] = [];
  for (const army of Object.values(state.armies)) {
    if (army.hexId === hexId) out.push(army);
  }
  return out.sort((x, y) => (x.id < y.id ? -1 : 1));
}

/** The first hostile army standing on a hex, relative to `playerId`. */
export function hostileArmyOnHex(
  state: GameState,
  hexId: HexId,
  playerId: PlayerId,
): Army | undefined {
  for (const army of armiesOnHex(state, hexId)) {
    if (army.units.length === 0) continue;
    if (areHostile(state, army.ownerId, playerId)) return army;
  }
  return undefined;
}

// ─────────────────────────────────────────────────────────────────────────────
// Timing
// ─────────────────────────────────────────────────────────────────────────────

/** Milliseconds for one army step onto `hexId` (GDD §3.4). */
export function stepMs(world: WorldState, hexId: HexId): number {
  const hex = world.hexes[hexId];
  const mult = hex ? MAP.moveCostByTerrain[hex.terrain] : 1;
  return Math.round(MAP.moveMsPerHex * mult);
}

/**
 * Capture duration — forts must be reduced before ownership flips (GDD §6).
 *
 * Occupied ground costs more than unclaimed dirt: this timer is the window in
 * which the owner (and their guild) can march something back onto the hex and
 * break the capture, so ground that belongs to a person is deliberately slower
 * to take than ground that belongs to nobody. See `MAP.captureMs` for the
 * real-time table this produces.
 */
export function captureDurationMs(hex: Hex): number {
  const owned = hex.ownerId ? MAP.captureMsOwnedBonus : 0;
  return MAP.captureMs + owned + MAP.captureMsPerFortLevel * hex.fortLevel;
}

// ─────────────────────────────────────────────────────────────────────────────
// Post-march regroup (movement cooldown)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A column that has just come to a stop must regroup before it can be sent
 * anywhere else. Without it the strategic layer has no defensive tempo at all:
 * an attacker takes a hex and is already walking off it, and nobody ever gets a
 * window in which to answer.
 *
 * The gate lives in `beginMove` on purpose — that is the single chokepoint
 * every march passes through. `MockBackend.moveArmy` delegates straight to it
 * and the bot director calls it directly, so players and AI are bound by the
 * same clock. A cooldown that only applied to the human would be worse than
 * none at all.
 *
 * Explicitly NOT gated: `haltArmy` (stopping is always allowed), `retreatArmy`
 * and the sector-shutdown force-retreat, which route through `clearOrders` and
 * never touch the stamp.
 */

/** How much longer this column must regroup. 0 once it is free to march. */
export function moveCooldownRemaining(army: Army, now: number): number {
  const until = army.moveReadyAt;
  if (until === undefined) return 0;
  return Math.max(0, until - now);
}

/** Convenience predicate for the UI. */
export function isRegrouping(army: Army, now: number): boolean {
  return moveCooldownRemaining(army, now) > 0;
}

/** Stamp the regroup window. Called wherever a march comes to a stop. */
function beginRegroup(army: Army, at: number): void {
  army.moveReadyAt = at + MAP.moveCooldownMs;
}

/** `mm:ss` / `h:mm` for a player-facing refusal. Pure — no UI imports here. */
function fmtWait(ms: number): string {
  const total = Math.ceil(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Pathing
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A* to `destHexId`. Locked / not-yet-open sectors are refused; the destination
 * may be enemy-occupied (that is how a battle is picked).
 */
export function planPath(state: GameState, armyId: ArmyId, destHexId: HexId): Result<HexId[]> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  const world = state.world;
  const dest = world.hexes[destHexId];
  if (!dest) return err('destination is outside the world');
  if (!isHexOpen(world, destHexId)) return err('destination sector is locked');
  if (!world.hexes[army.hexId]) return err('army is not on the map');
  if (army.hexId === destHexId) return err('army is already there');

  const passable = (id: HexId): boolean => isHexOpen(world, id);
  const cost = (id: HexId): number => {
    const hex = world.hexes[id];
    return hex ? MAP.moveCostByTerrain[hex.terrain] : 1;
  };
  const path = findPath(army.hexId, destHexId, passable, cost);
  if (!path || path.length === 0) return err('no route through open sectors');
  return ok(path);
}

/** Issue a march order: writes `army.path` with cumulative arrival stamps. */
export function beginMove(
  state: GameState,
  armyId: ArmyId,
  destHexId: HexId,
  now: number,
): Result<void> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  if (army.units.length === 0) return err('army has no units');

  // The regroup gate. Binds the local commander, every rival guild and every
  // bot identically, because every march in the game arrives here.
  const regroup = moveCooldownRemaining(army, now);
  if (regroup > 0) {
    return err(`${army.name} is regrouping — ready to march in ${fmtWait(regroup)}`);
  }

  const planned = planPath(state, armyId, destHexId);
  if (!planned.ok) return err(planned.error);

  const steps: MoveStep[] = [];
  let at = now;
  for (const hexId of planned.value) {
    at += stepMs(state.world, hexId);
    steps.push({ hexId, arrivesAt: at });
  }
  army.path = steps;
  army.movingFrom = army.hexId;
  army.departedAt = now;
  army.arrivesAt = steps[0].arrivesAt;
  army.siege = undefined;
  return ok(undefined);
}

/**
 * Cancel remaining movement. The army holds the hex it currently occupies.
 *
 * Never gated by the regroup window and never starts one: stopping is always
 * allowed, and a column that pulled up short never actually took ground.
 */
export function haltArmy(state: GameState, armyId: ArmyId): Result<void> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  if (army.path.length === 0 && army.arrivesAt === undefined) return err('army is not moving');
  clearOrders(army);
  return ok(undefined);
}

/**
 * Drop every queued order without moving the army.
 *
 * Deliberately leaves `moveReadyAt` alone. Sector shutdown (rotation) and the
 * post-battle retreat both come through here, and neither may be turned into a
 * punishment — nor may either hand out a free reset of a regroup already owed.
 */
export function clearOrders(army: Army): void {
  army.path = [];
  army.movingFrom = undefined;
  army.departedAt = undefined;
  army.arrivesAt = undefined;
  army.siege = undefined;
}


// ─────────────────────────────────────────────────────────────────────────────
// Arrival resolution
// ─────────────────────────────────────────────────────────────────────────────

/** Advance every army whose next leg is due. One leg at a time. */
export function tickArmies(state: GameState, now: number): MoveEvent[] {
  const out: MoveEvent[] = [];
  for (const army of Object.values(state.armies)) {
    let guard = 0;
    while (army.arrivesAt !== undefined && army.arrivesAt <= now && guard++ < 1024) {
      if (!advanceLeg(state, army, now, out)) break;
    }
  }
  return out;
}

function advanceLeg(state: GameState, army: Army, now: number, out: MoveEvent[]): boolean {
  const step = army.path[0];
  if (!step) {
    clearOrders(army);
    return false;
  }
  const world = state.world;
  const hex = world.hexes[step.hexId];
  if (!hex || !isHexOpen(world, step.hexId)) {
    out.push({
      t: 'blocked',
      at: now,
      armyId: army.id,
      hexId: step.hexId,
      reason: hex ? 'sector closed ahead of the column' : 'hex no longer exists',
    });
    clearOrders(army);
    return false;
  }

  const at = step.arrivesAt;
  const defender = hostileArmyOnHex(state, step.hexId, army.ownerId);

  // GDD §6 — a Citadel forces a siege wait before the battle may start.
  if (defender && hex.fortLevel === 3) {
    if (!army.siege || army.siege.hexId !== step.hexId) {
      const readyAt = at + FORT_RULES.siegeMs;
      army.siege = { hexId: step.hexId, startedAt: at, readyAt };
      step.arrivesAt = readyAt;
      army.arrivesAt = readyAt;
      out.push({
        t: 'siege_started',
        at,
        armyId: army.id,
        hexId: step.hexId,
        defenderArmyId: defender.id,
        readyAt,
      });
      return true;
    }
    if (army.siege.readyAt > now) return false;
  }

  const fromHexId = army.hexId;
  army.hexId = step.hexId;
  army.path.shift();
  army.siege = undefined;
  out.push({ t: 'arrived', at, armyId: army.id, hexId: step.hexId, fromHexId });

  // Any hostile capture running here is broken by the arrival.
  if (hex.capture && areHostile(state, hex.capture.playerId, army.ownerId)) {
    hex.capture = undefined;
  }

  if (defender) {
    clearOrders(army);
    beginRegroup(army, at);
    out.push({
      t: 'battle_trigger',
      at,
      armyId: army.id,
      hexId: step.hexId,
      defenderArmyId: defender.id,
    });
    return false;
  }

  const contestable = !hex.ownerId || areHostile(state, hex.ownerId, army.ownerId);
  if (contestable && (!hex.capture || hex.capture.armyId !== army.id)) {
    const completesAt = at + captureDurationMs(hex);
    hex.capture = {
      playerId: army.ownerId,
      guildId: factionOf(state, army.ownerId),
      armyId: army.id,
      startedAt: at,
      completesAt,
    };
    out.push({ t: 'capture_started', at, armyId: army.id, hexId: hex.id, completesAt });
  }

  if (army.path.length > 0) {
    // Mid-march. A leg is not an arrival, so no regroup is owed yet.
    army.movingFrom = step.hexId;
    army.departedAt = at;
    army.arrivesAt = army.path[0].arrivesAt;
    return true;
  }
  // End of the march: the column has taken this ground and must now hold it.
  clearOrders(army);
  beginRegroup(army, at);
  return false;
}

/** Resolve capture timers. Ownership flips only once the timer has run out. */
export function tickCaptures(state: GameState, now: number): CaptureEvent[] {
  const out: CaptureEvent[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    const cap = hex.capture;
    if (!cap) continue;

    const army = state.armies[cap.armyId];
    if (!army || army.hexId !== hex.id || army.units.length === 0) {
      hex.capture = undefined;
      out.push({
        t: 'capture_cancelled',
        at: now,
        hexId: hex.id,
        armyId: cap.armyId,
        reason: 'the capturing force left the hex',
      });
      continue;
    }
    if (hostileArmyOnHex(state, hex.id, cap.playerId)) {
      hex.capture = undefined;
      out.push({
        t: 'capture_cancelled',
        at: now,
        hexId: hex.id,
        armyId: cap.armyId,
        reason: 'hex contested',
      });
      continue;
    }
    if (cap.completesAt > now) continue;

    const previousOwnerId = hex.ownerId;
    hex.ownerId = cap.playerId;
    destroyFort(hex);
    hex.production = [];
    hex.reserves = {};
    hex.capture = undefined;
    out.push({
      t: 'captured',
      at: cap.completesAt,
      hexId: hex.id,
      armyId: cap.armyId,
      playerId: cap.playerId,
      guildId: cap.guildId,
      previousOwnerId,
    });
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Army composition
// ─────────────────────────────────────────────────────────────────────────────

function isMoving(army: Army): boolean {
  return army.arrivesAt !== undefined || army.path.length > 0;
}

/** Split units out into a new army standing on the same hex. */
export function splitArmy(state: GameState, armyId: ArmyId, unitIds: UnitId[]): Result<ArmyId> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  if (isMoving(army)) return err('halt the column before splitting it');
  if (unitIds.length === 0) return err('select at least one unit');

  const wanted = new Set(unitIds);
  const taken: ArmyUnit[] = [];
  const kept: ArmyUnit[] = [];
  for (const unit of army.units) {
    if (wanted.has(unit.id)) taken.push(unit);
    else kept.push(unit);
  }
  if (taken.length !== wanted.size) return err('some units are not in this army');
  if (kept.length === 0) return err('a split must leave units behind');

  const owned = Object.values(state.armies).filter((a) => a.ownerId === army.ownerId).length;
  const id = uid('army');
  army.units = kept;
  state.armies[id] = {
    id,
    ownerId: army.ownerId,
    guildId: army.guildId,
    name: `${army.name} · DET-${String(owned + 1).padStart(2, '0')}`,
    hexId: army.hexId,
    units: taken,
    path: [],
    // A detachment inherits the parent's regroup — peeling off two chassis is
    // not a way to walk a fresh column off a hex you only just took.
    moveReadyAt: army.moveReadyAt,
  };
  return ok(id);
}

/** Merge two co-located armies owned by the same commander. */
export function mergeArmies(
  state: GameState,
  intoArmyId: ArmyId,
  fromArmyId: ArmyId,
): Result<void> {
  const into = state.armies[intoArmyId];
  const from = state.armies[fromArmyId];
  if (!into || !from) return err('no such army');
  if (into.id === from.id) return err('cannot merge an army into itself');
  if (into.ownerId !== from.ownerId) return err('armies have different commanders');
  if (into.hexId !== from.hexId) return err('armies are not on the same hex');
  if (isMoving(into) || isMoving(from)) return err('halt both columns before merging');
  if (into.units.length + from.units.length > BATTLE.armyCap) {
    return err(`an army carries at most ${BATTLE.armyCap} units`);
  }
  into.units = [...into.units, ...from.units];
  // The merged force is ready no sooner than its slowest half.
  const readyAt = Math.max(into.moveReadyAt ?? 0, from.moveReadyAt ?? 0);
  into.moveReadyAt = readyAt > 0 ? readyAt : undefined;
  delete state.armies[fromArmyId];
  return ok(undefined);
}

/** Move units from an army into the reserve garrison of the hex it stands on. */
export function garrisonUnits(state: GameState, armyId: ArmyId, unitIds: UnitId[]): Result<void> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  if (isMoving(army)) return err('halt the column before garrisoning');
  const hex = state.world.hexes[army.hexId];
  if (!hex) return err('army is not on the map');
  if (hex.ownerId !== army.ownerId) return err('you do not hold this hex');
  if (unitIds.length === 0) return err('select at least one unit');

  const wanted = new Set(unitIds);
  const kept: ArmyUnit[] = [];
  const moved: ArmyUnit[] = [];
  for (const unit of army.units) {
    if (wanted.has(unit.id)) moved.push(unit);
    else kept.push(unit);
  }
  if (moved.length !== wanted.size) return err('some units are not in this army');

  for (const unit of moved) {
    hex.reserves[unit.type] = (hex.reserves[unit.type] ?? 0) + 1;
  }
  army.units = kept;
  if (army.units.length === 0) delete state.armies[armyId];
  return ok(undefined);
}

/** Pull reserve units out of a hex garrison and into a co-located army. */
export function withdrawUnits(
  state: GameState,
  armyId: ArmyId,
  hexId: HexId,
  take: Partial<Record<UnitType, number>>,
): Result<void> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  if (isMoving(army)) return err('halt the column before loading reserves');
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (army.hexId !== hexId) return err('army is not on that hex');
  if (hex.ownerId !== army.ownerId) return err('you do not hold this hex');

  let total = 0;
  for (const [type, want] of Object.entries(take) as [UnitType, number][]) {
    if (!want || want <= 0) continue;
    const have = hex.reserves[type] ?? 0;
    if (want > have) return err(`only ${have} ${UNITS[type].name} in reserve`);
    total += want;
  }
  if (total === 0) return err('select at least one unit');
  if (army.units.length + total > BATTLE.armyCap) {
    return err(`an army carries at most ${BATTLE.armyCap} units`);
  }

  for (const [type, want] of Object.entries(take) as [UnitType, number][]) {
    if (!want || want <= 0) continue;
    for (let i = 0; i < want; i++) {
      army.units.push({ id: uid('u'), type, hp: UNITS[type].hp });
    }
    const left = (hex.reserves[type] ?? 0) - want;
    if (left > 0) hex.reserves[type] = left;
    else delete hex.reserves[type];
  }
  return ok(undefined);
}

// ─────────────────────────────────────────────────────────────────────────────
// Retreat (GDD §7.3)
// ─────────────────────────────────────────────────────────────────────────────

/** Can a retreating army stand here? */
function retreatViable(state: GameState, army: Army, id: HexId): boolean {
  const hex = state.world.hexes[id];
  if (!hex) return false;
  if (!isHexOpen(state.world, id)) return false;
  if (hex.ownerId && areHostile(state, hex.ownerId, army.ownerId)) return false;
  if (hostileArmyOnHex(state, id, army.ownerId)) return false;
  return true;
}

function retreatRank(state: GameState, army: Army, id: HexId): number {
  const hex = state.world.hexes[id];
  if (!hex) return 9;
  if (hex.ownerId === army.ownerId) return 0;
  if (hex.ownerId) return 1; // allied territory
  return 2; // neutral ground
}

/**
 * Fall back one hex. Attackers retreat toward the hex they came from; anyone
 * else takes the nearest friendly or neutral adjacent hex. With nowhere to go
 * the army is destroyed (GDD §7.3).
 *
 * Never gated by the regroup window and never starts one. A beaten column
 * being pushed off a hex — and a column force-retreated out of a sector that
 * has just shut down — is not making a choice, so there is nothing to price.
 */
export function retreatArmy(
  state: GameState,
  armyId: ArmyId,
  fromHexId: HexId,
  now: number,
): Result<HexId> {
  const army = state.armies[armyId];
  if (!army) return err('no such army');
  const origin = army.hexId;

  let target: HexId | undefined;
  if (
    fromHexId &&
    fromHexId !== origin &&
    hexDistanceId(fromHexId, origin) === 1 &&
    retreatViable(state, army, fromHexId)
  ) {
    target = fromHexId;
  } else {
    const options = neighborIds(origin).filter((id) => retreatViable(state, army, id));
    options.sort((a, b) => {
      const ra = retreatRank(state, army, a);
      const rb = retreatRank(state, army, b);
      if (ra !== rb) return ra - rb;
      const fa = state.world.hexes[a]?.fortLevel ?? 0;
      const fb = state.world.hexes[b]?.fortLevel ?? 0;
      if (fa !== fb) return fb - fa;
      return a < b ? -1 : 1;
    });
    target = options[0];
  }

  const originHex = state.world.hexes[origin];
  if (originHex?.capture?.armyId === armyId) originHex.capture = undefined;

  if (!target) {
    delete state.armies[armyId];
    return err('no retreat lane — the army was destroyed');
  }

  // The fall-back is instantaneous — the army is simply standing on `target`
  // as of `now`, with every queued order cancelled.
  clearOrders(army);
  army.hexId = target;
  return ok(target);
}

/**
 * Is a battle sitting in its grace window (GDD §7.4) waiting for the LOCAL
 * human to answer?
 *
 * Pure so the offline sim can ask it every tick. It exists because the mock
 * backend compresses world time (`SIM.timeScale`), and a compressed clock must
 * never be allowed to run out a deadline that belongs to a person: five minutes
 * of game time at 90× is 3.3 real seconds, which silently handed every
 * defensive battle to the auto-defense AI before the player could answer.
 */
export function awaitingHumanAnswer(state: GameState): boolean {
  const me = state.players[state.meId];
  if (!me || me.bot) return false;
  return state.pendingBattles.some((pb) => !pb.accepted && pb.defenderId === state.meId);
}
