/**
 * Seeded, logged PRNG.
 *
 * GDD §13: "Dice rolls and battle logic run behind seeded, logged interfaces so
 * any battle is replayable deterministically." Every draw is recorded, so a
 * battle can be replayed from (seed, log) alone.
 */

export interface Rng {
  readonly seed: number;
  /** Uniform float in [0, 1). */
  next(): number;
  /** Uniform integer in [min, max] inclusive. */
  int(min: number, max: number): number;
  /** True with probability p. */
  chance(p: number): boolean;
  pick<T>(arr: readonly T[]): T;
  shuffle<T>(arr: T[]): T[];
  /** Number of draws taken so far — the PRNG cursor. */
  readonly draws: number;
  /** Fork a child stream deterministically (for independent sub-systems). */
  fork(tag: string): Rng;
}

/** mulberry32 — small, fast, good enough distribution for game dice. */
export function makeRng(seed: number): Rng {
  let state = seed >>> 0;
  let draws = 0;

  const next = (): number => {
    draws++;
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  const rng: Rng = {
    seed,
    next,
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    chance: (p) => next() < p,
    pick: <T,>(arr: readonly T[]): T => arr[Math.floor(next() * arr.length)],
    shuffle: <T,>(arr: T[]): T[] => {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(next() * (i + 1));
        const tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
      }
      return arr;
    },
    get draws() {
      return draws;
    },
    fork: (tag: string) => makeRng((seed ^ hashString(tag)) >>> 0),
  };
  return rng;
}

export function hashString(s: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/** Non-deterministic seed for starting a fresh battle/world. */
export function randomSeed(): number {
  return (Math.floor(Math.random() * 0xffffffff) ^ Date.now()) >>> 0;
}

let idCounter = 0;
/** Monotonic, collision-free id generator for client-created entities. */
export function uid(prefix = 'id'): string {
  idCounter = (idCounter + 1) % 1_000_000;
  return `${prefix}_${Date.now().toString(36)}_${idCounter.toString(36)}_${Math.floor(
    Math.random() * 46656,
  ).toString(36)}`;
}
