/**
 * GDD §8 — Guild structure, hierarchy and the permission matrix.
 *
 * | Capability                                  | Leader | Officer | Member |
 * |---------------------------------------------|--------|---------|--------|
 * | Appoint/demote officers                     |   ✔    |    —    |   —    |
 * | Diplomacy (parley, sign treaties)           |   ✔    |    ✔*   |   —    |
 * | Set grand objective                         |   ✔    |    ✔    |   —    |
 * | Set short objectives, pings, marks          |   ✔    |    ✔    |   ✔    |
 * | Kick members                                |   ✔    |    ✔    |   —    |
 * | Chat, trade, view intel                     |   ✔    |    ✔    |   ✔    |
 *
 * (*) Officers additionally need to be *designated diplomats* — the leader adds
 * them to `guild.diplomats` via {@link setDiplomat}. The leader always has
 * diplomacy access whether or not they appear in that list.
 *
 * PURE: no DOM, no Three.js. Mutates the GameState it is handed (the backend
 * owns that object and re-publishes it after every call).
 */
import { GUILD } from '../../config/balance';
import { GUILD_COLORS } from '../../config/visual';
import { uid } from '../rng';
import type {
  GameState,
  Guild,
  GuildCapability,
  GuildId,
  GuildRole,
  Player,
  PlayerId,
  Result,
} from '../types';
import { err, ok } from '../types';

// ─────────────────────────────────────────────────────────────────────────────
// Lookups
// ─────────────────────────────────────────────────────────────────────────────

/** The guild a player belongs to, if any. */
export function guildOf(state: GameState, playerId: PlayerId): Guild | undefined {
  const player = state.players[playerId];
  if (!player || !player.guildId) return undefined;
  return state.guilds[player.guildId];
}

/**
 * A player's role inside their guild, or `undefined` when they are guildless.
 * `guild.leaderId` is authoritative — the `roles` map is a cache that this
 * module keeps in sync, never the other way round.
 */
export function roleOf(state: GameState, playerId: PlayerId): GuildRole | undefined {
  const guild = guildOf(state, playerId);
  if (!guild) return undefined;
  if (!guild.memberIds.includes(playerId)) return undefined;
  if (guild.leaderId === playerId) return 'leader';
  const role = guild.roles[playerId];
  return role === 'officer' ? 'officer' : 'member';
}

/** Officers and the leader. */
export function isOfficerOrAbove(state: GameState, playerId: PlayerId): boolean {
  const role = roleOf(state, playerId);
  return role === 'leader' || role === 'officer';
}

/** Leader, or an officer the leader designated as a diplomat (GDD §10). */
export function isDiplomat(state: GameState, playerId: PlayerId): boolean {
  return can(state, playerId, 'diplomacy');
}

/** Members of a guild, leader first, then officers, then members. */
export function membersOf(state: GameState, guildId: GuildId): Player[] {
  const guild = state.guilds[guildId];
  if (!guild) return [];
  const rank: Record<GuildRole, number> = { leader: 0, officer: 1, member: 2 };
  return guild.memberIds
    .map((id) => state.players[id])
    .filter((p): p is Player => !!p)
    .sort((a, b) => {
      const ra = rank[roleOf(state, a.id) ?? 'member'];
      const rb = rank[roleOf(state, b.id) ?? 'member'];
      return ra !== rb ? ra - rb : a.name.localeCompare(b.name);
    });
}

// ─────────────────────────────────────────────────────────────────────────────
// The matrix
// ─────────────────────────────────────────────────────────────────────────────

/** GDD §8 permission matrix. Exhaustive over every GuildCapability. */
export function can(state: GameState, playerId: PlayerId, cap: GuildCapability): boolean {
  const role = roleOf(state, playerId);
  if (!role) return false;

  switch (cap) {
    // Hierarchy changes are the leader's alone.
    case 'appoint':
      return role === 'leader';

    // Leader always; officers only once explicitly designated as diplomats.
    case 'diplomacy': {
      if (role === 'leader') return true;
      if (role !== 'officer') return false;
      const guild = guildOf(state, playerId);
      return !!guild && guild.diplomats.includes(playerId);
    }

    case 'grand_objective':
    case 'kick':
      return role === 'leader' || role === 'officer';

    // Everyone: short objectives, pings, marks, chat, trade, intel.
    case 'short_objective':
    case 'chat':
      return true;

    default: {
      const exhaustive: never = cap;
      return exhaustive;
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Membership
// ─────────────────────────────────────────────────────────────────────────────

export interface CreateGuildInput {
  name: string;
  tag: string;
  motto?: string;
  /** 0xRRGGBB banner colour; defaults to a deterministic slot in GUILD_COLORS. */
  color?: number;
  emblem?: number;
}

/** Found a new guild. The founder becomes its leader and its first diplomat. */
export function createGuild(
  state: GameState,
  playerId: PlayerId,
  input: CreateGuildInput,
  now: number,
): Result<Guild> {
  const player = state.players[playerId];
  if (!player) return err('unknown commander');
  if (player.guildId) return err('leave your current guild first');

  const name = input.name.trim();
  const tag = input.tag.trim().toUpperCase();
  if (name.length < 2) return err('guild name too short');
  if (tag.length < 2 || tag.length > 5) return err('guild tag must be 2-5 characters');

  const taken = Object.values(state.guilds).some(
    (g) => g.tag.toUpperCase() === tag || g.name.toLowerCase() === name.toLowerCase(),
  );
  if (taken) return err('that name or tag is already flying');

  const index = Object.keys(state.guilds).length;
  const guild: Guild = {
    id: uid('gld'),
    name,
    tag,
    motto: (input.motto ?? '').trim(),
    color: input.color ?? GUILD_COLORS[index % GUILD_COLORS.length],
    leaderId: playerId,
    memberIds: [playerId],
    roles: { [playerId]: 'leader' },
    diplomats: [playerId],
    createdAt: now,
    emblem: input.emblem ?? index % 8,
  };

  state.guilds[guild.id] = guild;
  player.guildId = guild.id;
  return ok(guild);
}

/** Join an existing guild. Enforces GUILD.maxMembers. */
export function joinGuild(state: GameState, playerId: PlayerId, guildId: GuildId): Result<Guild> {
  const player = state.players[playerId];
  if (!player) return err('unknown commander');
  if (player.guildId === guildId) return err('already in this guild');
  if (player.guildId) return err('leave your current guild first');

  const guild = state.guilds[guildId];
  if (!guild) return err('unknown guild');
  if (guild.memberIds.length >= GUILD.maxMembers) {
    return err(`guild is full (${GUILD.maxMembers} commanders)`);
  }

  guild.memberIds.push(playerId);
  guild.roles[playerId] = 'member';
  player.guildId = guildId;
  return ok(guild);
}

export interface LeaveResult {
  guildId: GuildId;
  /** Set when the departing player was the leader and succession fired. */
  newLeaderId?: PlayerId;
  /** True when the last member left and the guild was struck from the register. */
  disbanded: boolean;
}

/**
 * Leave a guild.
 *
 * Succession (GDD §8 — hierarchies are leader-selected, so the chain of command
 * must never break): when the leader leaves, the most senior officer inherits
 * the seat; with no officers the longest-standing member does; with nobody left
 * the guild is disbanded.
 */
export function leaveGuild(state: GameState, playerId: PlayerId): Result<LeaveResult> {
  const player = state.players[playerId];
  if (!player) return err('unknown commander');
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');
  return ok(detach(state, guild, player));
}

/** Kick a member. Leader may kick anyone; officers may only kick plain members. */
export function kickMember(
  state: GameState,
  byPlayerId: PlayerId,
  targetId: PlayerId,
): Result<LeaveResult> {
  if (byPlayerId === targetId) return err('use leave, not kick');
  if (!can(state, byPlayerId, 'kick')) return err('officers and above only');

  const guild = guildOf(state, byPlayerId);
  const target = state.players[targetId];
  if (!guild || !target) return err('unknown commander');
  if (target.guildId !== guild.id) return err('not one of yours');
  if (guild.leaderId === targetId) return err('the leader cannot be kicked');

  const byRole = roleOf(state, byPlayerId);
  if (byRole === 'officer' && roleOf(state, targetId) === 'officer') {
    return err('only the leader can remove an officer');
  }
  return ok(detach(state, guild, target));
}

/** Shared removal path for leave + kick, including leader succession. */
function detach(state: GameState, guild: Guild, player: Player): LeaveResult {
  guild.memberIds = guild.memberIds.filter((id) => id !== player.id);
  delete guild.roles[player.id];
  guild.diplomats = guild.diplomats.filter((id) => id !== player.id);
  player.guildId = undefined;

  const result: LeaveResult = { guildId: guild.id, disbanded: false };

  if (guild.leaderId !== player.id) return result;

  // Leader left. With nobody remaining the guild is struck from the register.
  if (guild.memberIds.length === 0) {
    delete state.guilds[guild.id];
    result.disbanded = true;
    return result;
  }

  // Promote a successor in seniority order: senior officer, else senior member.
  const successor =
    guild.memberIds.find((id) => guild.roles[id] === 'officer') ?? guild.memberIds[0];

  guild.leaderId = successor;
  guild.roles[successor] = 'leader';
  if (!guild.diplomats.includes(successor)) guild.diplomats.push(successor);
  result.newLeaderId = successor;
  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
// Hierarchy (leader-only)
// ─────────────────────────────────────────────────────────────────────────────

export function appointOfficer(
  state: GameState,
  byPlayerId: PlayerId,
  targetId: PlayerId,
): Result<GuildRole> {
  if (!can(state, byPlayerId, 'appoint')) return err('leader only');
  const guild = guildOf(state, byPlayerId);
  if (!guild) return err('you are not in a guild');
  if (!guild.memberIds.includes(targetId)) return err('not one of yours');
  if (guild.leaderId === targetId) return err('the leader already outranks officers');
  if (guild.roles[targetId] === 'officer') return err('already an officer');

  guild.roles[targetId] = 'officer';
  return ok<GuildRole>('officer');
}

export function demoteOfficer(
  state: GameState,
  byPlayerId: PlayerId,
  targetId: PlayerId,
): Result<GuildRole> {
  if (!can(state, byPlayerId, 'appoint')) return err('leader only');
  const guild = guildOf(state, byPlayerId);
  if (!guild) return err('you are not in a guild');
  if (!guild.memberIds.includes(targetId)) return err('not one of yours');
  if (guild.leaderId === targetId) return err('demote the leader by transferring leadership');
  if (guild.roles[targetId] !== 'officer') return err('not an officer');

  guild.roles[targetId] = 'member';
  // Diplomacy access is an officer privilege — it lapses with the rank.
  guild.diplomats = guild.diplomats.filter((id) => id !== targetId);
  return ok<GuildRole>('member');
}

/** Hand the seat over. The outgoing leader keeps officer rank. */
export function transferLeadership(
  state: GameState,
  byPlayerId: PlayerId,
  targetId: PlayerId,
): Result<PlayerId> {
  if (!can(state, byPlayerId, 'appoint')) return err('leader only');
  if (byPlayerId === targetId) return err('you already hold the seat');
  const guild = guildOf(state, byPlayerId);
  if (!guild) return err('you are not in a guild');
  if (!guild.memberIds.includes(targetId)) return err('not one of yours');

  guild.leaderId = targetId;
  guild.roles[targetId] = 'leader';
  guild.roles[byPlayerId] = 'officer';
  if (!guild.diplomats.includes(targetId)) guild.diplomats.push(targetId);
  return ok(targetId);
}

/** Grant or revoke an officer's diplomacy access (GDD §10 — leader's call). */
export function setDiplomat(
  state: GameState,
  byPlayerId: PlayerId,
  targetId: PlayerId,
  enabled: boolean,
): Result<boolean> {
  if (!can(state, byPlayerId, 'appoint')) return err('leader only');
  const guild = guildOf(state, byPlayerId);
  if (!guild) return err('you are not in a guild');
  if (!guild.memberIds.includes(targetId)) return err('not one of yours');
  if (guild.leaderId === targetId) return err('the leader always holds diplomacy access');
  if (enabled && guild.roles[targetId] !== 'officer') {
    return err('promote them to officer first');
  }

  const has = guild.diplomats.includes(targetId);
  if (enabled && !has) guild.diplomats.push(targetId);
  if (!enabled && has) guild.diplomats = guild.diplomats.filter((id) => id !== targetId);
  return ok(enabled);
}
