/**
 * TERRA BELLUM — offline world seeding.
 *
 * Builds the initial `GameState` for the mock backend: a generated continent,
 * `SEEDED_BANNERS` established guilds, territory already carved up between them,
 * forts standing, production lines running, columns in the field, guild chat
 * with a history, objectives, marks, live pings, a shipment in transit and one
 * diplomatic channel with a signed treaty already in the archive.
 *
 * The point is that the player never sees a blank map. By the time they pick a
 * landing site the war has been running for days without them.
 *
 * GDD §3.1: the player starts OUTSIDE the map, in the staging area, with no hex
 * position — `deployed` is false and no army exists until they choose a site.
 *
 * BANNER (playtest change): the seeder no longer quietly founds a guild FOR the
 * player. Waking up already leading a banner you never chose is exactly what the
 * feedback objected to, so every seeded banner is founded and led by a simulated
 * commander and the human arrives **unaffiliated**. The onboarding step then
 * asks them to join one of these or found their own; `inductAllies` below is the
 * shared path that puts AI allies on a roster either way, so a player-founded
 * banner is populated and settled by the same code that built the rivals.
 *
 * PURE: no DOM, no Three.js. Deterministic for a given seed except for entity
 * ids, which come from the shared `uid()` helper.
 */
import type {
  Army,
  ArmyUnit,
  GameState,
  Guild,
  GuildId,
  Hex,
  HexId,
  Player,
  PlayerId,
  Sector,
  UnitType,
} from '../../game/types';
import { ECONOMY, FORTS, GUILD, SIM } from '../../config/balance';
import { EMBLEM_COUNT, RIVAL_BANNER_COLORS } from '../../config/visual';
import { UNITS } from '../../config/units';
import { makeRng, uid, type Rng } from '../../game/rng';
import { hexDistanceId, neighborIds } from '../../game/hex';
import { generateWorld, isHexOpen } from '../../game/world/generate';
import { writeIntel } from '../../game/world/drones';
import {
  appointOfficer,
  createGuild,
  joinGuild,
  setDiplomat,
} from '../../game/guild/permissions';
import {
  createObjective,
  commitToObjective,
  guildChannel,
  placeMark,
  placePing,
  sendChat,
  systemMessage,
} from '../../game/guild/social';
import { createTransfer } from '../../game/guild/transfers';
import {
  createTreaty,
  openParley,
  setPeace,
  signTreaty,
  submitTreatyRevision,
} from '../../game/diplomacy/diplomacy';
import { makeNameForge } from '../names';
import { chatterLine } from './bots';

const MIN = 60_000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

/** Fraction of the open map already carved up when the player arrives. */
const OCCUPANCY = 0.42;
/** Hexes claimed per simulated commander (clamped against the budget). */
const HEXES_PER_BOT = { min: 2, max: 6 } as const;

/**
 * Established banners on the register when the world opens.
 *
 * `SIM.botGuilds` rivals, plus one more standing in for the banner the seeder
 * used to hand the player unasked. Keeping the count identical means the
 * onboarding register still offers the same number of real choices and the map
 * is carved up exactly as densely as before.
 */
const SEEDED_BANNERS = SIM.botGuilds + 1;

/** Lines a freshly inducted roster puts on the channel so it is never silent. */
const MUSTER_TOPICS = ['general', 'logistics', 'defense'] as const;

export interface SeedWorldOptions {
  seed: number;
  now: number;
  /** Display name for the human commander; generated when omitted. */
  playerName?: string;
  /** Stable id for the human commander. */
  playerId?: PlayerId;
}

// ─────────────────────────────────────────────────────────────────────────────
// Entry point
// ─────────────────────────────────────────────────────────────────────────────

export function seedWorld(options: SeedWorldOptions): GameState {
  const { seed, now } = options;
  const meId = options.playerId ?? 'cmdr-local';

  const generated = generateWorld(seed, now);
  const rng = makeRng((seed ^ 0x2b7c91f3) >>> 0);
  const forge = makeNameForge(rng.fork('names'));

  const state: GameState = {
    now,
    meId,
    world: generated.world,
    players: {},
    guilds: {},
    armies: {},
    drones: {},
    transfers: [],
    chat: {},
    pings: [],
    marks: [],
    objectives: [],
    parleys: {},
    trades: [],
    treaties: {},
    intel: {},
    season: generated.season,
    pendingBattles: [],
    notifications: [],
    lastTick: now,
  };

  // ── the human commander: staging area, no banner, no ground ───────────────
  //
  // Unaffiliated on purpose. The onboarding step (ui/screens/onboarding.ts) is
  // the first real decision of the season and it cannot be a real decision if
  // the seeder has already made it.
  const human: Player = {
    id: meId,
    name: options.playerName ?? forge.commander(),
    minerals: ECONOMY.startMinerals,
    gas: ECONOMY.startGas,
    online: true,
    lastSeen: now,
    hue: 192,
    deployed: false,
    harvested: { m: 0, g: 0 },
    bot: false,
  };
  state.players[meId] = human;
  forge.reserve(human.name);

  // ── guilds ────────────────────────────────────────────────────────────────
  const guildIds: GuildId[] = [];

  for (let g = 0; g < SEEDED_BANNERS; g++) {
    const founder = spawnBot(state, rng, forge, now);
    const guild = foundGuild(state, rng, forge, now - rng.int(3, 9) * DAY, founder.id, {
      color: RIVAL_BANNER_COLORS[g % RIVAL_BANNER_COLORS.length],
      emblem: g % EMBLEM_COUNT,
    });
    if (guild) guildIds.push(guild.id);
  }

  // Fill every roster out to SIM.botsPerGuild.
  for (const guildId of guildIds) {
    const guild = state.guilds[guildId];
    if (!guild) continue;
    while (guild.memberIds.length < SIM.botsPerGuild) {
      const bot = spawnBot(state, rng, forge, now);
      if (!joinGuild(state, bot.id, guildId).ok) {
        delete state.players[bot.id];
        break;
      }
    }
  }

  // ── hierarchy: a couple of officers each, one designated diplomat ─────────
  for (const guildId of guildIds) assignRanks(state, guildId);

  // ── territory, forts, production, columns ─────────────────────────────────
  distributeTerritory(state, rng, guildIds, now);

  // ── the world already knows things ────────────────────────────────────────
  for (const guildId of guildIds) seedIntelFor(state, rng, guildId, now);
  for (const guildId of guildIds) seedChatHistoryFor(state, rng, guildId, now);
  seedObjectives(state, rng, guildIds, now);
  seedMarksAndPings(state, rng, guildIds, now);
  seedLogistics(state, rng, guildIds, now);
  seedDiplomacy(state, rng, guildIds, now);

  state.now = now;
  state.lastTick = now;
  return state;
}

// ─────────────────────────────────────────────────────────────────────────────
// Population
// ─────────────────────────────────────────────────────────────────────────────

function spawnBot(
  state: GameState,
  rng: Rng,
  forge: ReturnType<typeof makeNameForge>,
  now: number,
): Player {
  const id = uid('bot');
  const player: Player = {
    id,
    name: forge.commander(),
    minerals: rng.int(250, 3200),
    gas: rng.int(0, 180),
    online: rng.chance(0.42),
    lastSeen: now - rng.int(0, 5 * HOUR),
    hue: rng.int(0, 359),
    deployed: true,
    harvested: { m: rng.int(1200, 24000), g: rng.int(0, 900) },
    bot: true,
  };
  state.players[id] = player;
  return player;
}

function foundGuild(
  state: GameState,
  rng: Rng,
  forge: ReturnType<typeof makeNameForge>,
  createdAt: number,
  leaderId: PlayerId,
  banner: { color: number; emblem: number },
): Guild | undefined {
  for (let attempt = 0; attempt < 8; attempt++) {
    const identity = forge.guild();
    const made = createGuild(
      state,
      leaderId,
      {
        name: identity.name,
        tag: identity.tag,
        motto: identity.motto,
        color: banner.color,
        emblem: banner.emblem,
      },
      createdAt,
    );
    if (made.ok) return made.value;
  }
  void rng;
  return undefined;
}

/** GDD §8 — two officers and one designated diplomat, leader-appointed. */
function assignRanks(state: GameState, guildId: GuildId): void {
  const guild = state.guilds[guildId];
  if (!guild) return;
  const candidates = guild.memberIds.filter(
    (id) => id !== guild.leaderId && guild.roles[id] !== 'officer',
  );
  const existing = guild.memberIds.filter((id) => guild.roles[id] === 'officer');
  const want = Math.max(0, 2 - existing.length);
  const officers = candidates.slice(0, Math.min(want, candidates.length));
  for (const id of officers) appointOfficer(state, guild.leaderId, id);

  const diplomat = existing[0] ?? officers[0];
  if (diplomat && !guild.diplomats.includes(diplomat)) {
    setDiplomat(state, guild.leaderId, diplomat, true);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Induction — shared by the seeder and by a guild founded at runtime
// ─────────────────────────────────────────────────────────────────────────────

/**
 * "AI allies will automatically join the guild regardless" (playtest feedback).
 *
 * Fills a roster out to `SIM.botsPerGuild`, appoints officers and a diplomat,
 * puts every new ally on real ground with a fort, a production line and a column
 * in the field, writes the guild's first intel and gets the channel talking.
 *
 * This is deliberately the same code path the seeder runs for the established
 * banners: a guild the player founds in onboarding is populated and settled by
 * `settleCommander` / `growClaim` / `seedIntelFor` exactly as a rival is, so a
 * fresh banner is a peer of the ones already on the map rather than a name with
 * nobody behind it.
 *
 * Returns the ids of the commanders that were inducted (empty when the roster
 * was already full).
 */
export function inductAllies(
  state: GameState,
  rng: Rng,
  guildId: GuildId,
  now: number,
): PlayerId[] {
  const guild = state.guilds[guildId];
  if (!guild) return [];

  // The forge is stateful and this one is new, so tell it what the world has
  // already used or it will hand out a call-sign that is already on the net.
  const forge = makeNameForge(rng.fork('induct'));
  for (const player of Object.values(state.players)) forge.reserve(player.name);
  for (const other of Object.values(state.guilds)) forge.reserve(other.name);

  const target = Math.min(SIM.botsPerGuild, GUILD.maxMembers);
  const fresh: PlayerId[] = [];
  while (guild.memberIds.length < target) {
    const bot = spawnBot(state, rng, forge, now);
    if (!joinGuild(state, bot.id, guildId).ok) {
      delete state.players[bot.id];
      break;
    }
    fresh.push(bot.id);
  }

  assignRanks(state, guildId);
  if (fresh.length > 0) settleAllies(state, rng, guildId, fresh, now);
  seedIntelFor(state, rng, guildId, now);
  musterChatter(state, rng, guildId, fresh);
  return fresh;
}

/**
 * Ground for commanders inducted into an already-running world.
 *
 * Follows the same rule as `distributeTerritory`: a foothold in every active
 * theatre, spaced against the banners already standing in THAT theatre. It used
 * to anchor the whole claim "as far as possible from every banner on the board",
 * which dropped a freshly founded guild into whichever corner nobody wanted —
 * the player's own banner started the season with no neighbours and nothing to
 * fight over, which is the same segregation the seeder had.
 */
function settleAllies(
  state: GameState,
  rng: Rng,
  guildId: GuildId,
  memberIds: PlayerId[],
  now: number,
): void {
  const guild = state.guilds[guildId];
  if (!guild) return;

  const sectors = activeSectorsOf(state);
  if (sectors.length === 0) return;

  const bots = memberIds.filter((id) => state.players[id]?.bot);
  if (bots.length === 0) return;

  // Free ground split per sector, so the new banner can be placed INTO each
  // contest rather than into whatever is left over after all of them.
  const free = freeGroundPool(state);
  if (free.size === 0) return;
  const pools = new Map<string, Set<HexId>>();
  for (const sector of sectors) {
    const pool = new Set<HexId>();
    for (const id of sector.hexIds) if (free.has(id)) pool.add(id);
    pools.set(sector.id, pool);
  }

  const perBot = Math.max(
    HEXES_PER_BOT.min,
    Math.min(HEXES_PER_BOT.max, Math.floor((free.size * OCCUPANCY) / bots.length)),
  );

  const forge = makeNameForge(rng.fork('armies'));
  const footholds = new Map<string, HexId[]>();

  for (let i = 0; i < bots.length; i++) {
    const player = state.players[bots[i]];
    if (!player) continue;

    // Walk the sectors so the banner ends up present in each of them. A sector
    // with nothing free left is skipped rather than dropping the commander.
    for (let step = 0; step < sectors.length; step++) {
      const sector = sectors[(i + step) % sectors.length];
      const pool = pools.get(sector.id);
      if (!pool || pool.size === 0) continue;

      const held = footholds.get(sector.id) ?? [];
      let seeds: HexId[];
      if (held.length > 0) {
        seeds = rng.shuffle([...held]).slice(0, 3);
      } else {
        const rivals = bannerAnchorsInSector(state, sector.id, guildId);
        const anchor = pickSpreadStart(pool, rivals, rng);
        if (!anchor) continue;
        seeds = [anchor];
      }

      const claimed = growClaim(pool, seeds, perBot, rng);
      if (claimed.length === 0) continue;
      footholds.set(sector.id, [...held, ...claimed]);
      settleCommander(state, rng, forge, player, guild, claimed, now);
      break;
    }
  }
}

/** Playable hexes nobody holds, nobody is flipping and nobody is standing on. */
function freeGroundPool(state: GameState): Set<HexId> {
  const standing = new Set<HexId>();
  for (const army of Object.values(state.armies)) {
    if (army.units.length > 0) standing.add(army.hexId);
  }
  const pool = new Set<HexId>();
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId || hex.capture) continue;
    if (standing.has(hex.id)) continue;
    const sector = state.world.sectors[hex.sectorId];
    if (!sector || sector.state !== 'active') continue;
    if (!isHexOpen(state.world, hex.id)) continue;
    pool.add(hex.id);
  }
  return pool;
}

/**
 * One representative hex per rival banner holding ground INSIDE a sector.
 *
 * Sector-scoped on purpose: spread is a question about where the rivals in this
 * theatre already stand, not about the whole world. Measuring it globally is
 * what pushed every new banner off to the far edge of the map.
 */
function bannerAnchorsInSector(
  state: GameState,
  sectorId: string,
  exceptGuildId?: GuildId,
): HexId[] {
  const sector = state.world.sectors[sectorId];
  if (!sector) return [];
  const seen = new Set<GuildId>();
  const out: HexId[] = [];
  for (const id of [...sector.hexIds].sort()) {
    const hex = state.world.hexes[id];
    if (!hex?.ownerId) continue;
    const banner = state.players[hex.ownerId]?.guildId;
    if (!banner || banner === exceptGuildId || seen.has(banner)) continue;
    seen.add(banner);
    out.push(id);
  }
  return out;
}

/** A newly mustered roster reporting in, so the channel is never an empty box. */
function musterChatter(
  state: GameState,
  rng: Rng,
  guildId: GuildId,
  memberIds: PlayerId[],
): void {
  const channel = guildChannel(guildId);
  const speakers = memberIds.filter((id) => state.players[id]?.bot);
  if (speakers.length === 0) return;
  const lines = Math.min(speakers.length, rng.int(2, 3));
  for (let i = 0; i < lines; i++) {
    sendChat(state, channel, speakers[i], chatterLine(rng, rng.pick([...MUSTER_TOPICS])));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Territory
// ─────────────────────────────────────────────────────────────────────────────

function activeSectorsOf(state: GameState): Sector[] {
  return Object.values(state.world.sectors)
    .filter((s) => s.state === 'active')
    .sort((a, b) => (a.id < b.id ? -1 : 1));
}

/** Grow a compact blob of `count` hexes out of `pool`, starting from `seeds`. */
function growClaim(pool: Set<HexId>, seeds: HexId[], count: number, rng: Rng): HexId[] {
  const out: HexId[] = [];
  const seen = new Set<HexId>();
  const frontier: HexId[] = [];

  const consider = (id: HexId): void => {
    if (seen.has(id) || !pool.has(id)) return;
    seen.add(id);
    frontier.push(id);
  };

  for (const s of seeds) consider(s);
  if (frontier.length === 0) {
    for (const s of seeds) for (const nb of neighborIds(s)) consider(nb);
  }

  while (out.length < count && frontier.length > 0) {
    const window = Math.min(frontier.length, 3);
    const id = frontier.splice(rng.int(0, window - 1), 1)[0];
    if (!pool.has(id)) continue;
    pool.delete(id);
    out.push(id);
    for (const nb of neighborIds(id)) consider(nb);
  }
  return out;
}

/** A start hex as far as possible from everything already claimed. */
function pickSpreadStart(pool: Set<HexId>, taken: HexId[], rng: Rng): HexId | undefined {
  const ids = [...pool].sort();
  if (ids.length === 0) return undefined;
  if (taken.length === 0) return ids[rng.int(0, ids.length - 1)];

  const sample = ids.length > 64 ? rng.shuffle([...ids]).slice(0, 64) : ids;
  let best = sample[0];
  let bestScore = -1;
  for (const id of sample) {
    let minD = Infinity;
    for (const t of taken) minD = Math.min(minD, hexDistanceId(id, t));
    if (minD > bestScore) {
      bestScore = minD;
      best = id;
    }
  }
  return best;
}

function rollComposition(rng: Rng, size: number, allowGas: boolean): UnitType[] {
  const pool: UnitType[] = allowGas
    ? ['exo', 'exo', 'walker', 'walker', 'pallet', 'flyer', 'elite_flyer']
    : ['exo', 'exo', 'exo', 'walker', 'walker', 'pallet'];
  const out: UnitType[] = [];
  for (let i = 0; i < size; i++) out.push(rng.pick(pool));
  return out;
}

function makeUnits(rng: Rng, types: UnitType[]): ArmyUnit[] {
  return types.map((type) => {
    const full = UNITS[type].hp;
    // Most columns are combat-worn but not crippled.
    const hp = rng.chance(0.55) ? full : Math.max(1, Math.round(full * (0.5 + rng.next() * 0.45)));
    return { id: uid('u'), type, hp };
  });
}

/**
 * Carve the opening map up between the banners. EVERY SECTOR IS SHARED GROUND.
 *
 * This used to deal one sector per banner — `sectors[gi % sectors.length]` — and
 * grow that banner's whole claim inside it. With six banners over four sectors
 * the result was a map of private neighbourhoods: most sectors flew exactly one
 * flag, hardly any commander had a hostile border, and there was nothing to
 * compete over. Combined with active sectors that could not even be marched
 * between, each faction simply sat in its own quarter for the whole week.
 *
 * Now the deal is a Latin square: banner `gi`'s member `mi` settles in sector
 * `(gi + mi)`, so every banner takes a foothold in every theatre and every
 * theatre opens with every banner in it. Footholds are spaced against the other
 * footholds IN THAT SECTOR rather than against the whole map, which puts rival
 * borders a few hexes apart instead of half a world away.
 */
function distributeTerritory(
  state: GameState,
  rng: Rng,
  guildIds: GuildId[],
  now: number,
): void {
  const sectors = activeSectorsOf(state);
  if (sectors.length === 0) return;

  const pools = new Map<string, Set<HexId>>();
  let openHexCount = 0;
  for (const sector of sectors) {
    const pool = new Set<HexId>(sector.hexIds.filter((id) => !!state.world.hexes[id]));
    pools.set(sector.id, pool);
    openHexCount += pool.size;
  }

  interface Deal {
    sectorId: string;
    guildId: GuildId;
    playerId: PlayerId;
  }
  const deals: Deal[] = [];
  for (let gi = 0; gi < guildIds.length; gi++) {
    const guild = state.guilds[guildIds[gi]];
    if (!guild) continue;
    let mi = 0;
    for (const memberId of guild.memberIds) {
      const player = state.players[memberId];
      if (!player?.bot) continue;
      deals.push({
        sectorId: sectors[(gi + mi) % sectors.length].id,
        guildId: guild.id,
        playerId: memberId,
      });
      mi++;
    }
  }
  if (deals.length === 0) return;

  const budget = Math.floor(openHexCount * OCCUPANCY);
  const perBot = Math.max(
    HEXES_PER_BOT.min,
    Math.min(HEXES_PER_BOT.max, Math.floor(budget / deals.length)),
  );

  const forge = makeNameForge(rng.fork('armies'));
  /** Footholds already planted in each sector, so claims inside one spread out. */
  const sectorAnchors = new Map<string, HexId[]>();
  /** Ground a banner already holds in a sector, so its members cluster there. */
  const footholds = new Map<string, HexId[]>();

  for (const deal of deals) {
    const pool = pools.get(deal.sectorId);
    const player = state.players[deal.playerId];
    const guild = state.guilds[deal.guildId];
    if (!pool || !player || !guild) continue;

    const key = `${deal.sectorId}|${deal.guildId}`;
    const held = footholds.get(key) ?? [];

    let seeds: HexId[];
    if (held.length > 0) {
      // A second commander from the same banner reinforces the same foothold.
      seeds = rng.shuffle([...held]).slice(0, 3);
    } else {
      const anchors = sectorAnchors.get(deal.sectorId) ?? [];
      const anchor = pickSpreadStart(pool, anchors, rng);
      if (!anchor) continue;
      anchors.push(anchor);
      sectorAnchors.set(deal.sectorId, anchors);
      seeds = [anchor];
    }

    const claimed = growClaim(pool, seeds, perBot, rng);
    if (claimed.length === 0) continue;
    footholds.set(key, [...held, ...claimed]);
    settleCommander(state, rng, forge, player, guild, claimed, now);
  }
}

/** Give one simulated commander their ground, their fort and their column. */
function settleCommander(
  state: GameState,
  rng: Rng,
  forge: ReturnType<typeof makeNameForge>,
  player: Player,
  guild: Guild,
  hexIds: HexId[],
  now: number,
): void {
  const hexes: Hex[] = [];
  for (const id of hexIds) {
    const hex = state.world.hexes[id];
    if (!hex) continue;
    hex.ownerId = player.id;
    hexes.push(hex);
  }
  if (hexes.length === 0) return;

  // Capital: a gas field if they hold one, otherwise the first claim.
  const capital = hexes.find((h) => h.gas) ?? hexes[0];
  const holdsGas = hexes.some((h) => h.gas);

  // ── fortification ────────────────────────────────────────────────────────
  const fortRoll = rng.next();
  capital.fortLevel = fortRoll < 0.1 ? 0 : fortRoll < 0.62 ? 1 : fortRoll < 0.9 ? 2 : 3;

  // A second holding sometimes has an Outpost, and one build is often running.
  if (hexes.length > 1 && rng.chance(0.45)) {
    const second = hexes[1];
    second.fortLevel = 1;
    if (rng.chance(0.4)) {
      const spec = FORTS[2];
      second.fortBuild = {
        targetLevel: 2,
        startedAt: now - rng.int(0, spec.buildMs),
        completesAt: now + rng.int(2 * MIN, spec.buildMs),
      };
    }
  }

  // ── garrison + production line ───────────────────────────────────────────
  if (capital.fortLevel >= 1) {
    const reserveCount = rng.int(0, 3);
    for (let i = 0; i < reserveCount; i++) {
      const type: UnitType = rng.chance(0.7) ? 'exo' : 'walker';
      capital.reserves[type] = (capital.reserves[type] ?? 0) + 1;
    }
    if (rng.chance(0.55)) {
      const type: UnitType = holdsGas && rng.chance(0.35) ? 'flyer' : rng.chance(0.6) ? 'exo' : 'walker';
      const def = UNITS[type];
      capital.production.push({
        id: uid('ord'),
        unitType: type,
        remaining: rng.int(1, 3),
        startedAt: now - rng.int(0, def.buildTimeMs),
        completesAt: now + rng.int(30_000, def.buildTimeMs),
      });
    }
  }

  // ── columns in the field ─────────────────────────────────────────────────
  const columns = rng.chance(0.28) ? 2 : 1;
  for (let c = 0; c < columns; c++) {
    const stand = c === 0 ? capital : rng.pick(hexes);
    const size = rng.int(2, 6);
    const units = makeUnits(rng, rollComposition(rng, size, holdsGas || player.gas > 60));
    const army: Army = {
      id: uid('army'),
      ownerId: player.id,
      guildId: guild.id,
      name: forge.army(),
      hexId: stand.id,
      units,
      path: [],
    };
    state.armies[army.id] = army;
  }

  // Commanders sitting on gas have banked some of it.
  if (holdsGas) {
    player.gas = Math.min(ECONOMY.capGas, player.gas + rng.int(60, 400));
    player.harvested = { m: player.harvested.m, g: player.harvested.g + rng.int(200, 1400) };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Flavour: intel, chat, objectives, marks, logistics, diplomacy
// ─────────────────────────────────────────────────────────────────────────────

function guildHexesOf(state: GameState, guildId: GuildId): Hex[] {
  const out: Hex[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.ownerId) continue;
    const owner = state.players[hex.ownerId];
    if (owner?.guildId === guildId) out.push(hex);
  }
  return out.sort((a, b) => (a.id < b.id ? -1 : 1));
}

function seedIntelFor(state: GameState, rng: Rng, guildId: GuildId, now: number): void {
  const mine = guildHexesOf(state, guildId);
  if (mine.length === 0) return;

  // Everything they hold, plus whatever the last recon sweep saw.
  for (const hex of mine) writeIntel(state, guildId, hex.id, now - rng.int(0, 30 * MIN));

  const border = new Set<HexId>();
  for (const hex of mine) {
    for (const nb of neighborIds(hex.id)) {
      const other = state.world.hexes[nb];
      if (!other) continue;
      const owner = other.ownerId ? state.players[other.ownerId] : undefined;
      if (owner && owner.guildId !== guildId) border.add(nb);
    }
  }
  const sweeps = [...border].sort().slice(0, 6);
  for (const id of sweeps) writeIntel(state, guildId, id, now - rng.int(20 * MIN, 8 * HOUR));
}

function seedChatHistoryFor(state: GameState, rng: Rng, guildId: GuildId, now: number): void {
  const guild = state.guilds[guildId];
  if (!guild) return;
  const channel = guildChannel(guildId);
  const speakers = guild.memberIds.filter((id) => state.players[id]?.bot);
  if (speakers.length === 0) return;

  systemMessage(
    state,
    channel,
    `${state.season.name} — CHANNEL ESTABLISHED. ${guild.motto.toUpperCase()}`,
    'system',
    guild.createdAt,
  );

  const lines = rng.int(9, 16);
  let at = now - rng.int(5 * HOUR, 10 * HOUR);
  for (let i = 0; i < lines; i++) {
    at += rng.int(4 * MIN, 40 * MIN);
    if (at >= now) break;
    const speaker = rng.pick(speakers);
    const previous = state.now;
    state.now = at;
    sendChat(state, channel, speaker, chatterLine(rng));
    state.now = previous;
  }

  const sectors = activeSectorsOf(state);
  if (sectors.length > 0) {
    systemMessage(
      state,
      channel,
      `SECTOR ${rng.pick(sectors).designation} REPORTED ACTIVE. ROTATION CLOCK RUNNING.`,
      'alert',
      now - rng.int(30 * MIN, 3 * HOUR),
    );
  }
}

function seedObjectives(state: GameState, rng: Rng, guildIds: GuildId[], now: number): void {
  for (let gi = 0; gi < guildIds.length; gi++) {
    const guildId = guildIds[gi];
    const guild = state.guilds[guildId];
    if (!guild) continue;

    const officer =
      guild.memberIds.find((id) => guild.roles[id] === 'officer' && state.players[id]?.bot) ??
      guild.memberIds.find((id) => state.players[id]?.bot);
    if (!officer) continue;

    const mine = guildHexesOf(state, guildId);
    const gasTargets: HexId[] = [];
    for (const hex of Object.values(state.world.hexes)) {
      if (!hex.gas) continue;
      const owner = hex.ownerId ? state.players[hex.ownerId] : undefined;
      if (owner?.guildId === guildId) continue;
      if (mine.some((h) => hexDistanceId(h.id, hex.id) <= 7)) gasTargets.push(hex.id);
    }

    const grand = createObjective(
      state,
      officer,
      {
        title: gasTargets.length > 0 ? 'CONTROL THE VENT LINE' : 'HOLD THE SECTOR CORE',
        detail:
          'Gas is the only gate on the heavy chassis. Everything else this season is bookkeeping.',
        hexIds: gasTargets.slice(0, 3),
        grand: true,
        dueAt: state.season.nextRotationAt,
      },
      now - rng.int(1 * HOUR, 2 * DAY),
    );
    if (grand.ok) {
      for (const id of guild.memberIds) {
        if (state.players[id]?.bot && rng.chance(0.5)) {
          commitToObjective(state, id, grand.value.id, true);
        }
      }
    }

    const shortCount = gi === 0 ? 2 : 1;
    for (let i = 0; i < shortCount; i++) {
      const anchor = mine.length > 0 ? rng.pick(mine) : undefined;
      if (!anchor) break;
      createObjective(
        state,
        officer,
        {
          title: rng.chance(0.5) ? 'RAISE A BASTION ON THE BORDER' : 'SCREEN THE NORTH APPROACH',
          detail: chatterLine(rng, 'defense'),
          hexIds: [anchor.id],
          grand: false,
        },
        now - rng.int(10 * MIN, 8 * HOUR),
      );
    }
  }
}

function seedMarksAndPings(state: GameState, rng: Rng, guildIds: GuildId[], now: number): void {
  for (let gi = 0; gi < guildIds.length; gi++) {
    const guildId = guildIds[gi];
    const guild = state.guilds[guildId];
    if (!guild) continue;
    const author = guild.memberIds.find((id) => state.players[id]?.bot);
    if (!author) continue;

    const mine = guildHexesOf(state, guildId);
    if (mine.length === 0) continue;

    // Marks: enemy forts and unclaimed vents near our line.
    const interesting: { id: HexId; label: string }[] = [];
    for (const hex of Object.values(state.world.hexes)) {
      const near = mine.some((h) => hexDistanceId(h.id, hex.id) <= 5);
      if (!near) continue;
      const owner = hex.ownerId ? state.players[hex.ownerId] : undefined;
      if (hex.gas && owner?.guildId !== guildId) {
        interesting.push({ id: hex.id, label: 'VENT FIELD' });
      } else if (owner && owner.guildId !== guildId && hex.fortLevel >= 2) {
        interesting.push({ id: hex.id, label: `${FORTS[hex.fortLevel as 1 | 2 | 3].label} — ${owner.name}` });
      }
    }
    const marks = rng.shuffle(interesting).slice(0, gi === 0 ? 4 : 2);
    for (const m of marks) {
      placeMark(state, author, m.id, m.label, now - rng.int(10 * MIN, 2 * DAY));
    }

    // A couple of live pings, well inside their TTL.
    const pingCount = gi === 0 ? 2 : 1;
    for (let i = 0; i < pingCount; i++) {
      const target = marks[i]?.id ?? rng.pick(mine).id;
      const kind = i === 0 ? 'rally' : 'danger';
      placePing(state, author, target, kind, now - rng.int(2 * MIN, Math.floor(GUILD.pingTtlMs / 2)));
    }
  }
}

function seedLogistics(state: GameState, rng: Rng, guildIds: GuildId[], now: number): void {
  for (const guildId of guildIds.slice(0, 3)) {
    const guild = state.guilds[guildId];
    if (!guild) continue;
    const bots = guild.memberIds.filter((id) => state.players[id]?.bot);
    if (bots.length < 2) continue;

    const richest = [...bots].sort(
      (a, b) => (state.players[b]?.minerals ?? 0) - (state.players[a]?.minerals ?? 0),
    );
    const from = richest[0];
    const to = richest[richest.length - 1];
    const sender = state.players[from];
    if (!sender || from === to) continue;

    const amount = Math.min(600, Math.floor(sender.minerals * 0.3));
    if (amount < 60) continue;

    createTransfer(
      state,
      from,
      to,
      { minerals: amount, gas: 0, units: {} },
      now - rng.int(1 * MIN, 4 * MIN),
    );
  }
}

function seedDiplomacy(state: GameState, rng: Rng, guildIds: GuildId[], now: number): void {
  if (guildIds.length < 2) return;
  const mineId = guildIds[0];
  const theirsId = guildIds[1];
  const mine = state.guilds[mineId];
  const theirs = state.guilds[theirsId];
  if (!mine || !theirs) return;

  const theirDiplomat = theirs.leaderId;
  const myDiplomat = mine.diplomats.find((id) => id !== state.meId && state.players[id]?.bot);
  if (!myDiplomat) return;

  const t0 = now - 4 * DAY;
  const opened = openParley(state, theirDiplomat, mineId, t0);
  if (!opened.ok) return;
  const parleyId = opened.value;

  const made = createTreaty(
    state,
    parleyId,
    theirDiplomat,
    `${theirs.tag}–${mine.tag} VENT ACCORD`,
    t0 + 20 * MIN,
  );
  if (!made.ok) return;
  const treatyId = made.value;

  submitTreatyRevision(
    state,
    treatyId,
    theirDiplomat,
    [
      `ARTICLE I — Neither signatory shall move a column onto a hex held by the other for the`,
      `remainder of the current sector rotation.`,
      '',
      `ARTICLE II — Vent fields between our lines remain unclaimed. Neither side raises a fort`,
      `on a gas hex inside the buffer.`,
      '',
      `ARTICLE III — Recon motes are not an act of war. Shooting one down is not either.`,
    ].join('\n'),
    t0 + 90 * MIN,
  );

  submitTreatyRevision(
    state,
    treatyId,
    myDiplomat,
    [
      `ARTICLE I — Neither signatory shall move a column onto a hex held by the other for the`,
      `remainder of the current sector rotation.`,
      '',
      `ARTICLE II — Vent fields between our lines remain unclaimed. Neither side raises a fort`,
      `on a gas hex inside the buffer.`,
      '',
      `ARTICLE III — Recon motes are not an act of war. Shooting one down is not either.`,
      '',
      `ARTICLE IV (ADDED) — Salvage on the neutral ridge belongs to whoever reaches it first.`,
      `No claim, no complaint.`,
      '',
      `This document binds nothing but reputation. Both signatories know it.`,
    ].join('\n'),
    t0 + 5 * HOUR,
  );

  signTreaty(state, treatyId, theirDiplomat, t0 + 6 * HOUR);
  signTreaty(state, treatyId, myDiplomat, t0 + 6 * HOUR + 12 * MIN);
  setPeace(state, parleyId, theirDiplomat, true, t0 + 6 * HOUR + 15 * MIN);

  // A little back-and-forth on the channel so it does not read as a stub.
  const channel = `parley:${parleyId}`;
  const previous = state.now;
  state.now = t0 + 7 * HOUR;
  sendChat(state, channel, myDiplomat, 'Accord logged. We will hold to it as long as it is useful.');
  state.now = t0 + 7 * HOUR + rng.int(2 * MIN, 40 * MIN);
  sendChat(state, channel, theirDiplomat, 'Everyone says that. Somebody always means it.');
  state.now = previous;
}
