/**
 * TERRA BELLUM — procedural nomenclature.
 *
 * Seeded generators for commander call-signs, guild names, guild tags, mottos
 * and army designations. The register is grounded military science fiction —
 * orbital drop corps, mining consortia, mercenary echelons. No fantasy, no
 * dragons, nothing that would look wrong stencilled on a hull.
 *
 * Everything is driven by an injected `Rng`, so a given world seed always
 * produces the same roster of rivals.
 *
 * PURE: no DOM, no Three.js.
 */
import type { Rng } from '../game/rng';

