// ─────────────────────────────────────────────────────────────────────────────
// Forge
// ─────────────────────────────────────────────────────────────────────────────

export interface GuildIdentity {
  name: string;
  tag: string;
  motto: string;
}

/**
 * A stateful name generator. It remembers what it has already handed out, so a
 * roster of several dozen commanders never repeats a call-sign or a banner.
 */
export interface NameForge {
  /** `K. VOSS` or, one time in four, `K. VOSS "RAMPART"`. */
  commander(): string;
  /** Guild name + a 3–5 character tag + a motto. */
  guild(): GuildIdentity;
  /** `III COLUMN` — an army designation, unique per commander. */
  army(): string;
  /** Reserve a name so it can never be generated again. */
  reserve(name: string): void;
}

function unique(pool: readonly string[], used: Set<string>, rng: Rng): string | undefined {
  const free = pool.filter((v) => !used.has(v));
  if (free.length === 0) return undefined;
  return free[rng.int(0, free.length - 1)];
}

export function makeNameForge(rng: Rng): NameForge {
  const usedCommanders = new Set<string>();
  const usedSurnames = new Set<string>();
  const usedGuilds = new Set<string>();
  const usedTags = new Set<string>();
  const usedCallSigns = new Set<string>();
  const usedMottos = new Set<string>();
  let armyCounter = 0;

  const motto = (): string => {
    const fresh = unique(MOTTOS, usedMottos, rng);
    const line = fresh ?? rng.pick(MOTTOS);
    usedMottos.add(line);
    return line;
  };

  const tagFor = (prefix: string, core: string): string => {
    const candidates = [
      (prefix.slice(0, 2) + core.slice(0, 2)).toUpperCase(),
      (prefix.slice(0, 3) + core.slice(0, 1)).toUpperCase(),
      (prefix.slice(0, 1) + core.slice(0, 3)).toUpperCase(),
      (prefix.slice(0, 2) + core.slice(0, 3)).toUpperCase(),
    ];
    for (const c of candidates) {
      if (c.length >= 2 && c.length <= 5 && !usedTags.has(c)) return c;
    }
    let n = 2;
    let fallback = `${prefix.slice(0, 2).toUpperCase()}${n}`;
    while (usedTags.has(fallback) && n < 99) {
      n++;
      fallback = `${prefix.slice(0, 2).toUpperCase()}${n}`;
    }
    return fallback;
  };

  return {
    commander(): string {
      for (let attempt = 0; attempt < 64; attempt++) {
        const surname = unique(SURNAMES, usedSurnames, rng) ?? rng.pick(SURNAMES);
        const initial = rng.pick(INITIALS);
        let name = `${initial}. ${surname}`;
        if (rng.chance(0.25)) {
          const sign = unique(CALL_SIGNS, usedCallSigns, rng);
          if (sign) {
            usedCallSigns.add(sign);
            name = `${initial}. ${surname} "${sign}"`;
          }
        }
        if (usedCommanders.has(name)) continue;
        usedCommanders.add(name);
        usedSurnames.add(surname);
        return name;
      }
      const fallback = `CMDR-${rng.int(100, 999)}`;
      usedCommanders.add(fallback);
      return fallback;
    },

    guild(): GuildIdentity {
      for (let attempt = 0; attempt < 96; attempt++) {
        const prefix = rng.pick(GUILD_PREFIXES);
        const core = rng.pick(GUILD_CORES);
        const name = `${prefix} ${core}`;
        if (usedGuilds.has(name)) continue;
        const tag = tagFor(prefix, core);
        if (usedTags.has(tag)) continue;
        usedGuilds.add(name);
        usedTags.add(tag);
        return { name, tag, motto: motto() };
      }
      const n = usedGuilds.size + 1;
      const name = `TASK GROUP ${n}`;
      const tag = `TG${n}`;
      usedGuilds.add(name);
      usedTags.add(tag);
      return { name, tag, motto: motto() };
    },

    army(): string {
      const numeral = ROMAN[armyCounter % ROMAN.length];
      armyCounter++;
      return `${numeral} ${rng.pick(ARMY_DESIGNATIONS)}`;
    },

    reserve(name: string): void {
      usedCommanders.add(name);
      usedGuilds.add(name);
    },
  };
}

/** Default name for a fresh anonymous commander. */
export function defaultCommanderName(rng: Rng): string {
  return `${rng.pick(INITIALS)}. ${rng.pick(SURNAMES)}`;
}
