// ─────────────────────────────────────────────────────────────────────────────
// Banners (GDD §8)
//
// A banner colour follows a commander onto every hex, army token, chat message
// and leaderboard row, so the one thing it must never be is *nearly* the colour
// of a rival. The wheel is therefore split in two:
//
//   RIVAL_BANNER_COLORS  — what the world seeder hands to simulated banners
//   BANNER_PRESETS       — what a founding commander may choose from
//
// The two sets are disjoint AND every preset sits at least
// BANNER_MIN_HUE_SEPARATION degrees away from every rival colour, so the default
// world can never produce a "which one of these is mine" moment. The separation
// is still enforced at runtime (`isBannerDistinct`) rather than trusted, because
// the guild count is a [TUNE] number and the register grows during a season.
// ─────────────────────────────────────────────────────────────────────────────

/** Number of procedural emblems `guildSigil` can draw. */
export const EMBLEM_COUNT = 8;

/**
 * Minimum hue separation, in degrees, between any two banners on the register.
 * Below roughly 20° two saturated banners stop being tellable apart on a hex
 * token once bloom has had its way with them. [TUNE]
 */
export const BANNER_MIN_HUE_SEPARATION = 22;

/**
 * Banner colours issued to simulated (AI-led) guilds, in seeding order.
 * Hues: 354 · 43 · 87 · 165 · 232 · 283 · 35 · 333 — spread so rival banners are
 * also tellable apart from each other. The last two are spare capacity for a
 * higher `SIM.botGuilds`.
 */
export const RIVAL_BANNER_COLORS: readonly number[] = [
  0xff4d5e, // crimson  354°
  0xffd15c, // gold      43°
  0xb6ff5c, // lime      87°
  0x3dffcf, // teal     165°
  0x7b8cff, // indigo   232°
  0xd97bff, // orchid   283°
  0xffb347, // amber     35°
  0xff4d9d, // rose     333°
];

export interface BannerPreset {
  id: string;
  /** Shown under the swatch. Two words maximum — it has to fit a 390px row. */
  label: string;
  /** 0xRRGGBB. */
  color: number;
  /** Emblem this preset arrives with; the founder may still change it. */
  emblem: number;
}

/**
 * The palette a commander founds a guild from. Every entry clears
 * BANNER_MIN_HUE_SEPARATION against all six default rival banners and against
 * each other. Hues: 189 · 127 · 255 · 311 · 19.
 */
export const BANNER_PRESETS: readonly BannerPreset[] = [
  { id: 'cyan', label: 'ICE CYAN', color: 0x4de3ff, emblem: 2 },
  { id: 'verdant', label: 'VERDANT', color: 0x5cff6e, emblem: 0 },
  { id: 'violet', label: 'VIOLET', color: 0x9d7bff, emblem: 3 },
  { id: 'magenta', label: 'MAGENTA', color: 0xff5ce1, emblem: 6 },
  { id: 'ember', label: 'EMBER', color: 0xff7a3d, emblem: 7 },
];

/** Hue of a 0xRRGGBB colour, 0–360. Greys report 0. */
export function hueOf(rgb: number): number {
  const r = ((rgb >> 16) & 255) / 255;
  const g = ((rgb >> 8) & 255) / 255;
  const b = (rgb & 255) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  if (d === 0) return 0;
  let h: number;
  if (max === r) h = ((g - b) / d) % 6;
  else if (max === g) h = (b - r) / d + 2;
  else h = (r - g) / d + 4;
  return (h * 60 + 360) % 360;
}

/** Shortest distance between two hues, 0–180. */
export function hueGap(a: number, b: number): number {
  const d = Math.abs(((a - b) % 360) + 360) % 360;
  return d > 180 ? 360 - d : d;
}

/** Would this banner colour read as its own banner next to `taken`? */
export function isBannerDistinct(
  color: number,
  taken: Iterable<number>,
  minSeparation: number = BANNER_MIN_HUE_SEPARATION,
): boolean {
  const hue = hueOf(color);
  for (const other of taken) {
    if (other === color) return false;
    if (hueGap(hue, hueOf(other)) < minSeparation) return false;
  }
  return true;
}

/** The first preset nobody on the register is already flying, if any. */
export function firstFreeBanner(taken: Iterable<number>): BannerPreset | undefined {
  const list = [...taken];
  return BANNER_PRESETS.find((preset) => isBannerDistinct(preset.color, list));
}

