export const BATTLE_VIEW = {
  tileSize: 1.0,
  tileGap: 0.06,
  tileHeight: 0.12,
  obstacleHeight: 0.9,
  camera: {
    fov: 42,
    near: 0.1,
    far: 200,
    /** Low angle so the full board fits portrait. */
    polar: 0.62,
    distance: 13.5,

    // ── free look (GDD §12.3 is a framing requirement, not a cage) ──────────
    //
    // The default view still SOLVES for the whole board on screen, but the
    // player can spin all the way around the board, drop to a grazing angle or
    // rise to near-overhead, and zoom in until a single chassis fills the frame.
    /** Highest the camera may rise. Near-overhead, never straight down. */
    minPolar: 0.15,
    /** Lowest it may drop. Kept above the board plane so tiles never edge-on. */
    maxPolar: 1.32,
    /**
     * User zoom, as a multiple of the solved fit distance. Below 1 the board
     * overflows the viewport on purpose — that is what zooming in means.
     */
    minZoom: 0.38,
    maxZoom: 1.9,
    /**
     * Slack left around the board when solving the fit distance, in tile
     * pitches. This is the "how close is close" dial for the default view:
     * every unit of margin here pushes the camera back at every angle.
     */
    fitMargin: 0.1,
    /**
     * Fraction of a chassis' height the fit solve has to keep on screen.
     *
     * Solving for the full standing height of a mech on the FAR CORNER of an
     * angled board is what used to hold the camera so far back. Framing the
     * board plane plus most of a chassis is what a player actually needs; the
     * tallest heads may graze the top edge at extreme angles, which free look
     * and zoom now make a non-problem.
     */
    fitContent: 0.55,
  },
} as const;

