/**
 * TERRA BELLUM — entry point.
 *
 * Boots the backend (Firebase when configured, otherwise the full offline
 * world simulation) and hands it to the UI shell. Nothing else lives here.
 */
import './styles/tokens.css';
import { createBackend } from './backend';
import { mountApp } from './ui/app';

async function boot(): Promise<void> {
  const root = document.getElementById('app');
  if (!root) throw new Error('#app missing');

  const backend = createBackend();
  await backend.init();
  mountApp(root, backend);

  // Dev-only console handle. The whole game is driveable through `IBackend`, so
  // exposing it makes any situation reachable from devtools without a UI path —
  // march a column onto a defended hex, force a siege, replay a battle log.
  // Never present in a production bundle.
  if (import.meta.env.DEV) {
    (window as unknown as Record<string, unknown>).TB = backend;
  }

  window.addEventListener('beforeunload', () => backend.dispose());
}

boot().catch((error: unknown) => {
  console.error('[terra-bellum] fatal boot failure', error);
  const preboot = document.getElementById('preboot');
  if (preboot) {
    preboot.classList.add('preboot--failed');
    const sub = preboot.querySelector('.preboot__sub');
    if (sub) sub.textContent = 'UPLINK FAILURE — ' + String((error as Error)?.message ?? error);
  }
});
