/**
 * World generation — GDD §3.1, §3.3, §4.
 *
 * Builds the hex world, partitions it into contiguous sectors with a seeded
 * multi-source flood fill, paints terrain with layered value noise, places gas
 * fields deliberately (never risk-free), opens `MAP.activeSectors` sectors and
 * pre-generates the season's rotation order.
 *
 * PURE: no Three.js, no DOM. Runs under node.
 */
import type {
  Axial,
  GameState,
  Hex,
  HexId,
  Sector,
  SectorId,
  SeasonState,
  Terrain,
  WorldState,
} from '../types';
import { MAP, SEASON } from '../../config/balance';
import {
  axialToWorld,
  findPath,
  hexDistance,
  hexId,
  hexesInRange,
  neighborIds,
  parseHexId,
} from '../hex';
import { makeRng, type Rng } from '../rng';

// ─────────────────────────────────────────────────────────────────────────────
// Generator shaping constants (worldgen internals — NOT balance values).
// Balance-relevant numbers all come from MAP / SEASON.
// ─────────────────────────────────────────────────────────────────────────────

const GEN = {
  /** Sector seeds are sampled inside this margin so blobs stay on the disc. */
  seedMargin: 3,
  /**
   * Head-room multiplier on the landmass disc. The sectors can never cover the
   * whole `MAP.worldRadius` disc (sectorCount × sectorSizeMax < its area), so
   * the continent is grown in the centre of that disc with a little slack for
   * an organic, ragged coastline.
   */
  coreSlack: 1.0,
  /** Attempts before accepting a best-effort partition. */
  partitionAttempts: 8,
  /** Passes of enclosed-hole absorption after the flood fill. */
  holePasses: 3,
  /** Noise frequencies (in hex-world units). */
  ridgeFreqX: 0.13,
  ridgeFreqY: 0.34,
  craterFreq: 0.19,
  ruinFreq: 0.44,
  ridgeOctaves: 3,
  craterOctaves: 2,
  ruinOctaves: 2,
  /** Terrain thresholds — calibrated for a plains-dominant, chain-ridged map. */
  ridgeThreshold: 0.865,
  craterThreshold: 0.63,
  ruinThreshold: 0.68,
  /** Gas fields must sit at least this far apart. */
  gasMinSeparation: 3,
  /**
   * A gas hex must be fully interior (all six neighbours exist). GDD §4: never
   * place gas where it can be held risk-free — a coastline hex has fewer
   * approach lanes and is therefore cheap to hold.
   */
  gasMinNeighbours: 6,
  /** Extra chokepoint gas fields, as a multiple of the sector count. */
  chokepointGasPerSector: 0.5,
} as const;

