// ─────────────────────────────────────────────────────────────────────────────
// Value noise (deterministic, seed-driven)
// ─────────────────────────────────────────────────────────────────────────────

function hash2(seed: number, x: number, y: number): number {
  let h = (seed ^ 0x9e3779b9) >>> 0;
  h = Math.imul(h ^ (x | 0), 0x27d4eb2f) >>> 0;
  h = Math.imul(h ^ (y | 0), 0x165667b1) >>> 0;
  h = Math.imul(h ^ (h >>> 15), 0x2545f491) >>> 0;
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const smoothstep = (t: number): number => t * t * (3 - 2 * t);

function valueNoise(seed: number, x: number, y: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = smoothstep(x - x0);
  const fy = smoothstep(y - y0);
  const a = hash2(seed, x0, y0);
  const b = hash2(seed, x0 + 1, y0);
  const c = hash2(seed, x0, y0 + 1);
  const d = hash2(seed, x0 + 1, y0 + 1);
  const top = a + (b - a) * fx;
  const bot = c + (d - c) * fx;
  return top + (bot - top) * fy;
}

function fbm(seed: number, x: number, y: number, octaves: number): number {
  let amp = 1;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(seed + i * 1013, x * freq, y * freq);
    norm += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return norm > 0 ? sum / norm : 0;
}

// ─────────────────────────────────────────────────────────────────────────────
// Public helpers
// ─────────────────────────────────────────────────────────────────────────────

/** The sector a hex belongs to, if the hex exists. */
export function sectorOf(world: WorldState, id: HexId): Sector | undefined {
  const hex = world.hexes[id];
  if (!hex) return undefined;
  return world.sectors[hex.sectorId];
}

/** Is this hex playable right now (exists and its sector is open)? */
export function isHexOpen(world: WorldState, id: HexId): boolean {
  const sector = sectorOf(world, id);
  if (!sector) return false;
  return sector.state === 'active' || sector.state === 'closing';
}

/** All hexes belonging to a sector, in stable order. */
export function hexesOfSector(world: WorldState, id: SectorId): Hex[] {
  const sector = world.sectors[id];
  if (!sector) return [];
  const out: Hex[] = [];
  for (const hid of sector.hexIds) {
    const hex = world.hexes[hid];
    if (hex) out.push(hex);
  }
  return out;
}

/** Sector adjacency map — two sectors are neighbours if any hexes touch. */
export function sectorNeighbors(world: WorldState): Record<SectorId, SectorId[]> {
  const sets = new Map<SectorId, Set<SectorId>>();
  for (const id of Object.keys(world.sectors)) sets.set(id, new Set());
  for (const hex of Object.values(world.hexes)) {
    const mine = sets.get(hex.sectorId);
    if (!mine) continue;
    for (const nb of neighborIds(hex.id)) {
      const other = world.hexes[nb];
      if (!other || other.sectorId === hex.sectorId) continue;
      mine.add(other.sectorId);
    }
  }
  const out: Record<SectorId, SectorId[]> = {};
  for (const [id, set] of sets) out[id] = [...set].sort();
  return out;
}

/**
 * Hexes a staging commander may deploy onto (GDD §3.1): ACTIVE sector, not
 * controlled or occupied by another guild's player, no capture in flight.
 * Deterministic: the ordering is derived from the season name, not Math.random.
 *
 * Note the sector test is stricter than `isHexOpen`, which also accepts
 * `closing`. A closing sector is still playable — armies fight and move through
 * it — but `IBackend.deploy` refuses to drop anyone into ground that is about to
 * go dark, so offering those hexes here would hand callers sites the backend
 * then rejects.
 */
export function randomDeployableHexes(state: GameState, count = 12): HexId[] {
  const me = state.players[state.meId];
  const myGuild = me ? (me.guildId ?? me.id) : state.meId;

  const occupied = new Map<HexId, string>();
  for (const army of Object.values(state.armies)) {
    const owner = state.players[army.ownerId];
    occupied.set(army.hexId, owner ? (owner.guildId ?? owner.id) : army.guildId);
  }

  const salt = `${state.season.name}#${state.season.index}`;
  const pool: { id: HexId; key: number }[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    if (sectorOf(state.world, hex.id)?.state !== 'active') continue;
    if (hex.capture) continue;
    if (hex.ownerId) {
      const owner = state.players[hex.ownerId];
      const key = owner ? (owner.guildId ?? owner.id) : hex.ownerId;
      if (key !== myGuild) continue;
    }
    const holder = occupied.get(hex.id);
    if (holder !== undefined && holder !== myGuild) continue;
    pool.push({ id: hex.id, key: hash2(0x5eed, hexKeyNum(hex.id, salt), 17) });
  }
  pool.sort((a, b) => (a.key === b.key ? (a.id < b.id ? -1 : 1) : a.key - b.key));

  // Greedy spread so the offered deploy sites are not all in one corner.
  const picked: HexId[] = [];
  for (const cand of pool) {
    if (picked.length >= count) break;
    const ax = parseHexId(cand.id);
    let far = true;
    for (const p of picked) {
      if (hexDistance(ax, parseHexId(p)) < GEN.gasMinSeparation) {
        far = false;
        break;
      }
    }
    if (far) picked.push(cand.id);
  }
  if (picked.length < count) {
    for (const cand of pool) {
      if (picked.length >= count) break;
      if (!picked.includes(cand.id)) picked.push(cand.id);
    }
  }
  return picked;
}

function hexKeyNum(id: HexId, salt: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < salt.length; i++) {
    h ^= salt.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

// ─────────────────────────────────────────────────────────────────────────────
// Partitioning
// ─────────────────────────────────────────────────────────────────────────────

interface Partition {
  assign: Map<HexId, number>;
  seeds: HexId[];
  sizes: number[];
}

/** Farthest-point sampling: well-spread, deterministic sector seed hexes. */
function pickSeeds(rng: Rng, candidates: HexId[], n: number): HexId[] {
  const seeds: HexId[] = [];
  if (candidates.length === 0) return seeds;
  seeds.push(candidates[rng.int(0, candidates.length - 1)]);
  const axials = candidates.map(parseHexId);
  const best = new Array<number>(candidates.length).fill(Infinity);
  while (seeds.length < n) {
    const last = parseHexId(seeds[seeds.length - 1]);
    let pickIdx = -1;
    let pickScore = -1;
    for (let i = 0; i < candidates.length; i++) {
      const d = hexDistance(axials[i], last);
      if (d < best[i]) best[i] = d;
      if (best[i] > pickScore) {
        pickScore = best[i];
        pickIdx = i;
      }
    }
    if (pickIdx < 0 || pickScore <= 0) break;
    seeds.push(candidates[pickIdx]);
  }
  return seeds;
}

/** Smallest hex-disc radius whose area covers `n` hexes. */
function coreRadiusFor(n: number): number {
  let r = 1;
  while (3 * r * (r + 1) + 1 < n) r++;
  return r;
}

function tryPartition(
  rng: Rng,
  allHexes: Set<HexId>,
  radius: number,
  strict = true,
): Partition | null {
  const targets: number[] = [];
  for (let i = 0; i < MAP.sectorCount; i++) targets.push(rng.int(MAP.sectorSizeMin, MAP.sectorSizeMax));
  const totalTarget = targets.reduce((a, b) => a + b, 0);
  const core = Math.min(radius, coreRadiusFor(Math.ceil(totalTarget * GEN.coreSlack)));

  const origin: Axial = { q: 0, r: 0 };
  const inWorld = new Set<HexId>();
  for (const id of allHexes) {
    if (hexDistance(parseHexId(id), origin) <= core) inWorld.add(id);
  }
  const candidates: HexId[] = [];
  for (const id of inWorld) {
    if (hexDistance(parseHexId(id), origin) <= core - GEN.seedMargin) candidates.push(id);
  }
  candidates.sort();
  const seeds = pickSeeds(rng, candidates, MAP.sectorCount);
  if (seeds.length < MAP.sectorCount) return null;

  const assign = new Map<HexId, number>();
  const sizes = new Array<number>(seeds.length).fill(0);
  const frontiers: HexId[][] = seeds.map((s) => [s]);

  const grow = (si: number): boolean => {
    const q = frontiers[si];
    while (q.length > 0) {
      const id = q.shift() as HexId;
      if (assign.has(id) || !inWorld.has(id)) continue;
      assign.set(id, si);
      sizes[si]++;
      for (const nb of neighborIds(id)) {
        if (inWorld.has(nb) && !assign.has(nb)) q.push(nb);
      }
      return true;
    }
    return false;
  };

  // Phase 1 — fairness: everyone reaches the minimum size before anyone grows on.
  for (let round = 0; round < MAP.sectorSizeMin; round++) {
    for (let si = 0; si < seeds.length; si++) {
      if (sizes[si] < MAP.sectorSizeMin) grow(si);
    }
  }
  if (strict) {
    for (let si = 0; si < seeds.length; si++) {
      if (sizes[si] < MAP.sectorSizeMin) return null;
    }
  }

  // Phase 2 — grow towards each sector's own target size.
  let moved = true;
  while (moved) {
    moved = false;
    for (let si = 0; si < seeds.length; si++) {
      if (sizes[si] < targets[si] && grow(si)) moved = true;
    }
  }

  // Absorb enclosed holes so sectors are solid blobs, never doughnuts.
  for (let pass = 0; pass < GEN.holePasses; pass++) {
    for (const id of inWorld) {
      if (assign.has(id)) continue;
      const tally = new Map<number, number>();
      let nbCount = 0;
      for (const nb of neighborIds(id)) {
        if (!inWorld.has(nb)) continue;
        nbCount++;
        const si = assign.get(nb);
        if (si !== undefined) tally.set(si, (tally.get(si) ?? 0) + 1);
      }
      let bestSi = -1;
      let bestN = 0;
      for (const [si, n] of tally) {
        if (n > bestN || (n === bestN && si < bestSi)) {
          bestN = n;
          bestSi = si;
        }
      }
      if (bestSi < 0) continue;
      if (bestN < nbCount - 1 || bestN < 4) continue;
      if (sizes[bestSi] >= MAP.sectorSizeMax) continue;
      assign.set(id, bestSi);
      sizes[bestSi]++;
    }
  }

  // Contiguity repair: keep the largest component, re-home or trim the rest.
  for (let si = 0; si < seeds.length; si++) {
    const members = new Set<HexId>();
    for (const [id, s] of assign) if (s === si) members.add(id);
    const components = splitComponents(members);
    if (components.length <= 1) continue;
    components.sort((a, b) => b.length - a.length);
    for (let ci = 1; ci < components.length; ci++) {
      for (const id of components[ci]) {
        assign.delete(id);
        sizes[si]--;
        const tally = new Map<number, number>();
        for (const nb of neighborIds(id)) {
          const s = assign.get(nb);
          if (s !== undefined && s !== si) tally.set(s, (tally.get(s) ?? 0) + 1);
        }
        let bestSi = -1;
        let bestN = 0;
        for (const [s, n] of tally) {
          if (n > bestN) {
            bestN = n;
            bestSi = s;
          }
        }
        if (bestSi >= 0 && sizes[bestSi] < MAP.sectorSizeMax) {
          assign.set(id, bestSi);
          sizes[bestSi]++;
        }
      }
    }
  }

  if (strict) {
    for (let si = 0; si < seeds.length; si++) {
      if (sizes[si] < MAP.sectorSizeMin || sizes[si] > MAP.sectorSizeMax) return null;
    }
  }
  return { assign, seeds, sizes };
}

function splitComponents(members: Set<HexId>): HexId[][] {
  const seen = new Set<HexId>();
  const out: HexId[][] = [];
  for (const start of members) {
    if (seen.has(start)) continue;
    const comp: HexId[] = [];
    const stack = [start];
    seen.add(start);
    while (stack.length > 0) {
      const id = stack.pop() as HexId;
      comp.push(id);
      for (const nb of neighborIds(id)) {
        if (members.has(nb) && !seen.has(nb)) {
          seen.add(nb);
          stack.push(nb);
        }
      }
    }
    out.push(comp);
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Terrain
// ─────────────────────────────────────────────────────────────────────────────

function terrainAt(seed: number, a: Axial): Terrain {
  const w = axialToWorld(a, 1);
  // Ridged noise, sampled anisotropically so uplifts form chains, not blobs.
  const ridgeRaw = fbm(seed ^ 0x1f3a, w.x * GEN.ridgeFreqX, w.z * GEN.ridgeFreqY, GEN.ridgeOctaves);
  const ridge = 1 - Math.abs(2 * ridgeRaw - 1);
  const crater = fbm(seed ^ 0x7c19, w.x * GEN.craterFreq, w.z * GEN.craterFreq, GEN.craterOctaves);
  const ruin = fbm(seed ^ 0x2b6d, w.x * GEN.ruinFreq, w.z * GEN.ruinFreq, GEN.ruinOctaves);

  if (ruin > GEN.ruinThreshold) return 'ruins';
  if (crater > GEN.craterThreshold) return 'crater';
  if (ridge > GEN.ridgeThreshold) return 'ridge';
  return 'plains';
}

// ─────────────────────────────────────────────────────────────────────────────
// Gas placement (GDD §4 — deliberate, contested, never risk-free)
// ─────────────────────────────────────────────────────────────────────────────

function gasEligible(world: WorldState, id: HexId): boolean {
  const hex = world.hexes[id];
  if (!hex) return false;
  if (hex.gas) return false;
  if (hexDistance({ q: hex.q, r: hex.r }, { q: 0, r: 0 }) >= world.radius) return false;
  let nb = 0;
  for (const n of neighborIds(id)) if (world.hexes[n]) nb++;
  return nb >= GEN.gasMinNeighbours;
}

function farEnoughFromGas(world: WorldState, gas: HexId[], id: HexId): boolean {
  const a = parseHexId(id);
  for (const g of gas) {
    if (hexDistance(a, parseHexId(g)) < GEN.gasMinSeparation) return false;
  }
  return true;
}

function placeGas(world: WorldState, gas: HexId[], id: HexId): void {
  const hex = world.hexes[id];
  if (!hex) return;
  hex.gas = true;
  hex.terrain = 'gasfield';
  gas.push(id);
}

// ─────────────────────────────────────────────────────────────────────────────
// generateWorld
// ─────────────────────────────────────────────────────────────────────────────

export interface GeneratedWorld {
  world: WorldState;
  season: SeasonState;
}

export function generateWorld(seed: number, now: number): GeneratedWorld {
  const radius = MAP.worldRadius;
  const all = hexesInRange({ q: 0, r: 0 }, radius);
  const inWorld = new Set<HexId>(all.map((a) => hexId(a.q, a.r)));

  let partition: Partition | null = null;
  for (let attempt = 0; attempt < GEN.partitionAttempts && !partition; attempt++) {
    partition = tryPartition(makeRng((seed + attempt * 7919) >>> 0), inWorld, radius);
  }
  if (!partition) {
    // Last resort: accept the un-validated fill from the base seed.
    partition = tryPartition(makeRng(seed >>> 0), inWorld, radius, false);
  }
  if (!partition) throw new Error('generateWorld: unable to partition the world');

  const rng = makeRng((seed ^ 0x51ed270b) >>> 0);
  const nameRng = rng.fork('names');

  // ── sectors ───────────────────────────────────────────────────────────────
  const callsigns = nameRng.shuffle([...SECTOR_CALLSIGNS]);
  const sectors: Record<SectorId, Sector> = {};
  const sectorIds: SectorId[] = [];
  for (let si = 0; si < partition.seeds.length; si++) {
    const id = `sec-${String(si + 1).padStart(2, '0')}`;
    const call = callsigns[si % callsigns.length];
    sectorIds.push(id);
    sectors[id] = {
      id,
      name: call,
      designation: `SEC-${String(si + 1).padStart(2, '0')} ${call}`,
      center: { q: 0, r: 0 },
      hexIds: [],
      state: 'locked',
      rotationIndex: -1,
    };
  }

  // ── hexes ─────────────────────────────────────────────────────────────────
  const hexes: Record<HexId, Hex> = {};
  const sortedIds = [...partition.assign.keys()].sort();
  for (const id of sortedIds) {
    const si = partition.assign.get(id) as number;
    const sectorId = sectorIds[si];
    const a = parseHexId(id);
    hexes[id] = {
      id,
      q: a.q,
      r: a.r,
      sectorId,
      terrain: terrainAt(seed, a),
      gas: false,
      fortLevel: 0,
      production: [],
      reserves: {},
    };
    sectors[sectorId].hexIds.push(id);
  }

  // `radius` describes the generated continent, not the sampling disc, so the
  // camera and the "outer ring" rules both work off a real extent.
  let extent = 0;
  for (const id of sortedIds) {
    const a = parseHexId(id);
    extent = Math.max(extent, hexDistance(a, { q: 0, r: 0 }));
  }
  const world: WorldState = { hexes, sectors, radius: extent };

  // ── sector centres ────────────────────────────────────────────────────────
  for (const sid of sectorIds) {
    const members = sectors[sid].hexIds;
    let sq = 0;
    let sr = 0;
    for (const id of members) {
      const h = hexes[id];
      sq += h.q;
      sr += h.r;
    }
    const avg: Axial = { q: sq / members.length, r: sr / members.length };
    let bestId = members[0];
    let bestD = Infinity;
    for (const id of members) {
      const h = hexes[id];
      const d =
        (h.q - avg.q) * (h.q - avg.q) +
        (h.r - avg.r) * (h.r - avg.r) +
        (h.q + h.r - avg.q - avg.r) * (h.q + h.r - avg.q - avg.r);
      if (d < bestD) {
        bestD = d;
        bestId = id;
      }
    }
    const c = hexes[bestId];
    sectors[sid].center = { q: c.q, r: c.r };
  }

  // ── gas: one at/near every sector centroid ────────────────────────────────
  const gas: HexId[] = [];
  for (const sid of sectorIds) {
    const centre = sectors[sid].center;
    const centreId = hexId(centre.q, centre.r);
    const members = [...sectors[sid].hexIds].sort((a, b) => {
      const da = hexDistance(parseHexId(a), centre);
      const db = hexDistance(parseHexId(b), centre);
      return da === db ? (a < b ? -1 : 1) : da - db;
    });
    let placed = false;
    if (gasEligible(world, centreId) && farEnoughFromGas(world, gas, centreId)) {
      placeGas(world, gas, centreId);
      placed = true;
    }
    for (let i = 0; i < members.length && !placed; i++) {
      const id = members[i];
      if (!gasEligible(world, id)) continue;
      if (!farEnoughFromGas(world, gas, id)) continue;
      placeGas(world, gas, id);
      placed = true;
    }
    if (!placed) {
      // Relax separation rather than leave a sector gasless.
      for (const id of members) {
        if (!gasEligible(world, id)) continue;
        placeGas(world, gas, id);
        break;
      }
    }
  }

  // ── gas: chokepoints between adjacent sectors ─────────────────────────────
  const adjacency = sectorNeighbors(world);
  const pairs: [SectorId, SectorId][] = [];
  for (const a of sectorIds) {
    for (const b of adjacency[a] ?? []) {
      if (a < b) pairs.push([a, b]);
    }
  }
  const extraBudget = MAP.sectorCount * GEN.chokepointGasPerSector;
  let extras = 0;
  const passable = (id: HexId): boolean => world.hexes[id] !== undefined;
  const stepCost = (id: HexId): number => {
    const h = world.hexes[id];
    return h ? MAP.moveCostByTerrain[h.terrain] : 1;
  };
  for (const [a, b] of pairs) {
    if (extras >= extraBudget) break;
    const from = hexId(sectors[a].center.q, sectors[a].center.r);
    const to = hexId(sectors[b].center.q, sectors[b].center.r);
    const path = findPath(from, to, passable, stepCost);
    if (!path || path.length === 0) continue;
    // The border crossing on the sector-to-sector corridor is the chokepoint.
    let chosen: HexId | undefined;
    for (const id of path) {
      const h = world.hexes[id];
      if (!h) continue;
      let touchesOther = false;
      for (const nb of neighborIds(id)) {
        const n = world.hexes[nb];
        if (n && n.sectorId !== h.sectorId) touchesOther = true;
      }
      if (!touchesOther) continue;
      if (!gasEligible(world, id)) continue;
      if (!farEnoughFromGas(world, gas, id)) continue;
      chosen = id;
      break;
    }
    if (chosen) {
      placeGas(world, gas, chosen);
      extras++;
    }
  }

  // ── active sectors: ONE CONNECTED THEATRE ─────────────────────────────────
  //
  // These used to be chosen for maximum separation, and that is what turned the
  // open map into a set of private neighbourhoods. `isHexOpen` bars every hex of
  // a locked sector, so four sectors scattered across a radius-22 world are four
  // SEALED ISLANDS: there is no passable ground between them, `planPath` cannot
  // route from one to another, and two banners holding different sectors were
  // physically unable to reach each other for the whole week.
  //
  // The open sectors now form a contiguous block. Every sector borders another
  // live sector, so every border is a real front and every banner on the map is
  // reachable by march.
  // `adjacency` is the sector border graph already built for the gas step above.
  const activeRng = rng.fork('active');
  const chosenActive: SectorId[] = [];
  const remaining = [...sectorIds];
  const firstIdx = activeRng.int(0, remaining.length - 1);
  chosenActive.push(remaining.splice(firstIdx, 1)[0]);
  while (chosenActive.length < Math.min(MAP.activeSectors, sectorIds.length)) {
    // Prefer a sector that actually shares a border with the theatre. The
    // centre-distance tie-break only decides between candidates that already
    // touch it; the fallback to `remaining` exists so a sector graph that cannot
    // be grown any further still opens the requested number of sectors.
    const touching = remaining.filter((cand) =>
      chosenActive.some((picked) => adjacency[cand]?.includes(picked)),
    );
    const pool = touching.length > 0 ? touching : remaining;
    let bestId = pool[0];
    let bestScore = Infinity;
    for (const cand of pool) {
      let minD = Infinity;
      for (const picked of chosenActive) {
        minD = Math.min(minD, hexDistance(sectors[cand].center, sectors[picked].center));
      }
      if (minD < bestScore) {
        bestScore = minD;
        bestId = cand;
      }
    }
    chosenActive.push(bestId);
    remaining.splice(remaining.indexOf(bestId), 1);
  }
  for (const sid of chosenActive) sectors[sid].state = 'active';

  // ── season + rotation ordered as a walk outward from the theatre ──────────
  //
  // A shuffled rotation can unseal a sector on the far side of the world, which
  // re-fragments the map into islands the moment it opens. Walking the sector
  // border graph instead keeps the playable ground contiguous all season, so
  // "pre-position near the next sector" (GDD §3.2) is a march somebody can
  // actually make rather than an instruction with no route.
  const rotationRng = rng.fork('rotation');
  const lockedIds = sectorIds.filter((id) => sectors[id].state === 'locked');
  const rotation: SectorId[] = [];
  const reachable = new Set<SectorId>(chosenActive);
  const pending = new Set<SectorId>(lockedIds);
  while (pending.size > 0) {
    const frontier = [...pending]
      .filter((id) => [...reachable].some((open) => adjacency[id]?.includes(open)))
      .sort();
    const choices = frontier.length > 0 ? frontier : [...pending].sort();
    const pick = rotationRng.pick(choices);
    rotation.push(pick);
    reachable.add(pick);
    pending.delete(pick);
  }
  rotation.forEach((sid, i) => {
    sectors[sid].rotationIndex = i;
  });

  const seasonIndex = 1;
  const seasonName = SEASON_NAMES[rng.fork('season').int(0, SEASON_NAMES.length - 1)];
  const season: SeasonState = {
    index: seasonIndex,
    name: `SEASON ${ROMAN[seasonIndex] ?? seasonIndex} — ${seasonName}`,
    startedAt: now,
    endsAt: now + SEASON.lengthMs,
    phase: 'running',
    rotation,
    rotationCursor: 0,
    nextRotationAt: now + SEASON.rotationMs,
    contested: [],
  };

  return { world, season };
}

