/**
 * Self-updating countdown readouts in tabular monospace.
 *
 * A single shared rAF loop drives every live countdown on screen, so a roster
 * with forty timers still costs one animation frame callback.
 */
import { el, fmtDuration } from '../dom';

export interface CountdownOpts {
  /** Clock source. Defaults to `Date.now`. Pass the simulated clock where relevant. */
  getNow?: () => number;
  onDone?: () => void;
  /** Small uppercase label before the digits. */
  prefix?: string;
  /** Drop the prefix and shrink the digits. */
  compact?: boolean;
  /** Text shown once the target has passed. Defaults to `READY`. */
  doneText?: string;
  class?: string;
}

export interface CountdownController {
  el: HTMLElement;
  stop(): void;
  /** Point the same readout at a new deadline (order re-queued, timer reset). */
  setTarget(at: number): void;
}

interface Entry {
  tick: () => void;
}

const live = new Set<Entry>();
let loopHandle = 0;
let lastPaint = 0;

function loop(t: number): void {
  // 4 Hz is plenty for second-resolution digits and keeps the main thread free.
  if (t - lastPaint >= 240) {
    lastPaint = t;
    for (const entry of live) entry.tick();
  }
  loopHandle = live.size > 0 ? requestAnimationFrame(loop) : 0;
}

function ensureLoop(): void {
  if (loopHandle === 0 && live.size > 0) loopHandle = requestAnimationFrame(loop);
}

/** Urgency thresholds, in REAL ms remaining. */
const URGENT_MS = 60_000;
const SOON_MS = 10 * 60_000;

/**
 * Simulated milliseconds per real millisecond.
 *
 * Every deadline in the game is stamped in world time, but the offline sim runs
 * world time compressed (`SIM.timeScale`), so a regroup that reads "47:00" is
 * over in ninety seconds of the player's life. Countdowns are promises about
 * when the player may act again, so they are rendered in the player's clock,
 * not the world's. The shell installs the real source at boot; the default of 1
 * keeps this honest for a server-backed build where the two clocks agree.
 */
let clockScale: () => number = () => 1;

export function setClockScale(fn: () => number): void {
  clockScale = fn;
}

function realRemaining(gameMs: number): number {
  const scale = clockScale();
  return Number.isFinite(scale) && scale > 0 ? gameMs / scale : gameMs;
}

export function countdown(targetAt: number, opts: CountdownOpts = {}): CountdownController {
  const now = opts.getNow ?? Date.now;
  const classes = ['cd'];
  if (opts.compact) classes.push('cd--compact');
  if (opts.class) classes.push(opts.class);

  const root = el('span', { class: classes.join(' '), aria: { live: 'off' } });
  if (opts.prefix && !opts.compact) {
    root.appendChild(el('span', { class: 'cd__prefix', text: opts.prefix }));
  }
  const value = el('span', { class: 'cd__value' });
  root.appendChild(value);

  let target = targetAt;
  let fired = false;
  let stopped = false;
  let lastText = '';

  const tick = (): void => {
    const remain = realRemaining(target - now());
    if (remain <= 0) {
      if (!fired) {
        fired = true;
        root.classList.remove('cd--urgent', 'cd--soon');
        root.classList.add('cd--done');
        value.textContent = opts.doneText ?? 'READY';
        opts.onDone?.();
      }
      return;
    }
    root.classList.toggle('cd--urgent', remain <= URGENT_MS);
    root.classList.toggle('cd--soon', remain > URGENT_MS && remain <= SOON_MS);
    root.classList.remove('cd--done');
    const text = fmtDuration(remain);
    if (text !== lastText) {
      lastText = text;
      value.textContent = text;
    }
  };

  const entry: Entry = { tick };
  live.add(entry);
  ensureLoop();
  tick();

  return {
    el: root,
    stop(): void {
      if (stopped) return;
      stopped = true;
      live.delete(entry);
    },
    setTarget(at: number): void {
      target = at;
      fired = false;
      lastText = '';
      if (!stopped && !live.has(entry)) {
        live.add(entry);
        ensureLoop();
      }
      tick();
    },
  };
}
