/**
 * Spy drones — GDD §5.1.
 *
 * Cheap, expendable recon. Drones never trigger battles and are invisible by
 * default. Every hex they enter that is enemy-controlled, or adjacent to an
 * enemy army, rolls a detection check. Whatever they saw is snapshotted into
 * the guild intel ledger and PERSISTS as last-seen data after the drone has
 * moved on — or died.
 *
 * PURE: no Three.js, no DOM.
 */
import type {
  ArmyIntel,
  Drone,
  DroneId,
  GameState,
  GuildId,
  Hex,
  HexId,
  IntelSnapshot,
  MoveStep,
  PlayerId,
  Result,
  UnitType,
} from '../types';
import { err, ok } from '../types';
import { DRONES, MAP } from '../../config/balance';
import { UNITS } from '../../config/units';
import { findPath, hexId as makeHexId, hexesInRange, neighborIds, parseHexId } from '../hex';
import type { Rng } from '../rng';
import { uid } from '../rng';
import { isHexOpen } from './generate';
import { canAfford, spend } from './economy';
import { areHostile, armiesOnHex, factionOf } from './movement';

export type DroneEvent =
  | { t: 'drone_moved'; at: number; droneId: DroneId; guildId: GuildId; hexId: HexId; risky: boolean }
  | { t: 'drone_arrived'; at: number; droneId: DroneId; guildId: GuildId; hexId: HexId }
  | {
      t: 'drone_detected';
      at: number;
      droneId: DroneId;
      hexId: HexId;
      /** Guild of origin — this is what the alert names. */
      droneGuildId: GuildId;
      droneOwnerId: PlayerId;
      /** Territory owner who caught it, when the hex is owned. */
      byGuildId?: GuildId;
      byPlayerId?: PlayerId;
      chance: number;
    };

// ─────────────────────────────────────────────────────────────────────────────
// Risk model
// ─────────────────────────────────────────────────────────────────────────────

/** Detection odds on a risky hex: base + per enemy fortification level. */
export function detectionChance(hex: Hex): number {
  const raw = DRONES.baseDetection + DRONES.perFortLevel * hex.fortLevel;
  return Math.min(1, Math.max(0, raw));
}

/** Enemy-controlled, or adjacent to an enemy army (GDD §5.1). */
export function isRiskyHex(state: GameState, ownerId: PlayerId, hexId: HexId): boolean {
  const hex = state.world.hexes[hexId];
  if (!hex) return false;
  if (hex.ownerId && areHostile(state, hex.ownerId, ownerId)) return true;
  for (const id of [hexId, ...neighborIds(hexId)]) {
    for (const army of armiesOnHex(state, id)) {
      if (army.units.length === 0) continue;
      if (areHostile(state, army.ownerId, ownerId)) return true;
    }
  }
  return false;
}

// ─────────────────────────────────────────────────────────────────────────────
// Intel ledger
// ─────────────────────────────────────────────────────────────────────────────

function armyIntelOn(state: GameState, hexId: HexId): ArmyIntel | undefined {
  const armies = armiesOnHex(state, hexId).filter((a) => a.units.length > 0);
  if (armies.length === 0) return undefined;
  const army = armies.reduce((a, b) => (b.units.length > a.units.length ? b : a));
  const owner = state.players[army.ownerId];
  const guild = state.guilds[army.guildId];
  const composition: Partial<Record<UnitType, number>> = {};
  for (const unit of army.units) {
    composition[unit.type] = (composition[unit.type] ?? 0) + 1;
  }
  return {
    ownerId: army.ownerId,
    ownerName: owner?.name ?? 'UNKNOWN',
    guildId: army.guildId,
    guildTag: guild?.tag ?? '???',
    unitCount: army.units.length,
    composition,
  };
}

/**
 * Snapshot the current hex plus its `DRONES.intelRadius` ring into the guild's
 * ledger. Entries are timestamped and never expire — they are the "last seen"
 * overlay on the guild map.
 */
export function writeIntel(state: GameState, guildId: GuildId, hexId: HexId, now: number): void {
  const ledger = (state.intel[guildId] ??= {});
  const centre = parseHexId(hexId);
  for (const a of hexesInRange(centre, DRONES.intelRadius)) {
    const id = makeHexId(a.q, a.r);
    const hex = state.world.hexes[id];
    if (!hex) continue;
    const owner = hex.ownerId ? state.players[hex.ownerId] : undefined;
    const ownerGuild = owner?.guildId ? state.guilds[owner.guildId] : undefined;
    const snap: IntelSnapshot = {
      hexId: id,
      at: now,
      ownerId: hex.ownerId,
      ownerName: owner?.name,
      guildId: owner?.guildId,
      guildTag: ownerGuild?.tag,
      fortLevel: hex.fortLevel,
      army: armyIntelOn(state, id),
    };
    ledger[id] = snap;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Orders
// ─────────────────────────────────────────────────────────────────────────────

function planDronePath(state: GameState, from: HexId, to: HexId): Result<HexId[]> {
  const world = state.world;
  if (!world.hexes[from]) return err('launch hex is outside the world');
  if (!world.hexes[to]) return err('target hex is outside the world');
  if (!isHexOpen(world, to)) return err('target sector is locked');
  if (from === to) return ok([]);
  const path = findPath(
    from,
    to,
    (id) => isHexOpen(world, id),
    () => 1,
  );
  if (!path || path.length === 0) return err('no route through open sectors');
  return ok(path);
}

function buildSteps(path: HexId[], now: number): MoveStep[] {
  const steps: MoveStep[] = [];
  let at = now;
  for (const hexId of path) {
    at += MAP.droneMsPerHex;
    steps.push({ hexId, arrivesAt: at });
  }
  return steps;
}

export function aliveDronesOf(state: GameState, playerId: PlayerId): Drone[] {
  return Object.values(state.drones).filter((d) => d.alive && d.ownerId === playerId);
}

/** Buy and launch a recon mote from friendly ground. */
export function launchDrone(
  state: GameState,
  playerId: PlayerId,
  fromHexId: HexId,
  destHexId: HexId,
  now: number,
): Result<DroneId> {
  const player = state.players[playerId];
  if (!player) return err('no such commander');
  const from = state.world.hexes[fromHexId];
  if (!from) return err('no such hex');
  if (!isHexOpen(state.world, fromHexId)) return err('sector is locked');

  const holdsGround =
    from.ownerId === playerId ||
    armiesOnHex(state, fromHexId).some((a) => a.ownerId === playerId && a.units.length > 0);
  if (!holdsGround) return err('drones launch from ground you hold');

  if (aliveDronesOf(state, playerId).length >= DRONES.maxPerPlayer) {
    return err(`drone control is capped at ${DRONES.maxPerPlayer}`);
  }
  const cost = UNITS.drone.cost;
  if (!canAfford(state, playerId, cost)) return err('insufficient resources');

  const planned = planDronePath(state, fromHexId, destHexId);
  if (!planned.ok) return err(planned.error);
  if (!spend(state, playerId, cost)) return err('insufficient resources');

  const steps = buildSteps(planned.value, now);
  const id = uid('drn');
  const guildId = factionOf(state, playerId);
  const drone: Drone = {
    id,
    ownerId: playerId,
    guildId,
    hexId: fromHexId,
    path: steps,
    movingFrom: steps.length > 0 ? fromHexId : undefined,
    departedAt: steps.length > 0 ? now : undefined,
    arrivesAt: steps.length > 0 ? steps[0].arrivesAt : undefined,
    alive: true,
  };
  state.drones[id] = drone;
  writeIntel(state, guildId, fromHexId, now);
  return ok(id);
}

/** Re-task a drone already in the field. */
export function moveDrone(
  state: GameState,
  droneId: DroneId,
  destHexId: HexId,
  now: number,
): Result<void> {
  const drone = state.drones[droneId];
  if (!drone) return err('no such drone');
  if (!drone.alive) return err('that drone is gone');
  const planned = planDronePath(state, drone.hexId, destHexId);
  if (!planned.ok) return err(planned.error);
  if (planned.value.length === 0) return err('drone is already there');

  drone.path = buildSteps(planned.value, now);
  drone.movingFrom = drone.hexId;
  drone.departedAt = now;
  drone.arrivesAt = drone.path[0].arrivesAt;
  return ok(undefined);
}

/** Pull a drone out of the field. Its intel stays on the guild map. */
export function recallDrone(state: GameState, droneId: DroneId): Result<void> {
  const drone = state.drones[droneId];
  if (!drone) return err('no such drone');
  delete state.drones[droneId];
  return ok(undefined);
}

// ─────────────────────────────────────────────────────────────────────────────
// Tick
// ─────────────────────────────────────────────────────────────────────────────

/** Advance drones, relay intel, roll detection. */
export function tickDrones(state: GameState, now: number, rng: Rng): DroneEvent[] {
  const out: DroneEvent[] = [];
  for (const drone of Object.values(state.drones)) {
    if (!drone.alive) continue;
    let guard = 0;
    while (drone.alive && drone.arrivesAt !== undefined && drone.arrivesAt <= now && guard++ < 1024) {
      const step = drone.path[0];
      if (!step) {
        clearDroneMovement(drone);
        break;
      }
      const hex = state.world.hexes[step.hexId];
      if (!hex || !isHexOpen(state.world, step.hexId)) {
        clearDroneMovement(drone);
        break;
      }

      const at = step.arrivesAt;
      drone.hexId = step.hexId;
      drone.path.shift();

      // Relay first — the mote transmits before anyone can shoot it down.
      writeIntel(state, drone.guildId, drone.hexId, at);

      const risky = isRiskyHex(state, drone.ownerId, drone.hexId);
      out.push({
        t: 'drone_moved',
        at,
        droneId: drone.id,
        guildId: drone.guildId,
        hexId: drone.hexId,
        risky,
      });

      if (risky) {
        const chance = detectionChance(hex);
        if (rng.chance(chance)) {
          drone.alive = false;
          clearDroneMovement(drone);
          const byPlayerId = hex.ownerId;
          out.push({
            t: 'drone_detected',
            at,
            droneId: drone.id,
            hexId: drone.hexId,
            droneGuildId: drone.guildId,
            droneOwnerId: drone.ownerId,
            byPlayerId,
            byGuildId: byPlayerId ? factionOf(state, byPlayerId) : undefined,
            chance,
          });
          break;
        }
      }

      if (drone.path.length > 0) {
        drone.movingFrom = step.hexId;
        drone.departedAt = at;
        drone.arrivesAt = drone.path[0].arrivesAt;
      } else {
        clearDroneMovement(drone);
        out.push({
          t: 'drone_arrived',
          at,
          droneId: drone.id,
          guildId: drone.guildId,
          hexId: drone.hexId,
        });
      }
    }
  }
  return out;
}

function clearDroneMovement(drone: Drone): void {
  drone.path = [];
  drone.movingFrom = undefined;
  drone.departedAt = undefined;
  drone.arrivesAt = undefined;
}
