/**
 * Unit production — GDD §5, §6.
 *
 * Units are built at any owned hex with fortification level ≥ 1. Finished units
 * join a co-located friendly army when it has room under `BATTLE.armyCap`,
 * otherwise they drop into the hex reserve garrison.
 *
 * PURE: no Three.js, no DOM.
 */
import type {
  ArmyId,
  Cost,
  GameState,
  HexId,
  PlayerId,
  ProductionOrder,
  Result,
  UnitType,
} from '../types';
import { err, ok } from '../types';
import { BATTLE } from '../../config/balance';
import { COMBAT_UNIT_TYPES, GAS_GATED, UNITS } from '../../config/units';
import { isHexOpen } from './generate';
import { canAfford, refund, scaleCost, spend } from './economy';
import { armiesOnHex } from './movement';
import { uid } from '../rng';

export type ProductionEvent =
  | {
      t: 'unit_ready';
      at: number;
      hexId: HexId;
      ownerId: PlayerId;
      orderId: string;
      unitType: UnitType;
      /** Set when the unit joined a co-located army instead of the reserve. */
      toArmyId?: ArmyId;
    }
  | {
      t: 'order_complete';
      at: number;
      hexId: HexId;
      ownerId: PlayerId;
      orderId: string;
      unitType: UnitType;
    }
  | { t: 'order_cancelled'; at: number; hexId: HexId; orderId: string; reason: string };

/** Validate a production request and return the total cost. */
export function canProduce(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  unitType: UnitType,
  count: number,
): Result<Cost> {
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (!isHexOpen(state.world, hexId)) return err('sector is locked');
  if (hex.ownerId !== playerId) return err('you do not hold this hex');
  if (hex.fortLevel < 1) return err('an Outpost is required to produce units');
  if (hex.capture) return err('hex is being contested');
  if (!Number.isInteger(count) || count < 1) return err('invalid unit count');
  if (!COMBAT_UNIT_TYPES.includes(unitType)) {
    return err('spy drones are launched from the map, not queued here');
  }

  const def = UNITS[unitType];
  const player = state.players[playerId];
  if (!player) return err('no such commander');
  if (GAS_GATED.includes(unitType) && player.gas < def.cost.g) {
    return err(`${def.name} needs ${def.cost.g} Gas per unit`);
  }
  const total = scaleCost(def.cost, count);
  if (!canAfford(state, playerId, total)) return err('insufficient resources');
  return ok(total);
}

/** Debit the full run and queue it. */
export function startProduction(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  unitType: UnitType,
  count: number,
  now: number,
): Result<string> {
  const check = canProduce(state, playerId, hexId, unitType, count);
  if (!check.ok) return err(check.error);
  if (!spend(state, playerId, check.value)) return err('insufficient resources');

  const hex = state.world.hexes[hexId];
  const order: ProductionOrder = {
    id: uid('ord'),
    unitType,
    remaining: count,
    startedAt: now,
    completesAt: now + UNITS[unitType].buildTimeMs,
  };
  hex.production.push(order);
  return ok(order.id);
}

/** Cancel a queued run; the units not yet delivered are refunded in full. */
export function cancelProduction(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  orderId: string,
): Result<Cost> {
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (hex.ownerId !== playerId) return err('you do not hold this hex');
  const idx = hex.production.findIndex((o) => o.id === orderId);
  if (idx < 0) return err('no such production order');

  const order = hex.production[idx];
  const back = scaleCost(UNITS[order.unitType].cost, order.remaining);
  hex.production.splice(idx, 1);
  refund(state, playerId, back);
  return ok(back);
}

/** Deliver every unit whose build timer has elapsed. */
export function tickProduction(state: GameState, now: number): ProductionEvent[] {
  const out: ProductionEvent[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.production.length === 0) continue;

    if (!hex.ownerId || !isHexOpen(state.world, hex.id) || hex.fortLevel < 1) {
      for (const order of hex.production) {
        out.push({
          t: 'order_cancelled',
          at: now,
          hexId: hex.id,
          orderId: order.id,
          reason: 'the production line was lost',
        });
      }
      hex.production = [];
      continue;
    }
    const ownerId = hex.ownerId;

    const keep: ProductionOrder[] = [];
    for (const order of hex.production) {
      const def = UNITS[order.unitType];
      let guard = 0;
      while (order.remaining > 0 && order.completesAt <= now && guard++ < 4096) {
        const at = order.completesAt;
        order.remaining--;

        const army = armiesOnHex(state, hex.id).find(
          (a) => a.ownerId === ownerId && a.units.length < BATTLE.armyCap && a.path.length === 0,
        );
        if (army) {
          army.units.push({ id: uid('u'), type: order.unitType, hp: def.hp });
        } else {
          hex.reserves[order.unitType] = (hex.reserves[order.unitType] ?? 0) + 1;
        }
        out.push({
          t: 'unit_ready',
          at,
          hexId: hex.id,
          ownerId,
          orderId: order.id,
          unitType: order.unitType,
          toArmyId: army?.id,
        });

        if (order.remaining > 0) {
          order.completesAt = at + def.buildTimeMs;
        } else {
          out.push({
            t: 'order_complete',
            at,
            hexId: hex.id,
            ownerId,
            orderId: order.id,
            unitType: order.unitType,
          });
        }
      }
      if (order.remaining > 0) keep.push(order);
    }
    hex.production = keep;
  }
  return out;
}

/** Total units queued at a hex — used by the build sheet. */
export function queuedUnits(state: GameState, hexId: HexId): number {
  const hex = state.world.hexes[hexId];
  if (!hex) return 0;
  return hex.production.reduce((n, o) => n + o.remaining, 0);
}
