/**
 * TERRA BELLUM — the dice engine (GDD §7.2), implemented exactly.
 *
 *   1. Roll 3 dice, each uniform 0–4. Shown to both players.
 *   2. AFTER seeing the roll, assign each die to one of your units.
 *      Max one die per unit. Triple zero skips the whole turn. No reroll.
 *   3. Die value = that unit's AP this turn. A 0 die skips the unit.
 *   4. Actions (1 AP each): move / attack / brace.
 *   5. Any order, any combination; max 2 attacks per unit per turn.
 *   6. Timer expiry auto-passes.
 *
 * Every function mutates the passed BattleState in place, returns Result<T>,
 * and appends the matching BattleEvent to `s.log`.
 *
 * PURE MODULE: no Three.js, no DOM.
 */

import type {
  ArmyUnit,
  BattleId,
  BattleParticipant,
  BattleSide,
  BattleState,
  BattleUnit,
  DieIndex,
  FortLevel,
  HexId,
  Result,
  Terrain,
  UnitId,
} from '../types';
import { err, ok } from '../types';
import type { Rng } from '../rng';
import { makeRng } from '../rng';
import { BATTLE, FORT_RULES } from '../../config/balance';
import { UNITS } from '../../config/units';
import { buildGrid, pickTemplate } from '../board/templates';
import {
  applyEndOfTurnHazards,
  applyTileEntry,
  battleDistance,
  canEndOn,
  computeDamage,
  deployRowsFor,
  deployZone,
  effectiveRange,
  hasLineOfSight,
  hasTrait,
  isBlocking,
  isNeutralGround,
  livingUnits,
  otherSide,
  reachableTiles,
  tileAt,
  tileKey,
  unitAt,
} from './rules';

const okv = (): Result<void> => ({ ok: true, value: undefined });

const DIE_INDICES: readonly DieIndex[] = [0, 1, 2];

export interface CreateBattleInput {
  id: BattleId;
  seed: number;
  hexId: HexId;
  terrain: Terrain;
  fortLevel: FortLevel;
  attacker: BattleParticipant;
  defender: BattleParticipant;
  attackerUnits: ArmyUnit[];
  defenderUnits: ArmyUnit[];
  now: number;
}

export interface Placement {
  unitId: UnitId;
  x: number;
  y: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Construction
// ─────────────────────────────────────────────────────────────────────────────

function rosterFor(units: ArmyUnit[]): ArmyUnit[] {
  return units.filter((u) => UNITS[u.type].combat && u.hp > 0).slice(0, BATTLE.armyCap);
}

function battleUnitId(side: BattleSide, sourceId: UnitId): UnitId {
  return `${side === 'attacker' ? 'atk' : 'def'}_${sourceId}`;
}

function makeBattleUnit(au: ArmyUnit, side: BattleSide, hpBonus: number): BattleUnit {
  const def = UNITS[au.type];
  const maxHp = def.hp + hpBonus;
  const hp = Math.max(1, Math.min(au.hp + hpBonus, maxHp));
  return {
    id: battleUnitId(side, au.id),
    side,
    type: au.type,
    hp,
    maxHp,
    x: -1,
    y: -1,
    alive: true,
    braced: false,
    ap: 0,
    attacksThisTurn: 0,
    sourceUnitId: au.id,
  };
}

/**
 * Build a fresh battle. Board template, bonus-obstacle count and the default
 * deployment layouts are all drawn from forked streams off `seed`, so the whole
 * setup is reproducible from (seed, log) alone.
 */
export function createBattle(input: CreateBattleInput): BattleState {
  const rng = makeRng(input.seed);
  const atkRoster = rosterFor(input.attackerUnits);
  const defRoster = rosterFor(input.defenderUnits);
  const total = atkRoster.length + defRoster.length;

  const template = pickTemplate(input.terrain, total, rng.fork('board'));
  const grid = buildGrid(template);

  const defenderHpBonus = input.fortLevel >= 3 ? FORT_RULES.defenderHpBonus : 0;
  const units: BattleUnit[] = [
    ...atkRoster.map((au) => makeBattleUnit(au, 'attacker', 0)),
    ...defRoster.map((au) => makeBattleUnit(au, 'defender', defenderHpBonus)),
  ];

  const obstaclesToPlace =
    input.fortLevel >= 2
      ? rng.fork('obstacles').int(FORT_RULES.bonusObstaclesMin, FORT_RULES.bonusObstaclesMax)
      : 0;

  const s: BattleState = {
    id: input.id,
    seed: input.seed,
    boardId: template.id,
    boardName: template.name,
    terrain: input.terrain,
    hexId: input.hexId,
    w: template.w,
    h: template.h,
    grid,
    units,
    turn: 'attacker',
    turnNumber: 0,
    dice: null,
    assignments: {},
    phase: input.fortLevel >= 1 ? 'side_pick' : 'deploy',
    bottomSide: 'defender',
    obstaclesToPlace,
    log: [],
    turnEndsAt: input.now + BATTLE.turnMs,
    attacker: input.attacker,
    defender: input.defender,
    missedTimers: { attacker: 0, defender: 0 },
    fortLevel: input.fortLevel,
  };

  // A board can simply have nowhere legal to put a barricade: `rg_spine` and
  // `ru_atrium` are 6×6 boards whose entire neutral band is massif, rough and
  // partition, with not one plain floor tile between the deployment zones. The
  // allowance has to be clamped to what the board can actually take, or an L2
  // defender is handed tiles they cannot spend and `obstacle_place` never ends.
  s.obstaclesToPlace = Math.min(s.obstaclesToPlace, obstacleSpots(s).length);

  s.log.push({ t: 'battle_start', at: input.now, boardId: template.id, seed: input.seed });

  const deployRng = rng.fork('deploy');
  autoDeploy(s, 'attacker', deployRng);
  autoDeploy(s, 'defender', deployRng);

  return s;
}

// ─────────────────────────────────────────────────────────────────────────────
// Setup phases
// ─────────────────────────────────────────────────────────────────────────────

/** GDD §6: an L1+ fort lets the defender choose which end of the board is theirs. */
export function pickSide(s: BattleState, bottom: BattleSide, now = 0): Result<void> {
  if (s.phase !== 'side_pick') return err(`cannot pick a side during phase "${s.phase}"`);
  s.bottomSide = bottom;
  s.log.push({ t: 'side_pick', at: now, side: 'defender', bottom });

  // Zones just swapped — rebuild both default layouts from scratch.
  for (const u of s.units) {
    u.x = -1;
    u.y = -1;
  }
  const rng = makeRng(s.seed).fork(`sidepick:${bottom}`);
  autoDeploy(s, 'attacker', rng);
  autoDeploy(s, 'defender', rng);

  s.phase = s.obstaclesToPlace > 0 ? 'obstacle_place' : 'deploy';
  return okv();
}

/**
 * Would sealing (x, y) cut the board in half?
 *
 * Measured for the least mobile chassis in the game — a one-tile tracked hull
 * that may not stop on rough ground — so an L2 defender can never wall the
 * board into a maze that siege armour is physically unable to cross.
 */
function deployZonesStayConnected(s: BattleState, sealX: number, sealY: number): boolean {
  const blocked = (x: number, y: number): boolean => {
    if (x === sealX && y === sealY) return true;
    if (isBlocking(s, x, y)) return true;
    return s.grid[y][x].kind === 'rough';
  };

  const topRows: number[] = [];
  const bottomRows: number[] = [];
  for (let i = 0; i < BATTLE.deployRows; i++) {
    topRows.push(i);
    bottomRows.push(s.h - 1 - i);
  }
  const goal = new Set<string>();
  for (const y of bottomRows) {
    for (let x = 0; x < s.w; x++) if (!blocked(x, y)) goal.add(tileKey(x, y));
  }
  if (goal.size === 0) return false;

  const seen = new Set<string>();
  const queue: { x: number; y: number }[] = [];
  for (const y of topRows) {
    for (let x = 0; x < s.w; x++) {
      if (blocked(x, y)) continue;
      const k = tileKey(x, y);
      if (seen.has(k)) continue;
      seen.add(k);
      queue.push({ x, y });
    }
  }
  for (let i = 0; i < queue.length; i++) {
    const n = queue[i];
    if (goal.has(tileKey(n.x, n.y))) return true;
    const steps: [number, number][] = [
      [n.x, n.y - 1],
      [n.x + 1, n.y],
      [n.x, n.y + 1],
      [n.x - 1, n.y],
    ];
    for (const [nx, ny] of steps) {
      if (nx < 0 || ny < 0 || nx >= s.w || ny >= s.h) continue;
      const k = tileKey(nx, ny);
      if (seen.has(k) || blocked(nx, ny)) continue;
      seen.add(k);
      queue.push({ x: nx, y: ny });
    }
  }
  return false;
}

/**
 * Every tile a bonus obstacle could legally be dropped on right now.
 *
 * Mirrors `placeObstacle`. Note this is an UPPER BOUND on how many can still be
 * placed, not an exact count: sealing one lane can be exactly what makes the
 * remaining candidates illegal, because connectivity is judged against the
 * board as it stands. `finishObstacles` covers that case.
 */
export function obstacleSpots(s: BattleState): { x: number; y: number }[] {
  const out: { x: number; y: number }[] = [];
  for (let y = 0; y < s.h; y++) {
    if (!isNeutralGround(s, y)) continue;
    for (let x = 0; x < s.w; x++) {
      if (s.grid[y][x].kind !== 'floor') continue;
      if (unitAt(s, x, y)) continue;
      if (!deployZonesStayConnected(s, x, y)) continue;
      out.push({ x, y });
    }
  }
  return out;
}

/**
 * End the bonus-obstacle step, keeping whatever is already down.
 *
 * This is a rule, not a convenience. A defender can hold an allowance they are
 * physically unable to spend — seal two of the four floor tiles on `cr_ejecta`
 * and the other two would cut the board in half, so both are refused — and
 * there is no other exit from this phase. Without it the battle never starts.
 */
export function finishObstacles(s: BattleState, now = 0): Result<void> {
  if (s.phase !== 'obstacle_place') {
    return err(`cannot finish obstacle placement during phase "${s.phase}"`);
  }
  const tiles: { x: number; y: number }[] = [];
  for (let ty = 0; ty < s.h; ty++) {
    for (let tx = 0; tx < s.w; tx++) {
      if (s.grid[ty][tx].placed) tiles.push({ x: tx, y: ty });
    }
  }
  s.obstaclesToPlace = 0;
  s.log.push({ t: 'obstacles_placed', at: now, side: 'defender', tiles });
  s.phase = 'deploy';
  return okv();
}

/** GDD §6: an L2 fort defender seals 2–4 extra tiles before deployment. */
export function placeObstacle(s: BattleState, x: number, y: number, now = 0): Result<void> {
  if (s.phase !== 'obstacle_place') return err(`cannot place obstacles during phase "${s.phase}"`);
  if (s.obstaclesToPlace <= 0) return err('no bonus obstacles remaining');
  const t = tileAt(s, x, y);
  if (!t) return err('tile is off the board');
  if (t.kind !== 'floor') return err('bonus obstacles may only be placed on empty floor');
  if (!isNeutralGround(s, y)) return err('bonus obstacles may not be placed in a deployment zone');
  if (unitAt(s, x, y)) return err('tile is occupied');
  if (!deployZonesStayConnected(s, x, y)) return err('that would seal the board shut');

  t.kind = 'obstacle';
  t.placed = true;
  s.obstaclesToPlace--;

  // Out of allowance, or the seals just used up every remaining legal tile.
  if (s.obstaclesToPlace === 0 || obstacleSpots(s).length === 0) finishObstacles(s, now);
  return okv();
}

/**
 * Lay a side out automatically: short-ranged, heavily armoured chassis on the
 * front rank, artillery and flyers behind. Used by the auto-defense AI and as
 * the default layout a human commander can then drag around.
 */
export function autoDeploy(s: BattleState, side: BattleSide, rng: Rng): void {
  const zone = deployZone(s, side);
  if (zone.length === 0) return;

  const rows = deployRowsFor(s, side);
  const frontRow = side === s.bottomSide ? rows[0] : rows[rows.length - 1];
  const cx = (s.w - 1) / 2;

  const slots = zone.slice().sort((a, b) => {
    const ra = Math.abs(a.y - frontRow);
    const rb = Math.abs(b.y - frontRow);
    if (ra !== rb) return ra - rb;
    const da = Math.abs(a.x - cx);
    const db = Math.abs(b.x - cx);
    if (da !== db) return da - db;
    return a.x - b.x;
  });

  const roster = rng.shuffle(s.units.filter((u) => u.side === side && u.alive));
  roster.sort((a, b) => {
    const ra = UNITS[a.type].rng;
    const rb = UNITS[b.type].rng;
    if (ra !== rb) return ra - rb; // knife-fighters up front
    const ha = UNITS[a.type].hp;
    const hb = UNITS[b.type].hp;
    if (ha !== hb) return hb - ha; // then the thickest armour
    return 0;
  });

  for (const u of roster) {
    u.x = -1;
    u.y = -1;
  }
  const used = new Set<string>();
  for (const u of roster) {
    for (const slot of slots) {
      const k = tileKey(slot.x, slot.y);
      if (used.has(k)) continue;
      if (!canEndOn(s, u, slot.x, slot.y)) continue;
      used.add(k);
      u.x = slot.x;
      u.y = slot.y;
      break;
    }
  }
}

export function hasDeployed(s: BattleState, side: BattleSide): boolean {
  return s.log.some((e) => e.t === 'deploy' && e.side === side);
}

export function commitDeployment(
  s: BattleState,
  side: BattleSide,
  placements: Placement[],
  now = 0,
): Result<void> {
  if (s.phase !== 'deploy') return err(`cannot deploy during phase "${s.phase}"`);
  if (hasDeployed(s, side)) return err(`${side} has already deployed`);

  const roster = s.units.filter((u) => u.side === side && u.alive);
  if (placements.length !== roster.length) {
    return err(`expected ${roster.length} placements, got ${placements.length}`);
  }

  const zone = new Set(deployZone(s, side).map((p) => tileKey(p.x, p.y)));
  const seenUnits = new Set<UnitId>();
  const seenTiles = new Set<string>();

  for (const p of placements) {
    const u = roster.find((r) => r.id === p.unitId);
    if (!u) return err(`unit "${p.unitId}" is not a living ${side} unit`);
    if (seenUnits.has(p.unitId)) return err(`unit "${p.unitId}" was placed twice`);
    seenUnits.add(p.unitId);

    const key = tileKey(p.x, p.y);
    if (!zone.has(key)) return err(`(${p.x},${p.y}) is outside the ${side} deployment zone`);
    if (seenTiles.has(key)) return err(`two units were placed on (${p.x},${p.y})`);
    seenTiles.add(key);

    const t = tileAt(s, p.x, p.y);
    if (!t) return err(`(${p.x},${p.y}) is off the board`);
    if (t.kind === 'rough' && hasTrait(u, 'no_rough_end')) {
      return err(`${UNITS[u.type].name} cannot settle on rough ground`);
    }
    const occupant = unitAt(s, p.x, p.y);
    if (occupant && occupant.side !== side) return err(`(${p.x},${p.y}) is occupied`);
  }

  for (const u of roster) {
    u.x = -1;
    u.y = -1;
  }
  for (const p of placements) {
    const u = roster.find((r) => r.id === p.unitId);
    if (u) {
      u.x = p.x;
      u.y = p.y;
    }
  }

  s.log.push({
    t: 'deploy',
    at: now,
    side,
    units: roster.map((u) => ({ id: u.id, type: u.type, x: u.x, y: u.y })),
  });

  if (hasDeployed(s, 'attacker') && hasDeployed(s, 'defender')) {
    s.phase = 'rolling';
    s.turn = 'attacker';
    s.turnNumber = 1;
    s.turnEndsAt = now + BATTLE.turnMs;
    s.log.push({ t: 'turn_start', at: now, side: 'attacker', turn: 1 });
  }
  return okv();
}

// ─────────────────────────────────────────────────────────────────────────────
// The dice
// ─────────────────────────────────────────────────────────────────────────────

export function rollDice(
  s: BattleState,
  rng: Rng,
  now: number,
): Result<[number, number, number]> {
  if (s.phase !== 'rolling') return err(`cannot roll during phase "${s.phase}"`);

  // Somebody is at the console. See `timeoutPass` for why this matters.
  s.missedTimers[s.turn] = 0;

  const dice: [number, number, number] = [
    rng.int(BATTLE.diceMin, BATTLE.diceMax),
    rng.int(BATTLE.diceMin, BATTLE.diceMax),
    rng.int(BATTLE.diceMin, BATTLE.diceMax),
  ];
  s.dice = dice;
  s.assignments = {};
  for (const u of s.units) {
    u.ap = 0;
    u.die = undefined;
    u.attacksThisTurn = 0;
  }
  s.log.push({ t: 'roll', at: now, side: s.turn, dice });

  // GDD §7.2 — the 0-0-0 rule. Legal, brutal, broadcast. No mercy reroll.
  if (dice[0] === 0 && dice[1] === 0 && dice[2] === 0) {
    const who = s.turn === 'attacker' ? s.attacker : s.defender;
    s.log.push({ t: 'triple_zero', at: now, side: s.turn, playerName: who.playerName });
    advanceTurn(s, now);
    return ok(dice);
  }

  s.phase = 'assign';
  return ok(dice);
}

export function assignDie(s: BattleState, die: DieIndex, unitId: UnitId, now = 0): Result<void> {
  if (s.phase !== 'assign') return err(`cannot assign dice during phase "${s.phase}"`);
  if (!s.dice) return err('no dice have been rolled');
  if (!DIE_INDICES.includes(die)) return err(`"${String(die)}" is not a die index`);
  if (s.assignments[die] !== undefined) return err(`die ${die} is already assigned`);

  const u = s.units.find((x) => x.id === unitId);
  if (!u) return err(`unknown unit "${unitId}"`);
  if (!u.alive) return err('that unit is destroyed');
  if (u.side !== s.turn) return err('that unit is not yours this turn');

  for (const d of DIE_INDICES) {
    if (s.assignments[d] === unitId) return err('one die per unit per turn');
  }

  s.assignments[die] = unitId;
  s.log.push({ t: 'assign', at: now, side: s.turn, die, unitId, ap: s.dice[die] });
  return okv();
}

export function unassignDie(s: BattleState, die: DieIndex, _now = 0): Result<void> {
  if (s.phase !== 'assign') return err(`cannot change assignments during phase "${s.phase}"`);
  if (s.assignments[die] === undefined) return err(`die ${die} is not assigned`);
  delete s.assignments[die];
  return okv();
}

export function confirmAssignments(s: BattleState, now: number): Result<void> {
  if (s.phase !== 'assign') return err(`cannot confirm during phase "${s.phase}"`);
  const dice = s.dice;
  if (!dice) return err('no dice have been rolled');

  for (const u of s.units) {
    if (u.side !== s.turn) continue;
    u.ap = 0;
    u.die = undefined;
    u.attacksThisTurn = 0;
  }
  for (const die of DIE_INDICES) {
    const unitId = s.assignments[die];
    if (unitId === undefined) continue;
    const u = s.units.find((x) => x.id === unitId);
    if (!u || !u.alive) continue;
    u.die = die;
    u.ap = dice[die]; // a 0 die means the unit sits this one out
  }

  s.phase = 'acting';
  return okv();
}

// ─────────────────────────────────────────────────────────────────────────────
// Actions (1 AP each)
// ─────────────────────────────────────────────────────────────────────────────

function activeUnit(s: BattleState, unitId: UnitId): Result<BattleUnit> {
  if (s.phase !== 'acting') return err(`cannot act during phase "${s.phase}"`);
  const u = s.units.find((x) => x.id === unitId);
  if (!u) return err(`unknown unit "${unitId}"`);
  if (!u.alive) return err('that unit is destroyed');
  if (u.side !== s.turn) return err('that unit is not yours this turn');
  if (u.ap <= 0) return err('that unit has no action points left');
  return ok(u);
}

export function moveUnit(
  s: BattleState,
  unitId: UnitId,
  x: number,
  y: number,
  now: number,
): Result<void> {
  const found = activeUnit(s, unitId);
  if (!found.ok) return err(found.error);
  const u = found.value;

  const reach = reachableTiles(s, u, 1);
  const node = reach.get(tileKey(x, y));
  if (!node) return err(`(${x},${y}) is out of reach this action`);

  const from = { x: u.x, y: u.y };
  u.x = x;
  u.y = y;
  u.ap--;
  s.log.push({ t: 'move', at: now, unitId: u.id, from, to: { x, y }, path: node.path });
  applyTileEntry(s, u, x, y, now);
  return okv();
}

export function attack(
  s: BattleState,
  unitId: UnitId,
  targetId: UnitId,
  now: number,
): Result<void> {
  const found = activeUnit(s, unitId);
  if (!found.ok) return err(found.error);
  const u = found.value;
  if (u.attacksThisTurn >= BATTLE.maxAttacksPerTurn) {
    return err(`a unit may attack at most ${BATTLE.maxAttacksPerTurn} times per turn`);
  }

  const target = s.units.find((x) => x.id === targetId);
  if (!target) return err(`unknown target "${targetId}"`);
  if (!target.alive) return err('that target is already destroyed');
  if (target.side === u.side) return err('no friendly fire');
  if (battleDistance(u.x, u.y, target.x, target.y) > effectiveRange(s, u)) {
    return err('target is out of range');
  }
  if (!hasLineOfSight(s, u.x, u.y, target.x, target.y)) return err('no line of sight');

  const { damage, mitigated } = computeDamage(s, u, target);
  target.hp -= damage;
  const killed = target.hp <= 0;
  if (killed) {
    target.hp = 0;
    target.alive = false;
  }
  u.ap--;
  u.attacksThisTurn++;
  s.log.push({ t: 'attack', at: now, unitId: u.id, targetId: target.id, damage, mitigated, killed });

  if (killed) checkVictory(s, now);
  return okv();
}

export function attackTile(
  s: BattleState,
  unitId: UnitId,
  x: number,
  y: number,
  now: number,
): Result<void> {
  const found = activeUnit(s, unitId);
  if (!found.ok) return err(found.error);
  const u = found.value;
  if (u.attacksThisTurn >= BATTLE.maxAttacksPerTurn) {
    return err(`a unit may attack at most ${BATTLE.maxAttacksPerTurn} times per turn`);
  }

  const t = tileAt(s, x, y);
  if (!t) return err('tile is off the board');
  if (t.kind !== 'destructible' || (t.hp ?? 0) <= 0) return err('there is no wall there');
  if (battleDistance(u.x, u.y, x, y) > effectiveRange(s, u)) return err('wall is out of range');
  if (!hasLineOfSight(s, u.x, u.y, x, y)) return err('no line of sight');

  const damage = UNITS[u.type].atk;
  t.hp = (t.hp ?? 0) - damage;
  const destroyed = t.hp <= 0;
  if (destroyed) {
    t.hp = 0;
    t.kind = 'floor';
  }
  u.ap--;
  u.attacksThisTurn++;
  s.log.push({ t: 'attack_wall', at: now, unitId: u.id, x, y, damage, destroyed });
  return okv();
}

export function brace(s: BattleState, unitId: UnitId, now: number): Result<void> {
  const found = activeUnit(s, unitId);
  if (!found.ok) return err(found.error);
  const u = found.value;
  u.braced = true;
  u.ap--;
  s.log.push({ t: 'brace', at: now, unitId: u.id });
  return okv();
}

// ─────────────────────────────────────────────────────────────────────────────
// Turn flow
// ─────────────────────────────────────────────────────────────────────────────

/** Shared tail of endTurn / triple-zero: hand the board to the other side. */
function advanceTurn(s: BattleState, now: number): void {
  const acting = s.turn;
  const next = otherSide(acting);

  s.dice = null;
  s.assignments = {};
  for (const u of s.units) {
    u.ap = 0;
    u.die = undefined;
    u.attacksThisTurn = 0;
  }
  // A brace holds through the enemy turn and lifts when that unit acts again.
  for (const u of s.units) {
    if (u.side === next) u.braced = false;
  }

  applyEndOfTurnHazards(s, acting, now);

  s.turn = next;
  s.turnNumber++;
  s.turnEndsAt = now + BATTLE.turnMs;
  s.phase = 'rolling';
  s.log.push({ t: 'turn_start', at: now, side: next, turn: s.turnNumber });

  checkVictory(s, now);
}

export function endTurn(s: BattleState, now: number): Result<void> {
  if (s.phase === 'ended') return err('the battle is over');
  if (s.phase !== 'rolling' && s.phase !== 'assign' && s.phase !== 'acting') {
    return err(`cannot end a turn during phase "${s.phase}"`);
  }
  s.missedTimers[s.turn] = 0;
  s.log.push({ t: 'turn_end', at: now, side: s.turn });
  advanceTurn(s, now);
  return okv();
}

/** GDD §7.3 — concede: instant defeat, salvage handled by `concedeSurvivors`. */
export function concede(s: BattleState, side: BattleSide, now: number): Result<void> {
  if (s.phase === 'ended') return err('the battle is over');
  s.log.push({ t: 'concede', at: now, side });
  finish(s, otherSide(side), 'concede', now);
  return okv();
}

/**
 * GDD §7.3 — three missed timers is a disconnect and auto-concedes.
 *
 * CONSECUTIVE misses, deliberately. The counter is cleared the moment that side
 * rolls or ends a turn under its own steam (`rollDice`, `endTurn`), so this only
 * ever fires on a commander who has genuinely stopped answering. Counting
 * lifetime misses instead would concede the battle out from under a present but
 * slow player who let the clock run three times across a forty-turn fight —
 * which is a disconnect penalty landing on somebody who never disconnected.
 *
 * Advances the turn directly rather than through `endTurn`, which would clear
 * the very counter this function just incremented.
 */
export function timeoutPass(s: BattleState, now: number): Result<void> {
  if (s.phase === 'ended') return err('the battle is over');
  if (s.phase !== 'rolling' && s.phase !== 'assign' && s.phase !== 'acting') {
    // Setup phases have no turn clock; nothing has been missed.
    return err(`there is no turn clock running during phase "${s.phase}"`);
  }
  const side = s.turn;
  s.missedTimers[side]++;
  s.log.push({ t: 'timeout_pass', at: now, side });

  if (s.missedTimers[side] >= BATTLE.missedTimersToConcede) {
    s.log.push({ t: 'concede', at: now, side });
    finish(s, otherSide(side), 'timeout', now);
    return okv();
  }
  advanceTurn(s, now);
  return okv();
}

function finish(
  s: BattleState,
  winner: BattleSide,
  reason: 'wipe' | 'concede' | 'timeout',
  now: number,
): void {
  s.winner = winner;
  s.endReason = reason;
  s.phase = 'ended';
  s.dice = null;
  s.assignments = {};
  s.log.push({ t: 'battle_end', at: now, winner, reason });
}

/** Wipe detection (GDD §7.3: destroy all enemy units). */
export function checkVictory(s: BattleState, now: number): void {
  if (s.phase === 'ended') return;
  const atk = livingUnits(s, 'attacker').length;
  const def = livingUnits(s, 'defender').length;
  if (atk > 0 && def > 0) return;
  // Mutual annihilation leaves the hex with whoever already held it.
  const winner: BattleSide = def > 0 || atk === 0 ? 'defender' : 'attacker';
  finish(s, winner, 'wipe', now);
}

// ─────────────────────────────────────────────────────────────────────────────
// Write-back to the strategic layer
// ─────────────────────────────────────────────────────────────────────────────

/** Winner's surviving units keep their current HP (GDD §7.3). */
export function survivorsOf(s: BattleState, side: BattleSide): { sourceUnitId: UnitId; hp: number }[] {
  return livingUnits(s, side).map((u) => ({ sourceUnitId: u.sourceUnitId, hp: u.hp }));
}

/** Conceding halves every survivor's HP, rounded up, floor of 1. That is the entire cost. */
export function concedeSurvivors(
  s: BattleState,
  side: BattleSide,
): { sourceUnitId: UnitId; hp: number }[] {
  return livingUnits(s, side).map((u) => ({
    sourceUnitId: u.sourceUnitId,
    hp: Math.max(1, Math.ceil(u.hp / 2)),
  }));
}
