// ─────────────────────────────────────────────────────────────────────────────
// Local helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Standing recon flight per simulated commander. Deliberately far below
 * `DRONES.maxPerPlayer` — that cap is a rule about what is *legal*, not a
 * target, and thirty commanders each parking six motes makes the strategic map
 * unreadable.
 */
const BOT_DRONE_LIMIT = 1;

const isIdle = (army: Army): boolean => army.path.length === 0 && army.arrivesAt === undefined;

function reserveTotal(hex: Hex): number {
  let n = 0;
  for (const type of Object.keys(hex.reserves) as UnitType[]) n += hex.reserves[type] ?? 0;
  return n;
}

function armiesOf(state: GameState, playerId: PlayerId): Army[] {
  const out: Army[] = [];
  for (const army of Object.values(state.armies)) {
    if (army.ownerId === playerId && army.units.length > 0) out.push(army);
  }
  return out.sort((a, b) => (a.id < b.id ? -1 : 1));
}

function hexesOf(state: GameState, playerId: PlayerId): Hex[] {
  const out: Hex[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId === playerId && isHexOpen(state.world, hex.id)) out.push(hex);
  }
  return out.sort((a, b) => (a.id < b.id ? -1 : 1));
}

/** Nearest hex matching a predicate, measured from `from`, within `maxRange`. */
function nearestHex(
  state: GameState,
  from: HexId,
  maxRange: number,
  match: (hex: Hex) => boolean,
): Hex | undefined {
  let best: Hex | undefined;
  let bestD = Infinity;
  for (const hex of Object.values(state.world.hexes)) {
    if (!isHexOpen(state.world, hex.id)) continue;
    if (!match(hex)) continue;
    const d = hexDistanceId(from, hex.id);
    if (d > maxRange || d >= bestD) continue;
    bestD = d;
    best = hex;
  }
  return best;
}

/** Is this hex free for a bot to walk onto and hold without a fight? */
function isFreeGround(state: GameState, playerId: PlayerId, hex: Hex): boolean {
  if (!isHexOpen(state.world, hex.id)) return false;
  if (hex.ownerId && !areHostile(state, hex.ownerId, playerId)) return false;
  if (hex.ownerId) return false; // enemy ground is an assault, handled elsewhere
  if (hostileArmyOnHex(state, hex.id, playerId)) return false;
  if (hex.capture && hex.capture.playerId !== playerId) return false;
  return true;
}

/**
 * Raise a fresh column out of the reserves garrisoned on a hex.
 *
 * GAP FILLED HERE, DELIBERATELY: the pure layer can put units *into* a garrison
 * (`garrisonUnits`, production overflow) and pull them out into an army that
 * already exists (`withdrawUnits`), but it has no way to create the first army
 * on a hex. Without this, any commander whose last column is destroyed is
 * permanently frozen — reserves pile up on their hexes and can never be
 * mobilised again. That froze the entire simulated war after one day.
 *
 * Used by the bot director and by the mock backend's re-deployment path, so
 * the player and the AI both get the same rule.
 */
export function formColumn(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  name: string,
): Result<ArmyId> {
  const player = state.players[playerId];
  if (!player) return err('unknown commander');
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (!isHexOpen(state.world, hexId)) return err('sector is locked');
  if (hex.ownerId !== playerId) return err('you do not hold this hex');
  if (hostileArmyOnHex(state, hexId, playerId)) return err('a hostile column holds that ground');

  const types = (Object.keys(hex.reserves) as UnitType[]).filter(
    (t) => (hex.reserves[t] ?? 0) > 0 && UNITS[t].combat,
  );
  if (types.length === 0) return err('no reserves garrisoned here');

  // Heaviest chassis first — a mobilised column should be the best on hand.
  types.sort((a, b) => UNITS[b].cost.m + UNITS[b].cost.g - (UNITS[a].cost.m + UNITS[a].cost.g));

  const units: ArmyUnit[] = [];
  for (const type of types) {
    let have = hex.reserves[type] ?? 0;
    while (have > 0 && units.length < BATTLE.armyCap) {
      units.push({ id: uid('u'), type, hp: UNITS[type].hp });
      have--;
    }
    if (have > 0) hex.reserves[type] = have;
    else delete hex.reserves[type];
    if (units.length >= BATTLE.armyCap) break;
  }
  if (units.length === 0) return err('no combat units in reserve');

  const id = uid('army');
  state.armies[id] = {
    id,
    ownerId: playerId,
    guildId: player.guildId ?? playerId,
    name,
    hexId,
    units,
    path: [],
  };
  return ok(id);
}

function affordableUnitTypes(state: GameState, player: Player, hex: Hex): UnitType[] {
  const out: UnitType[] = [];
  for (const type of COMBAT_UNIT_TYPES) {
    const def = UNITS[type];
    if (GAS_GATED.includes(type) && player.gas < def.cost.g) continue;
    if (!canAfford(state, player.id, def.cost)) continue;
    if (!canProduce(state, player.id, hex.id, type, 1).ok) continue;
    out.push(type);
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Director
// ─────────────────────────────────────────────────────────────────────────────

interface Candidate {
  weight: number;
  run: () => boolean;
}

/**
 * Drives every simulated commander in the world. One instance lives inside the
 * mock backend and is ticked from the simulation loop.
 */
export class BotDirector {
  private readonly nextThink = new Map<PlayerId, number>();
  private readonly lastChat = new Map<PlayerId, number>();

  constructor(private readonly rng: Rng) {}

  /** Simulated milliseconds between re-evaluations for one commander. */
  private get intervalMs(): number {
    return Math.max(1000, SIM.botThinkMs * SIM.timeScale);
  }

  /** Forget a commander that no longer exists (guild disbanded, season reset). */
  forget(playerId: PlayerId): void {
    this.nextThink.delete(playerId);
    this.lastChat.delete(playerId);
  }

  /** Advance every bot whose think timer is due. */
  think(state: GameState, now: number): void {
    const jitter = Math.floor(this.intervalMs / 3);
    for (const player of Object.values(state.players)) {
      if (!player.bot || !player.deployed) continue;

      const due = this.nextThink.get(player.id);
      if (due === undefined) {
        // Stagger first activation so the whole world does not act in lockstep.
        this.nextThink.set(player.id, now + this.rng.int(0, this.intervalMs));
        continue;
      }
      if (now < due) continue;
      this.nextThink.set(player.id, now + this.intervalMs + this.rng.int(-jitter, jitter));

      if (!this.rng.chance(SIM.botActChance)) continue;
      this.takeAction(state, player, now);
    }
  }

  // ── action selection ──────────────────────────────────────────────────────

  private takeAction(state: GameState, player: Player, now: number): void {
    const candidates = this.candidatesFor(state, player, now);
    if (candidates.length === 0) return;

    // Weighted pick, with two fallbacks so a refused action does not waste the
    // whole tick (all of them re-validate through the pure layer anyway).
    for (let attempt = 0; attempt < 3 && candidates.length > 0; attempt++) {
      const total = candidates.reduce((sum, c) => sum + c.weight, 0);
      if (total <= 0) return;
      let roll = this.rng.next() * total;
      let index = 0;
      for (let i = 0; i < candidates.length; i++) {
        roll -= candidates[i].weight;
        if (roll <= 0) {
          index = i;
          break;
        }
        index = i;
      }
      const chosen = candidates.splice(index, 1)[0];
      if (chosen.run()) return;
    }
  }

  private candidatesFor(state: GameState, player: Player, now: number): Candidate[] {
    const out: Candidate[] = [];
    const armies = armiesOf(state, player.id);
    const idle = armies.filter(isIdle);
    const hexes = hexesOf(state, player.id);
    const guild = guildOf(state, player.id);

    // 0 ── mobilise. A commander with no column in the field does nothing else
    //      until they have one; garrisons exist to be turned back into armies.
    if (armies.length < 2 && hexes.length > 0) {
      out.push({
        weight: armies.length === 0 ? 40 : 4,
        run: () => this.mobilise(state, player, hexes),
      });
    }

    // 1 ── contest the gas fields. GDD §4: gas is the season, so this carries
    //      the heaviest weight and bots visibly converge on the vents.
    if (idle.length > 0) {
      out.push({
        weight: 6,
        run: () => this.pushToGas(state, player, idle),
      });
    }

    // 2 ── expand onto neutral ground.
    if (idle.length > 0) {
      out.push({ weight: 5, run: () => this.expand(state, player, idle) });
    }

    // 2b ── once the map is carved up, the only way to grow is off a rival.
    if (idle.length > 0) {
      out.push({ weight: 4, run: () => this.assault(state, player, idle) });
    }

    // 3 ── reinforce a threatened holding.
    if (idle.length > 0 && hexes.length > 0) {
      out.push({ weight: 4, run: () => this.reinforce(state, player, idle, hexes) });
    }

    // 4 ── raise or upgrade a fort.
    if (hexes.length > 0) {
      out.push({ weight: 3, run: () => this.fortify(state, player, hexes, now) });
    }

    // 5 ── queue production.
    if (hexes.length > 0) {
      out.push({ weight: 5, run: () => this.produce(state, player, hexes, now) });
    }

    // 6 ── load reserves into a co-located column.
    if (hexes.length > 0) {
      out.push({ weight: 3, run: () => this.consolidate(state, player, hexes) });
    }

    // 7 ── recon. Bots keep a small standing flight, not the hard cap: a world
    //      carrying six motes per commander is unreadable on the map.
    if (hexes.length > 0) {
      out.push({ weight: 2, run: () => this.scout(state, player, hexes, now) });
    }

    // 8 ── logistics inside the guild.
    if (guild && player.minerals > ECONOMY.capMinerals * 0.4) {
      out.push({ weight: 2, run: () => this.supply(state, player, now) });
    }

    // 9 ── talk.
    if (guild) {
      const last = this.lastChat.get(player.id) ?? 0;
      if (now - last > this.intervalMs * 6) {
        out.push({ weight: 2, run: () => this.talk(state, player, now) });
      }
      out.push({ weight: 1, run: () => this.signal(state, player, now) });
    }

    return out;
  }

  // ── individual behaviours ─────────────────────────────────────────────────

  /** Turn a garrison back into a column. The lifeline for a wiped commander. */
  private mobilise(state: GameState, player: Player, hexes: Hex[]): boolean {
    const ranked = [...hexes].sort((a, b) => reserveTotal(b) - reserveTotal(a));
    for (const hex of ranked) {
      if (reserveTotal(hex) < 2) break;
      if (armiesOnHex(state, hex.id).some((a) => a.ownerId === player.id)) continue;
      const name = `${this.rng.pick(ARMY_DESIGNATIONS)} DET`;
      if (formColumn(state, player.id, hex.id, name).ok) return true;
    }
    return false;
  }

  /** March the nearest idle column at the closest gas field we do not hold. */
  private pushToGas(state: GameState, player: Player, idle: Army[]): boolean {
    let bestArmy: Army | undefined;
    let bestTarget: Hex | undefined;
    let bestD = Infinity;

    for (const army of idle) {
      const target = nearestHex(state, army.hexId, 14, (hex) => {
        if (!hex.gas) return false;
        if (hex.ownerId === player.id) return false;
        if (hex.ownerId && !areHostile(state, hex.ownerId, player.id)) return false;
        return true;
      });
      if (!target) continue;
      const d = hexDistanceId(army.hexId, target.id);
      if (d >= bestD) continue;
      bestD = d;
      bestArmy = army;
      bestTarget = target;
    }
    if (!bestArmy || !bestTarget) return false;
    if (bestArmy.hexId === bestTarget.id) return false;
    return beginMove(state, bestArmy.id, bestTarget.id, state.now).ok;
  }

  /** Take unclaimed ground next door — the bread and butter of map growth. */
  private expand(state: GameState, player: Player, idle: Army[]): boolean {
    const army = this.rng.pick(idle);

    const adjacent: Hex[] = [];
    for (const id of neighborIds(army.hexId)) {
      const hex = state.world.hexes[id];
      if (hex && isFreeGround(state, player.id, hex)) adjacent.push(hex);
    }
    if (adjacent.length > 0) {
      const target = this.rng.pick(adjacent);
      return beginMove(state, army.id, target.id, state.now).ok;
    }

    const far = nearestHex(state, army.hexId, 6, (hex) => isFreeGround(state, player.id, hex));
    if (!far) return false;
    return beginMove(state, army.id, far.id, state.now).ok;
  }

  /**
   * Take ground off a rival. Only a column with real weight behind it goes in,
   * and it picks the softest reachable target — bots probe, they do not throw
   * two Exos at a Citadel.
   */
  private assault(state: GameState, player: Player, idle: Army[]): boolean {
    const capable = idle.filter((a) => a.units.length >= 3);
    if (capable.length === 0) return false;
    const army = this.rng.pick(capable);

    let best: Hex | undefined;
    let bestScore = -Infinity;
    for (const hex of Object.values(state.world.hexes)) {
      if (!isHexOpen(state.world, hex.id)) continue;
      if (!hex.ownerId || !areHostile(state, hex.ownerId, player.id)) continue;
      const d = hexDistanceId(army.hexId, hex.id);
      if (d === 0 || d > 5) continue;

      let defenders = 0;
      for (const other of armiesOnHex(state, hex.id)) {
        if (areHostile(state, other.ownerId, player.id)) defenders += other.units.length;
      }
      if (defenders > army.units.length + 1) continue;

      const score = (hex.gas ? 14 : 0) - hex.fortLevel * 5 - d * 2 - defenders * 3;
      if (score > bestScore) {
        bestScore = score;
        best = hex;
      }
    }
    if (!best) return false;
    return beginMove(state, army.id, best.id, state.now).ok;
  }

  /** Something hostile is close to ground we hold. Send the nearest column. */
  private reinforce(state: GameState, player: Player, idle: Army[], hexes: Hex[]): boolean {
    let threatened: Hex | undefined;
    let bestScore = -1;

    for (const hex of hexes) {
      let threat = 0;
      for (const id of [hex.id, ...neighborIds(hex.id)]) {
        for (const army of armiesOnHex(state, id)) {
          if (army.units.length === 0) continue;
          if (areHostile(state, army.ownerId, player.id)) threat += army.units.length;
        }
      }
      if (threat === 0) continue;
      const score = threat * 10 + hex.fortLevel * 4 + (hex.gas ? 8 : 0);
      if (score > bestScore) {
        bestScore = score;
        threatened = hex;
      }
    }
    if (!threatened) return false;

    let closest: Army | undefined;
    let bestD = Infinity;
    for (const army of idle) {
      if (army.hexId === threatened.id) return false; // already garrisoned
      const d = hexDistanceId(army.hexId, threatened.id);
      if (d < bestD) {
        bestD = d;
        closest = army;
      }
    }
    if (!closest || bestD > 8) return false;
    return beginMove(state, closest.id, threatened.id, state.now).ok;
  }

  /**
   * Dig in — but only where digging in means something. Concrete goes onto gas
   * fields and the border; a bot that fortifies every interior rock spends its
   * whole economy on walls nobody will ever walk into.
   */
  private fortify(state: GameState, player: Player, hexes: Hex[], now: number): boolean {
    const fortified = hexes.filter((h) => h.fortLevel > 0 || h.fortBuild).length;
    if (fortified > Math.ceil(hexes.length * 0.6)) return false;

    const worth = hexes.filter((h) => h.gas || this.isBorder(state, player, h));
    const ranked = worth.sort((a, b) => {
      const ga = (a.gas ? 2 : 0) - a.fortLevel;
      const gb = (b.gas ? 2 : 0) - b.fortLevel;
      if (ga !== gb) return gb - ga;
      return a.id < b.id ? -1 : 1;
    });
    for (const hex of ranked) {
      if (!canBuildFort(state, player.id, hex.id).ok) continue;
      if (startFort(state, player.id, hex.id, now).ok) return true;
    }
    return false;
  }

  /** Adjacent to unclaimed ground or to a rival — i.e. worth defending. */
  private isBorder(state: GameState, player: Player, hex: Hex): boolean {
    for (const id of neighborIds(hex.id)) {
      const other = state.world.hexes[id];
      if (!other) continue;
      if (!other.ownerId) return true;
      if (areHostile(state, other.ownerId, player.id)) return true;
    }
    return false;
  }

  /** Keep the production lines warm at every Outpost we own. */
  private produce(state: GameState, player: Player, hexes: Hex[], now: number): boolean {
    const lines = hexes.filter((h) => h.fortLevel >= 1 && h.production.length < 3);
    if (lines.length === 0) return false;
    const hex = this.rng.pick(lines);

    const options = affordableUnitTypes(state, player, hex);
    if (options.length === 0) return false;

    // Prefer the most expensive chassis this commander can currently field, but
    // keep a taste for cheap infantry so the swarm units still appear.
    options.sort((a, b) => UNITS[b].cost.m + UNITS[b].cost.g - (UNITS[a].cost.m + UNITS[a].cost.g));
    const type = this.rng.chance(0.65) ? options[0] : this.rng.pick(options);
    const count = this.rng.chance(0.3) ? 2 : 1;

    if (startProduction(state, player.id, hex.id, type, count, now).ok) return true;
    return startProduction(state, player.id, hex.id, type, 1, now).ok;
  }

  /** Move garrisoned reserves into a column that has room for them. */
  private consolidate(state: GameState, player: Player, hexes: Hex[]): boolean {
    for (const hex of hexes) {
      const reserveTypes = (Object.keys(hex.reserves) as UnitType[]).filter(
        (t) => (hex.reserves[t] ?? 0) > 0,
      );
      if (reserveTypes.length === 0) continue;

      const army = armiesOnHex(state, hex.id).find(
        (a) => a.ownerId === player.id && isIdle(a) && a.units.length > 0,
      );
      if (!army) continue;

      const take: Partial<Record<UnitType, number>> = {};
      let budget = Math.max(0, 8 - army.units.length);
      for (const type of reserveTypes) {
        if (budget <= 0) break;
        const want = Math.min(budget, hex.reserves[type] ?? 0);
        if (want <= 0) continue;
        take[type] = want;
        budget -= want;
      }
      if (budget === 8) continue;
      if (withdrawUnits(state, army.id, hex.id, take).ok) return true;
    }
    return false;
  }

  /**
   * Fly a mote at whatever the enemy is hiding, and pull the last one home.
   * Motes are expendable, but leaving every one of them parked on station
   * forever would bury the map under `DRONES.maxPerPlayer × commanders` tokens.
   */
  private scout(state: GameState, player: Player, hexes: Hex[], now: number): boolean {
    const alive = aliveDronesOf(state, player.id);
    const standing = alive.filter((d) => d.path.length === 0 && d.arrivesAt === undefined);
    if (standing.length > 0 && (alive.length >= BOT_DRONE_LIMIT || this.rng.chance(0.5))) {
      recallDrone(state, standing[0].id);
      if (alive.length >= BOT_DRONE_LIMIT) return true;
    }
    if (alive.length >= Math.min(BOT_DRONE_LIMIT, DRONES.maxPerPlayer)) return false;

    const from = this.rng.pick(hexes);
    const target = nearestHex(state, from.id, 10, (hex) => {
      if (!hex.ownerId) return false;
      return areHostile(state, hex.ownerId, player.id);
    });
    if (!target) return false;
    return launchDrone(state, player.id, from.id, target.id, now).ok;
  }

  /** Ship minerals to the poorest commander in the guild. */
  private supply(state: GameState, player: Player, now: number): boolean {
    const guild = guildOf(state, player.id);
    if (!guild) return false;

    let poorest: Player | undefined;
    for (const id of guild.memberIds) {
      if (id === player.id) continue;
      const mate = state.players[id];
      if (!mate) continue;
      if (!poorest || mate.minerals < poorest.minerals) poorest = mate;
    }
    if (!poorest) return false;
    if (poorest.minerals > player.minerals * 0.5) return false;

    const amount = Math.floor(player.minerals * 0.25);
    if (amount < 50) return false;

    const gas = player.gas > ECONOMY.capGas * 0.5 ? Math.floor(player.gas * 0.2) : 0;
    return createTransfer(
      state,
      player.id,
      poorest.id,
      { minerals: amount, gas, units: {} },
      now,
    ).ok;
  }

  /** Say something on the guild net. */
  private talk(state: GameState, player: Player, now: number): boolean {
    const guild = guildOf(state, player.id);
    if (!guild) return false;

    const channel = guildChannel(guild.id);
    const topic = this.pickTopic(state, player);
    const log = state.chat[channel] ?? [];
    const previous = log.length > 0 ? log[log.length - 1].text : '';

    let line = chatterLine(this.rng, topic);
    for (let attempt = 0; attempt < 3 && line === previous; attempt++) {
      line = chatterLine(this.rng);
    }
    if (line === previous) return false;

    const sent = sendChat(state, channel, player.id, line);
    if (!sent.ok) return false;
    this.lastChat.set(player.id, now);
    return true;
  }

  private pickTopic(state: GameState, player: Player): ChatterTopic {
    const holdsGas = hexesOf(state, player.id).some((h) => h.gas);
    if (!holdsGas && this.rng.chance(0.4)) return 'gas';
    const armies = armiesOf(state, player.id);
    if (armies.some((a) => !isIdle(a)) && this.rng.chance(0.4)) return 'attack';
    for (const hex of hexesOf(state, player.id)) {
      if (hostileArmyOnHex(state, hex.id, player.id)) return 'defense';
      for (const id of neighborIds(hex.id)) {
        if (hostileArmyOnHex(state, id, player.id)) return 'defense';
      }
    }
    return this.rng.pick(CHATTER_TOPICS);
  }

  /** Drop a ping, a mark, or (officers only) a short objective. */
  private signal(state: GameState, player: Player, now: number): boolean {
    const guild = guildOf(state, player.id);
    if (!guild) return false;

    const hexes = hexesOf(state, player.id);
    const anchor = hexes.length > 0 ? this.rng.pick(hexes) : undefined;
    if (!anchor) return false;

    const contested = nearestHex(state, anchor.id, 6, (hex) => {
      if (hex.gas && hex.ownerId !== player.id) return true;
      if (hex.ownerId && areHostile(state, hex.ownerId, player.id)) return true;
      return false;
    });
    if (!contested) return false;

    const roll = this.rng.next();
    if (roll < 0.6) {
      const kind: PingKind = contested.gas
        ? 'rally'
        : contested.fortLevel >= 2
          ? 'danger'
          : 'attack';
      return placePing(state, player.id, contested.id, kind, now).ok;
    }
    if (roll < 0.85) {
      const label = contested.gas ? 'VENT FIELD' : `${contested.terrain.toUpperCase()} HOLD`;
      const marked = state.marks.filter((m) => m.guildId === guild.id).length;
      if (marked >= GUILD.maxMarks) return false;
      return placeMark(state, player.id, contested.id, label, now).ok;
    }
    if (!isOfficerOrAbove(state, player.id)) return false;
    return createObjective(
      state,
      player.id,
      {
        title: contested.gas ? 'SEIZE THE VENT FIELD' : 'REDUCE THE BORDER HOLD',
        detail: chatterLine(this.rng, contested.gas ? 'gas' : 'attack'),
        hexIds: [contested.id],
        grand: false,
      },
      now,
    ).ok;
  }
}
