// ─────────────────────────────────────────────────────────────────────────────
// Primitives
// ─────────────────────────────────────────────────────────────────────────────

export type DocData = Record<string, unknown>;

export interface DocConverter<T> {
  toFirestore(value: T): DocData;
  /** Returns undefined when the payload is unusable rather than throwing. */
  fromFirestore(id: string, data: DocData): T | undefined;
}

const TERRAINS: readonly Terrain[] = ['plains', 'ridge', 'crater', 'ruins', 'gasfield'];
const SECTOR_STATES: readonly SectorState[] = ['active', 'locked', 'closing', 'unlocking'];
const UNIT_TYPES: readonly UnitType[] = [
  'exo',
  'walker',
  'pallet',
  'flyer',
  'heavy_pallet',
  'elite_flyer',
  'drone',
];
const TILE_KINDS: readonly TileKind[] = [
  'floor',
  'obstacle',
  'rough',
  'cover',
  'hazard',
  'teleport',
  'destructible',
  'elevation',
  'unstable',
];
const CHAT_KINDS: readonly ChatKind[] = [
  'text',
  'system',
  'triple_zero',
  'alert',
  'ping',
  'trade',
  'treaty',
];
const PING_KINDS: readonly PingKind[] = ['attack', 'defend', 'scout', 'rally', 'danger'];
const GUILD_ROLES: readonly GuildRole[] = ['leader', 'officer', 'member'];
const TRANSFER_STATUSES: readonly TransferStatus[] = ['in_transit', 'delivered', 'cancelled'];
const TRADE_STATUSES: readonly TradeStatus[] = ['open', 'accepted', 'declined', 'cancelled'];
const BATTLE_PHASES: readonly BattlePhase[] = [
  'intro',
  'side_pick',
  'obstacle_place',
  'deploy',
  'rolling',
  'assign',
  'acting',
  'ended',
];

const str = (v: unknown, fallback = ''): string => (typeof v === 'string' ? v : fallback);
const num = (v: unknown, fallback = 0): number =>
  typeof v === 'number' && Number.isFinite(v) ? v : fallback;
const bool = (v: unknown, fallback = false): boolean => (typeof v === 'boolean' ? v : fallback);
const list = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const obj = (v: unknown): DocData =>
  v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as DocData) : {};
const strList = (v: unknown): string[] => list(v).filter((x): x is string => typeof x === 'string');

function oneOf<T extends string>(v: unknown, allowed: readonly T[], fallback: T): T {
  return typeof v === 'string' && (allowed as readonly string[]).includes(v) ? (v as T) : fallback;
}

const optStr = (v: unknown): string | undefined => (typeof v === 'string' && v ? v : undefined);
const optNum = (v: unknown): number | undefined =>
  typeof v === 'number' && Number.isFinite(v) ? v : undefined;

/** Recursively drop `undefined` — Firestore rejects the value outright. */
export function stripUndefined<T>(value: T): T {
  if (Array.isArray(value)) {
    return value.map((v) => stripUndefined(v)) as unknown as T;
  }
  if (value !== null && typeof value === 'object') {
    const out: DocData = {};
    for (const [key, v] of Object.entries(value as DocData)) {
      if (v === undefined) continue;
      out[key] = stripUndefined(v);
    }
    return out as unknown as T;
  }
  return value;
}

/** Replace every `undefined` with `null` — RTDB deletes undefined keys. */
export function nullifyUndefined<T>(value: T): T {
  if (Array.isArray(value)) return value.map((v) => nullifyUndefined(v)) as unknown as T;
  if (value !== null && typeof value === 'object') {
    const out: DocData = {};
    for (const [key, v] of Object.entries(value as DocData)) {
      out[key] = v === undefined ? null : nullifyUndefined(v);
    }
    return out as unknown as T;
  }
  return value === undefined ? (null as unknown as T) : value;
}

const cost = (v: unknown): Cost => {
  const o = obj(v);
  return { m: num(o.m), g: num(o.g) };
};

/** Flatten a `Partial<Record<UnitType, number>>` into a dense plain record. */
function unitCounts(v: unknown): Partial<Record<UnitType, number>> {
  const src = obj(v);
  const out: Partial<Record<UnitType, number>> = {};
  for (const type of UNIT_TYPES) {
    const n = num(src[type], 0);
    if (n > 0) out[type] = n;
  }
  return out;
}

