// World & sectors
// ─────────────────────────────────────────────────────────────────────────────

export interface SectorDoc {
  id: string;
  name: string;
  designation: string;
  centerQ: number;
  centerR: number;
  hexIds: string[];
  state: SectorState;
  opensAt?: number;
  closesAt?: number;
  rotationIndex: number;
}

export interface WorldDoc {
  id: string;
  radius: number;
  seed: number;
  createdAt: number;
  sectors: SectorDoc[];
}

export const sectorConverter: DocConverter<Sector> = {
  toFirestore(sector) {
    return stripUndefined<DocData>({
      id: sector.id,
      name: sector.name,
      designation: sector.designation,
      centerQ: sector.center.q,
      centerR: sector.center.r,
      hexIds: sector.hexIds,
      state: sector.state,
      opensAt: sector.opensAt,
      closesAt: sector.closesAt,
      rotationIndex: sector.rotationIndex,
    });
  },
  fromFirestore(id, data) {
    return {
      id: str(data.id, id),
      name: str(data.name, 'UNNAMED'),
      designation: str(data.designation, str(data.name, 'SECTOR')),
      center: { q: num(data.centerQ), r: num(data.centerR) },
      hexIds: strList(data.hexIds),
      state: oneOf(data.state, SECTOR_STATES, 'locked'),
      opensAt: optNum(data.opensAt),
      closesAt: optNum(data.closesAt),
      rotationIndex: num(data.rotationIndex, -1),
    };
  },
};

export interface WorldPayload {
  world: WorldState;
  seed: number;
  createdAt: number;
}

export const worldConverter: DocConverter<WorldPayload> = {
  toFirestore(payload) {
    const doc: WorldDoc = {
      id: WORLD_ID,
      radius: payload.world.radius,
      seed: payload.seed,
      createdAt: payload.createdAt,
      sectors: Object.values(payload.world.sectors).map(
        (s) => sectorConverter.toFirestore(s) as unknown as SectorDoc,
      ),
    };
    return stripUndefined<DocData>(doc as unknown as DocData);
  },
  fromFirestore(id, data) {
    const sectors: Record<string, Sector> = {};
    for (const raw of list(data.sectors)) {
      const parsed = sectorConverter.fromFirestore('', obj(raw));
      if (parsed && parsed.id) sectors[parsed.id] = parsed;
    }
    return {
      world: { hexes: {}, sectors, radius: num(data.radius, 0) },
      seed: num(data.seed),
      createdAt: num(data.createdAt),
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// Hexes
// ─────────────────────────────────────────────────────────────────────────────

export interface HexDoc {
  id: string;
  q: number;
  r: number;
  sectorId: string;
  terrain: Terrain;
  gas: boolean;
  ownerId?: string;
  fortLevel: number;
  fortBuild?: FortBuild;
  production: ProductionOrder[];
  capture?: CaptureState;
  reserves: Record<string, number>;
}

export const hexConverter: DocConverter<Hex> = {
  toFirestore(hex) {
    return stripUndefined<DocData>({
      id: hex.id,
      q: hex.q,
      r: hex.r,
      sectorId: hex.sectorId,
      terrain: hex.terrain,
      gas: hex.gas,
      ownerId: hex.ownerId,
      fortLevel: hex.fortLevel,
      fortBuild: hex.fortBuild,
      production: hex.production,
      capture: hex.capture,
      reserves: { ...hex.reserves },
    });
  },
  fromFirestore(id, data) {
    const production: ProductionOrder[] = list(data.production).map((raw) => {
      const o = obj(raw);
      return {
        id: str(o.id),
        unitType: oneOf(o.unitType, UNIT_TYPES, 'exo'),
        remaining: num(o.remaining),
        startedAt: num(o.startedAt),
        completesAt: num(o.completesAt),
      };
    });

    let fortBuild: FortBuild | undefined;
    if (data.fortBuild) {
      const o = obj(data.fortBuild);
      const target = num(o.targetLevel, 1);
      fortBuild = {
        targetLevel: (target === 2 ? 2 : target === 3 ? 3 : 1) as 1 | 2 | 3,
        startedAt: num(o.startedAt),
        completesAt: num(o.completesAt),
      };
    }

    let capture: CaptureState | undefined;
    if (data.capture) {
      const o = obj(data.capture);
      capture = {
        playerId: str(o.playerId),
        guildId: str(o.guildId),
        armyId: str(o.armyId),
        startedAt: num(o.startedAt),
        completesAt: num(o.completesAt),
      };
    }

    const level = num(data.fortLevel);
    return {
      id: str(data.id, id),
      q: num(data.q),
      r: num(data.r),
      sectorId: str(data.sectorId),
      terrain: oneOf(data.terrain, TERRAINS, 'plains'),
      gas: bool(data.gas),
      ownerId: optStr(data.ownerId),
      fortLevel: (level >= 0 && level <= 3 ? level : 0) as FortLevel,
      fortBuild,
      production,
      capture,
      reserves: unitCounts(data.reserves),
    };
  },
};

