export interface GuildDoc {
  id: string;
  name: string;
  tag: string;
  motto: string;
  color: number;
  leaderId: string;
  memberIds: string[];
  /** `roles` is a domain Record keyed by player id — already a plain object. */
  roles: Record<string, GuildRole>;
  diplomats: string[];
  createdAt: number;
  emblem: number;
}

export const guildConverter: DocConverter<Guild> = {
  toFirestore(guild) {
    const roles: Record<string, GuildRole> = {};
    for (const [playerId, role] of Object.entries(guild.roles)) roles[playerId] = role;
    return stripUndefined<DocData>({
      id: guild.id,
      name: guild.name,
      tag: guild.tag,
      motto: guild.motto,
      color: guild.color,
      leaderId: guild.leaderId,
      memberIds: guild.memberIds,
      roles,
      diplomats: guild.diplomats,
      createdAt: guild.createdAt,
      emblem: guild.emblem,
    });
  },
  fromFirestore(id, data) {
    const roles: Record<PlayerId, GuildRole> = {};
    for (const [playerId, role] of Object.entries(obj(data.roles))) {
      roles[playerId] = oneOf(role, GUILD_ROLES, 'member');
    }
    return {
      id: str(data.id, id),
      name: str(data.name, 'UNCHARTERED'),
      tag: str(data.tag, '???'),
      motto: str(data.motto),
      color: num(data.color, 0x4de3ff),
      leaderId: str(data.leaderId),
      memberIds: strList(data.memberIds),
      roles,
      diplomats: strList(data.diplomats),
      createdAt: num(data.createdAt),
      emblem: num(data.emblem),
    };
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// Armies & drones
// ─────────────────────────────────────────────────────────────────────────────

const moveSteps = (v: unknown): MoveStep[] =>
  list(v).map((raw) => {
    const o = obj(raw);
    return { hexId: str(o.hexId), arrivesAt: num(o.arrivesAt) };
  });

export interface ArmyDoc {
  id: string;
  ownerId: string;
  guildId: string;
  name: string;
  hexId: string;
  units: ArmyUnit[];
  path: MoveStep[];
  movingFrom?: string;
  departedAt?: number;
  arrivesAt?: number;
  siege?: { hexId: string; startedAt: number; readyAt: number };
}

export const armyConverter: DocConverter<Army> = {
  toFirestore(army) {
    return stripUndefined<DocData>({
      id: army.id,
      ownerId: army.ownerId,
      guildId: army.guildId,
      name: army.name,
      hexId: army.hexId,
      units: army.units.map((u) => ({ id: u.id, type: u.type, hp: u.hp })),
      path: army.path,
      movingFrom: army.movingFrom,
      departedAt: army.departedAt,
      arrivesAt: army.arrivesAt,
      siege: army.siege,
    });
  },
  fromFirestore(id, data) {
    const units: ArmyUnit[] = list(data.units).map((raw) => {
      const o = obj(raw);
      return { id: str(o.id), type: oneOf(o.type, UNIT_TYPES, 'exo'), hp: num(o.hp, 1) };
    });

    let siege: Army['siege'];
    if (data.siege) {
      const o = obj(data.siege);
      siege = { hexId: str(o.hexId), startedAt: num(o.startedAt), readyAt: num(o.readyAt) };
    }

    return {
      id: str(data.id, id),
      ownerId: str(data.ownerId),
      guildId: str(data.guildId),
      name: str(data.name, 'COLUMN'),
      hexId: str(data.hexId),
      units,
      path: moveSteps(data.path),
      movingFrom: optStr(data.movingFrom),
      departedAt: optNum(data.departedAt),
      arrivesAt: optNum(data.arrivesAt),
      siege,
    };
  },
};

