export interface TransferDoc {
  id: string;
  guildId: string;
  fromId: string;
  toId: string;
  minerals: number;
  gas: number;
  units: Record<string, number>;
  sentAt: number;
  arrivesAt: number;
  distance: number;
  status: TransferStatus;
}

export const transferConverter: DocConverter<Transfer> = {
  toFirestore(transfer) {
    return stripUndefined<DocData>({
      id: transfer.id,
      guildId: transfer.guildId,
      fromId: transfer.fromId,
      toId: transfer.toId,
      minerals: transfer.payload.minerals,
      gas: transfer.payload.gas,
      units: { ...transfer.payload.units },
      sentAt: transfer.sentAt,
      arrivesAt: transfer.arrivesAt,
      distance: transfer.distance,
      status: transfer.status,
    });
  },
  fromFirestore(id, data) {
    const payload: TransferPayload = {
      minerals: num(data.minerals),
      gas: num(data.gas),
      units: unitCounts(data.units),
    };
    return {
      id: str(data.id, id),
      guildId: str(data.guildId),
      fromId: str(data.fromId),
      toId: str(data.toId),
      payload,
      sentAt: num(data.sentAt),
      arrivesAt: num(data.arrivesAt),
      distance: num(data.distance),
      status: oneOf(data.status, TRANSFER_STATUSES, 'in_transit'),
    };
  },
};

