export const treatyConverter: DocConverter<Treaty> = {
  toFirestore(treaty) {
    return stripUndefined<DocData>({
      id: treaty.id,
      parleyId: treaty.parleyId,
      guildA: treaty.guilds[0],
      guildB: treaty.guilds[1],
      title: treaty.title,
      text: treaty.text,
      status: treaty.status,
      editingGuild: treaty.editingGuild,
      signatures: treaty.signatures,
      createdAt: treaty.createdAt,
      signedAt: treaty.signedAt,
      revisions: treaty.revisions,
    });
  },
  fromFirestore(id, data) {
    const signatures: Signature[] = list(data.signatures).map((raw) => {
      const o = obj(raw);
      return {
        guildId: str(o.guildId),
        playerId: str(o.playerId),
        playerName: str(o.playerName, 'UNKNOWN'),
        at: num(o.at),
      };
    });
    const revisions: TreatyRevision[] = list(data.revisions).map((raw) => {
      const o = obj(raw);
      return {
        at: num(o.at),
        byGuild: str(o.byGuild),
        byName: str(o.byName, 'UNKNOWN'),
        text: str(o.text),
      };
    });
    return {
      id: str(data.id, id),
      parleyId: str(data.parleyId),
      guilds: [str(data.guildA), str(data.guildB)],
      title: str(data.title, 'UNTITLED'),
      text: str(data.text),
      status: data.status === 'signed' ? 'signed' : 'drafting',
      editingGuild: str(data.editingGuild),
      signatures,
      createdAt: num(data.createdAt),
      signedAt: optNum(data.signedAt),
      revisions,
    };
  },
};

