/**
 * Buttons: standard variants, icon buttons, and a press-and-hold confirm ring
 * for irreversible actions (concede, disband, kick, leave guild…).
 */
import { el, svg as svgEl, haptic } from '../dom';

export type ButtonVariant = 'primary' | 'ghost' | 'danger' | 'quiet';

export interface ButtonOpts {
  variant?: ButtonVariant;
  /** Raw inline `<svg>` markup rendered before the label. */
  icon?: string;
  onClick?: () => void;
  disabled?: boolean;
  wide?: boolean;
  /** Small secondary line under the label (cost, timing, hint). */
  sub?: string;
  /** Compact 34px height. */
  small?: boolean;
  class?: string;
  /** Accessible label when the visual label is a glyph. */
  aria?: string;
}

function attachSweep(node: HTMLElement): void {
  const sweep = el('span', { class: 'btn__sweep', aria: { hidden: 'true' } });
  node.appendChild(sweep);
  const on = (): void => {
    node.classList.remove('is-press');
    // force reflow so the sweep animation restarts on every press
    void node.offsetWidth;
    node.classList.add('is-press');
  };
  const off = (): void => {
    window.setTimeout(() => node.classList.remove('is-press'), 520);
  };
  node.addEventListener('pointerdown', on);
  node.addEventListener('pointerup', off);
  node.addEventListener('pointercancel', off);
  node.addEventListener('pointerleave', off);
}

/** Primary action button. Minimum 44px touch target by construction. */
export function button(label: string, opts: ButtonOpts = {}): HTMLButtonElement {
  const variant = opts.variant ?? 'ghost';
  const classes = ['btn', `btn--${variant}`];
  if (opts.wide) classes.push('btn--wide');
  if (opts.small) classes.push('btn--sm');
  if (opts.class) classes.push(opts.class);

  const node = el('button', {
    class: classes.join(' '),
    attrs: { type: 'button', disabled: opts.disabled === true },
    aria: { label: opts.aria },
  });

  if (opts.icon) {
    node.appendChild(el('span', { class: 'btn__icon', html: opts.icon, aria: { hidden: 'true' } }));
  }

  const text = el('span', { class: 'btn__text' }, el('span', { class: 'btn__label', text: label }));
  if (opts.sub) text.appendChild(el('span', { class: 'btn__sub', text: opts.sub }));
  node.appendChild(text);

  attachSweep(node);

  if (opts.onClick) {
    const handler = opts.onClick;
    node.addEventListener('click', () => {
      if (node.disabled) return;
      haptic(10);
      handler();
    });
  }
  return node;
}

export interface IconButtonOpts {
  onClick?: () => void;
  disabled?: boolean;
  /** Accessible name — always supply one; the button has no visible text. */
  label?: string;
  /** Visual treatment. */
  variant?: 'default' | 'bare' | 'danger';
  /** Persistent "on" state for toggles. */
  active?: boolean;
  small?: boolean;
  /** Numeric badge in the top-right corner (0 hides it). */
  badge?: number;
  class?: string;
}

/** Square 44px icon-only control. `svgMarkup` is raw inline `<svg>` source. */
export function iconButton(svgMarkup: string, opts: IconButtonOpts = {}): HTMLButtonElement {
  const classes = ['icon-btn'];
  if (opts.variant === 'bare') classes.push('icon-btn--bare');
  if (opts.variant === 'danger') classes.push('icon-btn--danger');
  if (opts.active) classes.push('icon-btn--on');
  if (opts.small) classes.push('icon-btn--sm');
  if (opts.class) classes.push(opts.class);

  const node = el('button', {
    class: classes.join(' '),
    attrs: { type: 'button', disabled: opts.disabled === true },
    aria: { label: opts.label ?? 'action' },
  });
  node.appendChild(svgEl(svgMarkup));

  if (opts.badge !== undefined && opts.badge > 0) {
    node.appendChild(
      el('span', { class: 'icon-btn__badge', text: opts.badge > 99 ? '99+' : String(opts.badge) }),
    );
  }

  if (opts.onClick) {
    const handler = opts.onClick;
    node.addEventListener('click', () => {
      if (node.disabled) return;
      haptic(8);
      handler();
    });
  }
  return node;
}

export interface HoldButtonOpts {
  variant?: 'primary' | 'danger';
  /** Hold duration in ms. Defaults to 900. */
  holdMs?: number;
  onComplete: () => void;
  disabled?: boolean;
  /** Replaces the default "HOLD TO CONFIRM" hint line. */
  hint?: string;
  icon?: string;
  class?: string;
}

const RING_R = 10;
const RING_C = 2 * Math.PI * RING_R;

/**
 * Press-and-hold confirmation. The ring fills over `holdMs`; releasing early
 * aborts and snaps back. Used for anything that cannot be undone.
 */
export function holdButton(label: string, opts: HoldButtonOpts): HTMLElement {
  const holdMs = Math.max(200, opts.holdMs ?? 900);
  const danger = opts.variant !== 'primary';
  const classes = ['hold-btn'];
  if (danger) classes.push('hold-btn--danger');
  if (opts.disabled) classes.push('is-disabled');
  if (opts.class) classes.push(opts.class);

  const root = el('div', {
    class: classes.join(' '),
    attrs: { role: 'button', tabindex: opts.disabled ? -1 : 0 },
    aria: { label },
  });

  const fill = el('span', { class: 'hold-btn__fill', aria: { hidden: 'true' } });
  root.appendChild(fill);

  const ring = svgEl(
    `<svg class="hold-btn__ring" viewBox="0 0 26 26" aria-hidden="true">
       <circle class="trk" cx="13" cy="13" r="${RING_R}"></circle>
       <circle class="val" cx="13" cy="13" r="${RING_R}"
               stroke-dasharray="${RING_C.toFixed(2)}" stroke-dashoffset="${RING_C.toFixed(2)}"></circle>
     </svg>`,
  );
  root.appendChild(ring);
  const valCircle = ring.querySelector('.val') as SVGCircleElement;

  const textWrap = el(
    'div',
    {},
    el('span', { class: 'hold-btn__label', text: label }),
    el('span', { class: 'hold-btn__hint', text: opts.hint ?? 'hold to confirm' }),
  );
  root.appendChild(textWrap);

  let raf = 0;
  let start = 0;
  let done = false;

  const render = (p: number): void => {
    fill.style.transform = `scaleX(${p})`;
    valCircle.style.strokeDashoffset = String(RING_C * (1 - p));
  };

  const reset = (): void => {
    if (raf) cancelAnimationFrame(raf);
    raf = 0;
    start = 0;
    root.classList.remove('is-holding');
    render(0);
  };

  const tick = (t: number): void => {
    if (!start) start = t;
    const p = Math.min(1, (t - start) / holdMs);
    render(p);
    if (p >= 1) {
      raf = 0;
      done = true;
      root.classList.remove('is-holding');
      root.classList.add('is-done');
      haptic([18, 40, 26]);
      window.setTimeout(() => root.classList.remove('is-done'), 420);
      opts.onComplete();
      window.setTimeout(reset, 260);
      return;
    }
    raf = requestAnimationFrame(tick);
  };

  const begin = (ev: Event): void => {
    if (root.classList.contains('is-disabled') || raf) return;
    ev.preventDefault();
    done = false;
    root.classList.add('is-holding');
    haptic(6);
    raf = requestAnimationFrame(tick);
  };

  const end = (): void => {
    if (done) return;
    reset();
  };

  root.addEventListener('pointerdown', begin);
  root.addEventListener('pointerup', end);
  root.addEventListener('pointercancel', end);
  root.addEventListener('pointerleave', end);
  root.addEventListener('keydown', (ev: KeyboardEvent) => {
    if (ev.key === ' ' || ev.key === 'Enter') begin(ev);
  });
  root.addEventListener('keyup', end);

  render(0);
  return root;
}

