  // ── battle (GDD §7) ───────────────────────────────────────────────────────

  async acceptBattle(battleId: string): Promise<Result<void>> {
    return this.run((s, meId) => {
      const pending = s.pendingBattles.find((p) => p.id === battleId);
      if (!pending) return err('that engagement is no longer pending');
      if (pending.defenderId !== meId && pending.attackerId !== meId) {
        return err('you are not party to that engagement');
      }
      if (s.battle) return err('you are already committed to a battle');
      if (s.now > pending.graceEndsAt) return err('the grace window has closed — auto-defense has command');

      pending.accepted = true;
      const side: BattleSide = pending.defenderId === meId ? 'defender' : 'attacker';
      this.beginInteractive(pending, side);
      return ok(undefined);
    });
  }

  async pickSide(bottom: BattleSide): Promise<Result<void>> {
    return this.run((s) => {
      const got = this.myBattle(s);
      if (!got.ok) return err(got.error);
      const { b, side } = got.value;
      if (side !== 'defender') return err('only the defending commander picks the deployment side');
      const result = engine.pickSide(b, bottom, s.now);
      this.drainBattleLog();
      return result;
    });
  }

