  async commitDeployment(
    placements: { unitId: UnitId; x: number; y: number }[],
  ): Promise<Result<void>> {
    return this.run((s) => {
      const got = this.myBattle(s);
      if (!got.ok) return err(got.error);
      const { b, side } = got.value;
      // An empty list means "accept the suggested layout".
      const layout =
        placements.length > 0
          ? placements
          : b.units
              .filter((u) => u.side === side && u.alive)
              .map((u) => ({ unitId: u.id, x: u.x, y: u.y }));
      const result = engine.commitDeployment(b, side, layout, s.now);
      this.drainBattleLog();
      return result;
    });
  }

