  // ── guild (GDD §8, §9) ────────────────────────────────────────────────────

  /**
   * Found a banner (GDD §8).
   *
   * Two things happen here that the pure layer deliberately does not do:
   *
   *  1. The banner colour is resolved against the whole register, so the founder
   *     never ends up flying something a rival already flies (`resolveBanner`).
   *  2. AI allies are inducted onto the roster — "AI allies will automatically
   *     join the guild regardless" (playtest feedback). `inductAllies` is the
   *     same seeding path that built every rival banner, so a guild founded in
   *     onboarding arrives with officers, a diplomat, ground, forts and columns
   *     rather than as a name with one commander behind it.
   */
  async createGuild(
    name: string,
    tag: string,
    motto: string,
    banner?: BannerRequest,
  ): Promise<Result<GuildId>> {
    return this.run((s, meId) => {
      const taken = Object.values(s.guilds).map((g) => g.color);
      const issued = resolveBanner(banner, taken);

      const made = createGuild(
        s,
        meId,
        { name, tag, motto, color: issued.color, emblem: issued.emblem },
        s.now,
      );
      if (!made.ok) return err(made.error);

      systemMessage(
        s,
        guildChannel(made.value.id),
        `${made.value.name.toUpperCase()} [${made.value.tag}] REGISTERED. ${made.value.motto.toUpperCase()}`,
        'system',
        s.now,
      );

      const allies = inductAllies(s, this.rng.fork(`induct:${made.value.id}`), made.value.id, s.now);
      if (allies.length > 0) {
        systemMessage(
          s,
          guildChannel(made.value.id),
          `${allies.length} COMMANDER(S) MUSTERED TO THE BANNER. RANKS ASSIGNED.`,
          'system',
          s.now,
        );
        this.notify(
          'info',
          'BANNER RAISED',
          `${made.value.name} [${made.value.tag}] is on the register. ${allies.length} commander(s) mustered to it.`,
        );
      }
      return ok(made.value.id);
    });
  }

  async joinGuild(guildId: GuildId): Promise<Result<void>> {
    return this.run((s, meId) => {
      const joined = joinGuild(s, meId, guildId);
      if (!joined.ok) return err(joined.error);
      const me = s.players[meId];
      systemMessage(
        s,
        guildChannel(guildId),
        `${(me?.name ?? 'A COMMANDER').toUpperCase()} HAS JOINED THE ROSTER.`,
        'system',
        s.now,
      );
      const guild = s.guilds[guildId];
      if (guild) {
        this.notify(
          'info',
          'ENLISTED',
          `You are on the roster of ${guild.name} [${guild.tag}]. ${guild.memberIds.length} commander(s) under the banner.`,
        );
      }
      return ok(undefined);
    });
  }

