  // ── debug / dev ───────────────────────────────────────────────────────────

  /** Fast-forward the sandbox. Steps in half-tick slices so timers fire in order. */
  async debugAdvanceTime(ms: number): Promise<void> {
    const s = this.ensure();
    let remaining = Math.max(0, Math.floor(ms));
    const step = Math.max(1000, Math.floor(ECONOMY.tickMs / 2));
    let guard = 0;
    while (remaining > 0 && guard++ < 1024) {
      const delta = Math.min(step, remaining);
      s.now += delta;
      remaining -= delta;
      try {
        this.simulate();
      } catch (error) {
        console.error('[mock-backend] debugAdvanceTime fault', error);
        break;
      }
    }
    this.publish();
  }

  async debugGrantResources(cost: Cost): Promise<void> {
    const s = this.ensure();
    refund(s, s.meId, { m: Math.max(0, cost.m), g: Math.max(0, cost.g) });
    this.notify('info', 'REQUISITION APPROVED', `+${cost.m}M +${cost.g}G credited to your stockpile.`);
    this.publish();
  }
