/**
 * Modal dialogs: generic `openModal`, plus promise-based `confirmModal` and
 * `promptModal` so callers can `await` a decision inline.
 *
 * Modals stack; each owns its own layer and restores focus on close.
 */
import { el, append, haptic } from '../dom';
import { button, iconButton, ICONS, type ButtonVariant } from './button';

export interface ModalAction {
  label: string;
  variant?: string;
  onClick?: () => void;
  /** Close the modal after `onClick`. Defaults to true. */
  close?: boolean;
}

export interface ModalOpts {
  title: string;
  body: Node | string;
  actions?: ModalAction[];
  /** Scrim tap, Escape and a close button dismiss the modal. Defaults to true. */
  dismissable?: boolean;
  /** Fired when the modal closes for ANY reason. */
  onClose?: () => void;
  /** Accent colour for the rim, e.g. `var(--crimson)`. */
  accent?: string;
  class?: string;
}

export interface ModalHandle {
  close: () => void;
}

function toVariant(v: string | undefined): ButtonVariant {
  return v === 'primary' || v === 'danger' || v === 'quiet' ? v : 'ghost';
}

let openCount = 0;

export function openModal(opts: ModalOpts): ModalHandle {
  const dismissable = opts.dismissable !== false;
  const previousFocus = document.activeElement as HTMLElement | null;

  const layer = el('div', {
    class: opts.class ? `modal-layer ${opts.class}` : 'modal-layer',
    attrs: { role: 'dialog' },
    aria: { modal: 'true', label: opts.title },
  });

  const scrim = el('div', { class: 'modal__scrim' });
  layer.appendChild(scrim);

  const card = el('div', {
    class: 'modal',
    style: opts.accent ? `--accent:${opts.accent}` : undefined,
  });

  let closed = false;

  const onKey = (ev: KeyboardEvent): void => {
    if (ev.key === 'Escape' && dismissable) {
      ev.preventDefault();
      close();
    }
  };

  function close(): void {
    if (closed) return;
    closed = true;
    window.removeEventListener('keydown', onKey);
    card.classList.add('modal--closing');
    window.setTimeout(() => {
      layer.remove();
      openCount = Math.max(0, openCount - 1);
      if (openCount === 0) document.body.classList.remove('modal-open');
      if (previousFocus && document.body.contains(previousFocus)) previousFocus.focus();
    }, 170);
    opts.onClose?.();
  }

  const head = el(
    'header',
    { class: 'modal__head' },
    el('h2', { class: 'modal__title', text: opts.title }),
  );
  if (dismissable) {
    head.appendChild(
      iconButton(ICONS.close, { variant: 'bare', small: true, label: 'close', onClick: close }),
    );
  }
  card.appendChild(head);

  const body = el('div', { class: 'modal__body' });
  if (typeof opts.body === 'string') {
    body.appendChild(el('p', { class: 'selectable', text: opts.body }));
  } else {
    body.appendChild(opts.body);
  }
  card.appendChild(body);

  const actions = opts.actions ?? [];
  if (actions.length > 0) {
    const bar = el('div', { class: 'modal__actions' });
    append(
      bar,
      actions.map((a) =>
        button(a.label, {
          variant: toVariant(a.variant),
          onClick: () => {
            a.onClick?.();
            if (a.close !== false) close();
          },
        }),
      ),
    );
    card.appendChild(bar);
  }

  layer.appendChild(card);

  if (dismissable) {
    scrim.addEventListener('pointerdown', (ev: PointerEvent) => {
      ev.preventDefault();
      close();
    });
  }
  window.addEventListener('keydown', onKey);

  document.body.appendChild(layer);
  openCount++;
  document.body.classList.add('modal-open');
  haptic(12);

  return { close };
}

export interface ConfirmOpts {
  title: string;
  body: string;
  confirmLabel?: string;
  cancelLabel?: string;
  danger?: boolean;
}

/** Yes/no dialog. Resolves `false` when cancelled or dismissed. */
export function confirmModal(opts: ConfirmOpts): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    let answer = false;
    openModal({
      title: opts.title,
      body: opts.body,
      accent: opts.danger ? 'var(--crimson)' : undefined,
      onClose: () => resolve(answer),
      actions: [
        { label: opts.cancelLabel ?? 'CANCEL', variant: 'ghost' },
        {
          label: opts.confirmLabel ?? 'CONFIRM',
          variant: opts.danger ? 'danger' : 'primary',
          onClick: () => {
            answer = true;
          },
        },
      ],
    });
  });
}

export interface PromptOpts {
  title: string;
  label: string;
  value?: string;
  multiline?: boolean;
  maxLength?: number;
  placeholder?: string;
  confirmLabel?: string;
  /** Reject empty input. Defaults to true. */
  required?: boolean;
  /** Uppercase-only field (guild tags). */
  uppercase?: boolean;
}

/** Single-field text prompt. Resolves `null` on cancel or dismissal. */
export function promptModal(opts: PromptOpts): Promise<string | null> {
  return new Promise<string | null>((resolve) => {
    const max = opts.maxLength ?? (opts.multiline ? 1200 : 60);

    const input: HTMLInputElement | HTMLTextAreaElement = opts.multiline
      ? el('textarea', {
          class: 'field__input',
          attrs: { maxlength: max, placeholder: opts.placeholder ?? '', rows: 6 },
        })
      : el('input', {
          class: 'field__input',
          attrs: {
            type: 'text',
            maxlength: max,
            placeholder: opts.placeholder ?? '',
            autocomplete: 'off',
            spellcheck: 'false',
          },
        });
    input.value = opts.value ?? '';

    const target: HTMLElement = input;
    const counter = el('div', { class: 'field__count', text: `${input.value.length}/${max}` });
    const field = el(
      'div',
      { class: 'field selectable' },
      el('span', { class: 'field__label', text: opts.label }),
      input,
      counter,
    );

    const required = opts.required !== false;
    let answer: string | null = null;

    const reject = (): void => {
      input.classList.remove('is-shake');
      void input.offsetWidth;
      input.classList.add('is-shake');
      haptic([14, 30, 14]);
    };

    const submit = (): void => {
      const text = input.value.trim();
      if (required && text.length === 0) {
        reject();
        return;
      }
      answer = text;
      handle.close();
    };

    target.addEventListener('input', () => {
      if (opts.uppercase) input.value = input.value.toUpperCase();
      counter.textContent = `${input.value.length}/${max}`;
      counter.classList.toggle('is-max', input.value.length >= max);
    });

    if (!opts.multiline) {
      target.addEventListener('keydown', (ev: KeyboardEvent) => {
        if (ev.key === 'Enter') {
          ev.preventDefault();
          submit();
        }
      });
    }

    const handle = openModal({
      title: opts.title,
      body: field,
      onClose: () => resolve(answer),
      actions: [
        { label: 'CANCEL', variant: 'ghost' },
        { label: opts.confirmLabel ?? 'CONFIRM', variant: 'primary', onClick: submit, close: false },
      ],
    });

    window.setTimeout(() => input.focus(), 90);
  });
}
