/**
 * GDD §9.1 — Communication: chat, pings, marks and objectives.
 *
 * Channels are flat string keys so the same log structure serves guild chat,
 * the officer channel and cross-guild parley threads:
 *   guild:<guildId>   officer:<guildId>   parley:<parleyId>
 *
 * PURE: no DOM, no Three.js.
 */
import { GUILD } from '../../config/balance';
import { uid } from '../rng';
import type {
  ChatKind,
  ChatMessage,
  GameState,
  GuildId,
  HexId,
  Mark,
  Objective,
  ParleyId,
  Ping,
  PingKind,
  PlayerId,
  Result,
} from '../types';
import { err, ok } from '../types';
import { can, guildOf, isOfficerOrAbove, roleOf } from './permissions';

// ─────────────────────────────────────────────────────────────────────────────
// Channels
// ─────────────────────────────────────────────────────────────────────────────

export const guildChannel = (guildId: GuildId): string => `guild:${guildId}`;
export const officerChannel = (guildId: GuildId): string => `officer:${guildId}`;
export const parleyChannel = (parleyId: ParleyId): string => `parley:${parleyId}`;

export type ChannelKind = 'guild' | 'officer' | 'parley';

export interface ChannelRef {
  kind: ChannelKind;
  id: string;
}

export function parseChannel(channel: string): ChannelRef | undefined {
  const cut = channel.indexOf(':');
  if (cut < 0) return undefined;
  const kind = channel.slice(0, cut);
  const id = channel.slice(cut + 1);
  if (!id) return undefined;
  if (kind === 'guild' || kind === 'officer' || kind === 'parley') return { kind, id };
  return undefined;
}

/** Messages in a channel, oldest first. Never returns undefined. */
export function messages(state: GameState, channel: string): ChatMessage[] {
  return state.chat[channel] ?? [];
}

function logOf(state: GameState, channel: string): ChatMessage[] {
  let log = state.chat[channel];
  if (!log) {
    log = [];
    state.chat[channel] = log;
  }
  return log;
}

/** Append and trim the rolling window to GUILD.chatHistory. */
function append(state: GameState, message: ChatMessage): ChatMessage {
  const log = logOf(state, message.channel);
  log.push(message);
  if (log.length > GUILD.chatHistory) log.splice(0, log.length - GUILD.chatHistory);
  return message;
}

/** May this player read this channel? */
export function canReadChannel(state: GameState, playerId: PlayerId, channel: string): boolean {
  const ref = parseChannel(channel);
  if (!ref) return false;
  switch (ref.kind) {
    case 'guild':
      return guildOf(state, playerId)?.id === ref.id;
    case 'officer':
      return guildOf(state, playerId)?.id === ref.id && isOfficerOrAbove(state, playerId);
    case 'parley': {
      const parley = state.parleys[ref.id];
      const guild = guildOf(state, playerId);
      if (!parley || !guild) return false;
      return parley.guilds.includes(guild.id) && can(state, playerId, 'diplomacy');
    }
    default: {
      const exhaustive: never = ref.kind;
      return exhaustive;
    }
  }
}

/** May this player post here? Same gate as reading, plus the chat capability. */
export function canPostChannel(state: GameState, playerId: PlayerId, channel: string): boolean {
  return can(state, playerId, 'chat') && canReadChannel(state, playerId, channel);
}

// ─────────────────────────────────────────────────────────────────────────────
// Chat
// ─────────────────────────────────────────────────────────────────────────────

export function sendChat(
  state: GameState,
  channel: string,
  playerId: PlayerId,
  text: string,
  kind: ChatKind = 'text',
): Result<ChatMessage> {
  const player = state.players[playerId];
  if (!player) return err('unknown commander');

  const body = text.trim();
  if (!body) return err('nothing to say');
  if (!parseChannel(channel)) return err('unknown channel');
  if (!canPostChannel(state, playerId, channel)) return err('no access to that channel');

  return ok(
    append(state, {
      id: uid('msg'),
      channel,
      authorId: playerId,
      authorName: player.name,
      text: body,
      at: state.now,
      kind,
    }),
  );
}

/**
 * Server-voice broadcast. Bypasses permission checks by design — it is the
 * world talking, not a player.
 */
export function systemMessage(
  state: GameState,
  channel: string,
  text: string,
  kind: ChatKind = 'system',
  at: number = state.now,
): ChatMessage {
  return append(state, {
    id: uid('sys'),
    channel,
    authorId: 'system',
    authorName: 'COMMAND',
    text,
    at,
    kind,
  });
}

/**
 * GDD §7.2 — the 0-0-0 rule.
 *
 * "It triggers a dedicated depressing animation for the affected player and is
 * BROADCAST TO THEIR GUILD CHAT as a system message so everyone knows exactly
 * how unlucky their friend is. No mercy reroll exists. This is intentional."
 *
 * Returns undefined only when the unlucky commander has no guild to be
 * humiliated in front of.
 */
export function broadcastTripleZero(
  state: GameState,
  playerId: PlayerId,
  now: number = state.now,
): ChatMessage | undefined {
  const player = state.players[playerId];
  const guild = guildOf(state, playerId);
  if (!player || !guild) return undefined;

  return systemMessage(
    state,
    guildChannel(guild.id),
    `${player.name.toUpperCase()} ROLLED 0-0-0. ENTIRE TURN SKIPPED. NO REROLL EXISTS.`,
    'triple_zero',
    now,
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Pings (GDD §9.1 — auto-expire after GUILD.pingTtlMs)
// ─────────────────────────────────────────────────────────────────────────────

export function placePing(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  kind: PingKind,
  now: number = state.now,
): Result<Ping> {
  const player = state.players[playerId];
  const guild = guildOf(state, playerId);
  if (!player) return err('unknown commander');
  if (!guild) return err('you are not in a guild');
  if (!can(state, playerId, 'short_objective')) return err('no access');

  // One live ping per author per hex — re-pinging refreshes it instead.
  state.pings = state.pings.filter(
    (p) => !(p.guildId === guild.id && p.hexId === hexId && p.authorId === playerId),
  );

  const ping: Ping = {
    id: uid('png'),
    guildId: guild.id,
    hexId,
    kind,
    authorId: playerId,
    authorName: player.name,
    at: now,
    expiresAt: now + GUILD.pingTtlMs,
  };
  state.pings.push(ping);
  return ok(ping);
}

/** Drop expired pings. Returns the ones that were removed. */
export function expirePings(state: GameState, now: number = state.now): Ping[] {
  const dead: Ping[] = [];
  const live: Ping[] = [];
  for (const ping of state.pings) {
    if (ping.expiresAt <= now) dead.push(ping);
    else live.push(ping);
  }
  if (dead.length > 0) state.pings = live;
  return dead;
}

/** Live pings belonging to a guild, newest first. */
export function pingsFor(state: GameState, guildId: GuildId, now: number = state.now): Ping[] {
  return state.pings
    .filter((p) => p.guildId === guildId && p.expiresAt > now)
    .sort((a, b) => b.at - a.at);
}

// ─────────────────────────────────────────────────────────────────────────────
// Marks (GDD §9.1 — placed by any member, removable by Officers+)
// ─────────────────────────────────────────────────────────────────────────────

export function placeMark(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  label: string,
  now: number = state.now,
): Result<Mark> {
  const player = state.players[playerId];
  const guild = guildOf(state, playerId);
  if (!player) return err('unknown commander');
  if (!guild) return err('you are not in a guild');
  if (!can(state, playerId, 'short_objective')) return err('no access');

  const text = label.trim();
  if (!text) return err('a mark needs a label');

  const existing = state.marks.filter((m) => m.guildId === guild.id).length;
  if (existing >= GUILD.maxMarks) return err(`mark limit reached (${GUILD.maxMarks})`);

  const mark: Mark = {
    id: uid('mrk'),
    guildId: guild.id,
    hexId,
    label: text,
    authorId: playerId,
    authorName: player.name,
    at: now,
  };
  state.marks.push(mark);
  return ok(mark);
}

/** GDD §9.1: marks are removable by Officers and above only. */
export function removeMark(state: GameState, playerId: PlayerId, markId: string): Result<Mark> {
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');

  const mark = state.marks.find((m) => m.id === markId);
  if (!mark) return err('unknown mark');
  if (mark.guildId !== guild.id) return err('not your guild mark');
  if (!isOfficerOrAbove(state, playerId)) return err('officers and above only');

  state.marks = state.marks.filter((m) => m.id !== markId);
  return ok(mark);
}

export function marksFor(state: GameState, guildId: GuildId): Mark[] {
  return state.marks.filter((m) => m.guildId === guildId).sort((a, b) => b.at - a.at);
}

// ─────────────────────────────────────────────────────────────────────────────
// Objectives (GDD §9.1)
// ─────────────────────────────────────────────────────────────────────────────

export interface ObjectiveInput {
  title: string;
  detail?: string;
  hexIds?: HexId[];
  grand: boolean;
  dueAt?: number;
}

export function objectivesFor(state: GameState, guildId: GuildId): Objective[] {
  return state.objectives
    .filter((o) => o.guildId === guildId)
    .sort((a, b) => {
      if (a.grand !== b.grand) return a.grand ? -1 : 1;
      if (a.done !== b.done) return a.done ? 1 : -1;
      return (a.dueAt ?? Infinity) - (b.dueAt ?? Infinity) || b.createdAt - a.createdAt;
    });
}

/** The single pinned grand objective for a guild, if one is set. */
export function grandObjective(state: GameState, guildId: GuildId): Objective | undefined {
  return state.objectives.find((o) => o.guildId === guildId && o.grand);
}

/**
 * Create an objective.
 * Short objectives: anyone. Grand objective: Officers+ and exactly one per
 * guild (GDD §9.1 — "one pinned grand objective for the season").
 */
export function createObjective(
  state: GameState,
  playerId: PlayerId,
  input: ObjectiveInput,
  now: number = state.now,
): Result<Objective> {
  const player = state.players[playerId];
  const guild = guildOf(state, playerId);
  if (!player) return err('unknown commander');
  if (!guild) return err('you are not in a guild');

  const cap = input.grand ? 'grand_objective' : 'short_objective';
  if (!can(state, playerId, cap)) return err('officers and above only');

  const title = input.title.trim();
  if (!title) return err('an objective needs a title');

  if (input.grand && grandObjective(state, guild.id)) {
    return err('a grand objective is already pinned — retire it first');
  }

  const objective: Objective = {
    id: uid('obj'),
    guildId: guild.id,
    title,
    detail: (input.detail ?? '').trim(),
    hexIds: [...(input.hexIds ?? [])],
    grand: input.grand,
    createdBy: playerId,
    createdByName: player.name,
    createdAt: now,
    dueAt: input.dueAt,
    committed: [],
    done: false,
  };
  state.objectives.push(objective);
  return ok(objective);
}

/** Any member may flag themselves committed to an objective. */
export function commitToObjective(
  state: GameState,
  playerId: PlayerId,
  objectiveId: string,
  committed: boolean,
): Result<Objective> {
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');

  const objective = state.objectives.find((o) => o.id === objectiveId);
  if (!objective) return err('unknown objective');
  if (objective.guildId !== guild.id) return err('not your guild objective');
  if (objective.done) return err('objective already closed');

  const has = objective.committed.includes(playerId);
  if (committed && !has) objective.committed.push(playerId);
  if (!committed && has) objective.committed = objective.committed.filter((id) => id !== playerId);
  return ok(objective);
}

/** Officers+ may close any objective; a member may close their own short one. */
function mayAdminister(state: GameState, playerId: PlayerId, objective: Objective): boolean {
  if (objective.grand) return can(state, playerId, 'grand_objective');
  return isOfficerOrAbove(state, playerId) || objective.createdBy === playerId;
}

export function completeObjective(
  state: GameState,
  playerId: PlayerId,
  objectiveId: string,
  now: number = state.now,
): Result<Objective> {
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');

  const objective = state.objectives.find((o) => o.id === objectiveId);
  if (!objective) return err('unknown objective');
  if (objective.guildId !== guild.id) return err('not your guild objective');
  if (!mayAdminister(state, playerId, objective)) return err('no access');
  if (objective.done) return err('objective already closed');

  objective.done = true;
  systemMessage(
    state,
    guildChannel(guild.id),
    `OBJECTIVE COMPLETE — ${objective.title.toUpperCase()}`,
    'system',
    now,
  );
  return ok(objective);
}

export function deleteObjective(
  state: GameState,
  playerId: PlayerId,
  objectiveId: string,
): Result<Objective> {
  const guild = guildOf(state, playerId);
  if (!guild) return err('you are not in a guild');

  const objective = state.objectives.find((o) => o.id === objectiveId);
  if (!objective) return err('unknown objective');
  if (objective.guildId !== guild.id) return err('not your guild objective');
  if (!mayAdminister(state, playerId, objective)) return err('no access');

  state.objectives = state.objectives.filter((o) => o.id !== objectiveId);
  return ok(objective);
}

/** Convenience for the roster/objective panels. */
export function roleLabel(state: GameState, playerId: PlayerId): string {
  const role = roleOf(state, playerId);
  if (role === 'leader') return 'LEADER';
  if (role === 'officer') return 'OFFICER';
  if (role === 'member') return 'MEMBER';
  return 'UNAFFILIATED';
}
