/**
 * Fortifications — GDD §6.
 *
 * Outpost → Bastion → Citadel. Real build timers, half refund on cancel, and a
 * total wipe when the hex is captured or its sector shuts down.
 *
 * PURE: no Three.js, no DOM.
 */
import type { Cost, GameState, Hex, HexId, PlayerId, Result } from '../types';
import { err, ok } from '../types';
import { FORTS, type FortSpec } from '../../config/balance';
import { isHexOpen } from './generate';
import { canAfford, halveCost, refund, spend } from './economy';

export type FortEvent =
  | { t: 'fort_complete'; at: number; hexId: HexId; ownerId?: PlayerId; level: 1 | 2 | 3 }
  | { t: 'fort_cancelled'; at: number; hexId: HexId; ownerId?: PlayerId; refunded: Cost };

/** Blow the emplacement off a hex. Used on capture and on sector shutdown. */
export function destroyFort(hex: Hex): void {
  hex.fortLevel = 0;
  hex.fortBuild = undefined;
}

/** The upgrade a player may start on this hex right now. */
export function canBuildFort(state: GameState, playerId: PlayerId, hexId: HexId): Result<FortSpec> {
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (!isHexOpen(state.world, hexId)) return err('sector is locked');
  if (hex.ownerId !== playerId) return err('you do not hold this hex');
  if (hex.capture) return err('hex is being contested');
  if (hex.fortBuild) return err('construction is already under way');
  if (hex.fortLevel >= 3) return err('already a Citadel — nothing left to build');

  const next = (hex.fortLevel + 1) as 1 | 2 | 3;
  const spec = FORTS[next];
  if (!canAfford(state, playerId, spec.cost)) return err('insufficient resources');
  return ok(spec);
}

/** Debit the cost and start the build timer. */
export function startFort(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  now: number,
): Result<void> {
  const check = canBuildFort(state, playerId, hexId);
  if (!check.ok) return err(check.error);
  const hex = state.world.hexes[hexId];
  const spec = check.value;
  if (!spend(state, playerId, spec.cost)) return err('insufficient resources');
  hex.fortBuild = {
    targetLevel: spec.level,
    startedAt: now,
    completesAt: now + spec.buildMs,
  };
  return ok(undefined);
}

/** Abort construction. Half the outlay comes back. */
export function cancelFort(
  state: GameState,
  playerId: PlayerId,
  hexId: HexId,
  now: number,
): Result<Cost> {
  const hex = state.world.hexes[hexId];
  if (!hex) return err('no such hex');
  if (hex.ownerId !== playerId) return err('you do not hold this hex');
  const build = hex.fortBuild;
  if (!build) return err('nothing under construction here');

  const back = halveCost(FORTS[build.targetLevel].cost);
  hex.fortBuild = undefined;
  refund(state, playerId, back);
  return ok(back);
}

/** Complete every build whose timer has run out. */
export function tickForts(state: GameState, now: number): FortEvent[] {
  const out: FortEvent[] = [];
  for (const hex of Object.values(state.world.hexes)) {
    const build = hex.fortBuild;
    if (!build) continue;
    if (build.completesAt > now) continue;
    if (!isHexOpen(state.world, hex.id) || !hex.ownerId) {
      // The ground was lost while the crews were working.
      hex.fortBuild = undefined;
      out.push({
        t: 'fort_cancelled',
        at: now,
        hexId: hex.id,
        ownerId: hex.ownerId,
        refunded: { m: 0, g: 0 },
      });
      continue;
    }
    hex.fortLevel = build.targetLevel;
    hex.fortBuild = undefined;
    out.push({
      t: 'fort_complete',
      at: build.completesAt,
      hexId: hex.id,
      ownerId: hex.ownerId,
      level: build.targetLevel,
    });
  }
  return out;
}

/** UI helper: the spec of the next tier, or undefined at Citadel. */
export function nextFortSpec(hex: Hex): FortSpec | undefined {
  if (hex.fortLevel >= 3) return undefined;
  return FORTS[(hex.fortLevel + 1) as 1 | 2 | 3];
}
