/**
 * Season standings & win conditions — GDD §9.2, §11.
 *
 * Three ways to win: domination (every rival holds zero hexes), forfeit (every
 * other guild is gone) and timeout (most tiles when the clock runs out, broken
 * by Power Points then by total resources harvested).
 *
 * PURE: no Three.js, no DOM.
 */
import type { Cost, GameState, GuildId, PlayerId, PowerBreakdown } from '../types';
import { GUILD } from '../../config/balance';
import { UNITS } from '../../config/units';
import { playerHexCount, playerYield } from './economy';

export type SeasonEndReason = 'domination' | 'forfeit' | 'timeout';

export interface GuildStanding {
  guildId: GuildId;
  name: string;
  tag: string;
  color: number;
  tiles: number;
  power: number;
  harvested: Cost;
  memberCount: number;
  onlineCount: number;
}

export type SeasonEvent = {
  t: 'season_end';
  at: number;
  winnerGuildId?: GuildId;
  reason: SeasonEndReason;
  standings: GuildStanding[];
};

// ─────────────────────────────────────────────────────────────────────────────
// Power points (GDD §9.2)
// ─────────────────────────────────────────────────────────────────────────────

/** Resource-equivalent worth of a unit roster. */
function rosterPower(state: GameState, playerId: PlayerId): number {
  let power = 0;
  for (const army of Object.values(state.armies)) {
    if (army.ownerId !== playerId) continue;
    for (const unit of army.units) {
      const cost = UNITS[unit.type].cost;
      power += cost.m + cost.g;
    }
  }
  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId !== playerId) continue;
    for (const [type, n] of Object.entries(hex.reserves) as [keyof typeof UNITS, number][]) {
      const cost = UNITS[type].cost;
      power += (cost.m + cost.g) * (n ?? 0);
    }
  }
  return power;
}

/** Unit worth + territory worth (hourly yield × k). */
export function playerPower(state: GameState, playerId: PlayerId): PowerBreakdown {
  const yieldPerHour = playerYield(state, playerId);
  const unitPower = rosterPower(state, playerId);
  const territoryPower = (yieldPerHour.m + yieldPerHour.g) * GUILD.powerYieldK;
  return {
    unitPower,
    territoryPower,
    total: unitPower + territoryPower,
    hexCount: playerHexCount(state, playerId),
    yieldPerHour,
  };
}

export function guildPower(state: GameState, guildId: GuildId): number {
  const guild = state.guilds[guildId];
  if (!guild) return 0;
  let total = 0;
  for (const memberId of guild.memberIds) total += playerPower(state, memberId).total;
  return total;
}

// ─────────────────────────────────────────────────────────────────────────────
// Standings
// ─────────────────────────────────────────────────────────────────────────────

/** Hexes held per guild. Every registered guild appears, zeroes included. */
export function guildTileCounts(state: GameState): Record<GuildId, number> {
  const out: Record<GuildId, number> = {};
  for (const id of Object.keys(state.guilds)) out[id] = 0;
  for (const hex of Object.values(state.world.hexes)) {
    if (!hex.ownerId) continue;
    const owner = state.players[hex.ownerId];
    if (!owner?.guildId) continue;
    if (!(owner.guildId in out)) out[owner.guildId] = 0;
    out[owner.guildId]++;
  }
  return out;
}

/** Leaderboard order: tiles, then Power Points, then total harvest. */
export function guildStandings(state: GameState): GuildStanding[] {
  const tiles = guildTileCounts(state);
  const rows: GuildStanding[] = [];
  for (const guild of Object.values(state.guilds)) {
    let harvestedM = 0;
    let harvestedG = 0;
    let online = 0;
    for (const memberId of guild.memberIds) {
      const player = state.players[memberId];
      if (!player) continue;
      harvestedM += player.harvested?.m ?? 0;
      harvestedG += player.harvested?.g ?? 0;
      if (player.online) online++;
    }
    rows.push({
      guildId: guild.id,
      name: guild.name,
      tag: guild.tag,
      color: guild.color,
      tiles: tiles[guild.id] ?? 0,
      power: guildPower(state, guild.id),
      harvested: { m: harvestedM, g: harvestedG },
      memberCount: guild.memberIds.length,
      onlineCount: online,
    });
  }
  rows.sort((a, b) => {
    if (a.tiles !== b.tiles) return b.tiles - a.tiles;
    if (a.power !== b.power) return b.power - a.power;
    const ha = a.harvested.m + a.harvested.g;
    const hb = b.harvested.m + b.harvested.g;
    if (ha !== hb) return hb - ha;
    return a.guildId < b.guildId ? -1 : 1;
  });
  return rows;
}

// ─────────────────────────────────────────────────────────────────────────────
// Win conditions (GDD §11)
// ─────────────────────────────────────────────────────────────────────────────

export interface SeasonVerdict {
  winnerGuildId?: GuildId;
  reason?: SeasonEndReason;
}

/**
 * Record every guild that currently holds ground. Call before evaluating, so
 * `season.contested` is the set of banners that have ever taken the field.
 */
export function markContested(state: GameState): void {
  const season = state.season;
  if (!season.contested) season.contested = [];
  const tiles = guildTileCounts(state);
  for (const [guildId, count] of Object.entries(tiles)) {
    if (count > 0 && !season.contested.includes(guildId)) season.contested.push(guildId);
  }
}

export function evaluateSeason(state: GameState, now: number): SeasonVerdict {
  const guilds = Object.values(state.guilds);
  if (guilds.length === 0) return {};

  // 2. Forfeit — everyone else quit or disbanded.
  if (guilds.length === 1) return { winnerGuildId: guilds[0].id, reason: 'forfeit' };

  // 1. Domination — every rival guild has been driven off every hex it held.
  //
  // This is deliberately NOT "exactly one guild owns a hex right now". At the
  // start of a season the map is almost entirely neutral, so that reading ends
  // the war the moment the first commander captures the first tile, before any
  // rival has even deployed. A banner can only be *removed* from the map if it
  // was on it, so domination is judged against `season.contested` and needs at
  // least two banners to have held ground.
  const tiles = guildTileCounts(state);
  const holders = guilds.filter((g) => (tiles[g.id] ?? 0) > 0);
  const contested = state.season.contested ?? [];
  if (holders.length === 1 && contested.length >= 2) {
    return { winnerGuildId: holders[0].id, reason: 'domination' };
  }

  // 3. Timeout — most tiles at the buzzer, tiebreak power then harvest.
  if (now >= state.season.endsAt) {
    const standings = guildStandings(state);
    const top = standings[0];
    return top ? { winnerGuildId: top.guildId, reason: 'timeout' } : { reason: 'timeout' };
  }
  return {};
}

/** Close the season the first time a win condition is met. */
export function tickSeason(state: GameState, now: number): SeasonEvent[] {
  const season = state.season;
  if (season.phase === 'ended') return [];
  markContested(state);
  const verdict = evaluateSeason(state, now);
  if (!verdict.reason) return [];

  season.phase = 'ended';
  season.winnerGuildId = verdict.winnerGuildId;
  season.endReason = verdict.reason;
  return [
    {
      t: 'season_end',
      at: now,
      winnerGuildId: verdict.winnerGuildId,
      reason: verdict.reason,
      standings: guildStandings(state),
    },
  ];
}

/** Milliseconds left in the season (never negative). */
export function seasonRemainingMs(state: GameState, now: number): number {
  return Math.max(0, state.season.endsAt - now);
}
