/**
 * TERRA BELLUM — board template loader (GDD §7.1, §13).
 *
 * "Board layouts, twist definitions, and sector layouts are data (JSON), not
 * code — adding a map or twist is a content edit."
 *
 * PURE MODULE: no Three.js, no DOM. Runs under node.
 */

import type { BoardTemplate, Terrain, Tile, TileKind } from '../types';
import type { Rng } from '../rng';
import { BATTLE } from '../../config/balance';
import boardsJson from '../../content/boards.json';

// ─────────────────────────────────────────────────────────────────────────────
// Character map — one char per tile in a template row string.
// ─────────────────────────────────────────────────────────────────────────────

export const CHAR_TO_TILE: Record<string, TileKind> = {
  '.': 'floor',
  '#': 'obstacle',
  '~': 'rough',
  c: 'cover',
  h: 'hazard',
  t: 'teleport',
  d: 'destructible',
  e: 'elevation',
  u: 'unstable',
};

/** Reverse map, handy for editors / debug rendering. */
export const TILE_TO_CHAR: Record<TileKind, string> = {
  floor: '.',
  obstacle: '#',
  rough: '~',
  cover: 'c',
  hazard: 'h',
  teleport: 't',
  destructible: 'd',
  elevation: 'e',
  unstable: 'u',
};

const TERRAINS: readonly Terrain[] = ['plains', 'ridge', 'crater', 'ruins', 'gasfield'];

/**
 * Chars that may never appear in a deployment row — they would strand a side.
 *
 * Rough ground counts: a `no_rough_end` chassis (both Pallet Tanks) cannot be
 * placed on it, so a deployment band containing `~` can leave a tank with no
 * legal tile. An unplaced unit is still a LIVING unit at (-1,-1) that nothing
 * can reach, and a battle with an unreachable survivor can never end.
 */
const DEPLOY_FORBIDDEN: readonly string[] = ['#', 'd', '~'];

/** GDD §7.1 twist pool. Every board must ship at least one of these. */
export const TWIST_KINDS: readonly TileKind[] = [
  'hazard',
  'teleport',
  'destructible',
  'elevation',
  'unstable',
];

// ─────────────────────────────────────────────────────────────────────────────
// Loading + validation
// ─────────────────────────────────────────────────────────────────────────────

let cache: BoardTemplate[] | null = null;

function fail(id: string, msg: string): never {
  throw new Error(`boards.json: template "${id}" ${msg}`);
}

function isStr(v: unknown): v is string {
  return typeof v === 'string' && v.length > 0;
}

function validate(raw: unknown, index: number, seenIds: Set<string>): BoardTemplate {
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error(`boards.json: entry #${index} is not an object`);
  }
  const o = raw as Record<string, unknown>;
  const id = typeof o.id === 'string' ? o.id : `#${index}`;

  if (!isStr(o.id)) fail(id, 'has no id');
  if (seenIds.has(id)) fail(id, 'has a duplicate id');
  seenIds.add(id);

  if (!isStr(o.name)) fail(id, 'has no name');
  if (!isStr(o.twist)) fail(id, 'has no twist');
  if (!isStr(o.blurb)) fail(id, 'has no blurb');

  const terrain = o.terrain;
  if (typeof terrain !== 'string' || !TERRAINS.includes(terrain as Terrain)) {
    fail(id, `has an unknown terrain "${String(terrain)}"`);
  }

  const w = o.w;
  const h = o.h;
  if (typeof w !== 'number' || typeof h !== 'number' || !Number.isInteger(w) || !Number.isInteger(h)) {
    fail(id, 'has a non-integer w/h');
  }
  if (w < BATTLE.boardSizeMin || w > BATTLE.boardSizeMax) {
    fail(id, `width ${w} is outside ${BATTLE.boardSizeMin}..${BATTLE.boardSizeMax}`);
  }
  if (h < BATTLE.boardSizeMin || h > BATTLE.boardSizeMax) {
    fail(id, `height ${h} is outside ${BATTLE.boardSizeMin}..${BATTLE.boardSizeMax}`);
  }
  if (w !== h) fail(id, `is not square (${w}x${h}); the tactical board is always square`);

  const rows = o.rows;
  if (!Array.isArray(rows) || rows.length !== h) {
    fail(id, `must declare exactly ${h} row strings`);
  }
  const rowStrings: string[] = [];
  for (let y = 0; y < rows.length; y++) {
    const r = rows[y];
    if (typeof r !== 'string') fail(id, `row ${y} is not a string`);
    if (r.length !== w) fail(id, `row ${y} is ${r.length} chars, expected ${w}`);
    for (let x = 0; x < r.length; x++) {
      if (!(r[x] in CHAR_TO_TILE)) fail(id, `row ${y} uses unknown tile char "${r[x]}"`);
    }
    rowStrings.push(r);
  }

  // Deployment rows must never be blocked — both sides must always be able to
  // put every unit on the board (GDD §7.1).
  const deployRows: number[] = [];
  for (let i = 0; i < BATTLE.deployRows; i++) {
    deployRows.push(i, h - 1 - i);
  }
  for (const y of deployRows) {
    const r = rowStrings[y];
    for (let x = 0; x < r.length; x++) {
      if (DEPLOY_FORBIDDEN.includes(r[x])) {
        fail(id, `blocks deployment row ${y} at x=${x} with "${r[x]}"`);
      }
    }
  }
  const perSideDeployTiles = BATTLE.deployRows * w;
  if (perSideDeployTiles < BATTLE.armyCap) {
    fail(id, `only offers ${perSideDeployTiles} deploy tiles for an army cap of ${BATTLE.armyCap}`);
  }

  // Counts.
  let obstacles = 0;
  let teleports = 0;
  let twists = 0;
  for (const r of rowStrings) {
    for (const ch of r) {
      const kind = CHAR_TO_TILE[ch];
      if (kind === 'obstacle') obstacles++;
      if (kind === 'teleport') teleports++;
      if (TWIST_KINDS.includes(kind)) twists++;
    }
  }
  if (obstacles === 0) fail(id, 'contains no blocking obstacles');
  if (twists === 0) fail(id, 'contains no twist feature');
  if (teleports % 2 !== 0) fail(id, `has ${teleports} teleport pads; pads must be paired`);

  return {
    id,
    name: o.name,
    terrain: terrain as Terrain,
    w,
    h,
    rows: rowStrings,
    twist: o.twist,
    blurb: o.blurb,
  };
}

/**
 * All shipped board templates. Validated on the first call; throws a
 * descriptive Error if the content file is malformed.
 */
export function allTemplates(): BoardTemplate[] {
  if (cache) return cache;
  const raw = boardsJson as unknown;
  if (!Array.isArray(raw)) throw new Error('boards.json: root is not an array');
  if (raw.length === 0) throw new Error('boards.json: no templates shipped');
  const seen = new Set<string>();
  const out: BoardTemplate[] = [];
  for (let i = 0; i < raw.length; i++) out.push(validate(raw[i], i, seen));
  cache = out;
  return out;
}

/** Test/hot-reload hook: drop the validated cache. */
export function resetTemplateCache(): void {
  cache = null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Selection
// ─────────────────────────────────────────────────────────────────────────────

export function templatesFor(terrain: Terrain, size: number): BoardTemplate[] {
  return allTemplates().filter((t) => t.terrain === terrain && t.w === size && t.h === size);
}

/** Board edge length for a given combined unit count (GDD §7.1). */
export function boardSizeFor(totalUnits: number): number {
  if (totalUnits <= BATTLE.smallBoardThreshold) return BATTLE.boardSizeMin;
  if (totalUnits <= BATTLE.mediumBoardThreshold) return BATTLE.boardSizeMin + 1;
  return BATTLE.boardSizeMax;
}

/**
 * Pick a board for a battle. Falls back across terrains (then across sizes)
 * so a battle can always be started.
 */
export function pickTemplate(terrain: Terrain, totalUnits: number, rng: Rng): BoardTemplate {
  const size = boardSizeFor(totalUnits);
  const all = allTemplates();

  const exact = templatesFor(terrain, size);
  if (exact.length) return rng.pick(exact);

  const anyTerrainSameSize = all.filter((t) => t.w === size && t.h === size);
  if (anyTerrainSameSize.length) return rng.pick(anyTerrainSameSize);

  const sameTerrainAnySize = all.filter((t) => t.terrain === terrain);
  if (sameTerrainAnySize.length) return rng.pick(sameTerrainAnySize);

  return rng.pick(all);
}

// ─────────────────────────────────────────────────────────────────────────────
// Grid construction
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Materialise a template into a live `grid[y][x]` tile matrix:
 * destructibles get `hp`, teleport pads get a `pairId` (paired in reading
 * order), unstable tiles get `crossings: 0`.
 */
export function buildGrid(t: BoardTemplate): Tile[][] {
  const grid: Tile[][] = [];
  let teleportIndex = 0;
  for (let y = 0; y < t.h; y++) {
    const row: Tile[] = [];
    const src = t.rows[y];
    for (let x = 0; x < t.w; x++) {
      const kind: TileKind = CHAR_TO_TILE[src[x]] ?? 'floor';
      const tile: Tile = { x, y, kind };
      if (kind === 'destructible') tile.hp = BATTLE.wallHp;
      if (kind === 'teleport') {
        tile.pairId = Math.floor(teleportIndex / 2);
        teleportIndex++;
      }
      if (kind === 'unstable') {
        tile.crossings = 0;
        tile.collapsed = false;
      }
      row.push(tile);
    }
    grid.push(row);
  }
  return grid;
}
