/**
 * TERRA BELLUM — auto-defense AI (GDD §7.4).
 *
 * "If the defender never connects, the battle resolves as an auto-defense: the
 * defender is played by simple AI (greedy heuristic)."
 *
 * Priority order, re-evaluated from scratch after every single action:
 *   1. killing blow
 *   2. highest damage per AP
 *   3. reposition that opens a shot this turn
 *   4. advance toward the nearest enemy along a real reachable path
 *   5. breach a wall that is in the way
 *   6. brace
 *
 * The action loop is hard-capped and any failed Result zeroes that unit's AP,
 * so the AI can never spin or desync the state.
 *
 * PURE MODULE: no Three.js, no DOM.
 */

import type { BattleSide, BattleState, BattleUnit, DieIndex, Tile, UnitId } from '../types';
import type { Rng } from '../rng';
import { BATTLE } from '../../config/balance';
import { UNITS } from '../../config/units';
import {
  assignDie,
  attack,
  attackTile,
  autoDeploy,
  brace,
  commitDeployment,
  confirmAssignments,
  endTurn,
  finishObstacles,
  moveUnit,
  obstacleSpots,
  pickSide,
  placeObstacle,
  rollDice,
} from './engine';
import {
  ORTHOGONAL,
  battleDistance,
  canAttack,
  computeDamage,
  effectiveRange,
  hasLineOfSight,
  hasTrait,
  isBlocking,
  isOver,
  livingUnits,
  otherSide,
  reachableTiles,
  stepDistance,
  tileAt,
  tileKey,
  unitAt,
} from './rules';

const DIE_INDICES: readonly DieIndex[] = [0, 1, 2];

type PlanKind = 'attack' | 'wall' | 'move' | 'brace';

interface Plan {
  kind: PlanKind;
  unitId: UnitId;
  score: number;
  targetId: UnitId;
  x: number;
  y: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Setup
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Play every pre-battle phase this side owns: side pick, bonus obstacles,
 * deployment. Safe to call at any point before the first roll.
 */
export function aiDeploy(s: BattleState, side: BattleSide, rng: Rng): void {
  if (s.phase === 'side_pick' && side === 'defender') {
    pickSide(s, 'defender', 0);
  }

  if (s.phase === 'obstacle_place' && side === 'defender') {
    let guard = 0;
    while (s.phase === 'obstacle_place' && s.obstaclesToPlace > 0 && guard++ < 240) {
      const spot = pickObstacleSpot(s, rng);
      if (!spot) break;
      if (!placeObstacle(s, spot.x, spot.y, 0).ok) break;
    }
    // The board refused any further seals; hand the rest back and get on with it.
    if (s.phase === 'obstacle_place') finishObstacles(s, 0);
  }

  if (s.phase !== 'deploy') return;
  autoDeploy(s, side, rng);
  const placements = s.units
    .filter((u) => u.side === side && u.alive)
    .map((u) => ({ unitId: u.id, x: u.x, y: u.y }));
  commitDeployment(s, side, placements, 0);
}

/**
 * Prefer sealing the lanes closest to the middle of the board.
 *
 * Drawn from `obstacleSpots`, which is the engine's own legality test — so this
 * never proposes a tile that would be refused and never spins on one.
 */
function pickObstacleSpot(s: BattleState, rng: Rng): { x: number; y: number } | null {
  const cx = (s.w - 1) / 2;
  const cy = (s.h - 1) / 2;
  const candidates = obstacleSpots(s)
    .map((p) => ({ x: p.x, y: p.y, w: Math.abs(p.x - cx) + Math.abs(p.y - cy) }))
    .sort((a, b) => a.w - b.w);
  if (candidates.length === 0) return null;
  return rng.pick(candidates.slice(0, Math.min(6, candidates.length)));
}

// ─────────────────────────────────────────────────────────────────────────────
// Scoring
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Cost of stepping ONTO a tile, used by the approach field. Danger is priced in
 * here rather than as a positional bonus so the field routes around a vent
 * field instead of leaving a unit stuck facing one.
 */
function stepWeight(s: BattleState, u: BattleUnit, x: number, y: number, lax: boolean): number {
  const t = tileAt(s, x, y);
  if (!t) return Number.POSITIVE_INFINITY;
  const flies = hasTrait(u, 'ignores_obstacles');
  if (t.kind === 'destructible' && (t.hp ?? 0) > 0) {
    // A wall is only a wall until someone shoots it.
    return flies ? 1 : lax ? 4 : Number.POSITIVE_INFINITY;
  }
  if (isBlocking(s, x, y)) return flies ? 1 : Number.POSITIVE_INFINITY;
  if (t.kind === 'rough' && hasTrait(u, 'no_rough_end') && UNITS[u.type].mov < 2) {
    // A one-tile tracked hull can never clear a rough tile in a single action.
    return lax ? 2 : Number.POSITIVE_INFINITY;
  }
  switch (t.kind) {
    case 'hazard':
      return lax ? 2 : 5;
    case 'unstable':
      return 2;
    default:
      return 1;
  }
}

/**
 * Positional tie-break for the destination tile. Deliberately small: it must
 * stay under the approach gradient (4 per step) or a unit will happily walk
 * backwards onto a firing step and camp there forever.
 */
function terrainAppeal(u: BattleUnit, t: Tile | null): number {
  if (!t) return 0;
  switch (t.kind) {
    case 'hazard':
      return -1;
    case 'unstable':
      return -1;
    case 'elevation':
      return 2;
    case 'cover':
      return hasTrait(u, 'cover_bonus') ? 2 : 0;
    default:
      return 0;
  }
}

/** Where a unit really ends up if it stops on (x, y) — teleport pads relocate. */
function landingOf(s: BattleState, x: number, y: number): { x: number; y: number } {
  const t = tileAt(s, x, y);
  if (!t || t.kind !== 'teleport' || t.pairId === undefined) return { x, y };
  for (let ty = 0; ty < s.h; ty++) {
    for (let tx = 0; tx < s.w; tx++) {
      const o = s.grid[ty][tx];
      if (o.kind === 'teleport' && o.pairId === t.pairId && !(tx === x && ty === y)) {
        return unitAt(s, tx, ty) ? { x, y } : { x: tx, y: ty };
      }
    }
  }
  return { x, y };
}

function nearestEnemyStepDistance(s: BattleState, side: BattleSide, x: number, y: number): number {
  let best = Number.POSITIVE_INFINITY;
  for (const e of livingUnits(s, otherSide(side))) {
    const d = stepDistance(x, y, e.x, e.y);
    if (d < best) best = d;
  }
  return Number.isFinite(best) ? best : 0;
}

/**
 * Weighted path cost from every tile to the nearest enemy, flooded out from the
 * enemies themselves and respecting this chassis' traversal rules.
 *
 * Straight-line distance is not good enough: on a board with lane walls and
 * vent fields it produces local minima, and a greedy unit will press its face
 * into a wall forever instead of walking around. Blocking units are ignored —
 * they move. Dijkstra, not BFS, because tile weights differ; the board is at
 * most 64 tiles so the naive scan is free.
 */
function enemyPathField(s: BattleState, u: BattleUnit, lax: boolean): Map<string, number> {
  const field = new Map<string, number>();
  const settled = new Set<string>();
  for (const e of livingUnits(s, otherSide(u.side))) {
    field.set(tileKey(e.x, e.y), 0);
  }

  for (;;) {
    let bestKey: string | null = null;
    let bestCost = Number.POSITIVE_INFINITY;
    for (const [key, cost] of field) {
      if (settled.has(key)) continue;
      if (cost < bestCost) {
        bestCost = cost;
        bestKey = key;
      }
    }
    if (bestKey === null) break;
    settled.add(bestKey);

    const comma = bestKey.indexOf(',');
    const cx = Number(bestKey.slice(0, comma));
    const cy = Number(bestKey.slice(comma + 1));
    for (const [dx, dy] of ORTHOGONAL) {
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= s.w || ny >= s.h) continue;
      const key = tileKey(nx, ny);
      if (settled.has(key)) continue;
      const w = stepWeight(s, u, nx, ny, lax);
      if (!Number.isFinite(w)) continue;
      const cand = bestCost + w;
      const known = field.get(key);
      if (known === undefined || cand < known) field.set(key, cand);
    }
  }
  return field;
}

interface ApproachField {
  strict: Map<string, number>;
  lax: Map<string, number>;
  offset: number;
}

function approachField(s: BattleState, u: BattleUnit): ApproachField {
  return {
    strict: enemyPathField(s, u, false),
    lax: enemyPathField(s, u, true),
    // Any legal route always beats a route that needs a wall breached first.
    offset: s.w * s.h * 8,
  };
}

/**
 * Cost of reaching the nearest enemy from (x, y). Falls back to a relaxed field
 * — walls treated as breachable, rough as merely awkward — plus a flat offset,
 * so a boxed-in unit still gets a gradient to follow toward the fight instead
 * of standing in place forever.
 */
function approachCost(s: BattleState, u: BattleUnit, f: ApproachField, x: number, y: number): number {
  const strict = f.strict.get(tileKey(x, y));
  if (strict !== undefined) return strict;
  const lax = f.lax.get(tileKey(x, y));
  if (lax !== undefined) return lax + f.offset;
  return nearestEnemyStepDistance(s, u.side, x, y) + f.offset * 2;
}

interface Shot {
  damage: number;
  lethal: boolean;
  targetId: UnitId;
}

/** Best damage this unit could deal standing at (x, y). */
function bestShotFrom(s: BattleState, u: BattleUnit, x: number, y: number): Shot | null {
  const t = tileAt(s, x, y);
  const range = UNITS[u.type].rng + (t && t.kind === 'elevation' ? BATTLE.elevationRange : 0);
  let best: Shot | null = null;
  for (const e of livingUnits(s, otherSide(u.side))) {
    if (battleDistance(x, y, e.x, e.y) > range) continue;
    if (!hasLineOfSight(s, x, y, e.x, e.y)) continue;
    const { damage } = computeDamage(s, u, e);
    const lethal = damage >= e.hp;
    if (best === null || (lethal && !best.lethal) || (lethal === best.lethal && damage > best.damage)) {
      best = { damage, lethal, targetId: e.id };
    }
  }
  return best;
}

/** How much this unit stands to accomplish if handed action points. */
function opportunity(s: BattleState, u: BattleUnit): number {
  const def = UNITS[u.type];
  let score = def.atk * 3 + def.mov * 4;
  const shot = bestShotFrom(s, u, u.x, u.y);
  if (shot !== null) {
    score += 120 + shot.damage * 12 + (shot.lethal ? 180 : 0);
  } else {
    const field = approachField(s, u);
    score += Math.max(0, 50 - approachCost(s, u, field, u.x, u.y) * 3);
  }
  return score;
}

function bestPlanFor(s: BattleState, u: BattleUnit): Plan | null {
  const plans: Plan[] = [];
  const canShoot = u.attacksThisTurn < BATTLE.maxAttacksPerTurn;

  // 1–2. Shoot something right now.
  if (canShoot) {
    for (const e of livingUnits(s, otherSide(u.side))) {
      if (!canAttack(s, u, e)) continue;
      const { damage } = computeDamage(s, u, e);
      const lethal = damage >= e.hp;
      let score: number;
      if (lethal) score = 1000 + e.maxHp * 5 + UNITS[e.type].atk * 8;
      else if (damage > 0) score = 300 + damage * 25 - e.hp;
      else score = -100; // bouncing shells off a braced target is worse than nothing
      plans.push({ kind: 'attack', unitId: u.id, score, targetId: e.id, x: e.x, y: e.y });
    }
  }

  // 3–4. Reposition: open a shot, or close the distance along a real path.
  const field = approachField(s, u);
  const positional = (x: number, y: number): number =>
    90 - approachCost(s, u, field, x, y) * 4 + terrainAppeal(u, tileAt(s, x, y));
  // Standing pat is always an option. A move has to strictly beat it, which is
  // what stops two units from pacing between the same pair of tiles forever.
  const holding = positional(u.x, u.y);

  for (const node of reachableTiles(s, u, 1).values()) {
    const land = landingOf(s, node.x, node.y);
    const gain = positional(land.x, land.y) - holding;
    // Only strictly better ground is worth an action point.
    let score = gain > 0 ? 60 + Math.min(30, gain) : 0;
    if (u.ap >= 2 && canShoot) {
      const shot = bestShotFrom(s, u, land.x, land.y);
      if (shot !== null && shot.damage > 0) {
        const opener =
          200 + shot.damage * 20 + (shot.lethal ? 320 : 0) + terrainAppeal(u, tileAt(s, land.x, land.y));
        if (opener > score) score = opener;
      }
    }
    if (score > 0) plans.push({ kind: 'move', unitId: u.id, score, targetId: '', x: node.x, y: node.y });
  }

  // 5. Breach a wall that is in the way.
  if (canShoot) {
    const range = effectiveRange(s, u);
    for (let y = 0; y < s.h; y++) {
      for (let x = 0; x < s.w; x++) {
        const t = s.grid[y][x];
        if (t.kind !== 'destructible' || (t.hp ?? 0) <= 0) continue;
        if (battleDistance(u.x, u.y, x, y) > range) continue;
        if (!hasLineOfSight(s, u.x, u.y, x, y)) continue;
        plans.push({ kind: 'wall', unitId: u.id, score: 35, targetId: '', x, y });
      }
    }
  }

  // 6. Dig in.
  if (!u.braced) plans.push({ kind: 'brace', unitId: u.id, score: 12, targetId: '', x: u.x, y: u.y });

  if (plans.length === 0) return null;
  let best = plans[0];
  for (let i = 1; i < plans.length; i++) {
    if (plans[i].score > best.score) best = plans[i];
  }
  return best;
}

// ─────────────────────────────────────────────────────────────────────────────
// Turn
// ─────────────────────────────────────────────────────────────────────────────

/** Play one complete legal turn for `side`: roll, assign, act, end. */
export function aiTakeTurn(s: BattleState, side: BattleSide, rng: Rng, now: number): void {
  if (isOver(s) || s.turn !== side) return;

  if (s.phase === 'rolling') {
    const rolled = rollDice(s, rng, now);
    if (!rolled.ok) return;
    // A triple zero already handed the board over — nothing more to do.
    if (isOver(s) || s.turn !== side) return;
  }

  if (s.phase === 'assign') {
    assignDice(s, side, now);
    if (!confirmAssignments(s, now).ok) return;
  }

  if (s.phase === 'acting') act(s, side, now);

  if (!isOver(s) && s.turn === side) endTurn(s, now);
}

/** Biggest die to the unit with the best scoring opportunity. */
function assignDice(s: BattleState, side: BattleSide, now: number): void {
  const dice = s.dice;
  if (!dice) return;

  const order = DIE_INDICES.filter((d) => dice[d] > 0).sort((a, b) => dice[b] - dice[a]);
  const pool = livingUnits(s, side)
    .map((u) => ({ u, score: opportunity(s, u) }))
    .sort((a, b) => b.score - a.score);

  let i = 0;
  for (const die of order) {
    if (i >= pool.length) break;
    if (assignDie(s, die, pool[i].u.id, now).ok) i++;
  }
}

function act(s: BattleState, side: BattleSide, now: number): void {
  const cap = s.units.length * BATTLE.diceMax * BATTLE.diceCount + 32;
  for (let guard = 0; guard < cap; guard++) {
    if (s.phase !== 'acting' || s.turn !== side) return;

    let best: Plan | null = null;
    for (const u of livingUnits(s, side)) {
      if (u.ap <= 0) continue;
      const plan = bestPlanFor(s, u);
      if (plan === null || plan.score <= 0) {
        u.ap = 0;
        continue;
      }
      if (best === null || plan.score > best.score) best = plan;
    }
    if (best === null) return;

    const chosen: Plan = best;
    let okResult = false;
    switch (chosen.kind) {
      case 'attack':
        okResult = attack(s, chosen.unitId, chosen.targetId, now).ok;
        break;
      case 'wall':
        okResult = attackTile(s, chosen.unitId, chosen.x, chosen.y, now).ok;
        break;
      case 'move':
        okResult = moveUnit(s, chosen.unitId, chosen.x, chosen.y, now).ok;
        break;
      case 'brace':
        okResult = brace(s, chosen.unitId, now).ok;
        break;
      default: {
        const never: never = chosen.kind;
        throw new Error(`unhandled AI plan "${String(never)}"`);
      }
    }

    // Never argue with the rules engine — drop the unit and keep going.
    if (!okResult) {
      const u = s.units.find((x) => x.id === chosen.unitId);
      if (u) u.ap = 0;
    }
  }
}
