/**
 * Glass panels, section headers, stat rows and empty states.
 *
 * These are the structural primitives every screen composes with. Visuals live
 * in styles/components.css; this module only assembles semantic markup.
 */
import { el, append, type Child } from '../dom';

export interface PanelOpts {
  title?: string;
  subtitle?: string;
  /** Any CSS colour (usually a token, e.g. `var(--gold)`). Drives brackets, rim and rules. */
  accent?: string;
  class?: string;
  actions?: HTMLElement[];
  /** Adds the animated sweeping highlight. */
  holo?: boolean;
  /** Draw corner brackets. Defaults to true. */
  brackets?: boolean;
}

/** Four L-shaped corner brackets, absolutely positioned over the parent. */
export function corners(): HTMLElement {
  return el(
    'div',
    { class: 'corners', aria: { hidden: 'true' } },
    el('i'),
    el('i'),
    el('i'),
    el('i'),
  );
}

/**
 * The workhorse container: hairline glass plate with an optional titled head,
 * corner brackets and an accent rim.
 */
export function panel(opts: PanelOpts = {}, ...children: Child[]): HTMLElement {
  const classes = ['panel'];
  if (opts.holo) classes.push('panel--holo');
  if (opts.class) classes.push(opts.class);

  const root = el('section', {
    class: classes.join(' '),
    style: opts.accent ? `--accent:${opts.accent}` : undefined,
  });

  if (opts.holo) root.appendChild(el('div', { class: 'panel__holo', aria: { hidden: 'true' } }));
  if (opts.brackets !== false) root.appendChild(corners());

  if (opts.title !== undefined || opts.subtitle !== undefined || opts.actions?.length) {
    const titles = el('div', { class: 'panel__titles' });
    if (opts.title !== undefined) {
      titles.appendChild(el('h2', { class: 'panel__title', text: opts.title }));
    }
    if (opts.subtitle !== undefined) {
      titles.appendChild(el('div', { class: 'panel__sub', text: opts.subtitle }));
    }
    const head = el('header', { class: 'panel__head' }, titles);
    if (opts.actions?.length) {
      const actions = el('div', { class: 'panel__actions' });
      append(actions, opts.actions);
      head.appendChild(actions);
    }
    root.appendChild(head);
  }

  const body = el('div', { class: 'panel__body' });
  append(body, children);
  root.appendChild(body);

  return root;
}

/** Labelled divider used inside panels and sheets. */
export function sectionHeader(text: string, right?: HTMLElement): HTMLElement {
  const node = el(
    'div',
    { class: 'sec-head' },
    el('span', { class: 'sec-head__text', text }),
    el('span', { class: 'sec-head__line', aria: { hidden: 'true' } }),
  );
  if (right) node.appendChild(el('div', { class: 'sec-head__right' }, right));
  return node;
}

/** `LABEL ······ value` readout row. */
export function statRow(
  label: string,
  value: string | HTMLElement,
  opts: { accent?: string } = {},
): HTMLElement {
  let valueNode: HTMLElement;
  if (typeof value === 'string') {
    valueNode = el('span', { class: 'stat-row__value', text: value });
  } else {
    value.classList.add('stat-row__value');
    valueNode = value;
  }

  return el(
    'div',
    { class: 'stat-row', style: opts.accent ? `--accent:${opts.accent}` : undefined },
    el('span', { class: 'stat-row__label', text: label }),
    el('span', { class: 'stat-row__dots', aria: { hidden: 'true' } }),
    valueNode,
  );
}

/** Dashed "nothing here" placeholder. `icon` is a glyph or emoji, not markup. */
export function emptyState(icon: string, text: string): HTMLElement {
  return el(
    'div',
    { class: 'empty' },
    el('div', { class: 'empty__icon', text: icon, aria: { hidden: 'true' } }),
    el('div', { class: 'empty__text', text }),
  );
}

/** Small uppercase pill used for statuses, roles and flags. */
export function badge(
  text: string,
  kind: 'default' | 'hot' | 'ok' | 'bad' | 'gold' | 'violet' = 'default',
): HTMLElement {
  return el('span', {
    class: kind === 'default' ? 'badge' : `badge badge--${kind}`,
    text,
  });
}

/** Diagonal-hatch "classified" plate for redacted / restricted content. */
export function classified(text: string): HTMLElement {
  return el('div', { class: 'classified', text });
}

/** Shimmering placeholder used while a screen waits on data. */
export function skeleton(
  variant: 'line' | 'block' | 'chip' | 'circle' = 'line',
  count = 1,
): HTMLElement {
  const wrap = el('div', { class: 'col' });
  for (let i = 0; i < count; i++) {
    wrap.appendChild(
      el('div', {
        class: `skel skel--${variant}${variant === 'line' && i % 3 === 2 ? ' short' : ''}`,
      }),
    );
  }
  return wrap;
}
