/**
 * Weekly sector rotation — GDD §3.2.
 *
 * Every `SEASON.rotationMs` one active sector shuts down and one locked sector
 * opens, following the order pre-generated at season start. Both are announced
 * `SEASON.announceMs` ahead so guilds can pre-position.
 *
 * Shutdown wipes fortifications, production and ownership, and force-retreats
 * every army inside to the nearest friendly or neutral ACTIVE hex — no damage.
 * Stockpiles are never touched.
 *
 * PURE: no Three.js, no DOM.
 */
import type { Army, ArmyId, GameState, HexId, Sector, SectorId } from '../types';
import { SEASON } from '../../config/balance';
import { neighborIds } from '../hex';
import { isHexOpen } from './generate';
import { destroyFort } from './fortify';
import { areHostile, armiesOnHex, clearOrders, hostileArmyOnHex } from './movement';

export type RotationEvent =
  | {
      t: 'rotation_announced';
      at: number;
      changeAt: number;
      openingSectorId?: SectorId;
      closingSectorId?: SectorId;
    }
  | { t: 'sector_opened'; at: number; sectorId: SectorId; designation: string }
  | {
      t: 'sector_closed';
      at: number;
      sectorId: SectorId;
      designation: string;
      evacuated: { armyId: ArmyId; toHexId: HexId }[];
      destroyedArmyIds: ArmyId[];
      clearedHexes: number;
    };

/** The sector that will shut down next: whichever has been open longest. */
function pickClosingSector(state: GameState, excludeId?: SectorId): Sector | undefined {
  const candidates = Object.values(state.world.sectors)
    .filter((s) => s.state === 'active' && s.id !== excludeId)
    .sort((a, b) => {
      const oa = a.opensAt ?? 0;
      const ob = b.opensAt ?? 0;
      if (oa !== ob) return oa - ob;
      return a.id < b.id ? -1 : 1;
    });
  return candidates[0];
}

/**
 * What the world knows about the next rotation. Returns empty slots until the
 * reveal window opens (`SEASON.announceMs` before the change).
 */
export function upcomingRotation(
  state: GameState,
  now: number,
): { opening?: Sector; closing?: Sector; at: number } {
  const season = state.season;
  const at = season.nextRotationAt;
  if (season.rotationCursor >= season.rotation.length) return { at };
  if (now < at - SEASON.announceMs) return { at };
  const opening = state.world.sectors[season.rotation[season.rotationCursor]];
  const closing = Object.values(state.world.sectors).find((s) => s.state === 'closing');
  return { opening, closing, at };
}

function canLandHere(state: GameState, army: Army, id: HexId): boolean {
  const hex = state.world.hexes[id];
  if (!hex) return false;
  if (!isHexOpen(state.world, id)) return false;
  if (hex.ownerId && areHostile(state, hex.ownerId, army.ownerId)) return false;
  if (hostileArmyOnHex(state, id, army.ownerId)) return false;
  return true;
}

/** Breadth-first search outward for the nearest friendly or neutral open hex. */
function nearestSafeHex(state: GameState, army: Army): HexId | undefined {
  const start = army.hexId;
  const seen = new Set<HexId>([start]);
  let frontier: HexId[] = [start];
  for (let depth = 0; depth < 128 && frontier.length > 0; depth++) {
    const next: HexId[] = [];
    for (const id of frontier) {
      for (const nb of neighborIds(id)) {
        if (seen.has(nb)) continue;
        seen.add(nb);
        if (!state.world.hexes[nb]) continue;
        next.push(nb);
      }
    }
    next.sort();
    for (const id of next) {
      if (canLandHere(state, army, id)) return id;
    }
    frontier = next;
  }
  return undefined;
}

function closeSector(state: GameState, sector: Sector, now: number): RotationEvent {
  sector.state = 'locked';
  sector.closesAt = undefined;
  sector.opensAt = undefined;

  const inside = new Set<HexId>(sector.hexIds);
  let cleared = 0;
  for (const hexId of sector.hexIds) {
    const hex = state.world.hexes[hexId];
    if (!hex) continue;
    destroyFort(hex);
    hex.production = [];
    hex.reserves = {};
    hex.capture = undefined;
    if (hex.ownerId) cleared++;
    hex.ownerId = undefined;
  }

  const evacuated: { armyId: ArmyId; toHexId: HexId }[] = [];
  const destroyedArmyIds: ArmyId[] = [];
  const trapped = Object.values(state.armies)
    .filter((a) => inside.has(a.hexId))
    .sort((a, b) => (a.id < b.id ? -1 : 1));
  for (const army of trapped) {
    clearOrders(army);
    const target = nearestSafeHex(state, army);
    if (target) {
      army.hexId = target;
      evacuated.push({ armyId: army.id, toHexId: target });
    } else {
      destroyedArmyIds.push(army.id);
      delete state.armies[army.id];
    }
  }

  // Recon and scheduled fights inside a dead sector simply stop existing.
  for (const drone of Object.values(state.drones)) {
    if (inside.has(drone.hexId)) delete state.drones[drone.id];
  }
  state.pendingBattles = state.pendingBattles.filter((b) => !inside.has(b.hexId));

  return {
    t: 'sector_closed',
    at: now,
    sectorId: sector.id,
    designation: sector.designation,
    evacuated,
    destroyedArmyIds,
    clearedHexes: cleared,
  };
}

/** Advance the rotation clock. Announces, opens and closes sectors. */
export function tickRotation(state: GameState, now: number): RotationEvent[] {
  const out: RotationEvent[] = [];
  const season = state.season;
  let guard = 0;

  while (guard++ < 64 && season.rotationCursor < season.rotation.length) {
    const changeAt = season.nextRotationAt;
    const opening = state.world.sectors[season.rotation[season.rotationCursor]];

    // ── announcement window ────────────────────────────────────────────────
    if (now >= changeAt - SEASON.announceMs) {
      let announced = false;
      if (opening && opening.state === 'locked') {
        opening.state = 'unlocking';
        opening.opensAt = changeAt;
        announced = true;
      }
      let closing = Object.values(state.world.sectors).find((s) => s.state === 'closing');
      if (!closing) {
        closing = pickClosingSector(state, opening?.id);
        if (closing) {
          closing.state = 'closing';
          closing.closesAt = changeAt;
          announced = true;
        }
      }
      if (announced) {
        out.push({
          t: 'rotation_announced',
          at: now,
          changeAt,
          openingSectorId: opening?.id,
          closingSectorId: closing?.id,
        });
      }
    }

    if (now < changeAt) break;

    // ── execute ────────────────────────────────────────────────────────────
    // The new front opens first so evacuating columns may fall back into it.
    if (opening) {
      opening.state = 'active';
      opening.opensAt = changeAt;
      opening.closesAt = undefined;
      out.push({
        t: 'sector_opened',
        at: changeAt,
        sectorId: opening.id,
        designation: opening.designation,
      });
    }

    const closing = Object.values(state.world.sectors).find((s) => s.state === 'closing');
    if (closing) out.push(closeSector(state, closing, changeAt));

    season.rotationCursor++;
    season.nextRotationAt = changeAt + SEASON.rotationMs;
  }
  return out;
}

/** Sectors currently playable. */
export function activeSectors(state: GameState): Sector[] {
  return Object.values(state.world.sectors)
    .filter((s) => s.state === 'active' || s.state === 'closing')
    .sort((a, b) => (a.id < b.id ? -1 : 1));
}

/** Armies standing inside a sector — used by the shutdown countdown UI. */
export function armiesInSector(state: GameState, sectorId: SectorId): Army[] {
  const sector = state.world.sectors[sectorId];
  if (!sector) return [];
  const inside = new Set<HexId>(sector.hexIds);
  const out: Army[] = [];
  for (const hexId of inside) {
    for (const army of armiesOnHex(state, hexId)) out.push(army);
  }
  return out;
}
