/** Hourly. Pays `ECONOMY.mineralsPerHex` per controlled hex, clamped to caps. */
export type ResourceTickReq = WorldScoped;
export interface ResourceTickRes {
  at: number;
  /** Whole `ECONOMY.tickMs` periods paid out this run. */
  periods: number;
  playersPaid: number;
  mineralsPaid: number;
  gasPaid: number;
}

/**
 * The heartbeat. Advances army legs, capture timers, fort builds, production
 * queues, drone flights and transfer deliveries, then opens any battle an
 * arrival triggered. Runs every minute and is idempotent for a given `now`.
 */
export type ResolveTimersReq = WorldScoped;
export interface ResolveTimersRes {
  at: number;
  arrivals: number;
  captures: number;
  fortsCompleted: number;
  unitsProduced: number;
  dronesLost: number;
  transfersDelivered: number;
  battlesOpened: number;
}

/** Weekly. Opens the next sector, closes the oldest, evacuates trapped armies. */
export type RotateSectorsReq = WorldScoped;
export interface RotateSectorsRes {
  at: number;
  openedSectorId?: string;
  closedSectorId?: string;
  armiesEvacuated: number;
  armiesDestroyed: number;
  hexesCleared: number;
  /** Next scheduled rotation, for the client countdown. */
  nextRotationAt: number;
}

/** Evaluates domination / forfeit / timeout and closes the season once. */
export type SeasonClockReq = WorldScoped;
export interface SeasonClockRes {
  at: number;
  phase: 'running' | 'ended';
  winnerGuildId?: GuildId;
  endReason?: 'domination' | 'forfeit' | 'timeout';
  endsAt: number;
}

// ─────────────────────────────────────────────────────────────────────────────
// Battle
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GDD §7.2 — the ONLY way dice enter the world. Runs inside an RTDB
 * transaction, appends `roll` (and `triple_zero`) to the signed battle log.
 */
export interface RollDiceReq extends WorldScoped {
  battleId: string;
}
export interface RollDiceRes {
  dice: [number, number, number];
  /** True when the roll was 0-0-0 and the whole turn was skipped. */
  tripleZero: boolean;
  turn: BattleSide;
  turnNumber: number;
}

/** Everything a commander can do inside a battle, as one signed intent. */
export type BattleIntent =
  | { t: 'pick_side'; bottom: BattleSide }
  | { t: 'place_obstacle'; x: number; y: number }
  /** Ends the obstacle step early — the allowance may be unspendable. */
  | { t: 'finish_obstacles' }
  | { t: 'commit_deployment'; placements: { unitId: UnitId; x: number; y: number }[] }
  | { t: 'assign_die'; die: DieIndex; unitId: UnitId }
  | { t: 'unassign_die'; die: DieIndex }
  | { t: 'confirm_assignments' }
  | { t: 'move'; unitId: UnitId; x: number; y: number }
  | { t: 'attack'; unitId: UnitId; targetId: UnitId }
  | { t: 'attack_tile'; unitId: UnitId; x: number; y: number }
  | { t: 'brace'; unitId: UnitId }
  | { t: 'end_turn' }
  /**
   * The 45 s clock expired. Kept separate from `end_turn` so the server can
   * charge it against the missed-timer tally (GDD §7.3); the server must verify
   * the clock really did expire rather than trusting the client's word.
   */
  | { t: 'timeout_pass' }
  | { t: 'concede' };

export interface BattleIntentReq extends WorldScoped {
  battleId: string;
  intent: BattleIntent;
}
export interface BattleIntentRes {
  /** Server-side phase after the intent was applied. */
  phase: string;
  turn: BattleSide;
  /** Index of the last log entry the server wrote for this intent. */
  logLength: number;
}

/** Defender takes the field inside the `BATTLE.defenderGraceMs` window. */
export interface AcceptBattleReq extends WorldScoped {
  battleId: string;
}
export interface AcceptBattleRes {
  battleId: string;
  /** RTDB path the client should attach its battle listener to. */
  path: string;
}

/**
 * Closes a battle. Called by the client only for the concede path; otherwise it
 * fires from the grace-window timer (auto-defense AI) or from the engine when a
 * side is wiped. Writes survivor HP back onto the armies, applies the concede
 * retreat, and resolves hex ownership.
 */
export interface ResolveBattleReq extends WorldScoped {
  battleId: string;
  reason: 'wipe' | 'concede' | 'timeout';
}
export interface ResolveBattleRes {
  winner: BattleSide;
  endReason: 'wipe' | 'concede' | 'timeout';
  survivingUnits: number;
  hexOwnerId?: PlayerId;
  retreatedToHexId?: HexId;
}

