/** Bound `httpsCallable` dispatcher. Rejects on transport or server error. */
export type CallableInvoker = <Req extends object, Res>(name: string, req: Req) => Promise<Res>;

/**
 * Every server call the client is allowed to make, fully typed and already
 * wrapped into `Result` — no wrapper ever throws.
 */
export interface TerraCallables {
  resourceTick(req: ResourceTickReq): Promise<Result<ResourceTickRes>>;
  resolveTimers(req: ResolveTimersReq): Promise<Result<ResolveTimersRes>>;
  rotateSectors(req: RotateSectorsReq): Promise<Result<RotateSectorsRes>>;
  seasonClock(req: SeasonClockReq): Promise<Result<SeasonClockRes>>;

  rollDice(req: RollDiceReq): Promise<Result<RollDiceRes>>;
  battleIntent(req: BattleIntentReq): Promise<Result<BattleIntentRes>>;
  acceptBattle(req: AcceptBattleReq): Promise<Result<AcceptBattleRes>>;
  resolveBattle(req: ResolveBattleReq): Promise<Result<ResolveBattleRes>>;

  deploy(req: DeployReq): Promise<Result<DeployRes>>;
  moveArmy(req: MoveArmyReq): Promise<Result<MoveArmyRes>>;
  haltArmy(req: HaltArmyReq): Promise<Result<EmptyRes>>;
  splitArmy(req: SplitArmyReq): Promise<Result<SplitArmyRes>>;
  mergeArmies(req: MergeArmiesReq): Promise<Result<EmptyRes>>;
  garrisonUnits(req: GarrisonUnitsReq): Promise<Result<EmptyRes>>;
  withdrawUnits(req: WithdrawUnitsReq): Promise<Result<EmptyRes>>;

  buildFort(req: HexRefReq): Promise<Result<BuildFortRes>>;
  cancelFort(req: HexRefReq): Promise<Result<RefundRes>>;
  produceUnits(req: ProduceUnitsReq): Promise<Result<ProduceUnitsRes>>;
  cancelProduction(req: CancelProductionReq): Promise<Result<RefundRes>>;

  launchDrone(req: LaunchDroneReq): Promise<Result<LaunchDroneRes>>;
  moveDrone(req: MoveDroneReq): Promise<Result<EmptyRes>>;
  recallDrone(req: DroneRefReq): Promise<Result<EmptyRes>>;

  setDisplayName(req: SetDisplayNameReq): Promise<Result<EmptyRes>>;
  createGuild(req: CreateGuildReq): Promise<Result<CreateGuildRes>>;
  joinGuild(req: GuildRefReq): Promise<Result<EmptyRes>>;
  leaveGuild(req: WorldScoped): Promise<Result<EmptyRes>>;
  kickMember(req: PlayerRefReq): Promise<Result<EmptyRes>>;
  setRole(req: SetRoleReq): Promise<Result<EmptyRes>>;
  transferLeadership(req: PlayerRefReq): Promise<Result<EmptyRes>>;
  setDiplomat(req: SetDiplomatReq): Promise<Result<EmptyRes>>;

  placePing(req: PlacePingReq): Promise<Result<IdRes>>;
  placeMark(req: PlaceMarkReq): Promise<Result<IdRes>>;
  removeMark(req: MarkRefReq): Promise<Result<EmptyRes>>;
  createObjective(req: CreateObjectiveReq): Promise<Result<IdRes>>;
  commitObjective(req: CommitObjectiveReq): Promise<Result<EmptyRes>>;
  completeObjective(req: ObjectiveRefReq): Promise<Result<EmptyRes>>;
  deleteObjective(req: ObjectiveRefReq): Promise<Result<EmptyRes>>;

  sendTransfer(req: SendTransferReq): Promise<Result<SendTransferRes>>;
  cancelTransfer(req: TransferRefReq): Promise<Result<EmptyRes>>;

  openParley(req: OpenParleyReq): Promise<Result<OpenParleyRes>>;
  proposeTrade(req: ProposeTradeReq): Promise<Result<IdRes>>;
  respondTrade(req: RespondTradeReq): Promise<Result<EmptyRes>>;
  setPeace(req: SetPeaceReq): Promise<Result<EmptyRes>>;
  createTreaty(req: CreateTreatyReq): Promise<Result<CreateTreatyRes>>;
  submitTreatyRevision(req: TreatyRevisionReq): Promise<Result<EmptyRes>>;
  signTreaty(req: TreatyRefReq): Promise<Result<EmptyRes>>;
}

/** Turn a thrown callable error into a human-readable line. */
export function callableError(name: string, error: unknown): string {
  if (error && typeof error === 'object') {
    const e = error as { code?: unknown; message?: unknown };
    const code = typeof e.code === 'string' ? e.code : '';
    const message = typeof e.message === 'string' ? e.message : '';
    if (code === 'functions/unavailable' || code === 'unavailable') {
      return `uplink to ${name} is down — the command was not sent`;
    }
    if (code === 'functions/not-found' || code === 'not-found') {
      return `server function "${name}" is not deployed`;
    }
    if (code === 'functions/unauthenticated' || code === 'unauthenticated') {
      return 'session expired — sign in again';
    }
    if (message) return message;
    if (code) return `${name} failed (${code})`;
  }
  if (error instanceof Error) return error.message;
  return `${name} failed`;
}

/**
 * Build the typed callable surface.
 *
 * Pass `null` when the SDK has not initialised (offline, misconfigured project,
 * blocked network): every method then resolves to a clear error Result instead
 * of throwing, so the app degrades to read-only rather than crashing.
 */
export function makeCallables(invoke: CallableInvoker | null): TerraCallables {
  const call = <Req extends object, Res>(name: FunctionName) => {
    return async (req: Req): Promise<Result<Res>> => {
      if (!invoke) return err<Res>(`server is unreachable — "${name}" was not sent`);
      try {
        const value = await invoke<Req, Res>(name, req);
        if (value === undefined || value === null) {
          return err<Res>(`server function "${name}" returned nothing`);
        }
        return ok(value);
      } catch (error) {
        return err<Res>(callableError(name, error));
      }
    };
  };

  return {
    resourceTick: call<ResourceTickReq, ResourceTickRes>(FUNCTION_NAMES.resourceTick),
    resolveTimers: call<ResolveTimersReq, ResolveTimersRes>(FUNCTION_NAMES.resolveTimers),
    rotateSectors: call<RotateSectorsReq, RotateSectorsRes>(FUNCTION_NAMES.rotateSectors),
    seasonClock: call<SeasonClockReq, SeasonClockRes>(FUNCTION_NAMES.seasonClock),

    rollDice: call<RollDiceReq, RollDiceRes>(FUNCTION_NAMES.rollDice),
    battleIntent: call<BattleIntentReq, BattleIntentRes>(FUNCTION_NAMES.battleIntent),
    acceptBattle: call<AcceptBattleReq, AcceptBattleRes>(FUNCTION_NAMES.acceptBattle),
    resolveBattle: call<ResolveBattleReq, ResolveBattleRes>(FUNCTION_NAMES.resolveBattle),

    deploy: call<DeployReq, DeployRes>(FUNCTION_NAMES.deploy),
    moveArmy: call<MoveArmyReq, MoveArmyRes>(FUNCTION_NAMES.moveArmy),
    haltArmy: call<HaltArmyReq, EmptyRes>(FUNCTION_NAMES.haltArmy),
    splitArmy: call<SplitArmyReq, SplitArmyRes>(FUNCTION_NAMES.splitArmy),
    mergeArmies: call<MergeArmiesReq, EmptyRes>(FUNCTION_NAMES.mergeArmies),
    garrisonUnits: call<GarrisonUnitsReq, EmptyRes>(FUNCTION_NAMES.garrisonUnits),
    withdrawUnits: call<WithdrawUnitsReq, EmptyRes>(FUNCTION_NAMES.withdrawUnits),

    buildFort: call<HexRefReq, BuildFortRes>(FUNCTION_NAMES.buildFort),
    cancelFort: call<HexRefReq, RefundRes>(FUNCTION_NAMES.cancelFort),
    produceUnits: call<ProduceUnitsReq, ProduceUnitsRes>(FUNCTION_NAMES.produceUnits),
    cancelProduction: call<CancelProductionReq, RefundRes>(FUNCTION_NAMES.cancelProduction),

    launchDrone: call<LaunchDroneReq, LaunchDroneRes>(FUNCTION_NAMES.launchDrone),
    moveDrone: call<MoveDroneReq, EmptyRes>(FUNCTION_NAMES.moveDrone),
    recallDrone: call<DroneRefReq, EmptyRes>(FUNCTION_NAMES.recallDrone),

    setDisplayName: call<SetDisplayNameReq, EmptyRes>(FUNCTION_NAMES.setDisplayName),
    createGuild: call<CreateGuildReq, CreateGuildRes>(FUNCTION_NAMES.createGuild),
    joinGuild: call<GuildRefReq, EmptyRes>(FUNCTION_NAMES.joinGuild),
    leaveGuild: call<WorldScoped, EmptyRes>(FUNCTION_NAMES.leaveGuild),
    kickMember: call<PlayerRefReq, EmptyRes>(FUNCTION_NAMES.kickMember),
    setRole: call<SetRoleReq, EmptyRes>(FUNCTION_NAMES.setRole),
    transferLeadership: call<PlayerRefReq, EmptyRes>(FUNCTION_NAMES.transferLeadership),
    setDiplomat: call<SetDiplomatReq, EmptyRes>(FUNCTION_NAMES.setDiplomat),

    placePing: call<PlacePingReq, IdRes>(FUNCTION_NAMES.placePing),
    placeMark: call<PlaceMarkReq, IdRes>(FUNCTION_NAMES.placeMark),
    removeMark: call<MarkRefReq, EmptyRes>(FUNCTION_NAMES.removeMark),
    createObjective: call<CreateObjectiveReq, IdRes>(FUNCTION_NAMES.createObjective),
    commitObjective: call<CommitObjectiveReq, EmptyRes>(FUNCTION_NAMES.commitObjective),
    completeObjective: call<ObjectiveRefReq, EmptyRes>(FUNCTION_NAMES.completeObjective),
    deleteObjective: call<ObjectiveRefReq, EmptyRes>(FUNCTION_NAMES.deleteObjective),

    sendTransfer: call<SendTransferReq, SendTransferRes>(FUNCTION_NAMES.sendTransfer),
    cancelTransfer: call<TransferRefReq, EmptyRes>(FUNCTION_NAMES.cancelTransfer),

    openParley: call<OpenParleyReq, OpenParleyRes>(FUNCTION_NAMES.openParley),
    proposeTrade: call<ProposeTradeReq, IdRes>(FUNCTION_NAMES.proposeTrade),
    respondTrade: call<RespondTradeReq, EmptyRes>(FUNCTION_NAMES.respondTrade),
    setPeace: call<SetPeaceReq, EmptyRes>(FUNCTION_NAMES.setPeace),
    createTreaty: call<CreateTreatyReq, CreateTreatyRes>(FUNCTION_NAMES.createTreaty),
    submitTreatyRevision: call<TreatyRevisionReq, EmptyRes>(FUNCTION_NAMES.submitTreatyRevision),
    signTreaty: call<TreatyRefReq, EmptyRes>(FUNCTION_NAMES.signTreaty),
  };
}
