/**
 * TERRA BELLUM — application shell.
 *
 * Owns everything that outlives a single screen: the status bar, the dock, the
 * toast host, routing, screen lifecycle, the frame loop, and the global error
 * boundary. Screens themselves are loaded on demand so the Three.js bundles
 * only download when the player actually reaches a 3D scene.
 */
import '../styles/base.css';
import '../styles/components.css';
import '../styles/shell.css';

import type { IBackend } from '../backend/IBackend';
import {
  focusHex,
  game,
  onFx,
  setScreen,
  view,
  type FxEvent,
  type ScreenId,
  type ViewState,
} from '../game/store';
import type { GameNotification, GameState } from '../game/types';
import { clear, el, haptic } from './dom';
import type { Screen, ScreenFactory } from './screen';
import {
  applyStoredSettings,
  button,
  clearToasts,
  countdown,
  Dock,
  mountToastHost,
  openModal,
  openShellMenu,
  panel,
  promptModal,
  setClockScale,
  toast,
  TopBar,
  type CountdownController,
  type ModalHandle,
  type ToastKind,
} from './components';

// ─────────────────────────────────────────────────────────────────────────────
// Screen registry — every entry is a dynamic import (its own chunk).
// ─────────────────────────────────────────────────────────────────────────────

const LOADERS: Record<ScreenId, () => Promise<ScreenFactory>> = {
  boot: () => import('./screens/boot').then((m) => m.createBootScreen),
  onboarding: () => import('./screens/onboarding').then((m) => m.createOnboardingScreen),
  staging: () => import('./screens/staging').then((m) => m.createStagingScreen),
  map: () => import('./screens/map').then((m) => m.createMapScreen),
  battle: () => import('./screens/battle').then((m) => m.createBattleScreen),
  guild: () => import('./screens/guild').then((m) => m.createGuildScreen),
  diplomacy: () => import('./screens/diplomacy').then((m) => m.createDiplomacyScreen),
  season_end: () => import('./screens/seasonEnd').then((m) => m.createSeasonEndScreen),
};

/** Which pieces of shell chrome each destination shows. */
const CHROME: Record<ScreenId, { top: boolean; dock: boolean }> = {
  boot: { top: false, dock: false },
  // No chrome: the banner choice is a gate, and a dock is an escape hatch out
  // of a decision the rest of the season is built on.
  onboarding: { top: false, dock: false },
  staging: { top: true, dock: false },
  map: { top: true, dock: true },
  battle: { top: false, dock: false },
  guild: { top: true, dock: true },
  diplomacy: { top: true, dock: true },
  season_end: { top: false, dock: false },
};

const WIPE_MS = 520;
const SWAP_DELAY_MS = 170;

// ─────────────────────────────────────────────────────────────────────────────
// Routing
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Forced-screen precedence (GDD §12):
 *   boot until auth resolves → live battle → no banner yet → not yet deployed →
 *   season over → whatever the player navigated to.
 *
 * The banner step sits between auth and staging: which guild you fight for
 * decides what "uncontested ground" even means, so it is answered before the
 * landing zone. It is gated on three things at once — the commander has no
 * guild, has never made planetfall, and the session latch has not fired — so it
 * can never reappear for a player who already has a banner, who left one, or who
 * was wiped off the map and bounced back to staging.
 */
function resolveScreen(state: GameState | null, v: ViewState): ScreenId {
  if (v.screen === 'boot' || !state) return 'boot';
  if (state.battle) return 'battle';
  const me = state.players[state.meId];
  if (me && !v.onboarded && !me.guildId && !me.deployed) return 'onboarding';
  if (me && !me.deployed) return 'staging';
  if (state.season.phase === 'ended') return 'season_end';
  return v.screen;
}

// ─────────────────────────────────────────────────────────────────────────────
// FX bus → toasts + haptics
// ─────────────────────────────────────────────────────────────────────────────

function asRecord(v: unknown): Record<string, unknown> | null {
  return typeof v === 'object' && v !== null ? (v as Record<string, unknown>) : null;
}

function str(v: unknown, fallback: string): string {
  return typeof v === 'string' && v.length > 0 ? v : fallback;
}

function toastKind(v: unknown): ToastKind {
  return v === 'ok' || v === 'warn' || v === 'bad' || v === 'intel' ? v : 'info';
}

function handleFx(e: FxEvent): void {
  const p = asRecord(e.payload);
  switch (e.type) {
    case 'toast':
      toast({
        title: str(p?.title, 'SIGNAL'),
        body: typeof p?.body === 'string' ? p.body : undefined,
        kind: toastKind(p?.kind),
      });
      return;

    case 'notification':
      toast({
        title: str(p?.title, 'INCOMING'),
        body: typeof p?.body === 'string' ? p.body : undefined,
        kind: toastKind(p?.kind ?? 'intel'),
      });
      haptic([10, 40, 10]);
      return;

    case 'ping':
      toast({
        title: str(p?.title, 'GUILD PING'),
        body: typeof p?.body === 'string' ? p.body : undefined,
        kind: 'warn',
      });
      haptic([14, 34, 14]);
      return;

    case 'triple_zero':
      toast({
        title: '0 · 0 · 0',
        body: str(p?.body, 'Every die came up empty. The turn is gone.'),
        kind: 'bad',
        ms: 5200,
      });
      haptic([40, 60, 40, 60, 120]);
      return;

    case 'battle_end':
      toast({
        title: str(p?.title, 'ENGAGEMENT RESOLVED'),
        body: typeof p?.body === 'string' ? p.body : undefined,
        kind: p?.won === true ? 'ok' : 'bad',
        ms: 5000,
      });
      haptic([28, 50, 28]);
      return;

    case 'capture':
      toast({
        title: str(p?.title, 'HEX SECURED'),
        body: typeof p?.body === 'string' ? p.body : undefined,
        kind: 'ok',
      });
      haptic([12, 30, 18]);
      return;

    case 'unit_destroyed':
      haptic([22, 30, 22]);
      return;

    case 'attack':
      haptic(9);
      return;

    case 'dice_roll':
      haptic([6, 24, 6, 24, 6]);
      return;

    case 'shake':
      haptic(20);
      return;

    default:
      return;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Mount
// ─────────────────────────────────────────────────────────────────────────────

export function mountApp(root: HTMLElement, backend: IBackend): void {
  applyStoredSettings();

  // Countdowns are promises to the player about when they may act again, so
  // they are rendered in the player's clock rather than the compressed world
  // clock the deadlines are stamped in.
  setClockScale(() => backend.clockScale());

  // ── shell DOM ─────────────────────────────────────────────────────────────
  const stage = el('div', { class: 'shell__stage' });
  const wipe = el(
    'div',
    { class: 'shell__wipe', aria: { hidden: 'true' } },
    el('i'),
    el('i'),
    el('i'),
  );

  const topBar = new TopBar({
    onSigil: () => {
      view.patch({ guildTab: 'chat' });
      setScreen('guild');
    },
    onMarkRead: (id) => {
      void backend.markNotificationRead(id);
    },
    onClearAll: () => {
      void backend.clearNotifications();
    },
    onNotification: (n: GameNotification) => {
      if (n.hexId) {
        focusHex(n.hexId);
        setScreen('map');
      }
    },
  });

  const dock = new Dock({
    onMenu: () => {
      const state = game.get();
      const me = state ? state.players[state.meId] : undefined;
      openShellMenu({
        commanderName: me?.name ?? 'UNKNOWN COMMANDER',
        onRename: () => {
          void (async () => {
            const next = await promptModal({
              title: 'CALLSIGN',
              label: 'Commander designation',
              value: me?.name ?? '',
              maxLength: 20,
            });
            if (next === null) return;
            const res = await backend.setDisplayName(next);
            if (!res.ok) toast({ title: 'REJECTED', body: res.error, kind: 'bad' });
            else toast({ title: 'CALLSIGN UPDATED', body: next, kind: 'ok' });
          })();
        },
      });
    },
  });

  dock.onSelect((screen) => setScreen(screen));

  const shell = el('div', { class: 'shell' }, stage, topBar.el, dock.el, wipe);
  clear(root);
  root.appendChild(shell);
  mountToastHost(shell);

  // ── screen lifecycle ──────────────────────────────────────────────────────
  const cache = new Map<ScreenId, Screen>();
  let currentId: ScreenId | null = null;
  let current: Screen | null = null;
  let pendingId: ScreenId | null = null;
  let booted = false;
  let wipeTimer = 0;

  const applyChrome = (id: ScreenId): void => {
    const chrome = CHROME[id];
    topBar.setHidden(!chrome.top);
    dock.setHidden(!chrome.dock);
    document.body.classList.toggle('has-topbar', chrome.top);
    document.body.classList.toggle('has-dock', chrome.dock);
    dock.setActive(id);
  };

  const markBooted = (): void => {
    if (booted) return;
    booted = true;
    document.body.classList.add('booted');
    window.setTimeout(() => document.getElementById('preboot')?.remove(), 720);
  };

  const playWipe = (): void => {
    wipe.classList.remove('is-on');
    void wipe.offsetWidth;
    wipe.classList.add('is-on');
    window.clearTimeout(wipeTimer);
    wipeTimer = window.setTimeout(() => wipe.classList.remove('is-on'), WIPE_MS + 40);
  };

  const loadingStage = (): HTMLElement =>
    el(
      'div',
      { class: 'loading-stage' },
      el('div', { class: 'spinner' }),
      el('div', { class: 'loading-stage__label', text: 'LOADING SUBSYSTEM' }),
    );

  async function ensureScreen(id: ScreenId): Promise<Screen> {
    const existing = cache.get(id);
    if (existing) return existing;
    const factory = await LOADERS[id]();
    const screen = factory(backend);
    cache.set(id, screen);
    return screen;
  }

  const detachCurrent = (): void => {
    if (!current) return;
    try {
      current.unmount();
    } catch (error: unknown) {
      console.error('[terra-bellum] screen unmount failed', error);
    }
    current.el.remove();
    current = null;
    currentId = null;
  };

  async function switchTo(id: ScreenId): Promise<void> {
    if (id === currentId || id === pendingId) return;
    pendingId = id;
    playWipe();
    if (id === 'battle') clearToasts();

    const delay = new Promise<void>((r) => window.setTimeout(r, SWAP_DELAY_MS));
    const loading = ensureScreen(id);

    let screen: Screen;
    try {
      const settled = await Promise.race([
        // Never let this arm reject on its own — the real error surfaces from
        // the `await loading` below, so there is exactly one rejection path.
        loading.then(
          () => 'ready' as const,
          () => 'ready' as const,
        ),
        delay.then(() => 'slow' as const),
      ]);
      if (settled === 'slow') {
        // Bundle still in flight — swap the old screen out for a placeholder so
        // the wipe does not reveal stale content behind it.
        detachCurrent();
        const holder = loadingStage();
        stage.appendChild(holder);
        screen = await loading;
        holder.remove();
      } else {
        await delay;
        screen = await loading;
      }
    } catch (error: unknown) {
      pendingId = null;
      showFault('SUBSYSTEM LOAD FAILURE', error);
      return;
    }

    if (pendingId !== id) return; // a newer route superseded this one
    pendingId = null;

    detachCurrent();
    for (const stale of Array.from(stage.querySelectorAll('.loading-stage'))) stale.remove();
    current = screen;
    currentId = id;
    stage.appendChild(screen.el);
    screen.el.classList.remove('stage-enter');
    void screen.el.offsetWidth;
    screen.el.classList.add('stage-enter');

    try {
      screen.mount();
    } catch (error: unknown) {
      showFault('SCREEN MOUNT FAILURE', error);
    }

    applyChrome(id);
    markBooted();

    // The world may have moved on while the chunk was downloading.
    if (desired !== null && desired !== currentId) void switchTo(desired);
  }

  let desired: ScreenId | null = null;

  const route = (): void => {
    const next = resolveScreen(game.get(), view.get());
    desired = next;
    if (next === currentId) {
      // Chrome can still change (guild tab switches move the dock indicator).
      dock.setActive(next);
      return;
    }
    if (next === pendingId) return;
    void switchTo(next);
  };

  // ── call to arms (GDD §7.4) ───────────────────────────────────────────────
  //
  // An army of yours is under attack and the grace window is running. Without
  // this the only way to answer is `IBackend.acceptBattle`, which nothing in the
  // UI called — so every defence was played by the auto-defense AI and a player
  // never saw the inside of a battle they did not start themselves. It lives in
  // the shell rather than a screen because an attack can land while you are
  // anywhere: reading chat, drafting a treaty, looking at the roster.
  let callHandle: ModalHandle | null = null;
  let callId: string | null = null;
  let callTimer: CountdownController | null = null;
  const declined = new Set<string>();

  const closeCall = (): void => {
    callTimer?.stop();
    callTimer = null;
    callHandle?.close();
    callHandle = null;
    callId = null;
  };

  function syncCallToArms(state: GameState): void {
    const incoming = state.pendingBattles.find(
      (pb) =>
        pb.defenderId === state.meId &&
        !pb.accepted &&
        pb.graceEndsAt > state.now &&
        !declined.has(pb.id),
    );

    if (!incoming || state.battle) {
      if (callHandle) closeCall();
      return;
    }
    if (callId === incoming.id) return; // already asking about this one
    closeCall();

    const attacker = state.players[incoming.attackerId];
    const army = state.armies[incoming.defenderArmyId];
    const battleId = incoming.id;
    callId = battleId;

    const clock = countdown(incoming.graceEndsAt, {
      getNow: () => game.get()?.now ?? Date.now(),
      prefix: 'AI TAKES OVER IN',
      doneText: 'HANDING OFF',
    });
    callTimer = clock;

    const body = el(
      'div',
      { class: 'call' },
      el('p', {
        class: 'call__lede',
        text: `${attacker?.name ?? 'A rival column'} has struck ${army?.name ?? 'your column'} at ${incoming.hexId}.`,
      }),
      el('p', {
        class: 'call__note',
        text: 'Take the field yourself, or let the auto-defense AI hold the line for you.',
      }),
      clock.el,
    );

    callHandle = openModal({
      title: 'UNDER ATTACK',
      body,
      accent: 'var(--crimson)',
      class: 'modal--call',
      dismissable: false,
      actions: [
        {
          label: 'LET AI HOLD',
          variant: 'quiet',
          onClick: () => {
            declined.add(battleId);
            closeCall();
          },
        },
        {
          label: 'TAKE THE FIELD',
          variant: 'danger',
          onClick: () => {
            closeCall();
            void (async () => {
              const res = await backend.acceptBattle(battleId);
              if (!res.ok) toast({ title: 'TOO LATE', body: res.error, kind: 'bad' });
            })();
          },
        },
      ],
      onClose: () => {
        callTimer?.stop();
        callTimer = null;
        callHandle = null;
        callId = null;
      },
    });

    haptic([40, 60, 40, 60, 120]);
  }

  // ── backend → store → shell ───────────────────────────────────────────────
  const push = (state: GameState): void => {
    game.set(state);
    // Latch the banner step shut the moment the commander is on a roster —
    // however they got there (onboarding, the guild screen, the staging sheet).
    if (!view.get().onboarded && state.players[state.meId]?.guildId) {
      view.patch({ onboarded: true });
    }
    try {
      topBar.sync(state);
    } catch (error: unknown) {
      console.error('[terra-bellum] topbar sync failed', error);
    }
    try {
      syncCallToArms(state);
    } catch (error: unknown) {
      console.error('[terra-bellum] call-to-arms sync failed', error);
    }
    route();
  };

  const unsubBackend = backend.subscribe(push);
  const unsubView = view.subscribe(() => route());
  const unsubFx = onFx(handleFx);

  try {
    push(backend.getState());
  } catch {
    // Backend not ready yet — the first subscription push will route us.
    route();
  }

  // ── frame loop ────────────────────────────────────────────────────────────
  let last = performance.now();
  let raf = requestAnimationFrame(function loop(t: number): void {
    const dt = Math.min(64, t - last);
    last = t;
    if (current?.frame) {
      try {
        current.frame(dt);
      } catch (error: unknown) {
        console.error('[terra-bellum] frame error', error);
      }
    }
    raf = requestAnimationFrame(loop);
  });

  // ── global error boundary ─────────────────────────────────────────────────
  let faultOpen = false;

  function showFault(title: string, error: unknown): void {
    console.error(`[terra-bellum] ${title}`, error);
    if (faultOpen) return;
    faultOpen = true;

    const err = error instanceof Error ? error : new Error(String(error));
    const layer = el('div', { class: 'fault' });
    const dismiss = button('CONTINUE', {
      variant: 'ghost',
      onClick: () => {
        faultOpen = false;
        layer.remove();
      },
    });
    const reload = button('RESTART CONSOLE', {
      variant: 'primary',
      onClick: () => window.location.reload(),
    });

    layer.appendChild(
      panel(
        {
          title: 'SYSTEM FAULT',
          subtitle: title,
          accent: 'var(--crimson)',
          class: 'panel--danger fault__panel',
        },
        el('div', { class: 'fault__code', text: 'ERR // UNHANDLED' }),
        el('div', { class: 'fault__msg selectable', text: err.message || 'unknown failure' }),
        err.stack ? el('pre', { class: 'fault__trace', text: err.stack }) : null,
        el('div', { class: 'row', style: 'gap:var(--sp-2);padding-top:var(--sp-2)' }, dismiss, reload),
      ),
    );
    document.body.appendChild(layer);
    haptic([40, 60, 40]);
  }

  const onWindowError = (ev: ErrorEvent): void => {
    showFault('UNCAUGHT EXCEPTION', ev.error ?? ev.message);
  };
  const onRejection = (ev: PromiseRejectionEvent): void => {
    showFault('UNHANDLED REJECTION', ev.reason);
  };
  window.addEventListener('error', onWindowError);
  window.addEventListener('unhandledrejection', onRejection);

  // ── service worker (production only) ──────────────────────────────────────
  if (import.meta.env.PROD && 'serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker
        .register(`${import.meta.env.BASE_URL}sw.js`)
        .catch(() => {
          /* offline support is a bonus, never a hard requirement */
        });
    });
  }

  // ── teardown ──────────────────────────────────────────────────────────────
  window.addEventListener('pagehide', () => {
    cancelAnimationFrame(raf);
    closeCall();
    unsubBackend();
    unsubView();
    unsubFx();
    window.removeEventListener('error', onWindowError);
    window.removeEventListener('unhandledrejection', onRejection);
    detachCurrent();
    for (const screen of cache.values()) {
      try {
        screen.unmount();
      } catch {
        /* ignore */
      }
    }
    cache.clear();
    topBar.dispose();
    dock.dispose();
  });

  // Failsafe: if no screen has mounted after 8 s, drop the curtain anyway so a
  // stalled subsystem never leaves the player staring at a boot animation.
  window.setTimeout(() => {
    if (!booted) markBooted();
  }, 8000);
}
